CREATE OR REPLACE FUNCTION "public"."actor_level"("_user_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(MAX(rc.level), 0)
  FROM public.user_roles ur
  JOIN public.roles_config rc ON rc.name = ur.role::text and rc.tenant_id = ur.tenant_id AND rc.is_active
  WHERE ur.user_id = _user_id;
$$;


ALTER FUNCTION "public"."actor_level"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_cowork_vs_hubstaff"("_desde" "date", "_hasta" "date") RETURNS TABLE("dia" "date", "profile_id" "uuid", "nombre" "text", "hubstaff_seg" integer, "hubstaff_actividad" integer, "cowork_activo_seg" integer, "cowork_pausa_seg" integer, "cowork_sin_camara_seg" integer, "cowork_sin_pantalla_seg" integer, "cowork_fuera_seg" integer, "cowork_en_sala_seg" integer, "cowork_sesiones" integer, "cowork_sin_conexion_seg" integer, "cowork_sin_conexion_larga_seg" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.has_role(auth.uid(), 'admin') then
    raise exception 'Solo admins' using errcode = '42501';
  end if;
  if _hasta < _desde or _hasta - _desde > 92 then
    raise exception 'Rango inválido (máximo 92 días)';
  end if;

  return query
  with hub as (
    select (a.starts_at at time zone 'America/Bogota')::date as dia,
           hm.profile_id,
           sum(a.tracked_seconds)::int as seg,
           round(sum(a.overall_activity * a.tracked_seconds) filter (where a.overall_activity is not null)
                 / nullif(sum(a.tracked_seconds) filter (where a.overall_activity is not null), 0))::int as actividad
    from public.hubstaff_activities a
    join public.hubstaff_members hm on hm.id = a.member_id
    where (a.starts_at at time zone 'America/Bogota')::date between _desde and _hasta
    group by 1, 2
    having sum(a.tracked_seconds) > 0
  ),
  cw as (
    select c.dia, c.user_id as profile_id,
           c.seg_activo, c.seg_pausa, c.seg_sin_camara, c.seg_sin_pantalla, c.seg_fuera_de_camara, c.seg_en_sala, c.sesiones,
           c.seg_sin_conexion, c.seg_sin_conexion_larga
    from public.cowork_tiempo_diario(_desde, _hasta, null, 500, 0) c
  )
  select coalesce(h.dia, c.dia) as dia,
         coalesce(h.profile_id, c.profile_id) as profile_id,
         p.full_name as nombre,
         coalesce(h.seg, 0), h.actividad,
         coalesce(c.seg_activo, 0), coalesce(c.seg_pausa, 0), coalesce(c.seg_sin_camara, 0),
         coalesce(c.seg_sin_pantalla, 0), coalesce(c.seg_fuera_de_camara, 0), coalesce(c.seg_en_sala, 0),
         coalesce(c.sesiones, 0),
         coalesce(c.seg_sin_conexion, 0), coalesce(c.seg_sin_conexion_larga, 0)
  from hub h
  full outer join cw c on c.dia = h.dia and c.profile_id = h.profile_id
  left join public.profiles p on p.id = coalesce(h.profile_id, c.profile_id)
  order by 1 desc, 3;
end;
$$;


ALTER FUNCTION "public"."admin_cowork_vs_hubstaff"("_desde" "date", "_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_user_roles"() RETURNS TABLE("user_id" "uuid", "role" "text", "level" integer, "is_admin" boolean, "manageable" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_caller uuid := auth.uid(); v_level int; v_is_admin boolean;
BEGIN
  IF NOT public.can_manage_users(v_caller) THEN
    RAISE EXCEPTION 'insufficient_privilege: se requiere permiso de gestión de usuarios'
      USING ERRCODE = '42501';
  END IF;
  v_level := public.actor_level(v_caller);
  v_is_admin := public.is_in_role_group(v_caller,'admin');

  RETURN QUERY
  SELECT p.id,
         ur.role::text,
         CASE WHEN ur.role IS NULL THEN 0 ELSE COALESCE(rc.level, 999) END,
         COALESCE(rg.is_admin,false),
         (p.id <> v_caller AND (v_is_admin OR v_level >
            CASE WHEN ur.role IS NULL THEN 0 ELSE COALESCE(rc.level,999) END))
  FROM public.profiles p
  JOIN public.tenant_members tm ON tm.user_id = p.id AND tm.tenant_id = public.current_tenant_id()
  LEFT JOIN public.user_roles ur ON ur.user_id = p.id
  LEFT JOIN public.roles_config rc ON rc.name = ur.role::text and rc.tenant_id = ur.tenant_id
  LEFT JOIN public.role_groups  rg ON rg.role_name = ur.role::text and rg.tenant_id = ur.tenant_id;
END;
$$;


ALTER FUNCTION "public"."admin_list_user_roles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agencia_de_sala_livekit"("_room" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  select case
    -- Las salas de Cowork llevan los 8 primeros caracteres del id de su sesión:
    -- cowork_hub_<s>, cowork_<s>_<n>, cowork_meet_<s>_<m>, cowork_1on1_<s>_<r>.
    -- Por el prefijo se encuentra también una sala ya cerrada (closeRoom borra la
    -- fila de cowork_rooms y la sala de LiveKit puede seguir viva un rato).
    when _room like 'cowork\_%' then (
      select case when count(distinct s.tenant_id) = 1 then min(s.tenant_id::text)::uuid end
      from public.cowork_sessions s
      where left(s.id::text, 8) = substring(_room from '^cowork_(?:hub_|meet_|1on1_)?([0-9a-f]{8})'))
    -- Meet: la agencia de la reunión (20261003120000; antes, la de quien la creó).
    when _room like 'meet\_%' then (
      select mr.tenant_id from public.meet_rooms mr where mr.livekit_room_name = _room)
    -- Llamadas del Messenger: la sala es call-<id de la conversación>, también las
    -- de grupo, que no tienen fila en calls (20261003120000). Si la conversación
    -- ya no existe, la de sus llamadas, si es una sola.
    when _room like 'call-%' then coalesce(
      (select c.tenant_id from public.chat_conversations c
        where c.id = (substring(_room from '^call-([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$'))::uuid),
      (select case when count(distinct k.tenant_id) = 1 then min(k.tenant_id::text)::uuid end
       from public.calls k where k.room_id = _room))
  end
$_$;


ALTER FUNCTION "public"."agencia_de_sala_livekit"("_room" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."agencia_de_sala_livekit"("_room" "text") IS 'La agencia de una sala de LiveKit por su nombre: Cowork por la sesión, Meet por quien la creó, llamadas por quien llamó. NULL si no se sabe.';



CREATE OR REPLACE FUNCTION "public"."alvaro_pulse"("p_dry_run" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_tenant uuid := '30869615-f579-4981-8a1f-dbebc61eae2d';
  v_dm uuid := '9eb0f764-cf6e-4d8f-87e0-c7b9cdc2d17f';
  v_warming_group uuid := 'a12d9f41-c962-4d98-b0bb-6b2d2573534c';
  v_managers_group uuid := '73a4414e-2546-4ca7-9289-7cbec70b0273';
  v_ventas_group uuid := 'd12ec56f-b324-4369-b72d-7540fb930ef6';
  v_today date := (now() at time zone 'America/Bogota')::date;
  v_when text := to_char(now() at time zone 'America/Bogota','HH24:MI');
  v_hora int := extract(hour from now() at time zone 'America/Bogota')::int;
  v_start timestamptz := v_today::timestamp at time zone 'America/Bogota';
  v_end timestamptz := (v_today::timestamp at time zone 'America/Bogota') + interval '24 hours';
  v_meta_contactadas int := greatest(2, v_hora - 9);
  v_es_domingo boolean := extract(dow from (now() at time zone 'America/Bogota'))::int = 0;
  v_dom_fichados text;
  v_managers text; v_ventas text; v_warming text;
  v_promo text; v_contacto text; v_hub_mgr text; v_caidas text; v_lbl_caida text;
  v_grupo_m text; v_grupo_v text; v_grupo_w text; v_hub_clo text;
  v_hitos_m text; v_hitos_v text;
  v_conc text; v_intervencion text;
  v_completadas_hoy int; v_confirmadas int; v_asignadas int; v_b2b_trabajo int; v_b2b_hoy int;
  v_negociando int; v_interesados int; v_ofrecidos int; v_ganados_mes int;
  v_feed_last timestamptz; v_feed_stale boolean;
  -- Caída a día vencido: tramo 1..(día de ayer) de este mes vs el MISMO tramo del
  -- mes pasado. Hoy 3 → "1–2 ago vs 1–2 jul", como lo pidió Jhon, con fechas dichas.
  v_dcorte int := extract(day from v_today)::int - 1;
  v_prev_ini date := (date_trunc('month', v_today) - interval '1 month')::date;
  v_meses constant text[] := array['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
begin
  -- ── GATE DE DOMINGO (pedido de Álvaro 02/08; ver migración domingos) ──
  if v_es_domingo and v_hora not in (12, 18) then return 'skip: domingo, solo 12:00 y 18:00'; end if;
  if (not v_es_domingo) and v_hora in (12, 18) then return 'skip: 12/18 son horarios de domingo'; end if;

  -- Frescura del feed en vivo de Hubstaff (única señal observable: max(starts_at)).
  select max(starts_at) into v_feed_last from hubstaff_activities;
  v_feed_stale := v_feed_last is null or v_feed_last < now() - interval '30 minutes';

  -- ── HITOS DEL DÍA (creator_milestones) ─────────────────────────────────────
  -- "Noticias de hoy": anotados hoy (aunque hayan ocurrido antes — se dice la
  -- fecha) u ocurridos hoy. Managers ve estados (retención/accesos/salidas);
  -- Ventas ve plata (cierres/meets/negociación/casos de éxito).
  select string_agg(
      '· ' || etiqueta || ' '
      || case when nullif(creator_handle,'') is not null and lower(title) not like lower(creator_handle) || '%' then '*' || creator_handle || '*: ' else '' end
      || title
      || case when occurred_on <> v_today then ' (' || to_char(occurred_on,'DD/MM') || ')' else '' end,
      E'\n' order by occurred_on desc, created_at desc)
  into v_hitos_m
  from (
    select m.creator_handle, m.title, m.occurred_on, m.created_at,
           case m.kind when 'en_retencion' then '🚨' when 'quito_accesos' then '🔒'
                       when 'salida_anunciada' then '👋' when 'record_ingreso' then '🏆'
                       else '📌' end as etiqueta
    from creator_milestones m
    where m.tenant_id = v_tenant
      and (m.created_at >= v_start or m.occurred_on = v_today)
      and m.kind in ('en_retencion','quito_accesos','salida_anunciada','record_ingreso')
    order by m.occurred_on desc, m.created_at desc limit 5
  ) t;

  select string_agg(
      '· ' || etiqueta || ' '
      || case when nullif(creator_handle,'') is not null and lower(title) not like lower(creator_handle) || '%' then '*' || creator_handle || '*: ' else '' end
      || title
      || case when occurred_on <> v_today then ' (' || to_char(occurred_on,'DD/MM') || ')' else '' end,
      E'\n' order by occurred_on desc, created_at desc)
  into v_hitos_v
  from (
    select m.creator_handle, m.title, m.occurred_on, m.created_at,
           case m.kind when 'caso_exito' then '📈' when 'venta_producto' then '💰'
                       when 'cierre' then '✅' when 'reunion_agendada' then '📅'
                       when 'en_negociacion' then '🤝' when 'cerca_de_cierre' then '🔥'
                       else '📌' end as etiqueta
    from creator_milestones m
    where m.tenant_id = v_tenant
      and (m.created_at >= v_start or m.occurred_on = v_today)
      and m.kind in ('caso_exito','venta_producto','cierre','reunion_agendada','en_negociacion','cerca_de_cierre')
    order by m.occurred_on desc, m.created_at desc limit 5
  ) t;

  -- ── MANAGERS · promo de HOY (X/N por manager) ──────────────────────────────
  -- Cuenta creadoras DISTINTAS con promoted='true' HOY (columna `dia`, Bogotá).
  -- Es un PISO durante el día: la promo se detecta a medida que corren los scans.
  select string_agg(
      '· ' || mgr || ': *' || con_promo || '/' || total || '*',
      E'\n' order by mgr)
  into v_promo
  from (
    select split_part(p.full_name,' ',1) as mgr,
           count(*)::int as total,
           count(*) filter (where exists (
             select 1 from promolog_entries e
             where e.creator_id = c.id and e.tenant_id = v_tenant
               and e.dia = v_today and e.promoted = 'true'))::int as con_promo
    from creators c join profiles p on p.id = c.assigned_manager_profile_id
    where c.status = 'active' and c.assigned_manager_profile_id is not null
    group by 1
  ) t;

  -- ── MANAGERS · contactadas hoy (línea compartida, atribución Kash) ─────────
  with sc as (
    select manager_name,
      count(days_since_contact) as silent,
      count(*) filter (where days_since_contact is null) as sin_reg
    from get_manager_silent_creators(v_tenant, 3) group by 1
  ),
  linea as (select id from wa_channels where department='manager' and coalesce(active, true)),
  convs as (select id, contact_id from wa_conversations where channel_id in (select id from linea) and contact_id is not null),
  sal as (
    select c.contact_id, count(*)::int as msgs
    from wa_conversation_messages wm join convs c on c.id = wm.conversation_id
    where wm.direction = 'out' and wm.deleted_at is null and coalesce(wm.status,'') <> 'failed'
      and wm.sent_at >= v_start and wm.sent_at < v_end
    group by 1
  ),
  cr_phone as (
    select cr.id, cr.assigned_manager_profile_id,
           right(public.canonical_phone(coalesce(cr.phone_e164, cr.whatsapp_number, cr.phone)), 10) as key10,
           right(regexp_replace(coalesce(cr.phone_e164, cr.whatsapp_number, cr.phone, ''), '\D', '', 'g'), 8) as key8
    from creators cr where cr.status = 'active'
  ),
  cr10 as (
    select distinct on (key10) key10, id from cr_phone
    where length(key10) = 10
    order by key10, (assigned_manager_profile_id is null)
  ),
  cr8 as (
    select key8, min(id::text)::uuid as id from cr_phone
    where length(key8) = 8
    group by key8 having count(distinct id) = 1
  ),
  matched as (
    select s.msgs, coalesce(c10.id, c8.id) as creator_id
    from sal s
    join wa_contacts ct on ct.id = s.contact_id
    left join cr10 c10 on c10.key10 = right(public.canonical_phone(ct.phone_e164), 10)
    left join cr8 c8 on c10.id is null and c8.key8 = right(regexp_replace(coalesce(ct.phone_e164,''), '\D', '', 'g'), 8)
  ),
  attrib as (
    select m.creator_id, m.msgs,
      split_part(coalesce(p.full_name, '(sin manager)'), ' ', 1) as mgr
    from matched m
    join creators cr on cr.id = m.creator_id
    left join creator_business cb on cb.creator_id = m.creator_id
    left join profiles p on p.id = cr.assigned_manager_profile_id
    where m.creator_id is not null
  ),
  per_mgr as (
    select mgr, count(distinct creator_id)::int as contactadas, sum(msgs)::int as msgs_tot
    from attrib group by mgr
  ),
  por_creadora as (select a.creator_id, sum(a.msgs)::int as msgs from attrib a group by 1),
  tot as (select coalesce(sum(msgs),0)::int as t, count(*)::int as n from por_creadora),
  top2 as (
    select coalesce(sum(x.msgs),0)::int as t2,
           string_agg(coalesce(nullif(cr.artistic_name,''), cr.name), ' y ') as nombres
    from (select creator_id, msgs from por_creadora order by msgs desc limit 2) x
    join creators cr on cr.id = x.creator_id
  )
  select
    (select string_agg(
        '· ' || mg.mgr || ': *' || coalesce(pm.contactadas,0) || ' contactadas* · '
        || coalesce(sc.silent,0) || ' sin contacto 3+ d'
        || case when coalesce(sc.sin_reg,0) > 0 then ' (+' || sc.sin_reg || ' sin reg)' else '' end
        || case when (not v_es_domingo) and coalesce(pm.contactadas,0) < v_meta_contactadas
                then ' ⚠️ bajo (~' || v_meta_contactadas || ')' else '' end,
        E'\n' order by mg.mgr)
      -- Se parte del ROSTER de managers, no de sc: una manager con CERO
      -- silenciosas desaparecería si la lista naciera del RPC de silenciosas.
      from (select distinct split_part(p2.full_name,' ',1) as mgr
              from creators c2 join profiles p2 on p2.id = c2.assigned_manager_profile_id
             where c2.status = 'active') mg
      left join sc on split_part(sc.manager_name,' ',1) = mg.mgr
      left join per_mgr pm on pm.mgr = mg.mgr),
    (select case when tot.t >= 10 and tot.n > 2 and top2.t2 * 2 >= tot.t
        then E'\n⚠️ Concentración: ' || top2.t2 || ' de ' || tot.t || ' msgs a 2 creadoras (' || top2.nombres || ').'
        else '' end
      from tot, top2)
  into v_contacto, v_conc;

  -- ── MANAGERS · horas y actividad de las managers en Hubstaff hoy ───────────
  select string_agg(
      '· ' || nombre || ': ' || (secs/3600)::int || 'h' || lpad(((secs%3600)/60)::int::text,2,'0')
      || coalesce(' · ' || act || '% act.', ''),
      E'\n' order by secs desc)
  into v_hub_mgr
  from (
    select split_part(p.full_name,' ',1) as nombre,
           sum(a.tracked_seconds)::bigint as secs,
           round(sum(a.overall_activity * a.tracked_seconds) filter (where a.overall_activity is not null)
                 / nullif(sum(a.tracked_seconds) filter (where a.overall_activity is not null), 0))::int as act
    from (select distinct assigned_manager_profile_id as pid from creators
          where status='active' and assigned_manager_profile_id is not null) mgrs
    join profiles p on p.id = mgrs.pid
    join hubstaff_members hm on hm.profile_id = p.id
    join hubstaff_activities a on a.member_id = hm.id and a.starts_at >= v_start
    group by 1 having sum(a.tracked_seconds) > 0
  ) t;

  -- ── MANAGERS · modelos en caída (día vencido, mismo tramo del mes pasado) ──
  if v_dcorte >= 1 then
    v_lbl_caida := '1–' || v_dcorte || ' ' || v_meses[extract(month from v_today)::int]
                 || ' vs 1–' || v_dcorte || ' ' || v_meses[extract(month from v_prev_ini)::int];
    select string_agg(
        '· ' || nombre || ': $' || act || ' vs $' || prev || ' (' || pct || '%)' || flag,
        E'\n' order by pct)
    into v_caidas
    from (
      select coalesce(nullif(c.artistic_name,''), c.name) as nombre,
             round(coalesce(sum(e.total_gross) filter (where e.date >= date_trunc('month',v_today)::date and e.date <= v_today - 1), 0))::int as act,
             round(coalesce(sum(e.total_gross) filter (where e.date >= v_prev_ini and e.date <= v_prev_ini + (v_dcorte-1)), 0))::int as prev,
             round(((coalesce(sum(e.total_gross) filter (where e.date >= date_trunc('month',v_today)::date and e.date <= v_today - 1), 0)
                     - coalesce(sum(e.total_gross) filter (where e.date >= v_prev_ini and e.date <= v_prev_ini + (v_dcorte-1)), 0))
                    / nullif(sum(e.total_gross) filter (where e.date >= v_prev_ini and e.date <= v_prev_ini + (v_dcorte-1)), 0)) * 100)::int as pct,
             -- Últimos 2 días en ~$0 tras venir facturando = probable corte de
             -- lectura (quitó accesos), no caída real. Se marca, no se esconde.
             case when coalesce((select sum(e2.total_gross) from creator_daily_earnings e2
                                 where e2.creator_id = c.id and e2.date >= v_today - 2), 0) < 5
                  then ' ⚠️ sin lectura BLU reciente (¿quitó accesos?)' else '' end as flag
      from creators c
      join creator_daily_earnings e on e.creator_id = c.id
      where c.status = 'active' and c.assigned_manager_profile_id is not null
        and e.date >= v_prev_ini and e.date <= v_today - 1
      group by c.id, nombre
      having coalesce(sum(e.total_gross) filter (where e.date >= v_prev_ini and e.date <= v_prev_ini + (v_dcorte-1)), 0) >= 100
         and coalesce(sum(e.total_gross) filter (where e.date >= date_trunc('month',v_today)::date and e.date <= v_today - 1), 0)
             < 0.75 * coalesce(sum(e.total_gross) filter (where e.date >= v_prev_ini and e.date <= v_prev_ini + (v_dcorte-1)), 0)
      order by 4 limit 5
    ) t;
  else
    v_lbl_caida := 'día 1 del mes';
    v_caidas := '· la comparación mes vs mes arranca mañana (hoy no hay día vencido del mes)';
  end if;

  -- ── MANAGERS · respaldo por keywords (solo si no hay hitos del día) ────────
  -- Los @lids/menciones se limpian del extracto para que se lea como frase.
  select string_agg('· ' || nombre || ': "' || left(limpio, 110) || '…"', E'\n' order by ult)
  into v_grupo_m
  from (
    select * from (
      select coalesce(split_part(nullif(pf.full_name,''),' ',1), wm.sender_display_name) as nombre,
             regexp_replace(regexp_replace(coalesce(nullif(wm.body,''), wm.transcribed_text, ''),
               '@[0-9]{6,}[[:space:]]*', '', 'g'), E'[\\n\\r\\t ]+', ' ', 'g') as limpio,
             max(wm.sent_at) as ult
      from whatsapp_messages wm
      left join whatsapp_members mm on mm.group_id = wm.group_id and mm.external_id = wm.sender_external_id
      left join profiles pf on pf.id = mm.user_id
      where wm.group_id = v_managers_group and wm.is_from_bot = false
        and wm.sent_at >= v_start
        and coalesce(nullif(wm.body,''), wm.transcribed_text, '') ~* '(retenc|quit[oó] (los )?accesos|carta de terminac|renunci|se va|firm[oó]|cerr[oó]|ballena|subi[oó]|subieron|let.?s ?shoot|letshoot|unlimited|reuni[oó]n|caso de [eé]xito)'
      group by 1, 2
    ) s
    where length(s.limpio) > 25
    order by s.ult desc limit 3
  ) t;

  v_managers :=
    E'📊 *MANAGERS* — ' || v_when || E' (Bogotá)\n'
    || E'\n*Promo*\n' || coalesce(v_promo, '· sin datos')
    || E'\n\n*Contacto* (por manager asignada en la ficha)\n' || coalesce(v_contacto, '· sin datos') || coalesce(v_conc, '')
    || E'\n\n*Hubstaff*\n' || coalesce(v_hub_mgr, '· sin horas registradas' || case when v_feed_stale then ' (feed atrasado)' else '' end)
    || E'\n\n*En caída* (' || v_lbl_caida || E', día vencido)\n' || coalesce(v_caidas, '· ninguna con caída fuerte (≥25%)')
    || case when v_dcorte >= 1 then E'\n_Cifras al último sync de BLU: puede ajustarlas en ambos sentidos._' else '' end
    || case when v_hitos_m is not null then E'\n\n*Hitos*\n' || v_hitos_m
            when v_grupo_m is not null then E'\n\n*Del grupo*\n' || v_grupo_m
            else '' end;

  -- ── VENTAS ─────────────────────────────────────────────────────────────────
  select
    count(*) filter (where stage='Completada' and confirmed_date::date = v_today and coalesce(lead_source,'maven') <> 'agencia'),
    count(*) filter (where stage='Confirmada' and coalesce(lead_source,'maven') <> 'agencia'),
    count(*) filter (where stage='Asignada' and coalesce(lead_source,'maven') <> 'agencia'),
    count(*) filter (where stage='Asignada' and coalesce(lead_source,'') = 'agencia'),
    count(*) filter (where coalesce(lead_source,'') = 'agencia' and assigned_to is not null
                     and (passed_date = v_today or (created_at at time zone 'America/Bogota')::date = v_today))
  into v_completadas_hoy, v_confirmadas, v_asignadas, v_b2b_trabajo, v_b2b_hoy
  from closer_creators;

  select
    count(*) filter (where stage='negotiating'),
    count(*) filter (where stage='interested'),
    count(*) filter (where stage='offered'),
    count(*) filter (where stage='won' and won_at >= date_trunc('month', v_today))
  into v_negociando, v_interesados, v_ofrecidos, v_ganados_mes
  from monetization_opportunities where tenant_id = v_tenant;

  select string_agg(
      format('@%s ($%s/mes, hace %sd)',
             coalesce(nullif(instagram_handle,''),'(sin handle)'),
             round(monthly_monetization)::text,
             (v_today - confirmed_date::date)::text),
      ' · ' order by monthly_monetization desc)
  into v_intervencion
  from (
    select instagram_handle, monthly_monetization, confirmed_date
    from closer_creators
    where stage = 'Confirmada' and coalesce(monthly_monetization,0) >= 10000
      and confirmed_date is not null and confirmed_date::date <= v_today - 3
    order by monthly_monetization desc limit 3
  ) t;

  -- Closers / closer supervisors en Hubstaff hoy (horas + % actividad).
  select string_agg(
      '· ' || nombre || ': ' || (secs/3600)::int || 'h' || lpad(((secs%3600)/60)::int::text,2,'0')
      || coalesce(' · ' || act || '% act.', ''),
      E'\n' order by secs desc)
  into v_hub_clo
  from (
    select split_part(p.full_name,' ',1) as nombre,
           sum(a.tracked_seconds)::bigint as secs,
           round(sum(a.overall_activity * a.tracked_seconds) filter (where a.overall_activity is not null)
                 / nullif(sum(a.tracked_seconds) filter (where a.overall_activity is not null), 0))::int as act
    from (select distinct ur.user_id from user_roles ur where ur.role::text ilike '%closer%') cl
    join profiles p on p.id = cl.user_id
    join hubstaff_members hm on hm.profile_id = p.id
    join hubstaff_activities a on a.member_id = hm.id and a.starts_at >= v_start
    group by 1 having sum(a.tracked_seconds) > 0
  ) t;

  -- VENTAS · respaldo por keywords (solo si no hay hitos del día).
  select string_agg('· ' || nombre || ': "' || left(limpio, 110) || '…"', E'\n' order by ult)
  into v_grupo_v
  from (
    select * from (
      select coalesce(split_part(nullif(pf.full_name,''),' ',1), wm.sender_display_name) as nombre,
             regexp_replace(regexp_replace(coalesce(nullif(wm.body,''), wm.transcribed_text, ''),
               '@[0-9]{6,}[[:space:]]*', '', 'g'), E'[\\n\\r\\t ]+', ' ', 'g') as limpio,
             max(wm.sent_at) as ult
      from whatsapp_messages wm
      left join whatsapp_members mm on mm.group_id = wm.group_id and mm.external_id = wm.sender_external_id
      left join profiles pf on pf.id = mm.user_id
      where wm.group_id = v_ventas_group and wm.is_from_bot = false
        and wm.sent_at >= v_start
        and coalesce(nullif(wm.body,''), wm.transcribed_text, '') ~* '(retenc|quit[oó] (los )?accesos|firm[oó]|cerr[oó]|subi[oó]|subieron|gracias a|let.?s ?shoot|letshoot|unlimited|caso de [eé]xito|reuni[oó]n de cierre)'
      group by 1, 2
    ) s
    where length(s.limpio) > 25
    order by s.ult desc limit 3
  ) t;

  v_ventas :=
    E'💼 *VENTAS* — ' || v_when || E' (Bogotá)\n'
    || E'\n*Pipeline*\n'
    || '· Reclutamiento: *' || v_completadas_hoy || ' completadas* · ' || v_confirmadas || ' por firmar · ' || v_asignadas || E' asignadas\n'
    || '· Productos: ' || v_negociando || ' negociando · ' || v_interesados || ' interesados · ' || v_ofrecidos || ' ofrecidos · *' || v_ganados_mes || ' ganados/mes*'
    || E'\n' || '· Agencias B2B: *' || v_b2b_trabajo || ' en trabajo*' || case when v_b2b_hoy > 0 then ' (+' || v_b2b_hoy || ' hoy)' else '' end
    || E'\n\n*Hubstaff*\n' || coalesce(v_hub_clo, '· sin horas registradas' || case when v_feed_stale then ' (feed atrasado)' else '' end)
    || case when v_hitos_v is not null then E'\n\n*Hitos*\n' || v_hitos_v
            when v_grupo_v is not null then E'\n\n*Del grupo*\n' || v_grupo_v
            else '' end
    || case when v_intervencion is not null
         then E'\n\n👉 *Intervén* (alto valor, 3+ d sin cierre): ' || v_intervencion
         else '' end;

  -- ── WARMING · corte del día primero, señales después ───────────────────────
  -- El corte es la fila de whatsapp_daily_reports que el bot registra cuando
  -- reportan en el grupo (Álvaro los pidió cada 2h). "sin corte aún" NO borra
  -- las señales: alguien sin reporte pero con 4h de Hubstaff se ve trabajando.
  with miembros as (
    select p.id, m.external_id,
           split_part(coalesce(nullif(p.full_name,''), m.display_name),' ',1) as nombre
    from whatsapp_members m join profiles p on p.id = m.user_id
    where m.group_id = v_warming_group
      and p.id not in ('c5b124cb-f272-458d-aa8e-1b11de0ff4d6','528453bd-f1e1-43d3-85c1-01c5fa5bbcfb','fcdfdfcb-c0ab-4c82-b6d9-d50d37ab086e','75bca8d9-ded5-4e86-b591-88209f6a5e6c','8b90f141-8546-4cfd-a358-56ff227623df','41b35cef-82a8-4991-9234-3514b0064767','3661183d-2c79-4a6b-86be-515f9ee441c2')
  ),
  rep as (
    select r.user_id, r.created_at, r.contactados, r.respuestas, r.numeros_obtenidos,
           r.videos_creados, r.fotos_creadas, r.posts_subidos, r.cuentas_creadas
    from whatsapp_daily_reports r where r.report_date = v_today
  ),
  datos as (
    select mi.nombre, mi.id,
      rep.created_at as corte_at,
      rep.contactados, rep.respuestas, rep.numeros_obtenidos,
      rep.videos_creados, rep.fotos_creadas, rep.posts_subidos, rep.cuentas_creadas,
      (select count(*) from closers_contacts cc
        where cc.created_by = mi.id and cc.phone is not null and cc.created_at::date = v_today) as numeros,
      (select count(*) from leadgen_entries le
        where le.lg_user_id = mi.id and le.created_at::date = v_today) as leads,
      (select coalesce(r2.videos_creados,0) + coalesce(r2.fotos_creadas,0) from whatsapp_daily_reports r2
        where r2.user_id = mi.id and r2.report_date = v_today - 1) as piezas_ayer,
      (select coalesce(sum(a.tracked_seconds),0)::bigint
        from hubstaff_activities a join hubstaff_members hm on hm.id = a.member_id
        where hm.profile_id = mi.id and a.starts_at >= v_start) as hub_secs,
      (select round(sum(a.overall_activity * a.tracked_seconds) filter (where a.overall_activity is not null)
                    / nullif(sum(a.tracked_seconds) filter (where a.overall_activity is not null), 0))::int
        from hubstaff_activities a join hubstaff_members hm on hm.id = a.member_id
        where hm.profile_id = mi.id and a.starts_at >= v_start) as hub_act,
      (select to_char(max(wm.sent_at) at time zone 'America/Bogota','HH24:MI')
        from whatsapp_messages wm
        where wm.group_id = v_warming_group and wm.sender_external_id = mi.external_id
          and wm.is_from_bot = false and wm.sent_at >= v_start) as ultimo_msg
    from miembros mi left join rep on rep.user_id = mi.id
  ),
  render as (
    select d.nombre, d.corte_at, d.hub_secs,
      -- Números del corte: los de llg (textos/resp/números) se muestran aunque
      -- sean 0 — el 0 ES la noticia (Daniel: 15 textos · 0 resp · 0 números).
      nullif(concat_ws(' · ',
        case when d.contactados is not null then d.contactados || ' textos' end,
        case when d.respuestas is not null then d.respuestas || ' resp' end,
        case when d.numeros_obtenidos is not null then d.numeros_obtenidos || ' números' end,
        case when coalesce(d.videos_creados,0) > 0 then d.videos_creados || ' videos' end,
        case when coalesce(d.fotos_creadas,0) > 0 then d.fotos_creadas || ' fotos' end,
        case when coalesce(d.posts_subidos,0) > 0 then d.posts_subidos || ' posts' end,
        case when coalesce(d.cuentas_creadas,0) > 0 then d.cuentas_creadas || ' cuentas' end
      ), '') as reporte,
      nullif(concat_ws(' · ',
        case when d.leads > 0 then d.leads || ' perfiles cargados' end,
        case when d.numeros > 0 then d.numeros || ' números en Maven' end,
        case when not v_feed_stale and d.hub_secs > 0
             then (d.hub_secs/3600)::int || 'h' || lpad(((d.hub_secs%3600)/60)::int::text,2,'0') || ' Hubstaff'
                  || coalesce(' (' || d.hub_act || '% act.)', '') end,
        case when d.ultimo_msg is not null then 'en el grupo ' || d.ultimo_msg end,
        case when d.corte_at is null and coalesce(d.piezas_ayer,0) > 0 then d.piezas_ayer || ' piezas ayer' end
      ), '') as senales
    from datos d
  )
  select string_agg(
    case when corte_at is null and senales is null
      then '· *' || nombre || '*: sin señales hoy'
           || case when v_feed_stale then ' (feed Hubstaff atrasado)' else '' end
      else '· *' || nombre || '*'
           || case when corte_at is not null
                then ' — corte ' || to_char(corte_at at time zone 'America/Bogota','HH24:MI') || ': '
                     || coalesce(reporte, 'registrado')
                else ' — sin corte aún' end
           || case when senales is not null then E'\n   ' || senales else '' end
    end,
    E'\n' order by (corte_at is null), hub_secs desc nulls last, nombre)
  into v_warming
  from render;

  -- WARMING · lo operativo del grupo (recuperadas/baneadas/campañas/bloqueos).
  select string_agg('· ' || nombre || ': "' || left(limpio, 110) || '…"', E'\n' order by ult)
  into v_grupo_w
  from (
    select * from (
      select coalesce(split_part(nullif(pf.full_name,''),' ',1), wm.sender_display_name) as nombre,
             regexp_replace(regexp_replace(coalesce(nullif(wm.body,''), wm.transcribed_text, ''),
               '@[0-9]{6,}[[:space:]]*', '', 'g'), E'[\\n\\r\\t ]+', ' ', 'g') as limpio,
             max(wm.sent_at) as ult
      from whatsapp_messages wm
      left join whatsapp_members mm on mm.group_id = wm.group_id and mm.external_id = wm.sender_external_id
      left join profiles pf on pf.id = mm.user_id
      where wm.group_id = v_warming_group and wm.is_from_bot = false
        and wm.sent_at >= v_start
        and coalesce(nullif(wm.body,''), wm.transcribed_text, '') ~* '(recuperad|banead|verificad|verificaci|campañ|aprob[oó]|granja|bloquead|suspendid|ca[ií]da)'
      group by 1, 2
    ) s
    where length(s.limpio) > 15
    order by s.ult desc limit 3
  ) t;

  v_warming := E'🔥 *WARMING (AI)* — ' || v_when || E' (Bogotá)\n\n' || coalesce(v_warming, '· sin datos')
    || case when v_grupo_w is not null then E'\n\n*Del grupo*\n' || v_grupo_w else '' end
    || E'\n\n_corte = reporte del día · % = actividad Hubstaff_'
    || case when v_feed_stale
         then E'\n⚠️ Hubstaff sin reportar desde ' ||
              coalesce(to_char(v_feed_last at time zone 'America/Bogota','HH24:MI'), '(nunca)') ||
              ' — las horas del día no son concluyentes.'
         else '' end;

  -- Domingo: sin control de gente, pero si alguien SÍ fichó, una línea informativa.
  if v_es_domingo then
    select string_agg(nombre || ' ' || horas, ' · ' order by secs desc) into v_dom_fichados
    from (
      select hm.name as nombre, sum(a.tracked_seconds) as secs,
             (sum(a.tracked_seconds)/3600)::int || 'h' || lpad((((sum(a.tracked_seconds)::int % 3600))/60)::text, 2, '0') as horas
      from hubstaff_activities a join hubstaff_members hm on hm.id = a.member_id
      where a.starts_at >= v_start
      group by hm.name
      having sum(a.tracked_seconds) >= 900
      order by 2 desc limit 8
    ) t;
    if v_dom_fichados is not null then
      v_managers := v_managers || E'\n\n_Fichando hoy domingo (Hubstaff): ' || v_dom_fichados || '_';
    end if;
  end if;

  if p_dry_run then
    if v_es_domingo then return v_managers || E'\n\n———\n\n' || v_ventas || E'\n\n———\n\n(domingo: WARMING no se manda)'; end if;
    return v_managers || E'\n\n———\n\n' || v_ventas || E'\n\n———\n\n' || v_warming;
  end if;

  perform net.http_post(
    url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/whatsapp-send',
    headers := jsonb_build_object('Content-Type','application/json',
      'Authorization','Bearer '||(select decrypted_secret from vault.decrypted_secrets where name='supabase_anon_key'),
      'X-Cron-Token',(select decrypted_secret from vault.decrypted_secrets where name='cron_internal_token')),
    body := jsonb_build_object('group_id', v_dm::text, 'body', v_managers),
    timeout_milliseconds := 30000);
  perform pg_sleep(1);
  perform net.http_post(
    url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/whatsapp-send',
    headers := jsonb_build_object('Content-Type','application/json',
      'Authorization','Bearer '||(select decrypted_secret from vault.decrypted_secrets where name='supabase_anon_key'),
      'X-Cron-Token',(select decrypted_secret from vault.decrypted_secrets where name='cron_internal_token')),
    body := jsonb_build_object('group_id', v_dm::text, 'body', v_ventas),
    timeout_milliseconds := 30000);
  if not v_es_domingo then
    perform pg_sleep(1);
    perform net.http_post(
      url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/whatsapp-send',
      headers := jsonb_build_object('Content-Type','application/json',
        'Authorization','Bearer '||(select decrypted_secret from vault.decrypted_secrets where name='supabase_anon_key'),
        'X-Cron-Token',(select decrypted_secret from vault.decrypted_secrets where name='cron_internal_token')),
      body := jsonb_build_object('group_id', v_dm::text, 'body', v_warming),
      timeout_milliseconds := 30000);
    return 'sent_3_sections';
  end if;
  return 'sent_2_sections_domingo';
end;
$_$;


ALTER FUNCTION "public"."alvaro_pulse"("p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_argos_notas"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with segs as (
    select user_id,
           (started_at at time zone 'America/Bogota')::date as dia,
           sum(case when estado in ('activo','pausa') then coalesce(seconds, 0) else 0 end)::int as segs_pantalla,
           sum(coalesce(seconds, 0))::int as segs_conectado
    from cowork_tiempo_segmentos
    where (_from is null or started_at >= _from::timestamptz)
      and (_to   is null or started_at <  (_to + 1)::timestamptz)
      and (_profile_id is null or user_id = _profile_id)
    group by user_id, dia
  ),
  caps as (
    select user_id,
           (created_at at time zone 'America/Bogota')::date as dia,
           count(*) filter (where tipo = 'camara')::int as caps_camara,
           count(*) filter (where tipo = 'camara' and cara_visible is true)::int as caps_cara,
           count(*) filter (where tipo = 'pantalla')::int as caps_pantalla,
           count(*) filter (where fuera_de_lugar is true and perdonado is not true)::int as caps_distraido
    from monitor_capturas
    where (_from is null or created_at >= _from::timestamptz)
      and (_to   is null or created_at <  (_to + 1)::timestamptz)
      and (_profile_id is null or user_id = _profile_id)
    group by user_id, dia
  ),
  union_dias as (
    select user_id, dia from segs
    union
    select user_id, dia from caps
  ),
  juntos as (
    select u.user_id, u.dia,
           coalesce(s.segs_pantalla, 0) as segs_pantalla,
           coalesce(s.segs_conectado, 0) as segs_conectado,
           coalesce(c.caps_camara, 0) as caps_camara,
           coalesce(c.caps_cara, 0) as caps_cara,
           coalesce(c.caps_pantalla, 0) as caps_pantalla,
           coalesce(c.caps_distraido, 0) as caps_distraido
    from union_dias u
    left join segs s on s.user_id = u.user_id and s.dia = u.dia
    left join caps c on c.user_id = u.user_id and c.dia = u.dia
  ),
  notas as (
    select user_id, dia, segs_pantalla, segs_conectado, caps_camara, caps_cara, caps_pantalla, caps_distraido,
           round((least(1.0, segs_pantalla / nullif(8 * 3600.0, 0)) * 45)::numeric, 1) as nota_pantalla,
           case when caps_camara > 0 then round((caps_cara::numeric / caps_camara) * 35, 1) else 0 end as nota_camara,
           case when caps_pantalla > 0 then round((1 - (caps_distraido::numeric / caps_pantalla)) * 20, 1) else 20 end as nota_distraccion
    from juntos
  )
  select jsonb_build_object(
    'data', coalesce(jsonb_agg(
      jsonb_build_object(
        'employee_id', user_id,
        'date', dia,
        'score', least(100, greatest(0, round((coalesce(nota_pantalla,0) + coalesce(nota_camara,0) + coalesce(nota_distraccion,0))::numeric, 1))),
        'breakdown', jsonb_build_object(
          'screen_score', nota_pantalla,
          'camera_score', nota_camara,
          'focus_score', nota_distraccion
        ),
        'raw', jsonb_build_object(
          'seconds_on_screen', segs_pantalla,
          'seconds_connected', segs_conectado,
          'camera_snapshots', caps_camara,
          'camera_face_visible', caps_cara,
          'screen_snapshots', caps_pantalla,
          'screen_off_task', caps_distraido
        )
      ) order by dia desc, user_id
    ), '[]'::jsonb),
    'count', (select count(*) from notas)
  )
  from (
    select * from notas order by dia desc, user_id
    offset coalesce(_offset, 0) limit coalesce(_limit, 100)
  ) q;
$$;


ALTER FUNCTION "public"."api_argos_notas"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_attendance"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with dias as (
    select user_id,
           (started_at at time zone 'America/Bogota')::date as dia,
           min(started_at) as entro_at,
           max(coalesce(ended_at, last_seen_at, started_at)) as salio_at,
           sum(case when estado = 'activo' then coalesce(seconds, 0) else 0 end)::int as segs_activo,
           sum(case when estado = 'pausa'  then coalesce(seconds, 0) else 0 end)::int as segs_pausa,
           sum(coalesce(seconds, 0))::int as segs_conectado
    from cowork_tiempo_segmentos
    where (_from is null or started_at >= _from::timestamptz)
      and (_to   is null or started_at <  (_to + 1)::timestamptz)
      and (_profile_id is null or user_id = _profile_id)
    group by user_id, dia
  ),
  tar as (
    select user_id, dia, horario_asignado, entro_at as tard_entro_at,
           tarde_min, turno_nombre
    from tardanzas_registro
    where (_from is null or dia >= _from)
      and (_to   is null or dia <= _to)
      and (_profile_id is null or user_id = _profile_id)
  )
  select jsonb_build_object(
    'data', coalesce(jsonb_agg(
      jsonb_build_object(
        'employee_id', q.user_id,
        'date', q.dia,
        'clock_in_at', q.entro_at,
        'clock_out_at', q.salio_at,
        'hours_worked', round(q.segs_activo / 3600.0, 2),
        'hours_paused', round(q.segs_pausa / 3600.0, 2),
        'hours_connected', round(q.segs_conectado / 3600.0, 2),
        'scheduled_entry', q.horario_asignado,
        'late_minutes', coalesce(q.tarde_min, 0),
        'shift_name', q.turno_nombre
      ) order by q.dia desc, q.user_id
    ), '[]'::jsonb),
    'count', (select count(*) from dias)
  )
  from (
    select d.user_id, d.dia, d.entro_at, d.salio_at, d.segs_activo, d.segs_pausa, d.segs_conectado,
           t.horario_asignado, t.tarde_min, t.turno_nombre
    from dias d
    left join tar t on t.user_id = d.user_id and t.dia = d.dia
    order by d.dia desc, d.user_id
    offset coalesce(_offset, 0) limit coalesce(_limit, 100)
  ) q;
$$;


ALTER FUNCTION "public"."api_attendance"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_cowork_breaks"("_from" "date" DEFAULT NULL::"date", "_to" "date" DEFAULT NULL::"date", "_profile_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 100, "_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "profile_id" "uuid", "employee" "text", "kind" "text", "started_at" timestamp with time zone, "ended_at" timestamp with time zone, "is_open" boolean, "seconds" integer, "limit_seconds" integer, "exceeded" boolean, "auto_closed" boolean, "session_id" "uuid", "session_name" "text", "room_id" "uuid", "room_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select b.id, b.user_id as profile_id, p.full_name as employee,
         case b.kind when 'bano' then 'bathroom' else b.kind end as kind,
         b.started_at, b.ended_at, (b.ended_at is null) as is_open,
         coalesce(b.duration_seconds, greatest(0, extract(epoch from (now() - b.started_at))::int)) as seconds,
         lim.limite_seg as limit_seconds,
         (lim.limite_seg is not null
          and coalesce(b.duration_seconds, greatest(0, extract(epoch from (now() - b.started_at))::int)) > lim.limite_seg) as exceeded,
         b.auto_closed,
         b.session_id, cs.name as session_name,
         b.room_id, cr.name as room_name
  from public.cowork_breaks b
  left join public.profiles p on p.id = b.user_id
  left join public.cowork_sessions cs on cs.id = b.session_id
  left join public.cowork_rooms cr on cr.id = b.room_id
  -- El tope es el de la agencia de la sesión (20261001213000).
  left join public.cowork_break_limits l on l.kind = b.kind and l.tenant_id = cs.tenant_id
  cross join lateral (
    select coalesce(
      nullif(cs.alert_rules->'pausas'->>(case when b.kind = 'break' then 'breakMin' else 'banoMin' end), '')::int,
      l.minutos
    ) * 60 as limite_seg
  ) lim
  where (_from is null or (b.started_at at time zone 'America/Bogota')::date >= _from)
    and (_to is null or (b.started_at at time zone 'America/Bogota')::date <= _to)
    and (_profile_id is null or b.user_id = _profile_id)
  order by b.started_at desc
  limit least(greatest(_limit, 1), 500)
  offset greatest(_offset, 0)
$$;


ALTER FUNCTION "public"."api_cowork_breaks"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."api_cowork_breaks"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) IS 'API pública: cada pausa de Cowork (bathroom | break) con duración, tope vigente y si se pasó. Para el baño el tope es el presupuesto del DÍA, no de la pausa: exceeded ahí es orientativo; el veredicto diario está en /cowork/time.';



CREATE OR REPLACE FUNCTION "public"."api_cowork_meets"("_from" "date" DEFAULT NULL::"date", "_to" "date" DEFAULT NULL::"date", "_profile_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 100, "_offset" integer DEFAULT 0) RETURNS TABLE("meet_id" "uuid", "session_id" "uuid", "session_name" "text", "invoked_by" "uuid", "invoked_by_name" "text", "meet_started_at" timestamp with time zone, "meet_ended_at" timestamp with time zone, "meet_end_reason" "text", "profile_id" "uuid", "employee" "text", "room_id" "uuid", "room_name" "text", "joined_at" timestamp with time zone, "left_at" timestamp with time zone, "is_open" boolean, "seconds" integer, "left_reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    m.id as meet_id, m.session_id, cs.name as session_name,
    m.created_by as invoked_by, pc.full_name as invoked_by_name,
    m.started_at as meet_started_at, m.ended_at as meet_ended_at, m.end_reason as meet_end_reason,
    p.user_id as profile_id, pr.full_name as employee,
    p.room_id, cr.name as room_name,
    p.joined_at, p.left_at, (p.left_at is null) as is_open,
    coalesce(p.duration_seconds, greatest(0, extract(epoch from (now() - p.joined_at)))::int) as seconds,
    case p.left_reason when 'volvio' then 'returned' when 'meet_terminado' then 'meet_ended' when 'barrido' then 'swept' else p.left_reason end as left_reason
  from public.cowork_meet_participants p
  join public.cowork_meets m on m.id = p.meet_id
  left join public.cowork_sessions cs on cs.id = m.session_id
  left join public.cowork_rooms cr on cr.id = p.room_id
  left join public.profiles pr on pr.id = p.user_id
  left join public.profiles pc on pc.id = m.created_by
  where (_from is null or (p.joined_at at time zone 'America/Bogota')::date >= _from)
    and (_to is null or (p.joined_at at time zone 'America/Bogota')::date <= _to)
    and (_profile_id is null or p.user_id = _profile_id)
  order by m.started_at desc, pr.full_name
  limit least(greatest(_limit, 1), 500)
  offset greatest(_offset, 0)
$$;


ALTER FUNCTION "public"."api_cowork_meets"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."api_cowork_meets"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) IS 'API pública: cada persona en cada meet grupal de Cowork (quién lo invocó, de qué sala vino, cuánto estuvo). Ese tiempo cuenta como trabajado y ya está dentro de active_seconds en /cowork/time; acá se ve aparte.';



CREATE OR REPLACE FUNCTION "public"."api_cowork_time_segments"("_from" "date" DEFAULT NULL::"date", "_to" "date" DEFAULT NULL::"date", "_profile_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 100, "_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "profile_id" "uuid", "employee" "text", "session_id" "uuid", "session_name" "text", "room_id" "uuid", "room_name" "text", "state" "text", "detail" "text", "started_at" timestamp with time zone, "ended_at" timestamp with time zone, "is_open" boolean, "seconds" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select s.id, s.user_id as profile_id, p.full_name as employee,
         s.session_id, cs.name as session_name,
         s.room_id, cr.name as room_name,
         case s.estado
           when 'activo' then 'active' when 'pausa' then 'paused' when 'sin_camara' then 'no_camera'
           when 'sin_pantalla' then 'no_screen' when 'fuera_de_camara' then 'away' when 'meet' then 'group_meet'
           when 'sin_conexion' then 'disconnected' when 'sin_conexion_larga' then 'disconnected_long'
           else s.estado end as state,
         s.detalle as detail,
         s.started_at, s.ended_at, (s.ended_at is null) as is_open, s.seconds
  from public.cowork_tiempo_segmentos s
  left join public.profiles p on p.id = s.user_id
  left join public.cowork_sessions cs on cs.id = s.session_id
  left join public.cowork_rooms cr on cr.id = s.room_id
  where (_from is null or (coalesce(s.ended_at, s.last_seen_at) at time zone 'America/Bogota')::date >= _from)
    and (_to is null or (s.started_at at time zone 'America/Bogota')::date <= _to)
    and (_profile_id is null or s.user_id = _profile_id)
  order by s.started_at desc
  limit least(greatest(_limit, 1), 500)
  offset greatest(_offset, 0)
$$;


ALTER FUNCTION "public"."api_cowork_time_segments"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_cupo_gastar"("_clave" "text", "_msj" integer DEFAULT 0, "_dest" integer DEFAULT 0, "_chats" integer DEFAULT 0, "_edic" integer DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _min  timestamptz := date_trunc('minute', now());
  _hora timestamptz := date_trunc('hour', now());
  _dia  date := (now() at time zone 'America/Bogota')::date;
  _c public.api_escritura_cupos;
  _nivel text;
  _limite text;
  _espera integer;
  _fin_dia timestamptz;
begin
  update public.api_escritura_cupos c set
    min_msj   = case when c.min_inicio  >= _min  then c.min_msj   else 0 end + _msj,
    min_dest  = case when c.min_inicio  >= _min  then c.min_dest  else 0 end + _dest,
    min_edic  = case when c.min_inicio  >= _min  then c.min_edic  else 0 end + _edic,
    min_inicio  = greatest(coalesce(c.min_inicio, _min), _min),
    hora_msj  = case when c.hora_inicio >= _hora then c.hora_msj  else 0 end + _msj,
    hora_dest = case when c.hora_inicio >= _hora then c.hora_dest else 0 end + _dest,
    hora_edic = case when c.hora_inicio >= _hora then c.hora_edic else 0 end + _edic,
    hora_inicio = greatest(coalesce(c.hora_inicio, _hora), _hora),
    dia_msj   = case when c.dia_inicio  >= _dia  then c.dia_msj   else 0 end + _msj,
    dia_dest  = case when c.dia_inicio  >= _dia  then c.dia_dest  else 0 end + _dest,
    dia_chats = case when c.dia_inicio  >= _dia  then c.dia_chats else 0 end + _chats,
    dia_inicio  = greatest(coalesce(c.dia_inicio, _dia), _dia),
    actualizado = now()
  where c.clave = _clave
    and (_msj   = 0 or (case when c.min_inicio  >= _min  then c.min_msj   else 0 end) + _msj   <= c.lim_msj_min)
    and (_msj   = 0 or (case when c.hora_inicio >= _hora then c.hora_msj  else 0 end) + _msj   <= c.lim_msj_hora)
    and (_msj   = 0 or (case when c.dia_inicio  >= _dia  then c.dia_msj   else 0 end) + _msj   <= c.lim_msj_dia)
    and (_dest  = 0 or (case when c.min_inicio  >= _min  then c.min_dest  else 0 end) + _dest  <= c.lim_dest_min)
    and (_dest  = 0 or (case when c.hora_inicio >= _hora then c.hora_dest else 0 end) + _dest  <= c.lim_dest_hora)
    and (_dest  = 0 or (case when c.dia_inicio  >= _dia  then c.dia_dest  else 0 end) + _dest  <= c.lim_dest_dia)
    and (_chats = 0 or (case when c.dia_inicio  >= _dia  then c.dia_chats else 0 end) + _chats <= c.lim_chats_dia)
    and (_edic  = 0 or (case when c.min_inicio  >= _min  then c.min_edic  else 0 end) + _edic  <= c.lim_edic_min)
    and (_edic  = 0 or (case when c.hora_inicio >= _hora then c.hora_edic else 0 end) + _edic  <= c.lim_edic_hora);
  if found then
    return;
  end if;

  -- No pasó: o falta la fila (falla cerrado) o se pasa de algún tope (cuál, y cuándo
  -- se libera). Solo corre al rechazar.
  select * into _c from public.api_escritura_cupos c where c.clave = _clave;
  if not found then
    raise exception using errcode = 'MV503',
      message = 'api_sin_cupo: no hay fila de cupo para ' || _clave,
      detail = '{"motivo": "sin_cupo"}';
  end if;
  if _dest > _c.lim_dest_min then
    raise exception using errcode = 'MV422',
      message = 'api_mensaje_demasiado_pesado: un solo mensaje pesa más que el tope por minuto',
      detail = '{"error": "conversation_too_large"}';
  end if;
  _nivel := case when _clave = 'plataforma' then 'platform' when _clave like 'agencia:%' then 'agency' else 'key' end;
  _fin_dia := ((_dia + 1)::timestamp at time zone 'America/Bogota');
  if _msj > 0 and (case when _c.min_inicio >= _min then _c.min_msj else 0 end) + _msj > _c.lim_msj_min then
    _limite := 'messages_minute';   _espera := ceil(extract(epoch from greatest(_c.min_inicio, _min) + interval '1 minute' - now()));
  elsif _msj > 0 and (case when _c.hora_inicio >= _hora then _c.hora_msj else 0 end) + _msj > _c.lim_msj_hora then
    _limite := 'messages_hour';     _espera := ceil(extract(epoch from greatest(_c.hora_inicio, _hora) + interval '1 hour' - now()));
  elsif _msj > 0 and (case when _c.dia_inicio >= _dia then _c.dia_msj else 0 end) + _msj > _c.lim_msj_dia then
    _limite := 'messages_day';      _espera := ceil(extract(epoch from _fin_dia - now()));
  elsif _dest > 0 and (case when _c.min_inicio >= _min then _c.min_dest else 0 end) + _dest > _c.lim_dest_min then
    _limite := 'recipients_minute'; _espera := ceil(extract(epoch from greatest(_c.min_inicio, _min) + interval '1 minute' - now()));
  elsif _dest > 0 and (case when _c.hora_inicio >= _hora then _c.hora_dest else 0 end) + _dest > _c.lim_dest_hora then
    _limite := 'recipients_hour';   _espera := ceil(extract(epoch from greatest(_c.hora_inicio, _hora) + interval '1 hour' - now()));
  elsif _dest > 0 and (case when _c.dia_inicio >= _dia then _c.dia_dest else 0 end) + _dest > _c.lim_dest_dia then
    _limite := 'recipients_day';    _espera := ceil(extract(epoch from _fin_dia - now()));
  elsif _chats > 0 and (case when _c.dia_inicio >= _dia then _c.dia_chats else 0 end) + _chats > _c.lim_chats_dia then
    _limite := 'new_chats_day';     _espera := ceil(extract(epoch from _fin_dia - now()));
  elsif _edic > 0 and (case when _c.min_inicio >= _min then _c.min_edic else 0 end) + _edic > _c.lim_edic_min then
    _limite := 'edits_minute';      _espera := ceil(extract(epoch from greatest(_c.min_inicio, _min) + interval '1 minute' - now()));
  else
    _limite := 'edits_hour';        _espera := ceil(extract(epoch from greatest(_c.hora_inicio, _hora) + interval '1 hour' - now()));
  end if;
  raise exception using errcode = 'MV429',
    message = 'api_tope: se alcanzó el tope ' || _nivel || '_' || _limite,
    detail = json_build_object('limite', _nivel || '_' || _limite, 'reintentar_en', greatest(coalesce(_espera, 1), 1))::text;
end;
$$;


ALTER FUNCTION "public"."api_cupo_gastar"("_clave" "text", "_msj" integer, "_dest" integer, "_chats" integer, "_edic" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_equipo_aplicar"("_cambios" "jsonb", "_resumen" "jsonb", "_ensayo" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  _k public.api_keys := public.api_equipo_llave();
  _yo uuid := auth.uid();
  _cfg public.integracion_equipo;
  _ensayo_final boolean;
  _bajas integer;
  _c jsonb;
  _uid uuid;
  _campo text;
  _txt text;
  _jefe uuid;
  _hs jsonb;
  _motivo text;
  _aplicados jsonb := '[]'::jsonb;
  _rechazados jsonb := '[]'::jsonb;
  _huella text;
  _ultima_id uuid;
  _ultima_huella text;
  _ultima_ensayo boolean;
  _sync uuid;
  _recibidas integer;
begin
  if _cambios is null or jsonb_typeof(_cambios) <> 'array' or jsonb_array_length(_cambios) > 10000 then
    raise exception 'api_equipo_aplicar: _cambios tiene que ser una lista (hasta 10.000)';
  end if;
  if _resumen is null or jsonb_typeof(_resumen) <> 'object' or pg_column_size(_resumen) > 4000000 then
    raise exception 'api_equipo_aplicar: _resumen tiene que ser un objeto (hasta 4 MB)';
  end if;

  -- Un envío a la vez por agencia: dos a la vez se pisarían.
  perform pg_advisory_xact_lock(hashtextextended('integracion_equipo:' || _k.tenant_id::text, 0));

  insert into public.integracion_equipo (tenant_id) values (_k.tenant_id) on conflict (tenant_id) do nothing;
  select * into _cfg from public.integracion_equipo c where c.tenant_id = _k.tenant_id for update;
  _ensayo_final := coalesce(_ensayo, false) or not _cfg.aplicar;

  select count(*) into _bajas from jsonb_array_elements(_cambios) as x(v) where x.v ->> 'campo' = 'papelera';

  -- Las bajas al final: un cambio de jefe hacia alguien que se va en este mismo envío
  -- se valida antes de que se vaya.
  for _c in
    select x.v from jsonb_array_elements(_cambios) as x(v) order by (x.v ->> 'campo' = 'papelera')
  loop
    _motivo := null;
    _campo := _c ->> 'campo';
    _uid := null;
    _jefe := null;
    _txt := null;
    _hs := null;
    begin
      _uid := (_c ->> 'user_id')::uuid;
    exception when others then
      _motivo := 'user_id_invalido';
    end;

    if _motivo is null and (_uid is null or not exists (
         select 1 from public.tenant_members tm
           join public.profiles p on p.id = tm.user_id
           join auth.users u on u.id = p.id
          where tm.user_id = _uid and tm.tenant_id = _k.tenant_id
            and coalesce(u.raw_app_meta_data ->> 'tipo', '') <> 'creadora')) then
      _motivo := 'no_es_de_la_agencia';
    end if;
    if _motivo is null and (_uid = _yo or public.equipo_protegido(_uid)) then
      _motivo := 'protegido';
    end if;
    if _motivo is null and exists (select 1 from public.profiles p where p.id = _uid and p.deleted_at is not null) then
      _motivo := 'en_papelera';
    end if;

    if _motivo is null then
      -- El valor: texto o null (nada de números ni objetos). El horario por semana
      -- llega como texto con su JSON.
      if _c -> 'valor' is null or jsonb_typeof(_c -> 'valor') = 'null' then
        _txt := null;
      elsif jsonb_typeof(_c -> 'valor') = 'string' then
        _txt := _c ->> 'valor';
      else
        _motivo := 'valor_invalido';
      end if;
    end if;

    if _motivo is null then
      case _campo
        when 'rol' then
          if _txt is null or not exists (
               select 1 from public.roles_config rc
                where rc.tenant_id = _k.tenant_id and rc.is_active and rc.name = _txt) then
            _motivo := 'rol_desconocido';
          elsif lower(_txt) = 'admin' or exists (
               select 1 from public.role_groups rg
                where rg.role_name = _txt and rg.tenant_id = _k.tenant_id and rg.is_admin) then
            _motivo := 'rol_de_admin';
          end if;
        when 'nivel' then
          if _txt is null or _txt not in ('manager', 'supervisor', 'agente') then
            _motivo := 'nivel_no_permitido';
          end if;
        when 'equipo' then
          if _txt is not null and (char_length(_txt) not between 1 and 80) then
            _motivo := 'equipo_invalido';
          end if;
        when 'reporta_a' then
          if _txt is not null then
            begin
              _jefe := _txt::uuid;
            exception when others then
              _motivo := 'jefe_invalido';
            end;
            if _motivo is null and _jefe = _uid then
              _motivo := 'jefe_es_la_misma_persona';
            elsif _motivo is null and not exists (
                 select 1 from public.tenant_members tm
                   join public.profiles p on p.id = tm.user_id
                  where tm.user_id = _jefe and tm.tenant_id = _k.tenant_id and p.deleted_at is null) then
              _motivo := 'jefe_no_esta_en_la_agencia';
            end if;
          end if;
        when 'hora_entrada', 'hora_salida' then
          if _txt is not null and _txt !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' then
            _motivo := 'hora_invalida';
          end if;
        when 'horario_semana' then
          if _txt is not null then
            begin
              _hs := _txt::jsonb;
            exception when others then
              _motivo := 'horario_invalido';
            end;
            if _motivo is null and not public.equipo_horario_semana_valido(_hs) then
              _motivo := 'horario_invalido';
            end if;
          end if;
        when 'papelera' then
          if _bajas > _cfg.max_bajas_por_sync then
            _motivo := 'freno_de_bajas';
          end if;
        else
          _motivo := 'campo_desconocido';
      end case;
    end if;

    if _motivo is not null then
      _rechazados := _rechazados || jsonb_build_object('user_id', _c ->> 'user_id', 'campo', _campo, 'motivo', _motivo);
      continue;
    end if;

    if not _ensayo_final then
      begin
        case _campo
          when 'rol' then
            -- Una persona, un rol (como «Cambiar rol» en la app).
            if exists (select 1 from public.user_roles ur where ur.user_id = _uid) then
              delete from public.user_roles ur
               where ur.user_id = _uid
                 and ur.id <> (select x.id from public.user_roles x where x.user_id = _uid
                                order by (x.role = _txt) desc, x.role limit 1);
              update public.user_roles set role = _txt where user_id = _uid and role is distinct from _txt;
            else
              insert into public.user_roles (user_id, role) values (_uid, _txt);
            end if;
          when 'nivel' then
            update public.profiles set nivel = _txt where id = _uid;
          when 'equipo' then
            insert into public.integracion_equipo_personas (user_id, tenant_id, equipo)
            values (_uid, _k.tenant_id, _txt)
            on conflict (user_id) do update
              set equipo = excluded.equipo, tenant_id = excluded.tenant_id, actualizado_at = now();
          when 'reporta_a' then
            insert into public.integracion_equipo_personas (user_id, tenant_id, reporta_a)
            values (_uid, _k.tenant_id, _jefe)
            on conflict (user_id) do update
              set reporta_a = excluded.reporta_a, tenant_id = excluded.tenant_id, actualizado_at = now();
          when 'hora_entrada' then
            update public.profiles set hora_entrada = _txt::time where id = _uid;
          when 'hora_salida' then
            update public.profiles set hora_salida = _txt::time where id = _uid;
          when 'horario_semana' then
            delete from public.horario_semanal where user_id = _uid;
            if _hs is not null then
              insert into public.horario_semanal (user_id, dia, entrada, salida)
              select _uid, d.n, (_hs -> d.k ->> 0)::time, (_hs -> d.k ->> 1)::time
                from (values (1, 'lun'), (2, 'mar'), (3, 'mie'), (4, 'jue'), (5, 'vie'), (6, 'sab'), (0, 'dom')) as d(n, k);
            end if;
          when 'papelera' then
            -- Lo mismo que «Eliminar» en la app (admin-user-actions, delete_user): fuera
            -- de la sesión, bloqueada la entrada, marcado el perfil y anotado. El buzón
            -- de Zoho no se toca: se borra al purgar, a los 30 días.
            update public.profiles set deleted_at = now(), deleted_by = _yo where id = _uid and deleted_at is null;
            perform public.app_revoke_user_sessions(_uid);
            update auth.users set banned_until = now() + interval '876000 hours' where id = _uid;
            insert into public.cuenta_eventos (user_id, user_email, user_full_name, accion, actor_id, actor_email, detalle)
            select _uid, u.email, p.full_name, 'eliminada', _yo,
                   (select a.email from auth.users a where a.id = _yo),
                   jsonb_build_object('origen', 'backstage', 'api_key_id', _k.id)
              from auth.users u join public.profiles p on p.id = u.id
             where u.id = _uid;
        end case;
      exception when others then
        _rechazados := _rechazados || jsonb_build_object('user_id', _uid, 'campo', _campo, 'motivo', 'error_de_base',
                                                         'detalle', left(sqlerrm, 200));
        continue;
      end;
    end if;

    _aplicados := _aplicados || jsonb_build_object('user_id', _uid, 'campo', _campo);
  end loop;

  -- La bitácora: un envío igual al último (misma huella, mismo modo) y sin nada
  -- aplicado no suma fila, suma una repetición.
  _huella := md5(_resumen::text);
  _recibidas := case when jsonb_typeof(_resumen -> 'recibidas') = 'number' then (_resumen ->> 'recibidas')::integer else 0 end;
  select s.id, s.huella, s.ensayo into _ultima_id, _ultima_huella, _ultima_ensayo
    from public.integracion_equipo_syncs s
   where s.tenant_id = _k.tenant_id
   order by s.created_at desc
   limit 1;
  if _ultima_id is not null and _ultima_huella = _huella and _ultima_ensayo = _ensayo_final
     and (_ensayo_final or jsonb_array_length(_aplicados) = 0) then
    update public.integracion_equipo_syncs
       set repeticiones = repeticiones + 1, ultima_vez = now()
     where id = _ultima_id;
    _sync := _ultima_id;
  else
    insert into public.integracion_equipo_syncs
      (tenant_id, api_key_id, actor_id, ensayo, recibidas, resumen, aplicados, rechazados_base, huella)
    values
      (_k.tenant_id, _k.id, _yo, _ensayo_final, _recibidas, _resumen, _aplicados, _rechazados, _huella)
    returning id into _sync;
  end if;

  update public.integracion_equipo
     set ultima_sync = jsonb_build_object(
           'sync_id', _sync,
           'ensayo', _ensayo_final,
           'recibidas', _recibidas,
           'cambios', jsonb_array_length(_cambios),
           'aplicados', case when _ensayo_final then 0 else jsonb_array_length(_aplicados) end,
           'rechazados', jsonb_array_length(_rechazados)),
         ultima_sync_at = now()
   where tenant_id = _k.tenant_id;

  return jsonb_build_object(
    'ensayo', _ensayo_final,
    'aplicar', _cfg.aplicar,
    'sync_id', _sync,
    'aplicados', _aplicados,
    'rechazados', _rechazados
  );
end;
$_$;


ALTER FUNCTION "public"."api_equipo_aplicar"("_cambios" "jsonb", "_resumen" "jsonb", "_ensayo" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_equipo_argos"("_desde" "date", "_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k public.api_keys := public.api_equipo_llave();
  _ahora timestamptz := now();
  _r jsonb;
begin
  if _desde is null or _hasta is null or _desde > _hasta or _hasta - _desde > 92 then
    raise exception 'api_equipo_argos: el rango va de 1 a 93 días, con desde <= hasta';
  end if;

  with gente as (
    select tm.user_id, lower(u.email) as correo, p.full_name as nombre, p.deleted_at,
           public.debe_estar_en_cowork(tm.user_id)
             and not coalesce((select h.exento from public.horario_de(tm.user_id) h), false) as vigilado
      from public.tenant_members tm
      join public.profiles p on p.id = tm.user_id
      join auth.users u on u.id = tm.user_id
     where tm.tenant_id = _k.tenant_id
       and coalesce(u.raw_app_meta_data ->> 'tipo', '') <> 'creadora'
       and not public.equipo_protegido(tm.user_id)
  ),
  turnos as (
    select g.user_id, x.dia, t.inicio, t.fin, least(t.fin, _ahora) as corte
      from gente g
     cross join lateral (
       select d::date as dia from generate_series(_desde::timestamp, _hasta::timestamp, interval '1 day') as d
     ) x
     cross join lateral public.turno_del_dia(g.user_id, x.dia) t
     where t.inicio <= _ahora
       and t.inicio < coalesce(g.deleted_at, 'infinity'::timestamptz)
  ),
  dias as (
    select tu.user_id, tu.dia, tu.inicio, tu.fin, (_ahora < tu.fin) as en_curso, e.entro,
           case when e.entro and tu.corte > tu.inicio
                then round(public.argos_sin_pantalla_seg(tu.user_id, tu.inicio, tu.corte) / 60.0)::int
                else 0 end as sin_pantalla_min,
           public.argos_permitido_min(tu.user_id) as permitido_min,
           f.veces, f.minutos, f.llamados, f.reportado,
           coalesce(n.llamados, 0) as no_entro_llamados, (n.reportado_at is not null) as no_entro_reportado,
           ar.camara_apagada, ar.fuera_cuadro, ar.sin_pantalla,
           ev.faltas, ca.fotos
      from turnos tu
     cross join lateral (
       select exists (select 1 from public.cowork_tiempo_segmentos s
                       where s.user_id = tu.user_id
                         and s.started_at < tu.fin
                         and s.started_at >= tu.inicio - interval '1 day'
                         and coalesce(s.ended_at, s.last_seen_at) >= tu.inicio - interval '30 minutes') as entro
     ) e
     cross join lateral (
       select count(*)::int as veces,
              coalesce(round(sum(extract(epoch from (least(coalesce(cf.hasta, _ahora), tu.fin) - greatest(cf.desde, tu.inicio)))) / 60), 0)::int as minutos,
              coalesce(sum(cf.llamados), 0)::int as llamados,
              coalesce(bool_or(cf.reportado_at is not null), false) as reportado
         from public.cowork_fuera cf
        where cf.user_id = tu.user_id and cf.desde < tu.fin and coalesce(cf.hasta, _ahora) > tu.inicio
     ) f
      left join public.argos_no_entro n on n.user_id = tu.user_id and n.turno = tu.dia
     cross join lateral (
       select count(*) filter (where a.tipo = 'camara_apagada')::int as camara_apagada,
              count(*) filter (where a.tipo = 'fuera_cuadro')::int as fuera_cuadro,
              count(*) filter (where a.tipo = 'sin_pantalla')::int as sin_pantalla
         from public.argos_reportes a
        where a.user_id = tu.user_id and a.created_at >= tu.inicio and a.created_at < tu.fin
     ) ar
     cross join lateral (
       select count(*)::int as faltas
         from public.monitor_eventos me
        where me.user_id = tu.user_id and me.created_at >= tu.inicio and me.created_at < tu.fin
          and coalesce(me.estado, '') <> 'descartado'
     ) ev
     cross join lateral (
       select count(*)::int as fotos
         from public.monitor_capturas c
        where c.user_id = tu.user_id and c.tipo = 'pantalla' and c.created_at >= tu.inicio and c.created_at < tu.fin
     ) ca
  )
  select jsonb_build_object(
    'desde', _desde,
    'hasta', _hasta,
    'personas', coalesce(jsonb_agg(jsonb_build_object(
                  'correo', x.correo,
                  'nombre', x.nombre,
                  'vigilado', x.vigilado,
                  'expediente_url', 'https://app.maven-ai.me/hr/expediente/' || x.user_id::text,
                  'dias', x.dias) order by x.correo), '[]'::jsonb)
  ) into _r
  from (
    select ge.user_id, ge.correo, ge.nombre, ge.vigilado,
           coalesce((
             select jsonb_agg(jsonb_build_object(
                      'fecha', d.dia,
                      'turno', jsonb_build_object('inicio', d.inicio, 'fin', d.fin),
                      'en_curso', d.en_curso,
                      'entro', d.entro,
                      'sin_pantalla_min', d.sin_pantalla_min,
                      'permitido_min', d.permitido_min,
                      'fuera_de_cowork_veces', d.veces,
                      'fuera_de_cowork_min', d.minutos,
                      'llamados_fuera', d.llamados,
                      'reportado_fuera', d.reportado,
                      'no_entro_llamados', d.no_entro_llamados,
                      'no_entro_reportado', d.no_entro_reportado,
                      'reportes_en_sala', jsonb_build_object(
                        'camara_apagada', d.camara_apagada,
                        'fuera_cuadro', d.fuera_cuadro,
                        'sin_pantalla', d.sin_pantalla),
                      'faltas', d.faltas,
                      'fotos', d.fotos)
                    order by d.dia)
               from dias d where d.user_id = ge.user_id
           ), '[]'::jsonb) as dias
      from gente ge
     where ge.deleted_at is null
        or exists (select 1 from dias d where d.user_id = ge.user_id and d.entro)
  ) x;
  return _r;
end;
$$;


ALTER FUNCTION "public"."api_equipo_argos"("_desde" "date", "_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_equipo_estado"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k public.api_keys := public.api_equipo_llave();
  _cfg public.integracion_equipo;
begin
  select * into _cfg from public.integracion_equipo c where c.tenant_id = _k.tenant_id;
  return jsonb_build_object(
    'agencia', _k.tenant_id,
    'aplicar', coalesce(_cfg.aplicar, false),
    'max_bajas', coalesce(_cfg.max_bajas_por_sync, 5),
    'mapa_roles', coalesce(_cfg.mapa_roles, '{}'::jsonb),
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object(
               'nombre', rc.name,
               'es_admin', lower(rc.name) = 'admin' or coalesce(rg.is_admin, false),
               'origen', rc.origen,
               'con_permisos', exists (select 1 from public.role_permissions rp
                                        where rp.role_id = rc.id and rp.can_access))
             order by rc.name)
        from public.roles_config rc
        left join public.role_groups rg on rg.role_name = rc.name and rg.tenant_id = rc.tenant_id
       where rc.tenant_id = _k.tenant_id and rc.is_active
    ), '[]'::jsonb),
    'personas', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id,
               'correo', lower(u.email),
               'nombre', p.full_name,
               'rol', (select ur.role from public.user_roles ur
                        where ur.user_id = p.id and ur.tenant_id = _k.tenant_id
                        order by ur.role limit 1),
               'nivel', p.nivel,
               'hora_entrada', p.hora_entrada::text,
               'hora_salida', p.hora_salida::text,
               'horario_semana', public.equipo_horario_semana(p.id),
               'equipo', ip.equipo,
               'reporta_a', ip.reporta_a,
               'en_papelera', p.deleted_at is not null,
               'protegido', public.equipo_protegido(p.id))
             order by p.id)
        from public.tenant_members tm
        join public.profiles p on p.id = tm.user_id
        join auth.users u on u.id = p.id
        left join public.integracion_equipo_personas ip on ip.user_id = p.id and ip.tenant_id = _k.tenant_id
       where tm.tenant_id = _k.tenant_id
         and coalesce(u.raw_app_meta_data ->> 'tipo', '') <> 'creadora'
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."api_equipo_estado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_equipo_horas"("_desde" "date", "_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k public.api_keys := public.api_equipo_llave();
  _r jsonb;
begin
  if _desde is null or _hasta is null or _desde > _hasta or _hasta - _desde > 92 then
    raise exception 'api_equipo_horas: el rango va de 1 a 93 días, con desde <= hasta';
  end if;

  with gente as (
    select tm.user_id, lower(u.email) as correo, p.full_name as nombre, p.deleted_at
      from public.tenant_members tm
      join public.profiles p on p.id = tm.user_id
      join auth.users u on u.id = tm.user_id
     where tm.tenant_id = _k.tenant_id
       and coalesce(u.raw_app_meta_data ->> 'tipo', '') <> 'creadora'
  ),
  tramos as (
    select s.user_id, s.session_id, s.estado,
           greatest(s.started_at, d.dia_ini) as ini,
           least(coalesce(s.ended_at, s.last_seen_at), d.dia_fin) as fin,
           d.dia
      from public.cowork_tiempo_segmentos s
      join gente g on g.user_id = s.user_id
     cross join lateral (
       select x::date as dia,
              (x::date)::timestamp at time zone 'America/Bogota' as dia_ini,
              (x::date + 1)::timestamp at time zone 'America/Bogota' as dia_fin
         from generate_series(
           ((s.started_at at time zone 'America/Bogota')::date)::timestamp,
           ((coalesce(s.ended_at, s.last_seen_at) at time zone 'America/Bogota')::date)::timestamp,
           interval '1 day') as x
     ) d
     where (coalesce(s.ended_at, s.last_seen_at) at time zone 'America/Bogota')::date >= _desde
       and (s.started_at at time zone 'America/Bogota')::date <= _hasta
  ),
  sumas as (
    select t.user_id, t.dia,
           sum(case when t.estado in ('activo', 'meet', 'sin_conexion') then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_trabajo,
           sum(case when t.estado = 'meet' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_meet,
           sum(case when t.estado = 'pausa' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_pausa,
           sum(extract(epoch from (t.fin - t.ini)))::int as seg_en_sala,
           count(distinct t.session_id)::int as sesiones,
           min(t.ini) as primera_entrada,
           max(t.fin) as ultima_salida
      from tramos t
     where t.fin > t.ini and t.dia between _desde and _hasta
     group by t.user_id, t.dia
  ),
  tarde as (
    select tr.user_id, tr.dia, tr.horario_asignado, tr.tarde_min, tr.turno_nombre
      from public.tardanzas_registro tr
      join gente g on g.user_id = tr.user_id
     where tr.tenant_id = _k.tenant_id and tr.dia between _desde and _hasta
  ),
  dias as (
    select coalesce(s.user_id, t.user_id) as user_id, coalesce(s.dia, t.dia) as dia,
           s.seg_trabajo, s.seg_meet, s.seg_pausa, s.seg_en_sala, s.sesiones, s.primera_entrada, s.ultima_salida,
           t.horario_asignado, t.tarde_min, t.turno_nombre
      from sumas s
      full join tarde t on t.user_id = s.user_id and t.dia = s.dia
  )
  select jsonb_build_object(
    'desde', _desde,
    'hasta', _hasta,
    'personas', coalesce(jsonb_agg(jsonb_build_object('correo', g.correo, 'nombre', g.nombre, 'dias', g.dias) order by g.correo), '[]'::jsonb)
  ) into _r
  from (
    select ge.correo, ge.nombre,
           coalesce((
             select jsonb_agg(jsonb_build_object(
                      'fecha', d.dia,
                      'minutos_trabajados', round(coalesce(d.seg_trabajo, 0) / 60.0)::int,
                      'minutos_en_meet', round(coalesce(d.seg_meet, 0) / 60.0)::int,
                      'minutos_pausa', round(coalesce(d.seg_pausa, 0) / 60.0)::int,
                      'minutos_en_sala', round(coalesce(d.seg_en_sala, 0) / 60.0)::int,
                      'sesiones', coalesce(d.sesiones, 0),
                      'primera_entrada', d.primera_entrada,
                      'ultima_salida', d.ultima_salida,
                      'llego_tarde', coalesce(d.tarde_min, 0) > 0,
                      'minutos_tarde', coalesce(d.tarde_min, 0),
                      'hora_asignada', d.horario_asignado,
                      'turno', d.turno_nombre)
                    order by d.dia)
               from dias d where d.user_id = ge.user_id
           ), '[]'::jsonb) as dias
      from gente ge
     where ge.deleted_at is null or exists (select 1 from dias d where d.user_id = ge.user_id)
  ) g;
  return _r;
end;
$$;


ALTER FUNCTION "public"."api_equipo_horas"("_desde" "date", "_hasta" "date") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."api_keys" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "key_prefix" "text" NOT NULL,
    "key_hash" "text" NOT NULL,
    "scopes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_by" "uuid",
    "created_by_email" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_used_at" timestamp with time zone,
    "request_count" bigint DEFAULT 0 NOT NULL,
    "expires_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "revoked_by" "uuid",
    "ip_whitelist" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "last_four" "text",
    "tenant_id" "uuid" NOT NULL,
    "acts_as_user_id" "uuid" NOT NULL,
    "limite_por_hora" integer DEFAULT 1000 NOT NULL,
    "ventana_inicio" timestamp with time zone,
    "ventana_pedidos" integer DEFAULT 0 NOT NULL,
    "limite_por_minuto" integer DEFAULT 60 NOT NULL,
    "minuto_inicio" timestamp with time zone,
    "minuto_pedidos" integer DEFAULT 0 NOT NULL,
    "api_display_name" "text",
    "integracion_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    CONSTRAINT "api_keys_escritura_con_lectura" CHECK (((NOT ('messenger:write'::"text" = ANY ("scopes"))) OR ('messenger:read'::"text" = ANY ("scopes")))),
    CONSTRAINT "api_keys_escritura_con_nombre" CHECK (((NOT ('messenger:write'::"text" = ANY ("scopes"))) OR ("api_display_name" IS NOT NULL))),
    CONSTRAINT "api_keys_limite_por_hora_check" CHECK (("limite_por_hora" > 0)),
    CONSTRAINT "api_keys_limite_por_minuto_check" CHECK (("limite_por_minuto" > 0))
);


ALTER TABLE "public"."api_keys" OWNER TO "postgres";


COMMENT ON TABLE "public"."api_keys" IS 'API keys para la API pública de Maven. Gestion solo-admin. Secreto guardado como hash SHA-256.';



CREATE OR REPLACE FUNCTION "public"."api_equipo_llave"() RETURNS "public"."api_keys"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _id uuid := public.api_mvk();
  _yo uuid := auth.uid();
  _k public.api_keys;
begin
  if _id is null then
    raise exception using errcode = 'MV401',
      message = 'api_sin_llave: este pedido no viene de una key',
      detail = '{"error": "unauthorized"}';
  end if;
  select * into _k from public.api_keys k where k.id = _id;
  if not found
     or _k.revoked_at is not null
     or (_k.expires_at is not null and _k.expires_at <= now())
     or _yo is null
     or _k.acts_as_user_id is distinct from _yo then
    raise exception using errcode = 'MV401',
      message = 'api_llave_invalida: la key del pedido no existe, está revocada, venció o no es de esta persona',
      detail = '{"error": "unauthorized"}';
  end if;
  if not ('equipo:write' = any (_k.scopes)) then
    raise exception using errcode = 'MV403',
      message = 'api_llave_sin_permiso: la key no tiene equipo:write',
      detail = '{"error": "forbidden"}';
  end if;
  if _k.tenant_id is null
     or not public.api_key_persona_vigente(_yo, _k.tenant_id)
     or _k.tenant_id is distinct from public.current_tenant_id() then
    raise exception using errcode = 'MV403',
      message = 'api_persona_no_vigente: la persona de la key ya no está activa en su agencia',
      detail = '{"error": "forbidden"}';
  end if;
  if not (exists (select 1 from public.tenant_owners o where o.user_id = _yo and o.tenant_id = _k.tenant_id)
          or exists (select 1 from public.user_roles ur
                      where ur.user_id = _yo and lower(ur.role) = 'admin' and ur.tenant_id = _k.tenant_id)) then
    raise exception using errcode = 'MV403',
      message = 'api_equipo_sin_permiso: la persona de la key no es admin ni dueña de su agencia',
      detail = '{"error": "forbidden"}';
  end if;
  return _k;
end;
$$;


ALTER FUNCTION "public"."api_equipo_llave"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_equipo_notas"("_desde" "date", "_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k public.api_keys := public.api_equipo_llave();
  _ini timestamptz;
  _fin timestamptz;
  _r jsonb;
begin
  if _desde is null or _hasta is null or _desde > _hasta or _hasta - _desde > 92 then
    raise exception 'api_equipo_notas: el rango va de 1 a 93 días, con desde <= hasta';
  end if;
  _ini := _desde::timestamp at time zone 'America/Bogota';
  _fin := (_hasta + 1)::timestamp at time zone 'America/Bogota';

  with gente as (
    select tm.user_id, lower(u.email) as correo, p.full_name as nombre
      from public.tenant_members tm
      join public.profiles p on p.id = tm.user_id
      join auth.users u on u.id = tm.user_id
     where tm.tenant_id = _k.tenant_id
       and coalesce(u.raw_app_meta_data ->> 'tipo', '') <> 'creadora'
  ),
  segs as (
    select s.user_id, (s.started_at at time zone 'America/Bogota')::date as dia,
           sum(case when s.estado in ('activo', 'pausa') then coalesce(s.seconds, 0) else 0 end)::int as seg_pantalla,
           sum(coalesce(s.seconds, 0))::int as seg_conectado
      from public.cowork_tiempo_segmentos s
      join gente g on g.user_id = s.user_id
     where s.started_at >= _ini and s.started_at < _fin
     group by s.user_id, dia
  ),
  caps as (
    select c.user_id, (c.created_at at time zone 'America/Bogota')::date as dia,
           count(*) filter (where c.tipo = 'camara')::int as cap_camara,
           count(*) filter (where c.tipo = 'camara' and c.cara_visible is true)::int as cap_cara,
           count(*) filter (where c.tipo = 'pantalla')::int as cap_pantalla,
           count(*) filter (where c.fuera_de_lugar is true and c.perdonado is not true)::int as cap_distraido
      from public.monitor_capturas c
      join gente g on g.user_id = c.user_id
     where c.created_at >= _ini and c.created_at < _fin
     group by c.user_id, dia
  ),
  juntos as (
    select coalesce(s.user_id, c.user_id) as user_id, coalesce(s.dia, c.dia) as dia,
           coalesce(s.seg_pantalla, 0) as seg_pantalla, coalesce(s.seg_conectado, 0) as seg_conectado,
           coalesce(c.cap_camara, 0) as cap_camara, coalesce(c.cap_cara, 0) as cap_cara,
           coalesce(c.cap_pantalla, 0) as cap_pantalla, coalesce(c.cap_distraido, 0) as cap_distraido
      from segs s
      full join caps c on c.user_id = s.user_id and c.dia = s.dia
  ),
  notas as (
    select j.*,
           round((least(1.0, j.seg_pantalla / (8 * 3600.0)) * 45)::numeric, 1) as n_pantalla,
           case when j.cap_camara > 0 then round((j.cap_cara::numeric / j.cap_camara) * 35, 1) else 0 end as n_camara,
           case when j.cap_pantalla > 0 then round((1 - (j.cap_distraido::numeric / j.cap_pantalla)) * 20, 1) else 20 end as n_foco
      from juntos j
     where j.dia between _desde and _hasta
  )
  select jsonb_build_object(
    'desde', _desde,
    'hasta', _hasta,
    'personas', coalesce(jsonb_agg(jsonb_build_object('correo', x.correo, 'nombre', x.nombre, 'dias', x.dias) order by x.correo), '[]'::jsonb)
  ) into _r
  from (
    select g.correo, g.nombre,
           jsonb_agg(jsonb_build_object(
             'fecha', n.dia,
             'nota', least(100, greatest(0, round((n.n_pantalla + n.n_camara + n.n_foco)::numeric, 1))),
             'desglose', jsonb_build_object('pantalla', n.n_pantalla, 'camara', n.n_camara, 'foco', n.n_foco),
             'maximos', jsonb_build_object('pantalla', 45, 'camara', 35, 'foco', 20),
             'crudo', jsonb_build_object(
               'segundos_en_pantalla', n.seg_pantalla,
               'segundos_conectado', n.seg_conectado,
               'capturas_camara', n.cap_camara,
               'capturas_con_cara', n.cap_cara,
               'capturas_pantalla', n.cap_pantalla,
               'capturas_distraido', n.cap_distraido))
             order by n.dia) as dias
      from notas n
      join gente g on g.user_id = n.user_id
     group by g.correo, g.nombre
  ) x;
  return _r;
end;
$$;


ALTER FUNCTION "public"."api_equipo_notas"("_desde" "date", "_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_equipo_pendientes"("_lista" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  _k public.api_keys := public.api_equipo_llave();
  _cfg public.integracion_equipo;
  _x jsonb;
  _correo text;
  _nivel text;
  _jefe text;
  _nueva boolean;
  _registradas integer := 0;
  _actualizadas integer := 0;
  _ignoradas jsonb := '[]'::jsonb;
  _txt text;
begin
  if _lista is null or jsonb_typeof(_lista) <> 'array' or jsonb_array_length(_lista) > 1000 then
    raise exception 'api_equipo_pendientes: _lista tiene que ser una lista de hasta 1000 personas';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('integracion_equipo:' || _k.tenant_id::text, 0));
  select * into _cfg from public.integracion_equipo c where c.tenant_id = _k.tenant_id;
  if not coalesce(_cfg.aplicar, false) then
    return jsonb_build_object('ensayo', true, 'registradas', 0, 'actualizadas', 0, 'ignoradas', '[]'::jsonb);
  end if;

  for _x in select v from jsonb_array_elements(_lista) as a(v) loop
    if jsonb_typeof(_x) <> 'object' or jsonb_typeof(_x -> 'correo') is distinct from 'string' then
      _ignoradas := _ignoradas || jsonb_build_object('correo', null, 'motivo', 'correo_invalido');
      continue;
    end if;
    _correo := lower(btrim(_x ->> 'correo'));
    if char_length(_correo) > 254 or _correo !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
      _ignoradas := _ignoradas || jsonb_build_object('correo', left(_correo, 120), 'motivo', 'correo_invalido');
      continue;
    end if;
    -- Ya tiene cuenta en ESTA agencia (también las cuentas externas, que la edge no ve).
    if exists (select 1 from public.tenant_members tm join auth.users u on u.id = tm.user_id
                where tm.tenant_id = _k.tenant_id and lower(u.email) = _correo) then
      _ignoradas := _ignoradas || jsonb_build_object('correo', _correo, 'motivo', 'ya_tiene_cuenta');
      continue;
    end if;
    _nivel := case when _x ->> 'nivel' in ('manager', 'supervisor', 'agente') then _x ->> 'nivel' end;
    _jefe := lower(btrim(_x ->> 'reporta_a'));
    if _jefe is not null and (char_length(_jefe) > 254 or _jefe !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then
      _jefe := null;
    end if;

    insert into public.integracion_equipo_pendientes as p
      (tenant_id, correo, nombre, rol, nivel, equipo, reporta_a_correo)
    values (
      _k.tenant_id, _correo,
      nullif(left(btrim(_x ->> 'nombre'), 200), ''),
      nullif(left(btrim(_x ->> 'rol'), 100), ''),
      _nivel,
      nullif(left(btrim(_x ->> 'equipo'), 80), ''),
      _jefe)
    on conflict (tenant_id, correo) do update
      set veces = p.veces + 1,
          ultima_vez = now(),
          nombre = case when p.estado = 'pendiente' then excluded.nombre else p.nombre end,
          rol = case when p.estado = 'pendiente' then excluded.rol else p.rol end,
          nivel = case when p.estado = 'pendiente' then excluded.nivel else p.nivel end,
          equipo = case when p.estado = 'pendiente' then excluded.equipo else p.equipo end,
          reporta_a_correo = case when p.estado = 'pendiente' then excluded.reporta_a_correo else p.reporta_a_correo end
    returning (xmax = 0) into _nueva;
    if _nueva then _registradas := _registradas + 1; else _actualizadas := _actualizadas + 1; end if;
  end loop;

  return jsonb_build_object('ensayo', false, 'registradas', _registradas, 'actualizadas', _actualizadas, 'ignoradas', _ignoradas);
end;
$_$;


ALTER FUNCTION "public"."api_equipo_pendientes"("_lista" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_equipo_roles"("_roles" "jsonb", "_ensayo" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k public.api_keys := public.api_equipo_llave();
  _cfg public.integracion_equipo;
  _ensayo_final boolean;
  _x jsonb;
  _nombre text;
  _clave text;
  _vistos text[] := '{}';
  _rc record;
  _creados jsonb := '[]'::jsonb;
  _ya jsonb := '[]'::jsonb;
  _rechazados jsonb := '[]'::jsonb;
begin
  if _roles is null or jsonb_typeof(_roles) <> 'array' or jsonb_array_length(_roles) > 50 then
    raise exception 'api_equipo_roles: _roles tiene que ser una lista de hasta 50 roles';
  end if;

  -- Un envío a la vez por agencia (el mismo candado que api_equipo_aplicar).
  perform pg_advisory_xact_lock(hashtextextended('integracion_equipo:' || _k.tenant_id::text, 0));
  insert into public.integracion_equipo (tenant_id) values (_k.tenant_id) on conflict (tenant_id) do nothing;
  select * into _cfg from public.integracion_equipo c where c.tenant_id = _k.tenant_id;
  _ensayo_final := coalesce(_ensayo, false) or not _cfg.aplicar;

  for _x in select v from jsonb_array_elements(_roles) as a(v) loop
    _nombre := case jsonb_typeof(_x)
                 when 'string' then _x #>> '{}'
                 when 'object' then case when jsonb_typeof(_x -> 'nombre') = 'string' then _x ->> 'nombre' end
               end;
    if _nombre is not null then
      _nombre := btrim(regexp_replace(_nombre, '\s+', ' ', 'g'));
    end if;
    if _nombre is null or _nombre = '' or _nombre ~ '[[:cntrl:]]' then
      _rechazados := _rechazados || jsonb_build_object('nombre', left(coalesce(_nombre, _x::text), 120), 'motivo', 'nombre_invalido');
      continue;
    end if;
    if char_length(_nombre) > 60 then
      _rechazados := _rechazados || jsonb_build_object('nombre', left(_nombre, 120), 'motivo', 'nombre_muy_largo');
      continue;
    end if;
    _clave := public.equipo_clave(_nombre);
    -- El mismo rol dos veces en el envío («Closer» y «closer»): cuenta una sola.
    if _clave = any (_vistos) then
      continue;
    end if;
    _vistos := _vistos || _clave;

    -- Nada que Maven trate como admin: los nombres de admin y dueño, y cualquier rol
    -- que role_groups marque is_admin en esta agencia (lo que mira is_in_role_group).
    if _clave in ('admin', 'admins', 'administrador', 'administradora', 'administrator', 'superadmin', 'super admin',
                  'dueno', 'duena', 'owner', 'propietario', 'propietaria')
       or exists (select 1 from public.role_groups rg
                   where rg.tenant_id = _k.tenant_id and rg.is_admin and public.equipo_clave(rg.role_name) = _clave) then
      _rechazados := _rechazados || jsonb_build_object('nombre', _nombre, 'motivo', 'rol_de_admin');
      continue;
    end if;

    -- Ya lo resuelve el mapa de la agencia (integracion_equipo.mapa_roles).
    if exists (select 1 from jsonb_object_keys(_cfg.mapa_roles) as m(k) where public.equipo_clave(m.k) = _clave) then
      _ya := _ya || to_jsonb(_nombre);
      continue;
    end if;

    select rc.name, rc.is_active into _rc
      from public.roles_config rc
     where rc.tenant_id = _k.tenant_id and public.equipo_clave(rc.name) = _clave
     order by (rc.name = _nombre) desc, rc.is_active desc, rc.name
     limit 1;
    if found then
      if _rc.is_active then
        _ya := _ya || to_jsonb(_nombre);
      else
        -- Volver a prender un rol apagado lo decide una persona en Maven.
        _rechazados := _rechazados || jsonb_build_object('nombre', _nombre, 'motivo', 'rol_inactivo');
      end if;
      continue;
    end if;

    if not _ensayo_final then
      begin
        insert into public.roles_config (tenant_id, name, is_active, origen)
        values (_k.tenant_id, _nombre, true, 'plataforma');
      exception when others then
        _rechazados := _rechazados || jsonb_build_object('nombre', _nombre, 'motivo', 'error_de_base');
        continue;
      end;
    end if;
    _creados := _creados || to_jsonb(_nombre);
  end loop;

  return jsonb_build_object(
    'ensayo', _ensayo_final,
    'creados', _creados,
    'ya_estaban', _ya,
    'rechazados', _rechazados
  );
end;
$$;


ALTER FUNCTION "public"."api_equipo_roles"("_roles" "jsonb", "_ensayo" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_escritura_habilitada"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _pasadas jsonb;
begin
  if not coalesce((select f.enabled from public.app_flags f where f.key = 'api_messenger_escritura'), false) then
    raise exception using errcode = 'MV503',
      message = 'api_escritura_apagada: la escritura del Messenger por API está apagada',
      detail = '{"motivo": "interruptor"}';
  end if;
  if (select count(*) from public.tenants) <> 1 then
    raise exception using errcode = 'MV503',
      message = 'api_varias_agencias: con más de una agencia la escritura por API está apagada',
      detail = '{"motivo": "varias_agencias"}';
  end if;
  select jsonb_agg(jsonb_build_object('senal', p.senal, 'valor', p.valor, 'umbral', p.umbral, 'medible', p.medible))
    into _pasadas
    from public.api_presion_medida() p
   where not p.medible or p.valor is null or p.valor > p.umbral;
  if _pasadas is not null then
    raise exception using errcode = 'MV503',
      message = 'api_escritura_en_pausa: la base está bajo presión o no se puede medir',
      detail = jsonb_build_object('motivo', 'presion', 'senales', _pasadas)::text;
  end if;
end;
$$;


ALTER FUNCTION "public"."api_escritura_habilitada"() OWNER TO "postgres";


