CREATE OR REPLACE FUNCTION "public"."api_fuente_backends"() RETURNS TABLE("valor" numeric, "medible" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  return query
  select count(*) filter (where a.state = 'active')::numeric,
         count(*) > 0 and count(*) filter (where a.state is null) = 0
    from pg_stat_activity a
   where a.backend_type = 'client backend';
exception when others then
  return query select null::numeric, false;
end;
$$;


ALTER FUNCTION "public"."api_fuente_backends"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_fuente_cola"() RETURNS TABLE("valor" numeric, "medible" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  return query
  select count(*)::numeric, true
    from (select 1 from net.http_request_queue limit 201) x;
exception when others then
  return query select null::numeric, false;
end;
$$;


ALTER FUNCTION "public"."api_fuente_cola"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_fuente_slot"() RETURNS TABLE("valor" numeric, "medible" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  return query
  select max(pg_wal_lsn_diff(pg_current_wal_lsn(), s.confirmed_flush_lsn)),
         count(*) > 0 and bool_and(s.confirmed_flush_lsn is not null)
    from pg_replication_slots s
   where s.slot_type = 'logical' and s.slot_name like 'supabase\_realtime%';
exception when others then
  return query select null::numeric, false;
end;
$$;


ALTER FUNCTION "public"."api_fuente_slot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_hubstaff_daily"("_from" "date" DEFAULT NULL::"date", "_to" "date" DEFAULT NULL::"date", "_profile_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 100, "_offset" integer DEFAULT 0) RETURNS TABLE("date" "date", "hubstaff_user_id" "text", "employee" "text", "profile_id" "uuid", "tracked_seconds" integer, "tracked_hours" numeric, "overall_activity" integer, "project_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select d.date,
         d.hubstaff_user_id,
         m.name as employee,
         m.profile_id,
         d.tracked_seconds,
         round(d.tracked_seconds / 3600.0, 2) as tracked_hours,
         d.overall_activity,
         d.project_name
  from public.hubstaff_daily_data d
  left join lateral (
    select mm.name, mm.profile_id
    from public.hubstaff_members mm
    where mm.hubstaff_user_id = d.hubstaff_user_id
      and mm.hubstaff_org_id = d.hubstaff_org_id
    limit 1
  ) m on true
  where (_from is null or d.date >= _from)
    and (_to is null or d.date <= _to)
    and (_profile_id is null or m.profile_id = _profile_id)
  order by d.date desc, m.name
  limit least(greatest(_limit, 1), 500)
  offset greatest(_offset, 0)
$$;


ALTER FUNCTION "public"."api_hubstaff_daily"("_from" "date", "_to" "date", "_profile_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_idem_buscar"("_clave" "bytea", "_huella" "bytea") RETURNS TABLE("coincide" boolean, "conversation_id" "uuid", "message_id" "uuid", "conversacion_creada" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k jsonb := public.api_llave_del_pedido(true);
begin
  return query
  select i.huella_sha = _huella, i.conversation_id, i.message_id, i.conversacion_creada
    from public.api_escritura_idem i
   where i.api_key_id = (_k ->> 'id')::uuid and i.clave_sha = _clave
     and i.created_at > now() - interval '72 hours';
end;
$$;


ALTER FUNCTION "public"."api_idem_buscar"("_clave" "bytea", "_huella" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_idem_clave"("_idem" "text") RETURNS "bytea"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
begin
  if _idem is null or _idem !~ '^[!-~]{8,100}$' then
    raise exception using errcode = 'MV422',
      message = 'api_idempotencia_invalida: la Idempotency-Key va de 8 a 100 caracteres ASCII visibles, sin espacios',
      detail = '{"error": "invalid_idempotency_key"}';
  end if;
  return sha256(convert_to(_idem, 'UTF8'));
end;
$_$;


ALTER FUNCTION "public"."api_idem_clave"("_idem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_idem_guardar"("_clave" "bytea", "_huella" "bytea", "_conv" "uuid", "_msg" "uuid", "_creada" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k jsonb := public.api_llave_del_pedido(true);
begin
  insert into public.api_escritura_idem as i (api_key_id, clave_sha, huella_sha, conversation_id, message_id, conversacion_creada)
  values ((_k ->> 'id')::uuid, _clave, _huella, _conv, _msg, coalesce(_creada, false))
  on conflict (api_key_id, clave_sha) do update
     set huella_sha = excluded.huella_sha, conversation_id = excluded.conversation_id,
         message_id = excluded.message_id, conversacion_creada = excluded.conversacion_creada,
         created_at = excluded.created_at
   where i.created_at <= now() - interval '72 hours';
  if not found then
    raise exception using errcode = 'MV429',
      message = 'api_escritura_en_curso: esa Idempotency-Key ya se está usando',
      detail = '{"limite": "concurrent_write", "reintentar_en": 1}';
  end if;
end;
$$;


ALTER FUNCTION "public"."api_idem_guardar"("_clave" "bytea", "_huella" "bytea", "_conv" "uuid", "_msg" "uuid", "_creada" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_key_consumir"("_id" "uuid") RETURNS TABLE("permitido" boolean, "limite" integer, "restantes" integer, "reinicio" timestamp with time zone, "actua_como" "uuid", "usuario_activo" boolean, "limite_minuto" integer, "motivo" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  _hora   timestamptz := date_trunc('hour', now());
  _minuto timestamptz := date_trunc('minute', now());
begin
  -- ⚠️ Las ventanas SOLO avanzan. now() es el del inicio de la transacción: un
  -- pedido que arrancó a las 12:00:59,998 puede escribir DESPUÉS de uno de las
  -- 12:01:00,001. Con "=" y "set = _minuto", el viejo encontraba la ventana 12:01,
  -- la creía distinta, se colaba y la hacía volver a 12:00 con 1 (se perdía la
  -- cuenta del minuto nuevo). Con ">=" y greatest(), el viejo cuenta en la ventana
  -- más nueva y respeta su límite.
  return query
  update public.api_keys k
     set ventana_pedidos = case when k.ventana_inicio >= _hora then k.ventana_pedidos + 1 else 1 end,
         ventana_inicio  = greatest(coalesce(k.ventana_inicio, _hora), _hora),
         minuto_pedidos  = case when k.minuto_inicio >= _minuto then k.minuto_pedidos + 1 else 1 end,
         minuto_inicio   = greatest(coalesce(k.minuto_inicio, _minuto), _minuto),
         request_count   = k.request_count + 1,
         last_used_at    = now()
   where k.id = _id
     and not (coalesce(k.ventana_inicio >= _hora, false) and k.ventana_pedidos >= k.limite_por_hora)
     and not (coalesce(k.minuto_inicio >= _minuto, false) and k.minuto_pedidos >= k.limite_por_minuto)
  returning true,
            k.limite_por_hora,
            greatest(k.limite_por_hora - k.ventana_pedidos, 0),
            k.ventana_inicio + interval '1 hour',
            k.acts_as_user_id,
            public.api_key_persona_vigente(k.acts_as_user_id, k.tenant_id),
            k.limite_por_minuto,
            null::text;
  if found then
    return;
  end if;

  -- Sin cupo (o la llave no existe: cero filas). Solo lectura.
  return query
  select false,
         k.limite_por_hora,
         case when coalesce(k.ventana_inicio >= _hora, false)
              then greatest(k.limite_por_hora - k.ventana_pedidos, 0)
              else k.limite_por_hora end,
         case when coalesce(k.ventana_inicio >= _hora, false) and k.ventana_pedidos >= k.limite_por_hora
              then greatest(k.ventana_inicio, _hora) + interval '1 hour'
              else greatest(coalesce(k.minuto_inicio, _minuto), _minuto) + interval '1 minute' end,
         k.acts_as_user_id,
         public.api_key_persona_vigente(k.acts_as_user_id, k.tenant_id),
         k.limite_por_minuto,
         case when coalesce(k.ventana_inicio >= _hora, false) and k.ventana_pedidos >= k.limite_por_hora
              then 'hora' else 'minuto' end
    from public.api_keys k
   where k.id = _id;
end;
$$;


ALTER FUNCTION "public"."api_key_consumir"("_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_key_persona_vigente"("_usuario" "uuid", "_agencia" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (select 1 from public.profiles p where p.id = _usuario and p.deleted_at is null)
     and not exists (select 1 from auth.users u where u.id = _usuario and u.banned_until > now())
     and exists (select 1 from public.tenant_members tm
                  where tm.user_id = _usuario and tm.tenant_id = _agencia);
$$;


ALTER FUNCTION "public"."api_key_persona_vigente"("_usuario" "uuid", "_agencia" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_key_vigente"("_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.api_key_persona_vigente(k.acts_as_user_id, k.tenant_id)
    from public.api_keys k
   where k.id = _id;
$$;


