CREATE OR REPLACE FUNCTION "public"."api_usage_summary"("_from" timestamp with time zone, "_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH bounded AS (
    SELECT * FROM public.api_usage_log
    WHERE occurred_at >= _from AND occurred_at <= _to
  ),
  totals AS (
    SELECT provider,
           COUNT(*)::bigint AS calls,
           COALESCE(SUM(cost_usd), 0)::numeric AS cost_usd
    FROM bounded
    GROUP BY provider
  ),
  daily AS (
    SELECT (occurred_at AT TIME ZONE 'UTC')::date::text AS day,
           provider,
           COALESCE(SUM(cost_usd), 0)::numeric AS cost_usd
    FROM bounded
    GROUP BY 1, 2
    ORDER BY 1
  ),
  recent AS (
    SELECT provider, occurred_at, cost_usd, operation, model
    FROM bounded
    ORDER BY occurred_at DESC
    LIMIT 50
  )
  SELECT jsonb_build_object(
    'totals', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM totals t), '[]'::jsonb),
    'daily',  COALESCE((SELECT jsonb_agg(to_jsonb(d)) FROM daily d),  '[]'::jsonb),
    'recent', COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM recent r), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."api_usage_summary"("_from" timestamp with time zone, "_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhook_deliveries_alta"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _endpoint public.api_webhook_endpoints;
begin
  -- FOR SHARE: si en este mismo instante alguien pausa o detiene el endpoint, el
  -- timbre espera a que eso confirme y lo vuelve a leer ya parado.
  select * into _endpoint from public.api_webhook_endpoints where id = new.endpoint_id for share;
  if _endpoint.id is null then
    raise exception 'webhooks: el endpoint de la entrega no existe';
  end if;
  if new.event_type = 'messages.created' then
    if _endpoint.status is distinct from 'active' then
      raise exception 'webhooks: solo un endpoint activo recibe timbres';
    end if;
    if new.state is distinct from 'pending' then
      raise exception 'webhooks: un timbre nace pendiente';
    end if;
    if (select count(*) from public.tenants) <> 1 then
      raise exception 'webhooks: con más de una agencia no sale ningún timbre';
    end if;
  end if;
  new.tenant_id := _endpoint.tenant_id;
  new.created_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."api_webhook_deliveries_alta"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhook_deliveries_cambio"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if old.state <> 'pending' then
    raise exception 'webhooks: una entrega terminada (%) ya no cambia', old.state;
  end if;
  if new.id is distinct from old.id
     or new.endpoint_id is distinct from old.endpoint_id
     or new.tenant_id is distinct from old.tenant_id
     or new.event_type is distinct from old.event_type
     or new.body is distinct from old.body
     or new.message_count is distinct from old.message_count
     or new.created_at is distinct from old.created_at then
    raise exception 'webhooks: lo que se firmó de una entrega no cambia (cada reintento manda los mismos bytes)';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."api_webhook_deliveries_cambio"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhook_endpoints_alta"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _llave public.api_keys;
  _motivo text;
begin
  select * into _llave from public.api_keys where id = new.api_key_id;
  _motivo := public.api_webhooks_llave_no_sirve(_llave);
  if _motivo is not null then
    raise exception 'webhooks: %', _motivo;
  end if;
  -- Lo registra la misma persona cuyas conversaciones lee la llave (y la llave
  -- con Messenger, a su vez, solo la crea esa persona: api_keys_reglas_messenger).
  if new.created_by is distinct from _llave.acts_as_user_id then
    raise exception 'webhooks: el webhook lo registra la persona cuyas conversaciones lee la llave';
  end if;
  if new.status is distinct from 'pending' then
    raise exception 'webhooks: un endpoint nace esperando la prueba (pending)';
  end if;

  new.tenant_id := _llave.tenant_id;
  new.acts_as_user_id := _llave.acts_as_user_id;
  new.url_host := public.api_webhooks_host_de_url(new.url);
  new.cursor_at := null;
  new.cursor_id := null;
  new.lease_until := null;
  new.next_attempt_at := now();
  new.consecutive_failures := 0;
  new.failing_since := null;
  new.created_at := now();
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."api_webhook_endpoints_alta"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhook_endpoints_cambio"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _llave public.api_keys;
  _motivo text;
begin
  if new.id is distinct from old.id
     or new.api_key_id is distinct from old.api_key_id
     or new.tenant_id is distinct from old.tenant_id
     or new.acts_as_user_id is distinct from old.acts_as_user_id
     or new.url is distinct from old.url
     or new.url_host is distinct from old.url_host
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at then
    raise exception 'webhooks: la llave, la agencia, la persona y la URL de un endpoint no cambian; hay que crear otro';
  end if;
  -- El secreto de firma no cambia (rotarlo es borrar y crear otro, con otro
  -- secreto para el integrador). Lo único permitido es volver a cifrar el MISMO
  -- secreto con una versión nueva de WEBHOOK_SIGNING_KEK, para poder retirar la
  -- vieja: sube la versión y los últimos 4 no cambian.
  if (new.secret_cipher, new.secret_nonce, new.secret_key_version, new.secret_last4)
     is distinct from (old.secret_cipher, old.secret_nonce, old.secret_key_version, old.secret_last4)
     and not (new.secret_key_version > old.secret_key_version
              and new.secret_last4 is not distinct from old.secret_last4
              and new.secret_cipher is distinct from old.secret_cipher
              and new.secret_nonce is distinct from old.secret_nonce) then
    raise exception 'webhooks: el secreto de un endpoint no cambia (solo se vuelve a cifrar con una versión nueva de la clave); hay que crear otro';
  end if;

  -- Activar (la primera vez, o al reanudar desde pausado o detenido).
  if new.status = 'active' and old.status is distinct from 'active' then
    select * into _llave from public.api_keys where id = new.api_key_id;
    _motivo := public.api_webhooks_llave_no_sirve(_llave);
    if _motivo is not null then
      raise exception 'webhooks: no se puede activar: %', _motivo;
    end if;
    if not exists (
      select 1 from public.api_webhook_deliveries d
       where d.endpoint_id = new.id
         and d.event_type = 'webhook.test'
         and d.state = 'delivered'
         and d.delivered_at >= now() - interval '15 minutes'
         -- el mismo margen de reloj que el cursor (la edge puede anotar la hora
         -- con su reloj; mejor que mande 'now' y use el de la base)
         and d.delivered_at <= now() + interval '5 seconds') then
      raise exception 'webhooks: no se puede activar sin una prueba entregada en los últimos 15 minutos';
    end if;
    -- Arranca desde ahora: nada de lo que pasó mientras estaba parado (o mientras
    -- la persona estaba de baja) se anuncia. La edge lo pone en ahora − 10 s.
    if new.cursor_at is null
       or new.cursor_at < now() - interval '2 minutes'
       or new.cursor_at > now() + interval '5 seconds' then
      raise exception 'webhooks: al activar, el cursor tiene que arrancar desde ahora';
    end if;
    -- Y de cero: sin la espera ni la racha de fallos de antes (si no, un Resume
    -- después de receiver_failing quedaría mudo hasta 8 h y el primer error lo
    -- volvería a detener por "3 días fallando"), y sin el timbre que haya quedado
    -- pendiente de antes de parar. lease_until no se toca: si quedó una corrida
    -- viva, que su reclamo venza solo.
    new.next_attempt_at := now();
    new.consecutive_failures := 0;
    new.failing_since := null;
    update public.api_webhook_deliveries
       set state = 'dropped',
           drop_reason = case old.status when 'disabled' then 'endpoint_disabled' else 'endpoint_paused' end
     where endpoint_id = new.id and state = 'pending' and event_type = 'messages.created';

  -- Salir de activo: el timbre pendiente se descarta en el momento (no se manda
  -- parado, y al volver se arranca de cero).
  elsif old.status = 'active' and new.status is distinct from 'active' then
    update public.api_webhook_deliveries
       set state = 'dropped',
           drop_reason = case
             when new.status = 'paused' then 'endpoint_paused'
             when new.disabled_reason in ('receiver_gone', 'receiver_failing') then new.disabled_reason
             else 'endpoint_disabled' end
     where endpoint_id = new.id and state = 'pending' and event_type = 'messages.created';

  -- Sigue activo y se mueve el cursor: solo hacia adelante, y nunca al futuro. Un
  -- cursor atrás repetiría timbres (o anunciaría lo de una pausa); uno en el
  -- futuro dejaría el endpoint "activo" y mudo para siempre.
  elsif old.status = 'active' and new.status = 'active'
        and (new.cursor_at, new.cursor_id) is distinct from (old.cursor_at, old.cursor_id) then
    if (new.cursor_at, new.cursor_id) < (old.cursor_at, old.cursor_id) then
      raise exception 'webhooks: el cursor de un endpoint activo solo avanza';
    end if;
    if new.cursor_at > now() + interval '5 seconds' then
      raise exception 'webhooks: el cursor no puede quedar en el futuro';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."api_webhook_endpoints_cambio"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_con_trabajo"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select e.id
    from public.api_webhook_endpoints e
   where e.status = 'active'
     and (e.lease_until is null or e.lease_until <= now())
     and e.next_attempt_at <= now()
     and (select count(*) from public.tenants) = 1
     and (
       exists (select 1 from public.api_webhook_deliveries d
                where d.endpoint_id = e.id
                  and d.state = 'pending'
                  and d.event_type = 'messages.created')
       or exists (select 1
                    from public.chat_participants p
                    join public.chat_messages m on m.conversation_id = p.conversation_id
                   where p.user_id = e.acts_as_user_id
                     and m.created_at >= e.cursor_at
                     and m.created_at <= now() - interval '10 seconds'
                     and (not e.exclude_own or m.sender_id <> e.acts_as_user_id))
     );
$$;


ALTER FUNCTION "public"."api_webhooks_con_trabajo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_detener"("_motivo" "text", "_endpoints" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    SET "lock_timeout" TO '1s'
    AS $$
begin
  update public.api_webhook_endpoints
     set status = 'disabled', disabled_reason = _motivo, disabled_at = now(),
         paused_at = null, paused_by = null
   where id = any (_endpoints) and status <> 'disabled';
exception when others then
  raise warning 'webhooks: no se pudieron detener % endpoint(s) por % (%): %',
    cardinality(_endpoints), _motivo, sqlstate, sqlerrm;
end;
$$;


ALTER FUNCTION "public"."api_webhooks_detener"("_motivo" "text", "_endpoints" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_hay_trabajo"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if (select count(*) from public.tenants) > 1 then
    return exists (select 1 from public.api_webhook_endpoints where status <> 'disabled');
  end if;
  if not exists (select 1 from public.api_webhook_endpoints
                  where status = 'active'
                    and next_attempt_at <= now()
                    and (lease_until is null or lease_until <= now())) then
    return false;
  end if;
  return exists (select 1 from public.api_webhooks_con_trabajo());
end;
$$;


ALTER FUNCTION "public"."api_webhooks_hay_trabajo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_host_de_url"("_url" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
declare
  _autoridad text;
  _host text;
begin
  if _url is null or _url !~ '^https://' then
    raise exception 'webhooks: la URL tiene que empezar con https://';
  end if;
  if char_length(_url) > 2048 then
    raise exception 'webhooks: la URL tiene más de 2048 caracteres';
  end if;
  if _url ~ '[[:space:][:cntrl:]]' then
    raise exception 'webhooks: la URL no puede tener espacios ni caracteres de control';
  end if;
  -- El href que arma la edge (new URL(x).href) es siempre ASCII visible, sin barra
  -- invertida (la pasa a /): si llega otra cosa, no es la URL que se va a mandar.
  if _url !~ '^[!-~]+$' or position(E'\\' in _url) > 0 then
    raise exception 'webhooks: la URL tiene que llegar normalizada (solo ASCII visible, sin barra invertida)';
  end if;
  if position('#' in _url) > 0 then
    raise exception 'webhooks: la URL no puede tener fragmento (#)';
  end if;

  _autoridad := substring(_url from '^https://([^/?]*)');
  if position('@' in _autoridad) > 0 then
    raise exception 'webhooks: la URL no puede llevar usuario ni contraseña';
  end if;
  if left(_autoridad, 1) = '[' then
    raise exception 'webhooks: la URL tiene que usar un nombre, no una IP';
  end if;

  _host := _autoridad;
  if position(':' in _autoridad) > 0 then
    if _autoridad !~ '^[^:]+:443$' then
      raise exception 'webhooks: la URL solo puede usar el puerto 443';
    end if;
    _host := split_part(_autoridad, ':', 1);
  end if;

  -- Minúsculas (así la normaliza la edge), al menos dos partes, y la última
  -- empieza con una letra: eso deja afuera las IPs (1.2.3.4, 0x7f000001…), los
  -- nombres de una sola parte (localhost, intranet) y el punto final.
  if _host is distinct from lower(_host)
     or char_length(_host) > 253
     or _host !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$' then
    raise exception 'webhooks: el host de la URL no es un nombre de dominio válido';
  end if;
  return _host;
end;
$_$;


ALTER FUNCTION "public"."api_webhooks_host_de_url"("_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_llave_no_sirve"("_llave" "public"."api_keys") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when _llave.id is null then 'la llave no existe'
    when _llave.revoked_at is not null then 'la llave está revocada'
    when _llave.expires_at is null or _llave.expires_at <= now() then 'la llave está vencida o no vence'
    when not ('messenger:read' = any (_llave.scopes)) then 'la llave no tiene el permiso de Messenger'
    when coalesce(cardinality(_llave.ip_whitelist), 0) = 0 then 'la llave no tiene IPs fijas'
    when (select count(*) from public.tenants) <> 1 then 'hay más de una agencia'
    when not public.api_key_persona_vigente(_llave.acts_as_user_id, _llave.tenant_id)
      then 'la persona de la llave ya no está activa en la agencia'
  end;
$$;


ALTER FUNCTION "public"."api_webhooks_llave_no_sirve"("_llave" "public"."api_keys") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_por_agencias"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "lock_timeout" TO '1s'
    AS $$
begin
  if (select count(*) from public.tenants) <> 1 then
    perform public.api_webhooks_detener('multi_agency',
      array(select id from public.api_webhook_endpoints where status <> 'disabled'));
  end if;
  return null;
exception when others then
  raise warning 'webhooks: falló el apagado por agencias (%): %', sqlstate, sqlerrm;
  return null;
end;
$$;


ALTER FUNCTION "public"."api_webhooks_por_agencias"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_por_baja"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "lock_timeout" TO '1s'
    AS $$
begin
  perform public.api_webhooks_detener('person_inactive',
    array(select id from public.api_webhook_endpoints
           where acts_as_user_id = new.id and status <> 'disabled'));
  return null;
exception when others then
  raise warning 'webhooks: falló el apagado por baja (%): %', sqlstate, sqlerrm;
  return null;
end;
$$;


ALTER FUNCTION "public"."api_webhooks_por_baja"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_por_llave"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    SET "lock_timeout" TO '1s'
    AS $$
begin
  perform public.api_webhooks_detener(
    case when new.revoked_at is not null then 'key_revoked' else 'scope_removed' end,
    array(select id from public.api_webhook_endpoints
           where api_key_id = new.id and status <> 'disabled'));
  return null;
exception when others then
  raise warning 'webhooks: falló el apagado por llave (%): %', sqlstate, sqlerrm;
  return null;
end;
$$;


ALTER FUNCTION "public"."api_webhooks_por_llave"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."api_webhook_endpoints" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "api_key_id" "uuid" NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "acts_as_user_id" "uuid" NOT NULL,
    "url" "text" NOT NULL,
    "url_host" "text" NOT NULL,
    "exclude_own" boolean DEFAULT true NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "disabled_reason" "text",
    "disabled_at" timestamp with time zone,
    "paused_by" "uuid",
    "paused_at" timestamp with time zone,
    "secret_cipher" "text" NOT NULL,
    "secret_nonce" "text" NOT NULL,
    "secret_key_version" smallint DEFAULT 1 NOT NULL,
    "secret_last4" "text" NOT NULL,
    "cursor_at" timestamp with time zone,
    "cursor_id" "uuid",
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_until" timestamp with time zone,
    "consecutive_failures" integer DEFAULT 0 NOT NULL,
    "failing_since" timestamp with time zone,
    "last_attempt_at" timestamp with time zone,
    "last_success_at" timestamp with time zone,
    "last_status_code" integer,
    "last_error" "text",
    "last_test_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "api_webhook_endpoints_activo_con_cursor" CHECK ((("status" <> 'active'::"text") OR ("cursor_at" IS NOT NULL))),
    CONSTRAINT "api_webhook_endpoints_consecutive_failures_check" CHECK (("consecutive_failures" >= 0)),
    CONSTRAINT "api_webhook_endpoints_cursor" CHECK ((("cursor_at" IS NULL) = ("cursor_id" IS NULL))),
    CONSTRAINT "api_webhook_endpoints_detenido" CHECK (((("status" = 'disabled'::"text") = ("disabled_reason" IS NOT NULL)) AND (("status" = 'disabled'::"text") = ("disabled_at" IS NOT NULL)))),
    CONSTRAINT "api_webhook_endpoints_disabled_reason_check" CHECK (("disabled_reason" = ANY (ARRAY['receiver_gone'::"text", 'receiver_failing'::"text", 'key_revoked'::"text", 'key_expired'::"text", 'scope_removed'::"text", 'person_inactive'::"text", 'multi_agency'::"text", 'config_error'::"text", 'admin'::"text"]))),
    CONSTRAINT "api_webhook_endpoints_last_error_check" CHECK (("char_length"("last_error") <= 60)),
    CONSTRAINT "api_webhook_endpoints_last_status_code_check" CHECK ((("last_status_code" >= 100) AND ("last_status_code" <= 999))),
    CONSTRAINT "api_webhook_endpoints_pausado" CHECK (((("status" = 'paused'::"text") = ("paused_at" IS NOT NULL)) AND (("paused_by" IS NULL) OR ("paused_at" IS NOT NULL)))),
    CONSTRAINT "api_webhook_endpoints_secret_key_version_check" CHECK (("secret_key_version" >= 1)),
    CONSTRAINT "api_webhook_endpoints_secret_last4_check" CHECK (("char_length"("secret_last4") = 4)),
    CONSTRAINT "api_webhook_endpoints_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'paused'::"text", 'disabled'::"text"]))),
    CONSTRAINT "api_webhook_endpoints_url_check" CHECK ((("char_length"("url") <= 2048) AND ("url" ~ '^https://'::"text")))
);


ALTER TABLE "public"."api_webhook_endpoints" OWNER TO "postgres";


COMMENT ON TABLE "public"."api_webhook_endpoints" IS 'Webhooks del Messenger (un timbre sin contenido por llave). Ver la migración 20260926120000.';



CREATE OR REPLACE FUNCTION "public"."api_webhooks_reclamar"("_max" integer DEFAULT 5, "_lease_s" integer DEFAULT 60) RETURNS SETOF "public"."api_webhook_endpoints"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if _max is null or _max < 1 or _max > 20 then
    raise exception 'webhooks: _max va de 1 a 20 (llegó %)', _max;
  end if;
  if _lease_s is null or _lease_s < 10 or _lease_s > 300 then
    raise exception 'webhooks: _lease_s va de 10 a 300 (llegó %)', _lease_s;
  end if;

  return query
  update public.api_webhook_endpoints e
     set lease_until = now() + make_interval(secs => _lease_s)
   where e.id in (
     select x.id
       from public.api_webhook_endpoints x
      where x.status = 'active'
        and (x.lease_until is null or x.lease_until <= now())
        and x.next_attempt_at <= now()
        and x.id in (select public.api_webhooks_con_trabajo())
      order by x.next_attempt_at, x.id
      limit _max
      for no key update skip locked)
  returning e.*;
end;
$$;


ALTER FUNCTION "public"."api_webhooks_reclamar"("_max" integer, "_lease_s" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_webhooks_timbrar"("_endpoint" "uuid", "_tenant" "uuid", "_reclamo" timestamp with time zone, "_cursor_at" timestamp with time zone, "_cursor_id" "uuid", "_nuevo_at" timestamp with time zone, "_nuevo_id" "uuid", "_timbre" "uuid", "_cuerpo" "text", "_cantidad" integer, "_limpiar_error" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.api_webhook_endpoints
     set cursor_at = _nuevo_at,
         cursor_id = _nuevo_id,
         last_error = case when _limpiar_error then null else last_error end
   where id = _endpoint
     and tenant_id = _tenant
     and lease_until = _reclamo
     and status = 'active'
     and cursor_at = _cursor_at
     and cursor_id = _cursor_id;
  if not found then
    return 'perdio';
  end if;
  -- Un 23505 acá (ya había un timbre pendiente) aborta TODO, cursor incluido.
  insert into public.api_webhook_deliveries (id, endpoint_id, tenant_id, event_type, body, message_count)
  values (_timbre, _endpoint, _tenant, 'messages.created', _cuerpo, _cantidad);
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."api_webhooks_timbrar"("_endpoint" "uuid", "_tenant" "uuid", "_reclamo" timestamp with time zone, "_cursor_at" timestamp with time zone, "_cursor_id" "uuid", "_nuevo_at" timestamp with time zone, "_nuevo_id" "uuid", "_timbre" "uuid", "_cuerpo" "text", "_cantidad" integer, "_limpiar_error" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_buzon_por_borrar_contexto"("p_user_id" "uuid", "p_direccion" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select jsonb_build_object(
    -- false = la cuenta ya se purgó: no se puede recuperar.
    'perfil_existe', exists (select 1 from public.profiles p where p.id = p_user_id),
    -- null con el perfil vivo = la recuperaron.
    'deleted_at', (select p.deleted_at from public.profiles p where p.id = p_user_id),
    -- La dirección se reusó: otra cuenta entra con ella o la tiene vinculada.
    'otra_cuenta_con_esa_direccion', exists (
      select 1 from auth.users u
       where lower(u.email) = lower(btrim(p_direccion)) and u.id <> p_user_id),
    'credencial_activa_de_otra', exists (
      select 1 from public.mail_credentials c
       where lower(c.email_address) = lower(btrim(p_direccion))
         and c.user_id <> p_user_id
         and c.revoked_at is null)
  );
$$;


ALTER FUNCTION "public"."app_buzon_por_borrar_contexto"("p_user_id" "uuid", "p_direccion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_buzon_por_borrar_resultado"("p_id" "uuid", "p_estado" "text", "p_motivo" "text", "p_cuenta" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.buzones_por_borrar;
begin
  if p_estado is null or p_estado not in ('pendiente', 'borrado', 'no_se_borra', 'fallido') then
    raise exception 'estado inválido: %', p_estado;
  end if;

  update public.buzones_por_borrar
     set estado = p_estado,
         motivo = p_motivo,
         intentos = intentos + case when p_cuenta then 1 else 0 end,
         ultimo_intento_el = now(),
         resuelto_el = case when p_estado = 'pendiente' then null else now() end
   where id = p_id
  returning * into v;

  if not found then
    raise exception 'no existe la fila % de buzones_por_borrar', p_id;
  end if;

  if v.evento_id is not null then
    update public.cuenta_eventos
       set detalle = coalesce(detalle, '{}'::jsonb) || jsonb_build_object(
             'casilla_zoho', v.direccion,
             'casilla_zoho_estado', p_estado,
             'casilla_zoho_liberada', case when p_estado = 'borrado' then v.direccion end,
             'casilla_zoho_motivo', p_motivo,
             'casilla_zoho_intentos', v.intentos,
             'casilla_zoho_actualizado_el', now())
     where id = v.evento_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."app_buzon_por_borrar_resultado"("p_id" "uuid", "p_estado" "text", "p_motivo" "text", "p_cuenta" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_casilla_de_la_cuenta"("p_user_id" "uuid", "p_dominio" "text" DEFAULT 'maven-ai.me'::"text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
  select coalesce(
    (select c.email_address
       from public.mail_credentials c
       left join public.profiles p on p.id = c.user_id
      where c.user_id = p_user_id
        and (c.revoked_at is null
             or (p.deleted_at is not null and c.revoked_at >= p.deleted_at - interval '10 minutes'))
      order by (c.revoked_at is null) desc, c.revoked_at desc, c.created_at desc
      limit 1),
    (select u.email
       from auth.users u
      where u.id = p_user_id
        and nullif(btrim(p_dominio), '') is not null
        and lower(split_part(u.email, '@', 2)) = lower(btrim(p_dominio)))
  );
$$;


ALTER FUNCTION "public"."app_casilla_de_la_cuenta"("p_user_id" "uuid", "p_dominio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_encolar_buzon"("p_user_id" "uuid", "p_direccion" "text", "p_eliminada_el" timestamp with time zone, "p_dias" integer, "p_origen" "text", "p_evento_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dir text := nullif(btrim(p_direccion), '');
  v_id uuid;
begin
  if v_dir is null then
    return null;
  end if;
  if p_dias is null or p_dias < 1 then
    raise exception 'p_dias tiene que ser al menos 1 (llegó %)', p_dias;
  end if;
  if p_eliminada_el is null then
    raise exception 'falta la fecha de baja de %', p_user_id;
  end if;

  insert into public.buzones_por_borrar as b
    (user_id, direccion, eliminada_el, borrar_desde, origen, evento_id)
  values
    (p_user_id, v_dir, p_eliminada_el, p_eliminada_el + make_interval(days => p_dias), p_origen, p_evento_id)
  on conflict (user_id, direccion) do update
    set eliminada_el = excluded.eliminada_el,
        borrar_desde = excluded.borrar_desde,
        origen = excluded.origen,
        evento_id = excluded.evento_id,
        estado = 'pendiente',
        motivo = null,
        intentos = 0,
        ultimo_intento_el = null,
        resuelto_el = null
    where b.estado <> 'borrado'
  returning b.id into v_id;

  if v_id is null then
    -- Ya estaba borrado: se devuelve esa fila, que la edge no vuelve a procesar.
    select b.id into v_id from public.buzones_por_borrar b
     where b.user_id = p_user_id and b.direccion = v_dir;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."app_encolar_buzon"("p_user_id" "uuid", "p_direccion" "text", "p_eliminada_el" timestamp with time zone, "p_dias" integer, "p_origen" "text", "p_evento_id" "uuid") OWNER TO "postgres";


