    "msg_type" "text" DEFAULT 'message'::"text" NOT NULL,
    "content" "text",
    "price" numeric,
    "images" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "deleted" "text",
    "from_examiner" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "purchased" boolean DEFAULT false NOT NULL,
    "reactions" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "edited_at" timestamp with time zone,
    "content_history" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "examiner_user_id" "uuid",
    "reply_to_id" "uuid",
    CONSTRAINT "chatter_messages_deleted_check" CHECK ((("deleted" = ANY (ARRAY['chatter'::"text", 'full'::"text"])) OR ("deleted" IS NULL))),
    CONSTRAINT "chatter_messages_msg_type_check" CHECK (("msg_type" = ANY (ARRAY['message'::"text", 'tip'::"text", 'purchase'::"text", 'notice'::"text"]))),
    CONSTRAINT "chatter_messages_role_check" CHECK (("role" = ANY (ARRAY['fan'::"text", 'chatter'::"text", 'system'::"text"])))
);

ALTER TABLE ONLY "public"."chatter_messages" REPLICA IDENTITY FULL;


ALTER TABLE "public"."chatter_messages" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_get_chatter_messages"("p_session_id" "text") RETURNS SETOF "public"."chatter_messages"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_session_examiner uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT examiner_user_id INTO v_session_examiner
  FROM public.chatter_sessions
  WHERE id = p_session_id;

  IF v_session_examiner IS NULL THEN
    RETURN;
  END IF;

  IF v_user_id = v_session_examiner
     OR public.has_chatter_global_scope(v_user_id) THEN
    RETURN QUERY
      SELECT *
      FROM public.chatter_messages
      WHERE session_id = p_session_id
      ORDER BY created_at ASC;
  END IF;
END;
$$;


ALTER FUNCTION "public"."app_get_chatter_messages"("p_session_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."app_get_chatter_messages"("p_session_id" "text") IS 'Devuelve los mensajes de una sesión de chatter-evaluator. Usa SECURITY DEFINER para evitar la policy compleja sobre chatter_messages (que rompe Realtime). Caller debe ser el examiner de la sesión O tener global scope (admin/manager).';



CREATE OR REPLACE FUNCTION "public"."app_purgar_cuentas_vencidas"("p_dias" integer DEFAULT 30, "p_tope" integer DEFAULT 50) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  r record;
  v_purgadas int := 0;
  v_casilla text;
  v_evento uuid;
begin
  if p_dias < 1 then
    raise exception 'p_dias tiene que ser al menos 1 (llegó %)', p_dias;
  end if;

  for r in
    select p.id, p.full_name, p.deleted_at, u.email
    from public.profiles p
    left join auth.users u on u.id = p.id
    where p.deleted_at is not null
      and p.deleted_at < now() - make_interval(days => p_dias)
    order by p.deleted_at
    limit p_tope
  loop
    -- El buzón, mientras mail_credentials todavía existe.
    v_casilla := public.app_casilla_de_la_cuenta(r.id);
    v_evento := gen_random_uuid();

    -- La constancia va ANTES de destruir: después no queda de dónde copiar el
    -- nombre ni el correo. actor_id NULL = lo hizo el cron, no una persona. La
    -- edge completa casilla_zoho_* cuando procesa la cola.
    insert into public.cuenta_eventos
      (id, user_id, user_email, user_full_name, accion, actor_id, actor_email, detalle)
    values
      (v_evento, r.id, r.email, r.full_name, 'purgada', null, 'cron',
       jsonb_build_object(
         'eliminada_el', r.deleted_at,
         'dias_de_papelera', p_dias,
         'casilla_zoho', v_casilla,
         'casilla_zoho_liberada', null,
         'casilla_zoho_estado', case when v_casilla is not null then 'pendiente' end,
         'casilla_zoho_motivo', case
           when v_casilla is null then 'la cuenta no tenía casilla de correo de Maven'
           else 'en cola: la borra la edge buzones-por-borrar'
         end));

    if v_casilla is not null then
      perform public.app_encolar_buzon(r.id, v_casilla, r.deleted_at, p_dias, 'purga_automatica', v_evento);
    end if;

    perform public.app_purge_user_refs(r.id);
    perform public.app_force_delete_auth_user(r.id);

    v_purgadas := v_purgadas + 1;
  end loop;

  return v_purgadas;
end;
$$;


ALTER FUNCTION "public"."app_purgar_cuentas_vencidas"("p_dias" integer, "p_tope" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_purgar_entregas_webhooks"("p_dias" integer DEFAULT 14, "p_tope" integer DEFAULT 10000) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _n integer;
begin
  if p_dias is null or p_dias < 1 then
    raise exception 'p_dias tiene que ser al menos 1 (llegó %)', p_dias;
  end if;
  if p_tope is null or p_tope < 1 then
    raise exception 'p_tope tiene que ser positivo (llegó %)', p_tope;
  end if;
  -- Un TIMBRE pendiente es trabajo vivo, no historia: no se borra por viejo. Una
  -- PRUEBA pendiente sí: no se reintenta, así que si quedó pendiente es porque la
  -- edge se cortó a mitad del envío.
  delete from public.api_webhook_deliveries
   where id in (
     select id from public.api_webhook_deliveries
      where created_at < now() - make_interval(days => p_dias)
        and (state <> 'pending' or event_type = 'webhook.test')
      order by created_at
      limit p_tope);
  get diagnostics _n = row_count;
  return _n;
end;
$$;


ALTER FUNCTION "public"."app_purgar_entregas_webhooks"("p_dias" integer, "p_tope" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_purgar_historial_cron"("p_dias" integer DEFAULT 7, "p_lote" integer DEFAULT 5000, "p_tope" integer DEFAULT 150000) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'cron', 'pg_temp'
    AS $$
declare
  v_limite timestamptz := now() - make_interval(days => p_dias);
  v_lo bigint;
  v_hi bigint;
  v_medio bigint;
  v_runid bigint;
  v_inicio timestamptz;
  v_corte bigint;
  v_desde bigint;
  v_ancho int;
  v_n int;
  v_borradas int := 0;
begin
  if p_dias < 1 then
    raise exception 'p_dias tiene que ser al menos 1 (llegó %)', p_dias;
  end if;
  if p_lote < 1 or p_tope < 1 then
    raise exception 'p_lote y p_tope tienen que ser positivos (llegaron % y %)', p_lote, p_tope;
  end if;

  -- runid sale de una secuencia, así que crece con el tiempo: la última
  -- corrida vieja marca el corte y todo lo de runid menor también es viejo.
  --
  -- El corte se busca por bisección sobre la llave primaria (unas 20
  -- lecturas de índice) porque la tabla no tiene índice por fecha y no es
  -- nuestra (es de supabase_admin): buscarlo con un WHERE start_time leería
  -- el archivo entero, y el archivo NO se achica al borrar, así que serían
  -- 439 MB cada noche aunque queden solo 7 días de filas.
  select min(runid), max(runid) into v_lo, v_hi from cron.job_run_details;
  if v_lo is null then
    return 0;
  end if;
  v_desde := v_lo;

  while v_lo <= v_hi loop
    v_medio := v_lo + (v_hi - v_lo) / 2;
    select runid, start_time into v_runid, v_inicio
    from cron.job_run_details
    where runid >= v_medio
    order by runid
    limit 1;
    -- Un start_time nulo cuenta como reciente: ante la duda, no se borra.
    if v_inicio < v_limite then
      v_corte := v_runid;
      v_lo := v_runid + 1;
    else
      v_hi := v_medio - 1;
    end if;
  end loop;

  if v_corte is null then
    return 0;
  end if;

  while v_desde <= v_corte and v_borradas < p_tope loop
    -- Un rango de runid nunca tiene más filas que su ancho: achicarlo al
    -- final asegura que no se pase del tope.
    v_ancho := least(p_lote, p_tope - v_borradas);
    delete from cron.job_run_details
    where runid >= v_desde
      and runid < v_desde + v_ancho
      and runid <= v_corte;
    get diagnostics v_n = row_count;
    v_borradas := v_borradas + v_n;
    v_desde := v_desde + v_ancho;
  end loop;

  return v_borradas;
end;
$$;


ALTER FUNCTION "public"."app_purgar_historial_cron"("p_dias" integer, "p_lote" integer, "p_tope" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_purge_user_refs"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  r record;
  v_sql text;
BEGIN
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl, a.attname AS col, a.attnotnull AS not_null
    FROM pg_constraint c
    JOIN unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord) ON true
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
    WHERE c.confrelid = 'auth.users'::regclass AND c.connamespace = 'public'::regnamespace
  LOOP
    IF r.not_null THEN v_sql := format('DELETE FROM %s WHERE %I = $1', r.tbl, r.col);
    ELSE v_sql := format('UPDATE %s SET %I = NULL WHERE %I = $1', r.tbl, r.col, r.col); END IF;
    EXECUTE v_sql USING p_user_id;
  END LOOP;
  DELETE FROM public.profiles WHERE id = p_user_id;
END; $_$;


ALTER FUNCTION "public"."app_purge_user_refs"("p_user_id" "uuid") OWNER TO "postgres";


