CREATE OR REPLACE FUNCTION "public"."argos_horario_persona"("_user" "uuid", "_entrada" time without time zone, "_salida" time without time zone, "_comida" integer, "_bano" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.es_admin_o_dueno((select auth.uid())) then
    raise exception 'sin permiso para cambiar horarios';
  end if;
  update public.profiles set
    hora_entrada = _entrada,
    hora_salida  = _salida,
    comida_min   = _comida,
    bano_min     = _bano
  where id = _user;
end;
$$;


ALTER FUNCTION "public"."argos_horario_persona"("_user" "uuid", "_entrada" time without time zone, "_salida" time without time zone, "_comida" integer, "_bano" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_horario_rol"("_role" "text", "_entrada" time without time zone, "_salida" time without time zone, "_comida" integer, "_bano" integer, "_tolerancia" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.es_admin_o_dueno((select auth.uid())) then
    raise exception 'sin permiso para cambiar horarios';
  end if;
  update public.roles_config set
    hora_entrada   = _entrada,
    hora_salida    = _salida,
    comida_min     = greatest(0, coalesce(_comida, 30)),
    bano_min       = greatest(0, coalesce(_bano, 10)),
    tolerancia_min = greatest(0, coalesce(_tolerancia, 5))
  where name = _role and tenant_id = (select public.current_tenant_id());
end;
$$;


ALTER FUNCTION "public"."argos_horario_rol"("_role" "text", "_entrada" time without time zone, "_salida" time without time zone, "_comida" integer, "_bano" integer, "_tolerancia" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_horas_dia"("_dia" "date") RETURNS TABLE("hora" integer, "pantalla" integer, "camara" integer, "atencion" integer, "personas" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with cap as (
    select extract(hour from (c.created_at at time zone 'America/Bogota'))::int as hora,
           c.user_id,
           floor(extract(epoch from c.created_at)/120)::bigint as bkt,
           c.tipo, c.veredicto, c.fuera_de_lugar, c.cara_visible
    from public.monitor_capturas c
    where c.created_at >= ((_dia)::timestamp at time zone 'America/Bogota')
      and c.created_at < ((_dia + 1)::timestamp at time zone 'America/Bogota')
      and public.es_dueno((select auth.uid()))
  ),
  pp as (
    select hora, user_id,
      count(distinct bkt) filter (where tipo='camara')  as mom_cam,
      count(distinct bkt) filter (where tipo='pantalla') as mom_pan,
      count(distinct bkt) filter (where tipo='camara' and cara_visible is true)      as cara_ok,
      count(distinct bkt) filter (where tipo='camara' and cara_visible is not null)  as cara_med,
      count(*) filter (where tipo='pantalla' and veredicto is not null)              as juzg,
      count(*) filter (where tipo='pantalla' and veredicto is not null and fuera_de_lugar is not true) as juzg_ok
    from cap group by hora, user_id
  )
  select hora,
    round(avg(case when mom_cam  > 0 then least(1.0, mom_pan::numeric / mom_cam) end) * 100)::int as pantalla,
    round(avg(case when cara_med > 0 then cara_ok::numeric / cara_med end)            * 100)::int as camara,
    round(avg(case when juzg     > 0 then juzg_ok::numeric / juzg end)                * 100)::int as atencion,
    count(distinct user_id)::int as personas
  from pp group by hora order by hora
$$;


ALTER FUNCTION "public"."argos_horas_dia"("_dia" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_jornada_cruda"("_uid" "uuid", "_desde" "date", "_hasta" "date", "_con_equipo" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_viewer uuid := (select auth.uid());
  v_ini timestamptz;
  v_fin timestamptz;
  v_equipo text;
  v_nivel text;
  v_res jsonb;
begin
  if v_viewer is null then
    raise exception 'Sin sesión' using errcode = '42501';
  end if;
  if _uid is null or _desde is null or _hasta is null or _hasta < _desde or _hasta - _desde > 31 then
    raise exception 'Rango de días inválido' using errcode = '22023';
  end if;
  if not public.puede_vigilar_a(v_viewer, _uid) then
    raise exception 'No puedes ver a esta persona' using errcode = '42501';
  end if;

  v_ini := (_desde::timestamp) at time zone 'America/Bogota';
  v_fin := ((_hasta + 2)::timestamp) at time zone 'America/Bogota';
  v_equipo := public.equipo_de(_uid);
  select coalesce(p.nivel, 'agente') into v_nivel from public.profiles p where p.id = _uid;

  with gente as (
    select p.id, p.full_name, p.avatar_url, p.avatar_seed, (p.id = _uid) as objetivo
      from public.profiles p
     where p.deleted_at is null
       and (
         p.id = _uid
         or (
           _con_equipo
           and p.id <> v_viewer
           and coalesce(p.nivel, 'agente') = v_nivel
           and public.equipo_de(p.id) = v_equipo
           and public.puede_vigilar_a(v_viewer, p.id)
         )
       )
  )
  select jsonb_build_object(
    'ahora', now(),
    'equipo', v_equipo,
    'limites', coalesce((
      select jsonb_object_agg(l.kind, l.minutos * 60)
        from public.cowork_break_limits l
       where l.tenant_id = public.current_tenant_id()
    ), '{}'::jsonb),
    'personas', coalesce(jsonb_agg(jsonb_build_object(
      'id', g.id,
      'nombre', g.full_name,
      'avatar_url', g.avatar_url,
      'avatar_seed', g.avatar_seed,
      'objetivo', g.objetivo,
      'entrada', h.entrada,
      'salida', h.salida,
      'exento', coalesce(h.exento, false),
      'segmentos', coalesce((
        select jsonb_agg(jsonb_build_array(s.estado, s.started_at, coalesce(s.ended_at, s.last_seen_at)) order by s.started_at)
          from public.cowork_tiempo_segmentos s
         where s.user_id = g.id
           and s.started_at < v_fin
           and coalesce(s.ended_at, s.last_seen_at) > v_ini
           and coalesce(s.ended_at, s.last_seen_at) > s.started_at
      ), '[]'::jsonb),
      'pausas', coalesce((
        select jsonb_agg(jsonb_build_array(b.kind, b.started_at, b.ended_at) order by b.started_at)
          from public.cowork_breaks b
         where b.user_id = g.id
           and b.started_at < v_fin
           and coalesce(b.ended_at, now()) > v_ini
      ), '[]'::jsonb),
      'fuera', coalesce((
        select jsonb_agg(jsonb_build_array(f.desde, f.hasta) order by f.desde)
          from public.cowork_fuera f
         where f.user_id = g.id
           and f.desde < v_fin
           and coalesce(f.hasta, now()) > v_ini
      ), '[]'::jsonb),
      'flojas', coalesce((
        select jsonb_agg(jsonb_build_array(
                 x.created_at,
                 least(coalesce(x.siguiente, x.created_at + interval '5 minutes'), x.created_at + interval '5 minutes')
               ) order by x.created_at)
          from (
            select c.created_at, c.fuera_de_lugar, coalesce(c.perdonado, false) as perdonado,
                   lead(c.created_at) over (order by c.created_at) as siguiente
              from public.monitor_capturas c
             where c.user_id = g.id
               and c.tipo = 'pantalla'
               and c.veredicto is not null
               and c.created_at >= v_ini
               and c.created_at < v_fin
          ) x
         where x.fuera_de_lugar is true and not x.perdonado
      ), '[]'::jsonb),
      'alertas', coalesce((
        select jsonb_agg(jsonb_build_array(a.tipo, a.abierta_at, coalesce(a.cerrada_at, a.actualizada_at)) order by a.abierta_at)
          from public.argos_alertas a
         where a.user_id = g.id
           and a.tipo in ('distraido', 'celular', 'no_mira')
           and a.abierta_at < v_fin
           and coalesce(a.cerrada_at, now()) > v_ini
      ), '[]'::jsonb)
    ) order by g.objetivo desc, g.full_name), '[]'::jsonb)
  ) into v_res
  from gente g
  left join lateral (select * from public.horario_de(g.id)) h on true;

  return v_res;
end;
$$;


ALTER FUNCTION "public"."argos_jornada_cruda"("_uid" "uuid", "_desde" "date", "_hasta" "date", "_con_equipo" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."argos_jornada_cruda"("_uid" "uuid", "_desde" "date", "_hasta" "date", "_con_equipo" boolean) IS 'Argos minuto a minuto: lo crudo del turno de una persona (y, si se pide, de su equipo) entre dos días de Bogotá: horario, tramos del reloj de Cowork, pausas, salidas de Cowork, pantallazos fuera de lugar no perdonados y alertas de distracción. La cuenta la hace lib/argosJornada.ts. Solo a quien puede_vigilar_a deja.';



CREATE OR REPLACE FUNCTION "public"."argos_llamadas_hoy"() RETURNS TABLE("user_id" "uuid", "nombre" "text", "equipo" "text", "cortes" integer, "graves" integer, "ultimo_corte" timestamp with time zone, "horas" integer[], "causa" "text", "causa_texto" "text", "causa_estimada" "text", "consejo" "text", "subida_estimada_kbps" integer, "rtt_ms" integer, "perdida_pct" numeric, "nav" "text", "nucleos" integer, "prueba_subida_mbps" numeric, "prueba_bajada_mbps" numeric, "prueba_ms" integer, "prueba_subida_tope" boolean, "prueba_at" timestamp with time zone, "nc" "text", "nc_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_desde timestamptz := ((now() at time zone 'America/Bogota')::date)::timestamp at time zone 'America/Bogota';
begin
  if not coalesce(public.ve_argos(), false) then
    raise exception 'argos_llamadas_hoy: sin permiso para ver las llamadas del equipo' using errcode = '42501';
  end if;

  return query
  with vis as (
    select v.user_id as uid from public.argos_vigilables() v
  ),
  c as (
    select lc.user_id as uid, lc.fase, lc.creado
      from public.llamada_cortes lc
     where lc.creado >= v_desde
       and lc.fase in ('parpadeo_ok', 'caida', 'reentrada_agotada', 'recarga')
       and (lc.user_id = (select auth.uid()) or lc.user_id in (select vis.uid from vis))
  ),
  pp as (
    select c.uid,
           count(*)::int as n_cortes,
           (count(*) filter (where c.fase in ('caida', 'reentrada_agotada', 'recarga')))::int as n_graves,
           max(c.creado) as ultimo
      from c
     group by c.uid
  ),
  ph as (
    select c.uid, extract(hour from c.creado at time zone 'America/Bogota')::int as h, count(*)::int as n
      from c
     group by c.uid, extract(hour from c.creado at time zone 'America/Bogota')::int
  ),
  base as (
    select pp.uid, pp.n_cortes, pp.n_graves, pp.ultimo,
           pr.full_name as nombre_p,
           public.equipo_de(pp.uid) as equipo_p,
           array(
             select coalesce(ph.n, 0)
               from generate_series(0, 23) as g(h)
               left join ph on ph.uid = pp.uid and ph.h = g.h
              order by g.h
           ) as horas_p,
           d.causa as causa_d, d.recargas as recargas_d,
           d.pct_computador, d.pct_inestable, d.pct_dormida,
           d.subida_kbps as kbps_d, d.rtt_ms as rtt_d, d.perdida_pct as perdida_d,
           d.nav as nav_d, d.nucleos as nucleos_d,
           lim.pct_limitada,
           pru.p as prueba, pru.creado as prueba_creado,
           public.llamada_num(pru.p, 'subida_mbps') as sub_mbps,
           public.llamada_num(pru.p, 'bajada_mbps') as baj_mbps,
           ncs.estado as nc_estado, ncs.creado as nc_creado
      from pp
      join public.profiles pr on pr.id = pp.uid and pr.deleted_at is null
      cross join lateral public.diagnostico_de_llamada(pp.uid, v_desde) d
      -- Qué parte del día el codificador estuvo de verdad limitado por ancho de
      -- banda (señal del navegador, no estimación).
      left join lateral (
        select case when count(*) > 0 then
                 round(100.0 * count(*) filter (where s.datos->>'limite_cam' = 'bandwidth' or s.datos->>'limite_pant' = 'bandwidth') / count(*))::int
               end as pct_limitada
          from public.llamada_salud s
         where s.user_id = pp.uid and s.creado >= v_desde
      ) lim on true
      -- La última prueba de velocidad real del día.
      left join lateral (
        select s.datos->'prueba' as p, s.creado
          from public.llamada_salud s
         where s.user_id = pp.uid and s.creado >= v_desde
           and jsonb_typeof(s.datos->'prueba') = 'object'
         order by s.creado desc
         limit 1
      ) pru on true
      -- Si la cancelación de ruido estaba corriendo en la última muestra que lo dice.
      left join lateral (
        select s.datos->>'nc' as estado, s.creado
          from public.llamada_salud s
         where s.user_id = pp.uid and s.creado >= v_desde
           and jsonb_typeof(s.datos->'nc') = 'string'
         order by s.creado desc
         limit 1
      ) ncs on true
  ),
  conc as (
    select b.*,
      case
        when b.causa_d = 'internet_subida' and b.sub_mbps >= 1.5 and coalesce(b.pct_limitada, 0) < 25 then
          case
            when greatest(b.pct_computador, b.pct_inestable, b.pct_dormida) < 25 then
              case when b.recargas_d >= 2 then 'recargas' else 'sin_causa_clara' end
            when b.pct_computador = greatest(b.pct_computador, b.pct_inestable, b.pct_dormida) then 'computador'
            when b.pct_inestable = greatest(b.pct_computador, b.pct_inestable, b.pct_dormida) then 'internet_inestable'
            else 'pestana_dormida'
          end
        when b.causa_d in ('sin_causa_clara', 'sin_datos') and b.sub_mbps < 1.5 then 'internet_subida'
        else b.causa_d
      end as causa_final
      from base b
  )
  select conc.uid,
         conc.nombre_p,
         conc.equipo_p,
         conc.n_cortes,
         conc.n_graves,
         conc.ultimo,
         conc.horas_p,
         conc.causa_final,
         public.causa_de_llamada_corta(conc.causa_final),
         conc.causa_d,
         public.consejo_de_llamada(conc.causa_final, round(conc.sub_mbps * 1000)::int, conc.rtt_d, conc.perdida_d),
         conc.kbps_d,
         conc.rtt_d,
         conc.perdida_d,
         conc.nav_d,
         conc.nucleos_d,
         conc.sub_mbps,
         conc.baj_mbps,
         public.llamada_num(conc.prueba, 'ms')::int,
         coalesce(conc.prueba->>'subida_tope' = 'true', false),
         conc.prueba_creado,
         conc.nc_estado,
         conc.nc_creado
    from conc
   order by conc.n_cortes desc, conc.n_graves desc, conc.ultimo desc;
end;
$$;


ALTER FUNCTION "public"."argos_llamadas_hoy"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."argos_llamadas_hoy"() IS 'Argos › Llamadas: cortes de hoy (día de Bogotá) por persona que el que mira puede vigilar, con causa, consejo, prueba de velocidad real y estado de la cancelación de ruido. Solo lee.';



CREATE OR REPLACE FUNCTION "public"."argos_momentos_dia"("_dia" "date") RETURNS TABLE("user_id" "uuid", "mom_camara" bigint, "mom_pantalla" bigint, "faltas_camara" bigint, "juzgadas" bigint, "juzgadas_ok" bigint, "mom_cara_ok" bigint, "mom_cara_medida" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with cap as (
    select c.user_id,
           floor(extract(epoch from c.created_at)/120)::bigint as bkt,
           c.tipo, c.veredicto, c.fuera_de_lugar, c.cara_visible
    from public.monitor_capturas c
    where c.created_at >= ((_dia)::timestamp at time zone 'America/Bogota')
      and c.created_at < ((_dia + 1)::timestamp at time zone 'America/Bogota')
      and (public.es_dueno((select auth.uid())) or c.user_id = (select auth.uid()))
  ),
  fal as (
    select e.user_id, count(*)::bigint fc
    from public.monitor_eventos e
    where e.tipo in ('camara_apagada','camara_tapada','se_fue')
      and e.estado <> 'descartado'
      and e.created_at >= ((_dia)::timestamp at time zone 'America/Bogota')
      and e.created_at < ((_dia + 1)::timestamp at time zone 'America/Bogota')
    group by e.user_id
  )
  select cap.user_id,
    count(distinct bkt) filter (where cap.tipo='camara')::bigint,                 -- momentos con cámara
    count(distinct bkt) filter (where cap.tipo='pantalla')::bigint,               -- momentos compartiendo pantalla
    coalesce(max(fal.fc), 0)::bigint,
    count(*) filter (where cap.tipo='pantalla' and cap.veredicto is not null)::bigint,
    count(*) filter (where cap.tipo='pantalla' and cap.veredicto is not null and cap.fuera_de_lugar is not true)::bigint,
    count(distinct bkt) filter (where cap.tipo='camara' and cap.cara_visible is true)::bigint,       -- momentos con CARA visible
    count(distinct bkt) filter (where cap.tipo='camara' and cap.cara_visible is not null)::bigint    -- momentos de cámara MEDIDOS
  from cap left join fal on fal.user_id = cap.user_id
  group by cap.user_id
$$;


ALTER FUNCTION "public"."argos_momentos_dia"("_dia" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_momentos_turno"("_dia" "date", "_h_desde" integer, "_h_hasta" integer) RETURNS TABLE("user_id" "uuid", "mom_camara" bigint, "mom_pantalla" bigint, "faltas_camara" bigint, "juzgadas" bigint, "juzgadas_ok" bigint, "mom_cara_ok" bigint, "mom_cara_medida" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with cap as (
    select c.user_id,
           floor(extract(epoch from c.created_at)/120)::bigint as bkt,
           c.tipo, c.veredicto, c.fuera_de_lugar, c.cara_visible
    from public.monitor_capturas c
    where c.created_at >= ((_dia)::timestamp at time zone 'America/Bogota')
      and c.created_at < ((_dia + 1)::timestamp at time zone 'America/Bogota')
      and extract(hour from (c.created_at at time zone 'America/Bogota'))::int >= _h_desde
      and extract(hour from (c.created_at at time zone 'America/Bogota'))::int < _h_hasta
      and (public.es_dueno((select auth.uid())) or c.user_id = (select auth.uid()))
  ),
  fal as (
    select e.user_id, count(*)::bigint fc
    from public.monitor_eventos e
    where e.tipo in ('camara_apagada','camara_tapada','se_fue')
      and e.estado <> 'descartado'
      and e.created_at >= ((_dia)::timestamp at time zone 'America/Bogota')
      and e.created_at < ((_dia + 1)::timestamp at time zone 'America/Bogota')
      and extract(hour from (e.created_at at time zone 'America/Bogota'))::int >= _h_desde
      and extract(hour from (e.created_at at time zone 'America/Bogota'))::int < _h_hasta
    group by e.user_id
  )
  select cap.user_id,
    count(distinct bkt) filter (where cap.tipo='camara')::bigint,
    count(distinct bkt) filter (where cap.tipo='pantalla')::bigint,
    coalesce(max(fal.fc), 0)::bigint,
    count(*) filter (where cap.tipo='pantalla' and cap.veredicto is not null)::bigint,
    count(*) filter (where cap.tipo='pantalla' and cap.veredicto is not null and cap.fuera_de_lugar is not true)::bigint,
    count(distinct bkt) filter (where cap.tipo='camara' and cap.cara_visible is true)::bigint,
    count(distinct bkt) filter (where cap.tipo='camara' and cap.cara_visible is not null)::bigint
  from cap left join fal on fal.user_id = cap.user_id
  group by cap.user_id
$$;


ALTER FUNCTION "public"."argos_momentos_turno"("_dia" "date", "_h_desde" integer, "_h_hasta" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_perdonar_captura"("_id" "uuid", "_perdonar" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.es_admin_o_dueno((select auth.uid())) then
    raise exception 'sin permiso para perdonar';
  end if;
  update public.monitor_capturas
    set perdonado     = coalesce(_perdonar, true),
        perdonado_por = case when coalesce(_perdonar, true) then (select auth.uid()) else null end,
        perdonado_at  = case when coalesce(_perdonar, true) then now() else null end
  where id = _id;
end;
$$;


ALTER FUNCTION "public"."argos_perdonar_captura"("_id" "uuid", "_perdonar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_permitido_min"("_uid" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select greatest(coalesce(p.comida_min, r.comida, 30), 0) + greatest(coalesce(p.bano_min, r.bano, 10), 0)
    from public.profiles p
    left join lateral (
      select max(c.comida_min) as comida, max(c.bano_min) as bano
        from public.user_roles ur
        join public.roles_config c on lower(c.name) = lower(ur.role) and c.is_active
                                  and (c.tenant_id = ur.tenant_id or ur.tenant_id is null)
       where ur.user_id = p.id
    ) r on true
   where p.id = _uid;
$$;


ALTER FUNCTION "public"."argos_permitido_min"("_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_reportarme"("_tipo" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_nom text;
  v_que text;
begin
  if v_uid is null or _tipo not in ('camara_apagada', 'fuera_cuadro', 'sin_pantalla') then return false; end if;
  if public.es_admin_o_dueno(v_uid) then return false; end if;
  -- Si sigue igual, se vuelve a reportar cada 10 min (no en cada llamado).
  if exists (select 1 from public.argos_reportes r
              where r.user_id = v_uid and r.tipo = _tipo and r.created_at > now() - interval '10 minutes') then
    return false;
  end if;
  insert into public.argos_reportes (user_id, tipo) values (v_uid, _tipo);

  select full_name into v_nom from public.profiles where id = v_uid;
  v_que := case _tipo when 'camara_apagada' then 'sigue con la cámara apagada'
                      when 'fuera_cuadro' then 'no se ve en la cámara'
                      else 'sigue sin compartir pantalla' end;
  insert into public.notifications
    (user_id, type, title, message, reference_id, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
  select d.user_id, 'argos_reporte',
         format('Argos reportó a %s: %s', coalesce(nullif(trim(v_nom), ''), 'un empleado'), v_que),
         'Está en Cowork y no hizo caso a 3 llamados de Argos.',
         v_uid, 'profile', 'HR', 'high', 'new', 'personal', format('/hr/en-vivo/%s', v_uid)
    from public.destinatarios_de_aviso(v_uid) d;
  return true;
end;
$$;


ALTER FUNCTION "public"."argos_reportarme"("_tipo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_sin_pantalla_seg"("_uid" "uuid", "_desde" timestamp with time zone, "_hasta" timestamp with time zone) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select (
    coalesce((
      select sum(extract(epoch from (least(coalesce(s.ended_at, s.last_seen_at), _hasta) - greatest(s.started_at, _desde))))
        from public.cowork_tiempo_segmentos s
       where s.user_id = _uid
         and s.estado in ('pausa', 'sin_pantalla', 'sin_camara', 'sin_conexion', 'sin_conexion_larga')
         and s.started_at < _hasta and coalesce(s.ended_at, s.last_seen_at) > _desde
    ), 0)
    + coalesce((
      select sum(extract(epoch from (least(coalesce(f.hasta, now()), _hasta) - greatest(f.desde, _desde))))
        from public.cowork_fuera f
       where f.user_id = _uid and f.desde < _hasta and coalesce(f.hasta, now()) > _desde
    ), 0)
  )::int;
$$;


ALTER FUNCTION "public"."argos_sin_pantalla_seg"("_uid" "uuid", "_desde" timestamp with time zone, "_hasta" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_tendencia"("_desde" "date", "_hasta" "date") RETURNS TABLE("dia" "date", "pantalla" integer, "camara" integer, "atencion" integer, "personas" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with cap as (
    select (c.created_at at time zone 'America/Bogota')::date as dia,
           c.user_id,
           floor(extract(epoch from c.created_at)/120)::bigint as bkt,
           c.tipo, c.veredicto, c.fuera_de_lugar, c.cara_visible
    from public.monitor_capturas c
    where c.created_at >= ((_desde)::timestamp at time zone 'America/Bogota')
      and c.created_at < ((_hasta + 1)::timestamp at time zone 'America/Bogota')
      and c.user_id in (select v.user_id from public.argos_vigilables() v)
  ),
  pp as (
    select dia, user_id,
      count(distinct bkt) filter (where tipo='camara')  as mom_cam,
      count(distinct bkt) filter (where tipo='pantalla') as mom_pan,
      count(distinct bkt) filter (where tipo='camara' and cara_visible is true)      as cara_ok,
      count(distinct bkt) filter (where tipo='camara' and cara_visible is not null)  as cara_med,
      count(*) filter (where tipo='pantalla' and veredicto is not null)              as juzg,
      count(*) filter (where tipo='pantalla' and veredicto is not null and fuera_de_lugar is not true) as juzg_ok
    from cap group by dia, user_id
  )
  select dia,
    round(avg(case when mom_cam  > 0 then least(1.0, mom_pan::numeric / mom_cam) end) * 100)::int as pantalla,
    round(avg(case when cara_med > 0 then cara_ok::numeric / cara_med end)            * 100)::int as camara,
    round(avg(case when juzg     > 0 then juzg_ok::numeric / juzg end)                * 100)::int as atencion,
    count(distinct user_id)::int as personas
  from pp group by dia order by dia
$$;


ALTER FUNCTION "public"."argos_tendencia"("_desde" "date", "_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."argos_turno_rol_borrar"("_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.es_admin_o_dueno((select auth.uid())) then raise exception 'sin permiso para borrar turnos'; end if;
  delete from public.rol_turnos where id = _id and tenant_id = (select public.current_tenant_id());
end;
$$;


