CREATE OR REPLACE FUNCTION "public"."assign_closer_to_contact"("p_contact_id" "uuid", "p_closer_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_creator_id uuid;
  v_contact public.closers_contacts%rowtype;
  v_handle text;
  v_kind text;
  v_is_agencia boolean;
  v_lead_source text;
  v_deal_type text;
begin
  if not public.has_permission(auth.uid(), 'Closers', 'Asignar Closer') then
    raise exception 'No tienes permiso para asignar closers (Closers / Asignar Closer).'
      using errcode = '42501';
  end if;

  select * into v_contact from public.closers_contacts where id = p_contact_id;
  if not found then
    raise exception 'Contacto no encontrado.' using errcode = 'P0002';
  end if;

  v_handle := coalesce(nullif(v_contact.handle, ''), nullif(v_contact.name, ''), 'sin_handle');

  -- La BASE sale del tipo de contacto, no de un if binario. 'ex_creadora' ya no
  -- cae en el else: es reclutamiento igual que 'maven' (mismo embudo, para Kash)
  -- pero se distingue para poder verla, contarla y que el bot sepa de dónde vino.
  v_kind := coalesce(v_contact.contact_kind, 'modelo');
  v_is_agencia := v_kind = 'agencia';
  v_lead_source := case v_kind when 'agencia' then 'agencia'
                               when 'ex_creadora' then 'ex_creadora'
                               else 'maven' end;
  v_deal_type   := case when v_is_agencia then 'venta_plataforma' else 'reclutamiento' end;

  select id into v_creator_id
  from public.closer_creators
  where source_contact_id = p_contact_id
    and deal_type = v_deal_type;

  if v_creator_id is null and lower(v_handle) <> 'sin_handle' then
    select id into v_creator_id
    from public.closer_creators
    where lower(instagram_handle) = lower(v_handle)
      and stage in ('Nuevo', 'Asignada', 'Confirmada')
    order by created_at asc
    limit 1;
  end if;

  if v_creator_id is not null then
    update public.closer_creators
    set assigned_to = p_closer_id,
        stage       = case when stage = 'Nuevo' then 'Asignada' else stage end,
        passed_date = coalesce(passed_date, current_date),
        source_contact_id = coalesce(source_contact_id, p_contact_id),
        phone       = coalesce(phone, v_contact.phone),
        lead_source = case when lead_source = 'maven' and v_lead_source <> 'maven'
                          then v_lead_source else lead_source end,
        deal_type   = case when v_is_agencia then 'venta_plataforma' else deal_type end
    where id = v_creator_id;
  else
    insert into public.closer_creators (
      instagram_handle, phone, category, source_contact_id,
      assigned_to, stage, passed_date, created_by,
      lead_source, deal_type, city
    ) values (
      v_handle, v_contact.phone, v_contact.physical_appearance, p_contact_id,
      p_closer_id, 'Asignada', current_date, auth.uid(),
      v_lead_source, v_deal_type, v_contact.city
    )
    returning id into v_creator_id;
  end if;

  update public.closers_contacts set status = 'converted' where id = p_contact_id;

  return v_creator_id;
end;
$$;


ALTER FUNCTION "public"."assign_closer_to_contact"("p_contact_id" "uuid", "p_closer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auth_user_by_email"("_email" "text") RETURNS TABLE("user_id" "uuid", "full_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select u.id,
         coalesce(nullif(btrim(p.full_name), ''), split_part(u.email, '@', 1))::text
  from auth.users u
  left join public.profiles p on p.id = u.id
  where lower(u.email) = lower(btrim(_email))
    and u.deleted_at is null
  limit 1
$$;


ALTER FUNCTION "public"."auth_user_by_email"("_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_conciliacion"("p_dias" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_desde date := (current_date - greatest(1, least(p_dias, 400)));
  v_a jsonb; v_b jsonb; v_c jsonb;
  v_cuentas int; v_cuentas_vinc int;
  v_vinculadas int; v_sueltas int; v_sueltas_nuestras int; v_personas int;
  v_activas int; v_plus int; v_massive int; v_estado_viejo int; v_sin_facturar int;
begin
  if not coalesce(public.blu_is_management(auth.uid()), false) then
    raise exception 'forbidden: management only' using errcode = '42501';
  end if;

  -- A) sueltas, UNA FILA POR PERSONA, con la agencia que la trajo
  select coalesce(jsonb_agg(t order by t.bruto desc), '[]'::jsonb) into v_a
  from (
    select string_agg(distinct e.blu_creator_name, ' + ') as cuenta,
           count(distinct lower(trim(e.blu_creator_name))) as n_cuentas,
           round(sum(e.total_gross)) as bruto,
           count(distinct e.date) as dias,
           max(e.date)::text as ultimo_dia,
           max(a.agency) as agencia
    from public.creator_daily_earnings e
    left join public.blu_account_agency a on a.cuenta = lower(trim(e.blu_creator_name))
    where e.creator_id is null and e.date >= v_desde
      and not exists (
        select 1 from public.blu_creator_map m
        where lower(trim(m.blu_name)) = lower(trim(e.blu_creator_name)) and m.status = 'ignored')
    group by public.blu_persona_key(e.blu_creator_name)
    having sum(e.total_gross) > 0
  ) t;
  v_sueltas := jsonb_array_length(v_a);
  select count(*) into v_sueltas_nuestras
  from jsonb_array_elements(v_a) x where x->>'agencia' is not null;

  -- B) facturan con estado ≠ active (el perfil existe, pero no cuenta como roster)
  select coalesce(jsonb_agg(t order by t.bruto desc), '[]'::jsonb) into v_b
  from (
    select coalesce(nullif(trim(c.artistic_name),''), c.name) as creadora,
           c.status, coalesce(cb.kash_type,'—') as kash,
           string_agg(distinct e.blu_creator_name, ' + ') as cuentas,
           round(sum(e.total_gross)) as bruto,
           max(e.date)::text as ultimo_dia
    from public.creator_daily_earnings e
    join public.creadoras_de_mi_agencia() c on c.id = e.creator_id
    left join public.creator_business cb on cb.creator_id = c.id
    where e.date >= v_desde and c.status <> 'active'
    group by c.id, c.artistic_name, c.name, c.status, cb.kash_type
    having sum(e.total_gross) > 0
  ) t;
  v_estado_viejo := jsonb_array_length(v_b);

  -- C) activas en Maven que no facturaron
  select coalesce(jsonb_agg(t order by t.creadora), '[]'::jsonb) into v_c
  from (
    select coalesce(nullif(trim(c.artistic_name),''), c.name) as creadora,
           coalesce(cb.kash_type,'—') as kash
    from public.creadoras_de_mi_agencia() c
    left join public.creator_business cb on cb.creator_id = c.id
    where c.status = 'active'
      and not exists (select 1 from public.creator_daily_earnings e
                       where e.creator_id = c.id and e.date >= v_desde
                         and e.total_gross > 0)
  ) t;
  v_sin_facturar := jsonb_array_length(v_c);

  -- Cuentas (para el detalle) y creadoras VINCULADAS que facturaron
  select count(*), count(*) filter (where cid is not null),
         count(distinct cid) filter (where bruto > 0)
    into v_cuentas, v_cuentas_vinc, v_vinculadas
  from (
    select max(e.creator_id::text) as cid, sum(e.total_gross) as bruto
    from public.creator_daily_earnings e
    where e.date >= v_desde
      and not exists (
        select 1 from public.blu_creator_map m
        where lower(trim(m.blu_name)) = lower(trim(e.blu_creator_name)) and m.status = 'ignored')
    group by lower(trim(e.blu_creator_name))
  ) x;

  v_personas := v_vinculadas + v_sueltas;

  select count(*),
         count(*) filter (where cb.kash_type = 'Plus'),
         count(*) filter (where cb.kash_type = 'Massive')
    into v_activas, v_plus, v_massive
  from public.creadoras_de_mi_agencia() c
  left join public.creator_business cb on cb.creator_id = c.id
  where c.status = 'active';

  return jsonb_build_object(
    'desde', v_desde,
    'blu_personas', v_personas,
    'blu_vinculadas', v_vinculadas,
    'blu_sin_vincular', v_sueltas,
    'blu_sueltas_con_agencia', v_sueltas_nuestras,
    'blu_cuentas', v_cuentas,
    'blu_cuentas_vinculadas', v_cuentas_vinc,
    'maven_activas', v_activas,
    'maven_plus', v_plus,
    'maven_massive', v_massive,
    'estado_viejo', v_estado_viejo,
    'activas_sin_facturar', v_sin_facturar,
    'cuadra', (v_personas = v_activas and v_sueltas = 0
               and v_estado_viejo = 0 and v_sin_facturar = 0),
    'sin_vincular', v_a,
    'facturan_sin_estar_activas', v_b,
    'activas_sin_blu', v_c);
end;
$$;


ALTER FUNCTION "public"."blu_conciliacion"("p_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_ignore_creator"("p_blu_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role') then
    raise exception 'forbidden: solo management' using errcode = '42501';
  end if;
  insert into public.blu_creator_map (blu_name, creator_id, status, confirmed_by, confirmed_at)
    values (p_blu_name, null, 'ignored', auth.uid(), now())
  on conflict (blu_name) do update set
    status = 'ignored', creator_id = null, confirmed_by = excluded.confirmed_by, confirmed_at = now();
end;
$$;


ALTER FUNCTION "public"."blu_ignore_creator"("p_blu_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_is_management"("p_uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.user_roles ur
    left join public.role_groups rg on rg.role_name = ur.role and rg.tenant_id = ur.tenant_id
    where ur.user_id = p_uid
      and (ur.role in ('admin', 'manager', 'owner') or rg.is_manager_or_above = true)
  );
$$;


ALTER FUNCTION "public"."blu_is_management"("p_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_list_orphans"() RETURNS TABLE("blu_name" "text", "total_gross" numeric, "days" integer, "first_date" "date", "last_date" "date", "agency" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role') then
    raise exception 'forbidden: solo management' using errcode = '42501';
  end if;
  return query
    select min(e.blu_creator_name),
           sum(e.total_gross)::numeric,
           count(distinct e.date)::int,
           min(e.date),
           max(e.date),
           max(a.agency)
    from public.creator_daily_earnings e
    left join public.blu_account_agency a on a.cuenta = lower(trim(e.blu_creator_name))
    where e.creator_id is null
      and not exists (
        select 1 from public.blu_creator_map m
        where lower(trim(m.blu_name)) = lower(trim(e.blu_creator_name)) and m.status = 'ignored'
      )
    group by lower(trim(e.blu_creator_name))
    order by sum(e.total_gross) desc;
end;
$$;


ALTER FUNCTION "public"."blu_list_orphans"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_map_creator"("p_blu_name" "text", "p_creator_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_updated int;
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role') then
    raise exception 'forbidden: solo management' using errcode = '42501';
  end if;
  if coalesce(p_blu_name,'') = '' or p_creator_id is null then
    raise exception 'blu_name y creator_id son requeridos';
  end if;

  insert into public.blu_creator_map (blu_name, creator_id, status, confirmed_by, confirmed_at)
    values (trim(p_blu_name), p_creator_id, 'confirmed', auth.uid(), now())
  on conflict (blu_name) do update set
    creator_id = excluded.creator_id, status = 'confirmed',
    confirmed_by = excluded.confirmed_by, confirmed_at = now();

  -- Vincula TODAS las grafías de la misma cuenta, no solo la que se clickeó.
  update public.creator_daily_earnings
    set creator_id = p_creator_id
    where lower(trim(blu_creator_name)) = lower(trim(p_blu_name))
      and creator_id is distinct from p_creator_id;
  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."blu_map_creator"("p_blu_name" "text", "p_creator_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_match_creator"("p_blu_name" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select c.id
  from public.creators c
  where public.blu_normalize(p_blu_name) <> ''
    and public.blu_normalize(p_blu_name) in (
      public.blu_normalize(regexp_replace(coalesce(c.onlyfans_url, ''), '^.*onlyfans\.com/', '')),
      public.blu_normalize(c.instagram_handle),
      public.blu_normalize(c.name),
      public.blu_normalize(c.artistic_name)
    )
  limit 1;
$$;


ALTER FUNCTION "public"."blu_match_creator"("p_blu_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_normalize"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select regexp_replace(
           regexp_replace(lower(coalesce(p, '')), '\m(elite|vip|free|[0-9]+k)\M', ' ', 'g'),
         '[^a-z0-9]', '', 'g');
$$;


ALTER FUNCTION "public"."blu_normalize"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_pending_mappings"() RETURNS TABLE("blu_name" "text", "dias" bigint, "total_gross" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.blu_is_management(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return query
    select e.blu_creator_name, count(*)::bigint, sum(e.total_gross)
    from public.creator_daily_earnings e
    where e.creator_id is null
      and not exists (select 1 from public.blu_creator_map m where m.blu_name = e.blu_creator_name and m.status = 'ignored')
    group by e.blu_creator_name
    order by sum(e.total_gross) desc;
end;
$$;


ALTER FUNCTION "public"."blu_pending_mappings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_persona_key"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select case
           when length(regexp_replace(public.blu_normalize(p), '(of|tv|vip|free|ok|mx|xxx)$', '')) >= 5
             then regexp_replace(public.blu_normalize(p), '(of|tv|vip|free|ok|mx|xxx)$', '')
           else public.blu_normalize(p)
         end;
$_$;


ALTER FUNCTION "public"."blu_persona_key"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_registrar_cuentas"("p_blu_names" "text"[], "p_agency" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_n int;
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role)' using errcode = '42501';
  end if;
  if p_agency not in ('plus','massive') then
    raise exception 'agency debe ser plus o massive, llegó %', p_agency;
  end if;

  insert into public.blu_account_agency (cuenta, agency, fuente)
  select distinct lower(trim(n)), p_agency, 'bridge'
  from unnest(p_blu_names) as n
  where coalesce(trim(n),'') <> ''
  on conflict (cuenta) do update set
    agency = excluded.agency,           -- si una cuenta se mudó de agencia, manda la última corrida
    ultimo_visto = now(),
    fuente = 'bridge';
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."blu_registrar_cuentas"("p_blu_names" "text"[], "p_agency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."blu_relink_orphans"("p_blu_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  v_n int;
  v_rows int := 0;
  v_names text[] := '{}';
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role) puede re-vincular ingresos' using errcode = '42501';
  end if;

  for r in
    select x.clave, x.nm,
           coalesce(
             (select bm.creator_id from public.blu_creator_map bm
               where lower(trim(bm.blu_name)) = x.clave and bm.status <> 'ignored'),
             public.blu_match_creator(x.nm)
           ) as cid
    from (
      select lower(trim(e.blu_creator_name)) as clave, min(e.blu_creator_name) as nm
      from public.creator_daily_earnings e
      where e.creator_id is null
        and (p_blu_name is null or lower(trim(e.blu_creator_name)) = lower(trim(p_blu_name)))
        and not exists (
          select 1 from public.blu_creator_map m
          where lower(trim(m.blu_name)) = lower(trim(e.blu_creator_name)) and m.status = 'ignored'
        )
      group by 1
    ) x
  loop
    if r.cid is not null then
      update public.creator_daily_earnings
         set creator_id = r.cid
       where lower(trim(blu_creator_name)) = r.clave and creator_id is null;
      get diagnostics v_n = row_count;
      if v_n > 0 then
        v_rows := v_rows + v_n;
        v_names := array_append(v_names, r.nm);
      end if;
    end if;
  end loop;

  return jsonb_build_object('relinked_rows', v_rows, 'relinked_names', to_jsonb(v_names));
end;
$$;


ALTER FUNCTION "public"."blu_relink_orphans"("p_blu_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."blu_relink_orphans"("p_blu_name" "text") IS 'Re-vincula filas de creator_daily_earnings con creator_id null cuyo blu_creator_name YA resuelve (mapeo manual o blu_match_creator). Respeta status=ignored. La llama import_blu_earnings al final para que el historico se auto-sane sin re-importarlo.';



CREATE OR REPLACE FUNCTION "public"."blu_set_creator_mapping"("p_blu_name" "text", "p_creator_id" "uuid", "p_ignore" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_updated int;
begin
  if not public.blu_is_management(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  insert into public.blu_creator_map (blu_name, creator_id, status, confirmed_by, confirmed_at)
  values (p_blu_name, case when p_ignore then null else p_creator_id end,
          case when p_ignore then 'ignored' else 'mapped' end, auth.uid(), now())
  on conflict (blu_name) do update set
    creator_id = excluded.creator_id, status = excluded.status,
    confirmed_by = excluded.confirmed_by, confirmed_at = now();

  update public.creator_daily_earnings
    set creator_id = case when p_ignore then null else p_creator_id end
    where blu_creator_name = p_blu_name;
  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."blu_set_creator_mapping"("p_blu_name" "text", "p_creator_id" "uuid", "p_ignore" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."broadcast_chatter_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'realtime'
    AS $$
BEGIN
  PERFORM realtime.send(
    jsonb_build_object('message_id', NEW.id, 'session_id', NEW.session_id),
    'new_message',
    'chatter-session:' || NEW.session_id,
    false
  );
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'broadcast_chatter_message failed: %', SQLERRM;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."broadcast_chatter_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calcular_notas_chatters"("_dia" "date" DEFAULT ((("now"() AT TIME ZONE 'America/Bogota'::"text"))::"date" - 1)) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  cfg public.chatter_score_config%ROWTYPE;
  r record;
  v_esperado numeric; v_ventas numeric; v_ratio numeric;
  v_nota_ventas numeric; v_horas numeric; v_nota_tiempo numeric;
  v_actividad numeric; v_nota_meet numeric; v_nota numeric;
  v_pausa_seg integer; v_estuvo_cowork boolean;
  n integer := 0;
BEGIN
  SELECT * INTO cfg FROM public.chatter_score_config WHERE id = 1;

  FOR r IN
    SELECT i.id AS identity_id, i.maven_user_id,
           (SELECT l.external_id FROM public.chatter_identity_link l
            WHERE l.identity_id = i.id AND l.source = 'blu' AND l.valid_to IS NULL
            LIMIT 1) AS blu_id
    FROM public.chatter_identity i
    WHERE i.active AND i.is_chatter
  LOOP
    v_ventas := public.chatter_ventas_del_dia(r.identity_id, _dia);
    v_esperado := public.chatter_expected_sales(r.identity_id, _dia, cfg.dias_promedio_modelo);

    IF v_ventas IS NULL OR v_esperado IS NULL OR v_esperado <= 0 THEN
      v_ratio := NULL;
      v_nota_ventas := NULL;
    ELSE
      v_ratio := v_ventas / v_esperado;
      v_nota_ventas := public.chatter_score_from_scale(cfg.escala_ventas, v_ratio);
      IF v_ventas < cfg.piso_ventas_usd THEN
        v_nota_ventas := LEAST(v_nota_ventas, cfg.nota_si_bajo_piso);
      END IF;
    END IF;

    v_horas := NULL; v_actividad := NULL; v_nota_tiempo := NULL;
    IF r.maven_user_id IS NOT NULL THEN
      SELECT SUM(h.tracked_seconds) / 3600.0, AVG(h.overall_activity)
        INTO v_horas, v_actividad
      FROM public.hubstaff_daily_data h
      JOIN public.hubstaff_members m ON m.hubstaff_user_id = h.hubstaff_user_id
      WHERE m.profile_id = r.maven_user_id AND h.date = _dia;
    END IF;
    IF v_horas IS NOT NULL AND cfg.horas_turno > 0 THEN
      v_nota_tiempo := public.chatter_score_from_scale(cfg.escala_tiempo, v_horas / cfg.horas_turno);
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM public.cowork_room_assignments a
      WHERE a.user_id = r.maven_user_id
        AND (a.assigned_at AT TIME ZONE 'America/Bogota')::date = _dia
    ) INTO v_estuvo_cowork;

    v_pausa_seg := NULL;
    v_nota_meet := NULL;
    IF v_estuvo_cowork THEN
      SELECT COALESCE(SUM(duration_seconds), 0) INTO v_pausa_seg
      FROM public.cowork_breaks
      WHERE user_id = r.maven_user_id
        AND (started_at AT TIME ZONE 'America/Bogota')::date = _dia
        AND NOT auto_closed;
      v_nota_meet := 10;
      IF v_pausa_seg > 3600 THEN v_nota_meet := v_nota_meet - 3;
      ELSIF v_pausa_seg > 1800 THEN v_nota_meet := v_nota_meet - 1;
      END IF;
      v_nota_meet := GREATEST(0, v_nota_meet);
    END IF;

    -- Sin ventas no hay nota: el resto es contexto, no desempeño.
    IF v_nota_ventas IS NULL THEN
      v_nota := NULL;
    ELSE
      SELECT SUM(peso * nota) / NULLIF(SUM(peso), 0) INTO v_nota
      FROM (VALUES
        (cfg.peso_ventas, v_nota_ventas),
        (cfg.peso_tiempo, v_nota_tiempo),
        (cfg.peso_meet, v_nota_meet)
      ) AS t(peso, nota)
      WHERE nota IS NOT NULL;
    END IF;

    INSERT INTO public.chatter_daily_score AS d
      (dia, identity_id, ventas, ventas_esperadas, nota_ventas, horas, nota_tiempo, nota_meet, nota, detalle, config_snapshot)
    VALUES (_dia, r.identity_id, v_ventas, v_esperado, v_nota_ventas, v_horas, v_nota_tiempo, v_nota_meet,
            ROUND(v_nota, 2),
            jsonb_build_object(
              'ratio_ventas', v_ratio,
              'pausa_segundos', v_pausa_seg,
              'actividad_pct', v_actividad,
              'estuvo_en_cowork', v_estuvo_cowork,
              'blu_id', r.blu_id,
              'faltantes', (
                CASE WHEN v_nota_ventas IS NULL THEN jsonb_build_array('ventas') ELSE '[]'::jsonb END
                || CASE WHEN v_nota_tiempo IS NULL THEN jsonb_build_array('horas') ELSE '[]'::jsonb END
                || CASE WHEN v_nota_meet   IS NULL THEN jsonb_build_array('cowork') ELSE '[]'::jsonb END
              )),
            to_jsonb(cfg))
    ON CONFLICT (dia, identity_id) DO UPDATE SET
      ventas = EXCLUDED.ventas, ventas_esperadas = EXCLUDED.ventas_esperadas,
      nota_ventas = EXCLUDED.nota_ventas, horas = EXCLUDED.horas,
      nota_tiempo = EXCLUDED.nota_tiempo, nota_meet = EXCLUDED.nota_meet,
      nota = EXCLUDED.nota, detalle = EXCLUDED.detalle,
      config_snapshot = EXCLUDED.config_snapshot, calculada_at = now();

    n := n + 1;
  END LOOP;

  RETURN n;
END;
$$;


ALTER FUNCTION "public"."calcular_notas_chatters"("_dia" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calcular_notas_chatters"("_dia" "date") IS 'Calcula y guarda la nota diaria de cada chatter activo (por defecto la de AYER, hora Bogota). La nota EXIGE el componente de ventas: sin ese dato no hay nota, porque fichar horas no es el trabajo. Horas y Cowork pueden faltar y se reparte su peso.';



CREATE OR REPLACE FUNCTION "public"."call_participants_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_de_la_llamada uuid;
begin
  if tg_op = 'UPDATE' then
    if new.call_id is distinct from old.call_id or new.user_id is distinct from old.user_id then
      raise exception 'call_participants_agencia: una participación no cambia de llamada ni de persona' using errcode = '42501';
    end if;
    return new;
  end if;
  select c.tenant_id into v_de_la_llamada from public.calls c where c.id = new.call_id;
  if v_de_la_llamada is null then
    return new;   -- no existe: decide la FK
  end if;
  if not exists (select 1 from public.tenant_members tm where tm.user_id = new.user_id and tm.tenant_id = v_de_la_llamada) then
    raise exception 'call_participants_agencia: % no es de la agencia de la llamada %', new.user_id, new.call_id using errcode = '42501';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."call_participants_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calls_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_de_quien_llama uuid;
  v_de_la_conversacion uuid;
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id is distinct from old.tenant_id
       -- Quién llama y a quién solo pueden pasar a NULL: es la purga de una cuenta.
       or (new.caller_id is distinct from old.caller_id and new.caller_id is not null)
       or (new.receiver_id is distinct from old.receiver_id and new.receiver_id is not null)
       or new.room_id is distinct from old.room_id
       -- La conversación solo puede pasar a NULL: es la FK (ON DELETE SET NULL).
       or (new.conversation_id is distinct from old.conversation_id and new.conversation_id is not null) then
      raise exception 'calls_agencia: quién llama, a quién, la sala, la conversación y la agencia de una llamada no cambian' using errcode = '42501';
    end if;
    return new;
  end if;

  v_de_quien_llama := (select tm.tenant_id from public.tenant_members tm where tm.user_id = new.caller_id);
  if v_de_quien_llama is null then
    raise exception 'calls_agencia: % no es de ninguna agencia, no puede llamar', new.caller_id using errcode = '42501';
  end if;
  if new.tenant_id is null then
    new.tenant_id := v_de_quien_llama;
  elsif new.tenant_id <> v_de_quien_llama then
    raise exception 'calls_agencia: la llamada tiene que ser de la agencia de quien llama' using errcode = '42501';
  end if;
  if new.conversation_id is null or new.room_id is distinct from 'call-' || new.conversation_id::text then
    raise exception 'calls_agencia: la sala de una llamada es call-<id de su conversación>' using errcode = '23514';
  end if;
  v_de_la_conversacion := (select c.tenant_id from public.chat_conversations c where c.id = new.conversation_id);
  if v_de_la_conversacion is distinct from v_de_quien_llama then
    raise exception 'calls_agencia: la conversación no es de la agencia de quien llama' using errcode = '42501';
  end if;
  if not exists (select 1 from public.chat_participants p where p.conversation_id = new.conversation_id and p.user_id = new.caller_id) then
    raise exception 'calls_agencia: quien llama no está en la conversación' using errcode = '42501';
  end if;
  if new.receiver_id is not null
     and not exists (select 1 from public.tenant_members tm where tm.user_id = new.receiver_id and tm.tenant_id = v_de_quien_llama) then
    raise exception 'calls_agencia: % no es de la agencia de quien llama', new.receiver_id using errcode = '42501';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."calls_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_chatters_qa"("p_uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    public.blu_is_management(p_uid)
    or exists (
      select 1
      from public.user_roles ur
      join public.roles_config rc on rc.name = ur.role and rc.tenant_id = ur.tenant_id
      join public.role_permissions rp on rp.role_id = rc.id
      where ur.user_id = p_uid
        and rp.module = 'Agency QA'
        and rp.submodule = 'Chatters QA'
        and rp.can_access = true
    );
$$;


