CREATE OR REPLACE FUNCTION "public"."can_manage_user"("_caller" "uuid", "_target" "uuid", "_action" "text", "_new_role" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_level int; v_target_level int; v_new_role_level int;
  v_is_admin boolean; v_target_is_admin boolean; v_new_role_is_admin boolean;
  v_admin_count int; v_effective_role text; v_ctx jsonb;
BEGIN
  -- Allowlist: una acción no declarada se DENIEGA acá, no queda abierta por olvido.
  IF _action IS NULL OR _action NOT IN
     ('assign_role','remove_role','delete_user','reset_password',
      'update_profile','create_user','list_users') THEN
    RETURN jsonb_build_object('allowed', false, 'reason','unknown_action');
  END IF;
  IF _caller IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason','no_caller');
  END IF;
  IF NOT public.can_manage_users(_caller) THEN
    RETURN jsonb_build_object('allowed', false, 'reason','no_user_management_permission');
  END IF;
  -- Otra agencia: nadie gestiona a quien no es de la suya (20261001211000).
  IF _target IS NOT NULL
     AND (SELECT tm.tenant_id FROM public.tenant_members tm WHERE tm.user_id = _target)
         IS DISTINCT FROM (SELECT tm.tenant_id FROM public.tenant_members tm WHERE tm.user_id = _caller) THEN
    RETURN jsonb_build_object('allowed', false, 'reason','other_agency');
  END IF;

  v_is_admin     := public.is_in_role_group(_caller,'admin');
  v_caller_level := public.actor_level(_caller);
  v_target_level := CASE WHEN _target IS NULL THEN NULL ELSE public.target_level(_target) END;
  v_ctx := jsonb_build_object('caller_level',v_caller_level,'target_level',v_target_level);

  -- Si el rol pedido es el que YA tiene, no es asignación: así "editar el nombre"
  -- (que el front manda siempre con role) no se convierte en cambio de rol.
  IF _new_role IS NOT NULL AND _target IS NOT NULL THEN
    SELECT ur.role::text INTO v_effective_role
    FROM public.user_roles ur WHERE ur.user_id = _target LIMIT 1;
    IF v_effective_role = _new_role THEN _new_role := NULL; END IF;
  END IF;

  IF _action IN ('assign_role','create_user','update_profile') AND _new_role IS NOT NULL THEN
    SELECT rc.level, COALESCE(rg.is_admin,false)
      INTO v_new_role_level, v_new_role_is_admin
    FROM public.roles_config rc
    LEFT JOIN public.role_groups rg ON rg.role_name = rc.name AND rg.tenant_id = rc.tenant_id
    WHERE rc.name = _new_role AND rc.is_active
      AND rc.tenant_id = (SELECT tm.tenant_id FROM public.tenant_members tm WHERE tm.user_id = _caller);

    IF v_new_role_level IS NULL THEN
      RETURN jsonb_build_object('allowed',false,'reason','invalid_or_inactive_role')||v_ctx;
    END IF;
    -- ESTRICTO (decisión de Jhon): >= , no >. Un supervisor no puede nombrar a otro
    -- supervisor, ni HHRR a otro HHRR. Solo el admin saltea la escalera.
    IF NOT v_is_admin AND v_new_role_level >= v_caller_level THEN
      RETURN jsonb_build_object('allowed',false,'reason','role_at_or_above_caller_level',
                                'new_role_level',v_new_role_level)||v_ctx;
    END IF;
  END IF;

  IF _action = 'create_user' THEN
    RETURN jsonb_build_object('allowed',true,'reason','ok')||v_ctx;
  END IF;
  IF _action = 'list_users' THEN
    RETURN jsonb_build_object('allowed',true,'reason','ok')||v_ctx;
  END IF;
  IF _target IS NULL THEN
    RETURN jsonb_build_object('allowed',false,'reason','no_target')||v_ctx;
  END IF;

  IF _target = _caller THEN
    IF _action = 'update_profile' AND _new_role IS NULL THEN
      RETURN jsonb_build_object('allowed',true,'reason','self_profile_ok')||v_ctx;
    END IF;
    RETURN jsonb_build_object('allowed',false,'reason','self_target_not_allowed')||v_ctx;
  END IF;

  v_target_is_admin := public.is_in_role_group(_target,'admin');

  -- Último admin: decide por role_groups.is_admin (fuente de verdad), no por level.
  IF v_target_is_admin AND (
       _action IN ('delete_user','remove_role')
       OR (_action IN ('assign_role','update_profile')
           AND _new_role IS NOT NULL AND NOT COALESCE(v_new_role_is_admin,false))
     ) THEN
    SELECT COUNT(DISTINCT ur.user_id) INTO v_admin_count
    FROM public.user_roles ur JOIN public.role_groups rg ON rg.role_name = ur.role::text and rg.tenant_id = ur.tenant_id
    WHERE rg.is_admin
      AND ur.tenant_id = (SELECT tm.tenant_id FROM public.tenant_members tm WHERE tm.user_id = _target);
    IF v_admin_count <= 1 THEN
      RETURN jsonb_build_object('allowed',false,'reason','last_admin')||v_ctx;
    END IF;
  END IF;

  IF v_is_admin THEN
    RETURN jsonb_build_object('allowed',true,'reason','admin_bypass')||v_ctx;
  END IF;
  IF v_caller_level > v_target_level THEN
    RETURN jsonb_build_object('allowed',true,'reason','ok')||v_ctx;
  END IF;
  RETURN jsonb_build_object('allowed',false,
    'reason', CASE WHEN v_target_level = 999 THEN 'unknown_target_role'
                   ELSE 'target_level_not_below_caller' END)||v_ctx;
END;
$$;


ALTER FUNCTION "public"."can_manage_user"("_caller" "uuid", "_target" "uuid", "_action" "text", "_new_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_users"("_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    _user_id IS NOT NULL
    AND public.can_use_module_function(_user_id,'Administración','Usuarios','manager_or_above')
    AND public.actor_level(_user_id) > 0, false);
$$;


ALTER FUNCTION "public"."can_manage_users"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_moderate_livekit_room"("_user_id" "uuid", "_room" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF _user_id IS NULL OR _room IS NULL OR _room = '' THEN
    RETURN false;
  END IF;

  -- Nadie modera una sala que no es de su agencia (20261003120000): ni un admin,
  -- ni el anfitrión, ni «el que llamó». Una sala que no es de ninguna, nadie.
  IF NOT EXISTS (
    SELECT 1 FROM public.tenant_members tm
    WHERE tm.user_id = _user_id AND tm.tenant_id = public.agencia_de_sala_livekit(_room)
  ) THEN
    RETURN false;
  END IF;

  -- Un admin modera las salas de SU agencia (20261001213000); antes, cualquiera.
  IF public.is_in_role_group(_user_id, 'admin') THEN
    RETURN true;
  END IF;

  IF _room LIKE 'meet\_%' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.meet_rooms mr
      WHERE mr.livekit_room_name = _room
        AND (
          mr.created_by = _user_id
          OR EXISTS (
            SELECT 1 FROM public.meet_room_cohosts c
            WHERE c.meet_room_id = mr.id AND c.user_id = _user_id
          )
        )
    );
  END IF;

  IF _room LIKE 'cowork\_%' THEN
    RETURN EXISTS (
      SELECT 1
      FROM public.cowork_sessions s
      JOIN public.cowork_memberships m ON m.session_id = s.id
      WHERE m.user_id = _user_id
        AND m.role = 'host'
        AND (
          s.host_hub_livekit_room = _room
          OR EXISTS (
            SELECT 1 FROM public.cowork_rooms r
            WHERE r.session_id = s.id AND r.livekit_room_name = _room
          )
        )
    );
  END IF;

  IF _room LIKE 'call-%' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.calls c
      WHERE c.room_id = _room AND c.caller_id = _user_id
    );
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."can_moderate_livekit_room"("_user_id" "uuid", "_room" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_moderate_livekit_room"("_user_id" "uuid", "_room" "text") IS 'Autorizacion de moderacion por sala de LiveKit (mutear/echar/terminar). La consulta la edge livekit-moderate ANTES de pedirle a LiveKit la accion real.';



CREATE OR REPLACE FUNCTION "public"."can_see_contact_phone"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.is_phone_privileged()
    or exists (
      select 1
      from public.user_roles ur
      join public.roles_config rc
        on rc.name = ur.role and rc.tenant_id = ur.tenant_id and rc.is_active
      join public.role_permissions rp
        on rp.role_id = rc.id
      where ur.user_id = auth.uid()
        and rp.module = 'Contactos'
        and rp.submodule = 'Ver Teléfonos'
        and rp.can_access = true
    );
$$;


ALTER FUNCTION "public"."can_see_contact_phone"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_see_contact_phone"() IS 'TRUE si el user es privilegiado (admin/service_role vía is_phone_privileged) O su rol tiene el permiso EXPLÍCITO Contactos/Ver Teléfonos. Default-deny (no usa el fallback bool_or de has_permission). Gate del teléfono en v_closers_contacts.';



CREATE OR REPLACE FUNCTION "public"."can_use_blu_mp"("p_uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    public.blu_is_management(p_uid)
    or exists (
      select 1
      from public.user_roles ur
      join public.roles_config rc on rc.name = ur.role and rc.tenant_id = ur.tenant_id
      join public.role_permissions rp on rp.role_id = rc.id
      where ur.user_id = p_uid
        and rp.can_access = true
        and (
          (rp.module = 'Mensajes Pro' and rp.submodule is null)
          or (rp.module = 'Agency QA' and rp.submodule = 'Chatters QA')
        )
    );
$$;


ALTER FUNCTION "public"."can_use_blu_mp"("p_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_use_module_function"("_user_id" "uuid", "_module" "text", "_submodule" "text", "_fallback_group" "text" DEFAULT 'supervisor_or_above'::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_explicit boolean;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;

  IF public.is_in_role_group(_user_id, 'admin') THEN
    RETURN true;
  END IF;

  SELECT rp.can_access INTO v_explicit
  FROM public.user_roles ur
  JOIN public.roles_config rc ON rc.name = ur.role and rc.tenant_id = ur.tenant_id AND rc.is_active
  JOIN public.role_permissions rp ON rp.role_id = rc.id
  WHERE ur.user_id = _user_id
    AND rp.module = _module
    AND rp.submodule = _submodule
  ORDER BY rp.can_access DESC
  LIMIT 1;

  IF v_explicit IS NOT NULL THEN
    RETURN v_explicit;
  END IF;

  RETURN public.is_in_role_group(_user_id, _fallback_group);
END;
$$;


ALTER FUNCTION "public"."can_use_module_function"("_user_id" "uuid", "_module" "text", "_submodule" "text", "_fallback_group" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_use_module_function"("_user_id" "uuid", "_module" "text", "_submodule" "text", "_fallback_group" "text") IS 'Permiso de una accion concreta: la fila explicita de role_permissions manda; sin fila, cae al nivel de acceso de role_groups indicado. Admin siempre true. Pensada para que las edge functions y el front apliquen la MISMA regla.';



CREATE OR REPLACE FUNCTION "public"."canonical_phone"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with d0 as (select regexp_replace(coalesce(p,''),'\D','','g') as d)
  select case
    when length(d) = 13 and left(d,3) = '521' then '52' || substr(d,4)
    when length(d) = 13 and left(d,2) = '55' and substr(d,5,1) = '9' then substr(d,1,4) || substr(d,6)
    else d
  end
  from d0;
$$;


ALTER FUNCTION "public"."canonical_phone"("p" "text") OWNER TO "postgres";


