CREATE OR REPLACE FUNCTION "public"."centro_ahora"() RETURNS TABLE("user_id" "uuid", "nombre" "text", "grupo" "text", "agencia" "text", "turno" "text", "programado" boolean, "conectado" boolean, "estado" "text", "pausa_kind" "text", "pausa_seg" integer, "pausa_limite_min" integer, "pausa_excedida" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with t as (
    select (now() at time zone 'America/Bogota') as ts
  ), marco as (
    select
      case
        when extract(hour from t.ts) between 8 and 15 then 'am'
        when extract(hour from t.ts) >= 16 then 'pm'
        else 'mad'
      end as turno,
      t.ts::date as hoy,
      (date_trunc('week', t.ts))::date as semana,
      (extract(isodow from t.ts)::int - 1)::smallint as dia
    from t
  ), programados as (
    select ci.maven_user_id as p_user_id,
           ci.display_name as p_nombre,
           g.name as p_grupo,
           g.agency as p_agencia,
           m.shift as p_turno
    from chatter_group_members m
    join chatter_groups g on g.id = m.group_id and g.active
    join chatter_identity ci on ci.id = m.identity_id and ci.active
    cross join marco
    where ci.maven_user_id is not null
      and m.valid_from <= marco.hoy
      and (m.valid_to is null or m.valid_to >= marco.hoy)
      and m.shift = marco.turno
      and not exists (
        select 1 from chatter_rest_days r
        where r.week_start = marco.semana
          and r.weekday = marco.dia
          and r.identity_id = m.identity_id
      )
  ), conectados as (
    select distinct on (s.user_id) s.user_id as c_user_id, s.estado as c_estado
    from cowork_tiempo_segmentos s
    where s.ended_at is null
      and s.last_seen_at > now() - interval '2 minutes'
    order by s.user_id, s.last_seen_at desc
  ), pausas as (
    select distinct on (b.user_id)
      b.user_id as b_user_id,
      b.kind as b_kind,
      extract(epoch from (now() - b.started_at))::int as b_seg,
      (select min(l.minutos) from cowork_break_limits l where l.kind = b.kind) as b_limite_min
    from cowork_breaks b
    where b.ended_at is null
    order by b.user_id, b.started_at desc
  ), gente as (
    select coalesce(p.p_user_id, c.c_user_id) as g_user_id,
           p.p_nombre, p.p_grupo, p.p_agencia, p.p_turno,
           (p.p_user_id is not null) as g_programado,
           (c.c_user_id is not null) as g_conectado,
           c.c_estado
    from programados p
    full outer join conectados c on c.c_user_id = p.p_user_id
  )
  select g.g_user_id,
         coalesce(g.p_nombre, pr.full_name),
         g.p_grupo, g.p_agencia, g.p_turno,
         g.g_programado, g.g_conectado, g.c_estado,
         pa.b_kind, pa.b_seg, pa.b_limite_min,
         (pa.b_kind is not null and pa.b_limite_min is not null and pa.b_seg > pa.b_limite_min * 60)
  from gente g
  left join pausas pa on pa.b_user_id = g.g_user_id
  left join profiles pr on pr.id = g.g_user_id
  where public.is_in_role_group((select auth.uid()), 'supervisor_or_above')
     or public.is_in_role_group((select auth.uid()), 'admin')
     or g.g_user_id = (select auth.uid());
$$;


ALTER FUNCTION "public"."centro_ahora"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cerrar_grabaciones_huerfanas_tick"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_token text;
  v_abiertas integer;
begin
  select count(*) into v_abiertas
  from public.meeting_recordings
  where status in ('recording', 'processing')
    and deleted_at is null
    and started_at < now() - interval '15 minutes';

  if v_abiertas = 0 then
    return jsonb_build_object('abiertas', 0, 'despertada', false);
  end if;

  select decrypted_secret into v_token
  from vault.decrypted_secrets
  where name = 'recordings_cron_token';

  if v_token is null then
    return jsonb_build_object('abiertas', v_abiertas, 'despertada', false,
                              'error', 'falta el secreto recordings_cron_token en vault');
  end if;

  perform net.http_post(
    url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/recordings',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Cron-Token', v_token
    ),
    body := jsonb_build_object('action', 'sweep'),
    timeout_milliseconds := 120000
  );

  return jsonb_build_object('abiertas', v_abiertas, 'despertada', true);
end;
$$;


ALTER FUNCTION "public"."cerrar_grabaciones_huerfanas_tick"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_conversations_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _agencia uuid;
  _agencias int;
  _tope int;
  _hechas int;
  _libre int;
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id is distinct from old.tenant_id
       or new.type is distinct from old.type
       or new.created_by is distinct from old.created_by
       or new.created_at is distinct from old.created_at then
      raise exception 'chat_conversacion_inmutable: la agencia, el tipo, el creador y la fecha de una conversación no cambian';
    end if;
    return new;
  end if;

  -- INSERT. La agencia es la de quien crea (la membresía más vieja, como
  -- current_tenant_id: ver «Límite conocido» arriba); lo que mande el pedido se
  -- ignora.
  if _uid is not null then
    _agencia := public.current_tenant_id();
  else
    select tm.tenant_id into _agencia
      from public.tenant_members tm
     where tm.user_id = new.created_by
     order by tm.created_at asc
     limit 1;
  end if;
  if _agencia is null then
    select count(*) into _agencias from public.tenants;
    if _agencias = 1 then
      select id into _agencia from public.tenants;
    else
      raise exception 'chat_sin_agencia: quien crea la conversación no es de ninguna agencia';
    end if;
  end if;
  new.tenant_id := _agencia;

  if _uid is not null then
    -- La fecha la pone la base.
    new.created_at := now();

    -- A9: 30 grupos y 100 directos nuevos por persona en 24 horas corridas,
    -- contando ALTAS. El candado por persona hace que dos altas a la vez no pasen
    -- las dos con 29; la cuenta de abajo corre con una foto nueva (función
    -- VOLATILE), así que ve lo que la otra ya confirmó. Si el INSERT falla
    -- después (la RLS), el alta se deshace con él.
    _tope := case when new.type = 'group' then 30 else 100 end;
    perform pg_advisory_xact_lock(hashtextextended('chat_altas:' || _uid::text, 0));
    select count(*) into _hechas from (
      select 1 from public.chat_conversaciones_creadas a
       where a.user_id = _uid and a.type = new.type
         and a.created_at > now() - interval '24 hours'
       limit _tope) x;
    if _hechas >= _tope then
      -- Se libera un lugar cuando la más vieja de esas altas cumple 24 horas (el
      -- PR 2 lo manda como Retry-After). Solo corre al rechazar.
      select ceil(extract(epoch from min(a.created_at) + interval '24 hours' - now()))::int into _libre
        from public.chat_conversaciones_creadas a
       where a.user_id = _uid and a.type = new.type
         and a.created_at > now() - interval '24 hours';
      _libre := greatest(coalesce(_libre, 1), 1);
      if new.type = 'group' then
        raise exception using errcode = 'MV429',
          message = 'chat_tope_grupos: ya creaste 30 grupos en las últimas 24 horas',
          detail = json_build_object('limite', 'person_new_groups_day', 'reintentar_en', _libre)::text;
      end if;
      raise exception using errcode = 'MV429',
        message = 'chat_tope_directos: ya abriste 100 chats directos en las últimas 24 horas',
        detail = json_build_object('limite', 'person_new_directs_day', 'reintentar_en', _libre)::text;
    end if;
    insert into public.chat_conversaciones_creadas (user_id, type, created_at)
    values (_uid, new.type, now());
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_conversations_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_conversations_api"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _c jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  _id uuid;
  _k public.api_keys;
  _n integer;
begin
  if tg_op = 'UPDATE' then
    if new.creada_por_api_key is distinct from old.creada_por_api_key then
      raise exception 'chat_conversacion_inmutable: la key que abrió una conversación no cambia';
    end if;
    return new;
  end if;
  if _c ->> 'role' = 'service_role' then
    raise exception using errcode = 'MV403',
      message = 'api_service_role_no_escribe_chat: con service_role no se crean conversaciones',
      detail = '{"error": "forbidden"}';
  end if;
  _id := public.api_mvk();
  if _id is null then
    if _c ?| array['mvf', 'mvk'] then
      raise exception using errcode = 'MV403',
        message = 'api_sesion_fabricada_sin_llave: una sesión fabricada sin key no escribe en el chat',
        detail = '{"error": "forbidden"}';
    end if;
    new.creada_por_api_key := null;
    return new;
  end if;

  _k := public.api_llave_valida(_id, true);
  perform public.api_escritura_habilitada();
  if not pg_try_advisory_xact_lock(hashtextextended('api_escritura:' || _k.id::text, 0)) then
    raise exception using errcode = 'MV429',
      message = 'api_escritura_en_curso: hay otro pedido de esta key en curso',
      detail = '{"limite": "concurrent_write", "reintentar_en": 1}';
  end if;
  if new.type is distinct from 'direct' or new.created_by is distinct from auth.uid() then
    raise exception using errcode = 'MV403',
      message = 'api_solo_directos: por API solo se abre un chat directo propio',
      detail = '{"error": "forbidden"}';
  end if;
  -- Margen contra el tope de lectura (500 conversaciones por persona) y contra las
  -- que abren sus propias keys.
  select count(*) into _n from (select 1 from public.chat_participants p where p.user_id = auth.uid() limit 450) x;
  if _n >= 450 then
    raise exception using errcode = 'MV422',
      message = 'api_demasiadas_conversaciones: la persona de la key ya está en 450 conversaciones',
      detail = '{"error": "too_many_conversations"}';
  end if;
  select count(*) into _n
    from (select 1 from public.chat_conversations c
            join public.api_keys k on k.id = c.creada_por_api_key
           where k.acts_as_user_id = auth.uid()
           limit 200) x;
  if _n >= 200 then
    raise exception using errcode = 'MV422',
      message = 'api_demasiadas_conversaciones: las keys de esta persona ya abrieron 200 conversaciones',
      detail = '{"error": "too_many_conversations"}';
  end if;
  perform public.api_cupo_gastar('llave:' || _k.id::text, _chats => 1);
  perform public.api_cupo_gastar('agencia:' || _k.tenant_id::text, _chats => 1);
  perform public.api_cupo_gastar('plataforma', _chats => 1);
  new.creada_por_api_key := _k.id;
  new.created_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_conversations_api"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_directo_con"("_otro" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select c.id
    from public.chat_participants yo
    join public.chat_conversations c on c.id = yo.conversation_id and c.type = 'direct'
    join public.chat_participants otro on otro.conversation_id = c.id and otro.user_id = _otro
    left join lateral (
      select m.created_at
        from public.chat_messages m
       where m.conversation_id = c.id
       order by m.created_at desc
       limit 1
    ) ultimo on true
   where yo.user_id = (select auth.uid())
     and _otro is distinct from (select auth.uid())
   order by ultimo.created_at desc nulls last, c.created_at asc, c.id asc
   limit 1
$$;


ALTER FUNCTION "public"."chat_directo_con"("_otro" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_evento_sistema"("_conv" "uuid", "_evento" "text", "_objetivo" "uuid" DEFAULT NULL::"uuid", "_texto" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  _uid uuid := auth.uid();
  _conversacion record;
  _actor text;
  _otro text;
  _nombre text;
  _contenido text;
  _id uuid := gen_random_uuid();
begin
  if _uid is null then
    raise exception 'chat_evento_sin_sesion: los avisos de sistema los manda una persona con sesión';
  end if;
  if _evento is null
     or _evento not in ('renombro', 'agrego', 'acepto', 'elimino', 'nombro_admin', 'quito_admin', 'salio') then
    raise exception 'chat_evento_desconocido: ese evento no existe';
  end if;

  -- Quien no participa no se entera de si la conversación existe.
  if not public.is_chat_participant(_uid, _conv) then
    raise exception 'chat_evento_no_autorizado: quien manda el aviso no participa de esa conversación';
  end if;
  select c.type, c.created_by, c.info_permission, c.add_permission into _conversacion
    from public.chat_conversations c
   where c.id = _conv;
  if _conversacion.type is distinct from 'group' then
    raise exception 'chat_evento_no_es_grupo: los avisos de sistema son de los grupos';
  end if;
  if not (public.is_chat_admin(_uid, _conv)
          or _evento = 'salio'
          or (_evento = 'agrego' and _conversacion.add_permission = 'all')
          or (_evento = 'renombro' and _conversacion.created_by = _uid
              and coalesce(_conversacion.info_permission, 'admins') = 'all')) then
    raise exception 'chat_evento_no_autorizado: ese aviso lo manda un admin del grupo';
  end if;

  -- La persona objetivo: la necesitan todos menos renombrar y salir.
  if _evento in ('renombro', 'salio') then
    if _objetivo is not null then
      raise exception 'chat_evento_objetivo: ese aviso no lleva persona objetivo';
    end if;
  else
    if _objetivo is null or not exists (select 1 from public.profiles p where p.id = _objetivo) then
      raise exception 'chat_evento_objetivo: ese aviso necesita a la persona a la que le pasó';
    end if;
    _otro := coalesce(nullif((select p.full_name from public.profiles p where p.id = _objetivo), ''), 'Usuario');
  end if;

  -- El único texto del pedido: el nombre nuevo del grupo.
  if _evento = 'renombro' then
    _nombre := regexp_replace(coalesce(_texto, ''),
      '[\u0001-\u001F\u007F-\u009F\u00AD\u061C\u180E\u200B-\u200F\u2028-\u202E\u2060-\u2064\u2066-\u206F\uFEFF]', '', 'g');
    _nombre := regexp_replace(_nombre,
      '^[[:space:]\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]+|[[:space:]\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]+$', '', 'g');
    if char_length(_nombre) not between 1 and 100 then
      raise exception 'chat_evento_texto: el nombre del grupo tiene que tener entre 1 y 100 caracteres';
    end if;
  elsif _texto is not null then
    raise exception 'chat_evento_texto: solo el cambio de nombre lleva texto';
  end if;

  -- Los rellenos son los de la app: «Alguien» al renombrar, «Usuario» al salir y
  -- «Admin» en lo demás (los hace un admin).
  _actor := coalesce(nullif((select p.full_name from public.profiles p where p.id = _uid), ''),
                     case _evento when 'renombro' then 'Alguien' when 'salio' then 'Usuario' else 'Admin' end);
  _contenido := case _evento
    when 'renombro'     then format('%s cambió el nombre del grupo a "%s"', _actor, _nombre)
    when 'agrego'       then format('%s agregó a %s al grupo', _actor, _otro)
    when 'acepto'       then format('%s aceptó a %s en el grupo', _actor, _otro)
    when 'elimino'      then format('%s eliminó a %s del grupo', _actor, _otro)
    when 'nombro_admin' then format('%s nombró admin a %s', _actor, _otro)
    when 'quito_admin'  then format('%s quitó admin a %s', _actor, _otro)
    when 'salio'        then format('%s salió del grupo', _actor)
  end;

  -- El permiso vale para ESTA fila y se apaga enseguida (local a la transacción).
  perform set_config('maven.evento_sistema', _id::text, true);
  insert into public.chat_messages (id, conversation_id, sender_id, type, content)
  values (_id, _conv, _uid, 'system', _contenido);
  perform set_config('maven.evento_sistema', '', true);
  return _id;
end;
$_$;


ALTER FUNCTION "public"."chat_evento_sistema"("_conv" "uuid", "_evento" "text", "_objetivo" "uuid", "_texto" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chat_evento_sistema"("_conv" "uuid", "_evento" "text", "_objetivo" "uuid", "_texto" "text") IS 'Avisos de sistema del Messenger: el texto lo arma la base con un evento (renombro, agrego, acepto, elimino, nombro_admin, quito_admin, salio) y los nombres de profiles. Lo único libre es el nombre nuevo del grupo, limpio.';



CREATE OR REPLACE FUNCTION "public"."chat_llave_de_par"("_a" "uuid", "_b" "uuid") RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select hashtextextended('chat_par:' || least(_a, _b)::text || ':' || greatest(_a, _b)::text, 0)
$$;


ALTER FUNCTION "public"."chat_llave_de_par"("_a" "uuid", "_b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_mensajes_de_sistema"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.type = 'system'
       and current_setting('maven.evento_sistema', true) is distinct from new.id::text then
      raise exception 'chat_sistema_sin_evento: los avisos de sistema los arma la base (chat_evento_sistema)';
    end if;
    return new;
  end if;
  if new.type = 'system' and old.type is distinct from 'system' then
    raise exception 'chat_sistema_sin_evento: un mensaje no pasa a ser un aviso de sistema';
  end if;
  if old.type = 'system'
     and (new.content is distinct from old.content or new.content_rich is distinct from old.content_rich)
     and not (new.is_deleted and not old.is_deleted and new.content is null and new.content_rich is null) then
    raise exception 'chat_sistema_inmutable: un aviso de sistema no se edita';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_mensajes_de_sistema"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_messages_al_insertar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return new;
  end if;
  new.created_at := now();
  new.is_edited := false;
  new.is_deleted := false;
  if new.reply_to_id is not null and not exists (
       select 1 from public.chat_messages r
        where r.id = new.reply_to_id and r.conversation_id = new.conversation_id) then
    raise exception using errcode = 'MV422',
      message = 'chat_cita_ajena: la cita tiene que ser un mensaje de la misma conversación';
  end if;
  if new.file_url is not null
     and new.file_url !~ '^https://lsagslbkliprespbyhts\.supabase\.co/storage/v1/object/public/chat-files/'
     and new.file_url !~ '^https://media[0-9]*\.giphy\.com/' then
    raise exception using errcode = 'MV422',
      message = 'chat_archivo_externo: el archivo de un mensaje tiene que estar en el almacenamiento de Maven';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_messages_al_insertar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_messages_api"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _c jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  _id uuid;
  _k public.api_keys;
  _t uuid;
  _cita_borrada boolean;
  _cita_en_hilo boolean;
  _n integer;
  _hay integer;
  _humanos integer;
  _personas integer;
  _desde timestamptz;
  _espera integer;
  _peso integer;
begin
  if _c ->> 'role' = 'service_role' then
    raise exception using errcode = 'MV403',
      message = 'api_service_role_no_escribe_chat: con service_role no se insertan mensajes',
      detail = '{"error": "forbidden"}';
  end if;
  _id := public.api_mvk();
  if _id is null then
    -- La app (y postgres sin claims). Las marcas no las pone el pedido.
    if _c ?| array['mvf', 'mvk'] then
      raise exception using errcode = 'MV403',
        message = 'api_sesion_fabricada_sin_llave: una sesión fabricada sin key no escribe en el chat',
        detail = '{"error": "forbidden"}';
    end if;
    new.api_key_id := null;
    new.api_display_name := null;
    return new;
  end if;

  -- ── La API ──
  _k := public.api_llave_valida(_id, true);
  perform public.api_escritura_habilitada();
  -- Reentrante: la RPC ya lo tiene. Un INSERT directo que llega mientras otro
  -- pedido de la misma key sigue en la base no espera: 429.
  if not pg_try_advisory_xact_lock(hashtextextended('api_escritura:' || _k.id::text, 0)) then
    raise exception using errcode = 'MV429',
      message = 'api_escritura_en_curso: hay otro pedido de esta key en curso',
      detail = '{"limite": "concurrent_write", "reintentar_en": 1}';
  end if;
  if new.sender_id is distinct from auth.uid() then
    raise exception using errcode = 'MV403',
      message = 'api_otro_autor: una key escribe a nombre de su persona',
      detail = '{"error": "forbidden"}';
  end if;
  -- Nunca un aviso de sistema: ni por INSERT directo ni por chat_evento_sistema
  -- (PR 1b, DEFINER), que inserta con la misma sesión y pasa por aquí.
  if new.type = 'system' then
    raise exception using errcode = 'MV403',
      message = 'api_sin_avisos_de_sistema: por API no se mandan avisos de sistema',
      detail = '{"error": "forbidden"}';
  end if;
  -- Solo texto plano (adjuntos, álbumes y texto rico quedan fuera de v1, §9).
  if new.type is distinct from 'text' or new.file_url is not null or new.file_name is not null
     or new.file_size is not null or new.album_id is not null or new.content_rich is not null then
    raise exception using errcode = 'MV422',
      message = 'api_solo_texto: por API solo se manda texto plano',
      detail = '{"error": "invalid_text"}';
  end if;
  new.content := public.api_texto_normalizado(new.content);
  if not public.api_texto_es_valido(new.content) then
    raise exception using errcode = 'MV422',
      message = 'api_texto_invalido: el texto tiene que tener de 1 a 4.000 caracteres, sin caracteres de control ni de dirección',
      detail = '{"error": "invalid_text"}';
  end if;
  new.is_edited := false;
  new.is_deleted := false;
  new.created_at := now();

  -- La conversación es de la agencia de la key (que sea participante lo decide la RLS).
  select c.tenant_id into _t from public.chat_conversations c where c.id = new.conversation_id;
  if not found or _t is distinct from _k.tenant_id then
    raise exception using errcode = 'MV404',
      message = 'api_conversacion_no_encontrada: esa conversación no existe para esta key',
      detail = '{"error": "conversation_not_found"}';
  end if;
  -- La cita: que sea de la misma conversación ya lo exige A (MV422 chat_cita_ajena).
  -- Aquí: que no esté borrada y que un hilo apunte a una raíz.
  if new.is_thread_reply and new.reply_to_id is null then
    raise exception using errcode = 'MV422',
      message = 'api_cita_invalida: una respuesta en hilo tiene que apuntar a un mensaje',
      detail = '{"error": "invalid_reply"}';
  end if;
  if new.reply_to_id is not null then
    select m.is_deleted, m.is_thread_reply into _cita_borrada, _cita_en_hilo
      from public.chat_messages m
     where m.id = new.reply_to_id and m.conversation_id = new.conversation_id;
    if not found or _cita_borrada or (new.is_thread_reply and _cita_en_hilo) then
      raise exception using errcode = 'MV422',
        message = 'api_cita_invalida: la cita no existe, está borrada o el hilo no apunta a una raíz',
        detail = '{"error": "invalid_reply"}';
    end if;
  end if;
  -- Tamaño: como mucho 50 personas.
  select count(*) into _n from (select 1 from public.chat_participants p where p.conversation_id = new.conversation_id limit 51) x;
  if _n > 50 then
    raise exception using errcode = 'MV422',
      message = 'api_conversacion_muy_grande: por API se escribe en conversaciones de hasta 50 personas',
      detail = '{"error": "conversation_too_large"}';
  end if;

  -- Por conversación, entre TODAS las keys: uno a la vez (espera como mucho el
  -- lock_timeout de la RPC), 6 por minuto, 150 por día de Bogotá y el corte de ronda.
  perform pg_advisory_xact_lock(hashtextextended('api_conv:' || new.conversation_id::text, 0));
  select count(*), min(u.created_at) into _hay, _desde
    from (select m.created_at from public.chat_messages m
           where m.conversation_id = new.conversation_id and m.api_key_id is not null
             and m.created_at > now() - interval '1 minute'
           order by m.created_at limit 6) u;
  if _hay >= 6 then
    _espera := greatest(ceil(extract(epoch from _desde + interval '1 minute' - now()))::integer, 1);
    raise exception using errcode = 'MV429',
      message = 'api_tope: se alcanzó el tope conversation_minute',
      detail = json_build_object('limite', 'conversation_minute', 'reintentar_en', _espera)::text;
  end if;
  _desde := (date_trunc('day', now() at time zone 'America/Bogota')) at time zone 'America/Bogota';
  select count(*) into _hay
    from (select 1 from public.chat_messages m
           where m.conversation_id = new.conversation_id and m.api_key_id is not null
             and m.created_at >= _desde
           limit 150) u;
  if _hay >= 150 then
    _espera := greatest(ceil(extract(epoch from _desde + interval '1 day' - now()))::integer, 1);
    raise exception using errcode = 'MV429',
      message = 'api_tope: se alcanzó el tope conversation_day',
      detail = json_build_object('limite', 'conversation_day', 'reintentar_en', _espera)::text;
  end if;
  -- La ronda entre integraciones: si los últimos 20 mensajes de la conversación son
  -- TODOS por API y de 2 personas o más, nadie humano está mirando. Se mide por
  -- persona, no por key: dos integraciones de la misma persona no se despiertan
  -- entre sí (exclude_own de los webhooks saca a la persona), y una sola integración
  -- que publica sola no se corta (la frenan conversation_day y los topes del día).
  select count(*), count(*) filter (where u.api_key_id is null), count(distinct u.sender_id)
    into _hay, _humanos, _personas
    from (select m.api_key_id, m.sender_id from public.chat_messages m
           where m.conversation_id = new.conversation_id
           order by m.created_at desc limit 20) u;
  if _hay = 20 and _humanos = 0 and _personas >= 2 then
    raise exception using errcode = 'MV429',
      message = 'api_ronda: los últimos 20 mensajes son de integraciones; hace falta que escriba una persona',
      detail = '{"limite": "conversation_loop", "reintentar_en": 3600}';
  end if;

  -- El costo: (N−1) destinatarios + 3 fijos (las escuchas de Realtime sin filtro).
  _peso := (_n - 1) + 3;
  perform public.api_cupo_gastar('llave:' || _k.id::text, _msj => 1, _dest => _peso);
  perform public.api_cupo_gastar('agencia:' || _k.tenant_id::text, _msj => 1, _dest => _peso);
  perform public.api_cupo_gastar('plataforma', _msj => 1, _dest => _peso);

  new.api_key_id := _k.id;
  new.api_display_name := _k.api_display_name;
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_messages_api"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_messages_api_editar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _c jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  _id uuid;
  _k public.api_keys;
  _borrado boolean;
begin
  new.api_key_id := old.api_key_id;
  new.api_display_name := old.api_display_name;
  _borrado := not old.is_deleted and new.is_deleted
              and current_setting('maven.borrado_autorizado', true) is not distinct from old.id::text;
  _id := public.api_mvk();
  if _id is null then
    if _c ?| array['mvf', 'mvk'] then
      raise exception using errcode = 'MV403',
        message = 'api_sesion_fabricada_sin_llave: una sesión fabricada sin key no escribe en el chat',
        detail = '{"error": "forbidden"}';
    end if;
    -- La app borra los mensajes por API de su persona (delete_chat_message), pero no
    -- los edita: quedaría bajo el nombre de la integración algo que ella no escribió.
    if old.api_key_id is not null and auth.uid() is not null and not _borrado
       and (new.content is distinct from old.content or new.content_rich is distinct from old.content_rich) then
      raise exception using errcode = 'MV403',
        message = 'api_mensaje_de_integracion: un mensaje que mandó una integración no se edita desde la app',
        detail = '{"error": "forbidden"}';
    end if;
    return new;
  end if;

  -- ── La API: solo lo que mandó la MISMA integración, también al borrar ──
  _k := public.api_llave_valida(_id, true);
  perform public.api_escritura_habilitada();
  if not pg_try_advisory_xact_lock(hashtextextended('api_escritura:' || _k.id::text, 0)) then
    raise exception using errcode = 'MV429',
      message = 'api_escritura_en_curso: hay otro pedido de esta key en curso',
      detail = '{"limite": "concurrent_write", "reintentar_en": 1}';
  end if;
  if old.sender_id is distinct from auth.uid() then
    raise exception using errcode = 'MV403',
      message = 'api_no_es_tuyo: ese mensaje es de otra persona',
      detail = '{"error": "not_your_message"}';
  end if;
  if old.api_key_id is null then
    raise exception using errcode = 'MV403',
      message = 'api_mensaje_escrito_a_mano: ese mensaje no lo mandó una integración',
      detail = '{"error": "not_an_api_message"}';
  end if;
  if not exists (select 1 from public.api_keys k where k.id = old.api_key_id and k.integracion_id = _k.integracion_id) then
    raise exception using errcode = 'MV403',
      message = 'api_otra_integracion: ese mensaje lo mandó otra integración',
      detail = '{"error": "other_integration_message"}';
  end if;
  if old.is_deleted then
    raise exception using errcode = 'MV409',
      message = 'api_mensaje_borrado: ese mensaje ya está borrado',
      detail = '{"error": "message_deleted"}';
  end if;
  if not _borrado then
    new.content := public.api_texto_normalizado(new.content);
    if not public.api_texto_es_valido(new.content) then
      raise exception using errcode = 'MV422',
        message = 'api_texto_invalido: el texto tiene que tener de 1 a 4.000 caracteres, sin caracteres de control ni de dirección',
        detail = '{"error": "invalid_text"}';
    end if;
    new.content_rich := null;
  end if;
  perform public.api_cupo_gastar('llave:' || _k.id::text, _edic => 1);
  perform public.api_cupo_gastar('agencia:' || _k.tenant_id::text, _edic => 1);
  perform public.api_cupo_gastar('plataforma', _edic => 1);
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_messages_api_editar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_participants_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  _uid uuid := auth.uid();
  _conv record;
  _hay int;
  _otro uuid;
begin
  if tg_op = 'UPDATE' then
    if new.user_id is distinct from old.user_id
       or new.conversation_id is distinct from old.conversation_id then
      raise exception 'chat_participacion_inmutable: una participación no se mueve de conversación ni cambia de persona';
    end if;
    return new;
  end if;

  select c.id, c.type, c.tenant_id, c.created_by into _conv
    from public.chat_conversations c
   where c.id = new.conversation_id;
  if not found then
    return new;  -- la FK la rechaza
  end if;

  -- La persona que entra, y quien la suma, son de la agencia de la conversación.
  if not exists (select 1 from public.tenant_members tm
                  where tm.user_id = new.user_id and tm.tenant_id = _conv.tenant_id) then
    raise exception 'chat_otra_agencia: esa persona no es de la agencia de la conversación';
  end if;
  if _uid is not null then
    if not exists (select 1 from public.tenant_members tm
                    where tm.user_id = _uid and tm.tenant_id = _conv.tenant_id) then
      raise exception 'chat_otra_agencia: quien suma no es de la agencia de la conversación';
    end if;

    -- Sin ser admin: a otro, solo como member (la política decide si se puede);
    -- a uno mismo, solo el creador en su conversación que nunca se usó (sin
    -- participantes Y sin mensajes). Así nadie vuelve solo a un grupo del que lo
    -- sacaron, ni el creador que se fue vuelve como admin a leer lo que se
    -- escribió después.
    if not public.is_chat_admin(_uid, new.conversation_id)
       and (new.role <> 'member' or new.user_id = _uid)
       and not (new.user_id = _uid
                and _conv.created_by = _uid
                and not exists (select 1 from public.chat_participants p
                                 where p.conversation_id = new.conversation_id)
                and not exists (select 1 from public.chat_messages m
                                 where m.conversation_id = new.conversation_id)) then
      raise exception 'chat_rol_no_autorizado: solo un admin suma admins, y a uno mismo solo se suma el creador al crear';
    end if;
  end if;

  if _conv.type = 'direct' then
    -- Uno a la vez por conversación: sin esto, dos altas simultáneas ven 1 y
    -- entran las dos. Las filas anteriores de la misma sentencia sí se ven.
    perform pg_advisory_xact_lock(hashtextextended('chat_directo:' || new.conversation_id::text, 0));
    select count(*) into _hay from public.chat_participants p where p.conversation_id = new.conversation_id;
    if _hay >= 2 then
      raise exception 'directo_lleno: un chat directo es de dos personas';
    end if;
    if _hay = 1 then
      select p.user_id into _otro from public.chat_participants p where p.conversation_id = new.conversation_id;
      if _otro is distinct from new.user_id then
        -- Uno a la vez por par: el segundo que llega ve el directo que el primero
        -- ya confirmó (foto nueva después del candado).
        perform pg_advisory_xact_lock(public.chat_llave_de_par(_otro, new.user_id));
        if exists (select 1
                     from public.chat_conversations c
                     join public.chat_participants a on a.conversation_id = c.id and a.user_id = _otro
                     join public.chat_participants b on b.conversation_id = c.id and b.user_id = new.user_id
                    where c.type = 'direct' and c.id <> new.conversation_id) then
          raise exception using errcode = 'MV409',
            message = 'directo_duplicado: ya hay un chat directo entre esas dos personas';
        end if;
      end if;
    end if;
    -- Un directo no cambia de interlocutor. Nadie saca al otro (la política
    -- DELETE, abajo), pero el otro puede irse solo, y sin esto el que queda suma a
    -- un tercero que lee la conversación entera, con las reacciones y los recibos
    -- de quien se fue. Entra solo quien no encuentra rastros de nadie más que de él
    -- y de quien ya está. La app nunca suma a nadie a un directo viejo: sus dos
    -- altas van antes del primer mensaje (y si el creador escribe antes de que
    -- termine el tercer paso, el mensaje es de quien ya está). Solo corre al sumar
    -- a un directo: en la app, un directo nuevo con 0 o 1 mensajes.
    if exists (select 1 from public.chat_messages m
                where m.conversation_id = new.conversation_id
                  and m.sender_id is distinct from new.user_id
                  and m.sender_id is distinct from _otro)
       or exists (select 1 from public.chat_messages m
                    join public.chat_reactions r on r.message_id = m.id
                   where m.conversation_id = new.conversation_id
                     and r.user_id is distinct from new.user_id
                     and r.user_id is distinct from _otro)
       or exists (select 1 from public.chat_messages m
                    join public.chat_read_receipts r on r.message_id = m.id
                   where m.conversation_id = new.conversation_id
                     and r.user_id is distinct from new.user_id
                     and r.user_id is distinct from _otro) then
      raise exception 'directo_con_historia_ajena: en este directo hay mensajes, reacciones o recibos de alguien que ya no está';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_participants_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_participants_api"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _c jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  _id uuid;
  _k public.api_keys;
  _abrio uuid;
  _abierta timestamptz;
begin
  if _c ->> 'role' = 'service_role' then
    raise exception using errcode = 'MV403',
      message = 'api_service_role_no_escribe_chat: con service_role no se suman participantes',
      detail = '{"error": "forbidden"}';
  end if;
  _id := public.api_mvk();
  if _id is null then
    if _c ?| array['mvf', 'mvk'] then
      raise exception using errcode = 'MV403',
        message = 'api_sesion_fabricada_sin_llave: una sesión fabricada sin key no escribe en el chat',
        detail = '{"error": "forbidden"}';
    end if;
    return new;
  end if;

  _k := public.api_llave_valida(_id, true);
  perform public.api_escritura_habilitada();
  if not pg_try_advisory_xact_lock(hashtextextended('api_escritura:' || _k.id::text, 0)) then
    raise exception using errcode = 'MV429',
      message = 'api_escritura_en_curso: hay otro pedido de esta key en curso',
      detail = '{"limite": "concurrent_write", "reintentar_en": 1}';
  end if;
  select c.creada_por_api_key, c.created_at into _abrio, _abierta from public.chat_conversations c where c.id = new.conversation_id;
  if not found or _abrio is distinct from _k.id or _abierta is distinct from now() then
    raise exception using errcode = 'MV403',
      message = 'api_no_suma_participantes: por API solo se suma gente al directo que se abre en el mismo pedido',
      detail = '{"error": "forbidden"}';
  end if;
  if new.user_id is distinct from auth.uid() and not public.api_persona_alcanzable(new.user_id, _k.tenant_id) then
    raise exception using errcode = 'MV404',
      message = 'api_persona_no_encontrada: a esa persona no se le puede escribir por API',
      detail = '{"error": "person_not_found"}';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."chat_participants_api"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_programado_cancelar"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r public.chat_programados;
begin
  -- La pared de la API (ver chat_programar).
  if (auth.jwt() ?| array['mvf', 'mvk']) is true then
    raise exception using errcode = 'MV403',
      message = 'api_programar_no_por_api: programar se hace desde Maven, no con una key',
      detail = '{"error": "forbidden"}';
  end if;
  update public.chat_programados
     set estado = 'cancelado', cerrado_en = now()
   where id = p_id and user_id = (select auth.uid()) and estado in ('pendiente', 'fallido')
  returning * into r;
  if r.id is null then return null; end if;
  return jsonb_build_object('id', r.id, 'conversation_id', r.conversation_id, 'enviar_en', r.enviar_en, 'mensajes', r.mensajes);
end $$;


ALTER FUNCTION "public"."chat_programado_cancelar"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_programado_revisar"("p_user" "uuid", "p_conversation" "uuid", "p_mensajes" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  m jsonb;
  tipo text;
begin
  if not public.is_chat_participant(p_user, p_conversation) then
    return 'ya no estás en esta conversación';
  end if;
  if exists (select 1 from public.chat_conversations c
              where c.id = p_conversation and c.type = 'group' and c.msg_permission = 'admins')
     and not public.is_chat_admin(p_user, p_conversation) then
    return 'en este grupo solo escriben los administradores';
  end if;
  if jsonb_typeof(p_mensajes) is distinct from 'array'
     or jsonb_array_length(p_mensajes) not between 1 and 20 then
    return 'el mensaje está vacío';
  end if;
  for m in select value from jsonb_array_elements(p_mensajes) loop
    if jsonb_typeof(m) is distinct from 'object' then return 'un mensaje viene con formato inválido'; end if;
    tipo := m ->> 'type';
    -- Nunca un aviso de sistema: esos los arma la base (chat_evento_sistema).
    if tipo is null or tipo not in ('text', 'image', 'file') then return 'un mensaje viene con un tipo inválido'; end if;
    if char_length(coalesce(m ->> 'content', '')) > 20000 then return 'un mensaje es demasiado largo'; end if;
    if tipo = 'text' and btrim(coalesce(m ->> 'content', '')) = '' then return 'el mensaje está vacío'; end if;
    if tipo <> 'text' and nullif(m ->> 'file_url', '') is null then return 'falta el archivo'; end if;
    -- Lo mismo que chat_messages_al_insertar, que sin sesión no corre.
    if nullif(m ->> 'file_url', '') is not null
       and (m ->> 'file_url') !~ '^https://lsagslbkliprespbyhts\.supabase\.co/storage/v1/object/public/chat-files/'
       and (m ->> 'file_url') !~ '^https://media[0-9]*\.giphy\.com/' then
      return 'el archivo tiene que estar en el almacenamiento de Maven';
    end if;
    if nullif(m ->> 'reply_to_id', '') is not null then
      if (m ->> 'reply_to_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         or not exists (select 1 from public.chat_messages r
                         where r.id = (m ->> 'reply_to_id')::uuid and r.conversation_id = p_conversation) then
        return 'el mensaje que respondes ya no está en esta conversación';
      end if;
    end if;
    if nullif(m ->> 'album_id', '') is not null
       and (m ->> 'album_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return 'un mensaje viene con formato inválido';
    end if;
  end loop;
  return null;
end $_$;


ALTER FUNCTION "public"."chat_programado_revisar"("p_user" "uuid", "p_conversation" "uuid", "p_mensajes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_programados_enviar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  m jsonb;
  motivo text;
  enviados integer := 0;
begin
  for r in
    select p.* from public.chat_programados p
     where p.estado = 'pendiente' and p.enviar_en <= now()
     order by p.enviar_en
     limit 50
     for update skip locked
  loop
    begin
      motivo := public.chat_programado_revisar(r.user_id, r.conversation_id, r.mensajes);
      if motivo is not null then raise exception '%', motivo using errcode = 'MV422'; end if;
      for m in select value from jsonb_array_elements(r.mensajes) loop
        insert into public.chat_messages (
          conversation_id, sender_id, content, type, file_url, file_name,
          reply_to_id, album_id, is_thread_reply, content_rich, created_at
        ) values (
          r.conversation_id, r.user_id, m ->> 'content', m ->> 'type',
          nullif(m ->> 'file_url', ''), nullif(m ->> 'file_name', ''),
          nullif(m ->> 'reply_to_id', '')::uuid, nullif(m ->> 'album_id', '')::uuid,
          coalesce((m ->> 'is_thread_reply')::boolean, false),
          nullif(m -> 'content_rich', 'null'::jsonb),
          -- clock_timestamp y no now(): en la misma transacción now() es UNO
          -- solo, y el texto y sus archivos empatarían en el orden del chat.
          clock_timestamp()
        );
      end loop;
      update public.chat_conversations set updated_at = now() where id = r.conversation_id;
      update public.chat_programados set estado = 'enviado', cerrado_en = now(), ultimo_error = null where id = r.id;
      enviados := enviados + 1;
    exception when others then
      update public.chat_programados
         set estado = 'fallido', cerrado_en = now(), ultimo_error = left(sqlerrm, 500)
       where id = r.id;
      insert into public.notifications (
        user_id, type, title, message, reference_id, reference_type,
        module_origin, priority, status, deep_link_url, required_permission_module
      ) values (
        r.user_id, 'chat_programado_fallido', 'No se pudo enviar tu mensaje programado',
        left(coalesce(nullif(r.resumen, ''), 'Mensaje') || ': ' || sqlerrm, 300),
        r.conversation_id, 'conversation', 'messenger', 'high', 'new',
        '/messenger?c=' || r.conversation_id, 'Messenger'
      );
    end;
  end loop;

  -- Lo que ya cumplió no se guarda para siempre.
  delete from public.chat_programados
   where estado in ('enviado', 'cancelado') and cerrado_en < now() - interval '30 days';
  return enviados;
end $$;


ALTER FUNCTION "public"."chat_programados_enviar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_programar"("p_conversation_id" "uuid", "p_enviar_en" timestamp with time zone, "p_mensajes" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  yo uuid := (select auth.uid());
  motivo text;
  nuevo uuid;
  primero jsonb;
begin
  if yo is null then raise exception 'chat_programar: hace falta una sesión' using errcode = '42501'; end if;
  -- La pared de la API: una función DEFINER no pasa por las políticas, así que
  -- una sesión fabricada con una key no puede usarla para escribir en el chat.
  if (auth.jwt() ?| array['mvf', 'mvk']) is true then
    raise exception using errcode = 'MV403',
      message = 'api_programar_no_por_api: programar se hace desde Maven, no con una key',
      detail = '{"error": "forbidden"}';
  end if;
  -- Unos segundos en el pasado se aceptan (el reloj siguió andando mientras se
  -- elegía); más, no. Y hasta un año, como el Correo.
  if p_enviar_en is null or p_enviar_en < now() - interval '5 minutes' then
    raise exception 'esa hora ya pasó' using errcode = 'MV422';
  end if;
  if p_enviar_en > now() + interval '366 days' then
    raise exception 'se puede programar hasta un año adelante' using errcode = 'MV422';
  end if;
  motivo := public.chat_programado_revisar(yo, p_conversation_id, p_mensajes);
  if motivo is not null then raise exception '%', motivo using errcode = 'MV422'; end if;
  if (select count(*) from public.chat_programados where user_id = yo and estado = 'pendiente') >= 100 then
    raise exception 'ya tienes 100 mensajes programados' using errcode = 'MV429';
  end if;

  -- El resumen de la lista: el texto (o el nombre del archivo) del primero que
  -- tenga algo que mostrar.
  select value into primero from jsonb_array_elements(p_mensajes)
   where coalesce(nullif(btrim(value ->> 'content'), ''), nullif(value ->> 'file_name', '')) is not null
   limit 1;
  insert into public.chat_programados (user_id, conversation_id, enviar_en, mensajes, resumen)
  values (
    yo, p_conversation_id, p_enviar_en, p_mensajes,
    left(coalesce(nullif(btrim(primero ->> 'content'), ''), primero ->> 'file_name', ''), 200)
  )
  returning id into nuevo;
  return nuevo;
end $$;


ALTER FUNCTION "public"."chat_programar"("p_conversation_id" "uuid", "p_enviar_en" timestamp with time zone, "p_mensajes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chatter_assignment_day"("_identity" "uuid", "_dia" "date") RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT max(dia) FROM public.chatter_creator_assignment_daily
      WHERE identity_id = _identity AND dia <= _dia),
    (SELECT min(dia) FROM public.chatter_creator_assignment_daily
      WHERE identity_id = _identity)
  );
$$;


