CREATE OR REPLACE FUNCTION "public"."chatter_model_backfill_tick"("_dias" integer DEFAULT 30, "_modelos_por_llamada" integer DEFAULT 6, "_llamadas" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token text;
  v_pendientes integer;
  v_disparados integer := 0;
  r record;
BEGIN
  SELECT decrypted_secret INTO v_token FROM vault.decrypted_secrets WHERE name = 'cron_internal_token';

  CREATE TEMP TABLE IF NOT EXISTS _pend (dia date, agency text, blu_model_id bigint) ON COMMIT DROP;
  INSERT INTO _pend
  SELECT d.dia, m.agency, m.blu_model_id
  FROM generate_series(
         ((now() AT TIME ZONE 'America/Bogota')::date - _dias),
         ((now() AT TIME ZONE 'America/Bogota')::date - 1),
         '1 day') AS d(dia)
  CROSS JOIN (
    SELECT DISTINCT agency, blu_model_id FROM public.chatter_creator_assignment_daily
  ) m
  WHERE NOT EXISTS (
    SELECT 1 FROM public.chatter_model_daily_sync s
    WHERE s.dia = d.dia AND s.agency = m.agency AND s.blu_model_id = m.blu_model_id
  );

  SELECT count(*) INTO v_pendientes FROM _pend;
  IF v_pendientes = 0 THEN
    RETURN jsonb_build_object('pendientes', 0, 'disparados', 0, 'listo', true);
  END IF;

  -- Se agrupa por DIA + AGENCIA: cada llamada pide varias modelos del mismo día
  -- y de la misma empresa, que es como la edge function espera el lote.
  FOR r IN
    WITH orden AS (
      SELECT dia, agency, blu_model_id,
             row_number() OVER (PARTITION BY dia, agency ORDER BY blu_model_id) AS n
      FROM _pend
    ),
    lotes AS (
      SELECT dia, agency, ((n - 1) / _modelos_por_llamada) AS lote, jsonb_agg(blu_model_id) AS ids
      FROM orden GROUP BY dia, agency, ((n - 1) / _modelos_por_llamada)
    )
    SELECT dia, agency, ids FROM lotes ORDER BY dia DESC, agency, lote LIMIT _llamadas
  LOOP
    PERFORM net.http_post(
      url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/chatter-sync',
      headers := jsonb_build_object('Content-Type', 'application/json', 'X-Cron-Token', v_token),
      body := jsonb_build_object('action', 'model-day', 'dia', r.dia,
                                 'agency', r.agency, 'modelIds', r.ids),
      timeout_milliseconds := 150000
    );
    v_disparados := v_disparados + 1;
  END LOOP;

  RETURN jsonb_build_object('pendientes', v_pendientes, 'disparados', v_disparados, 'listo', false);
END $$;


ALTER FUNCTION "public"."chatter_model_backfill_tick"("_dias" integer, "_modelos_por_llamada" integer, "_llamadas" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chatter_model_backfill_tick"("_dias" integer, "_modelos_por_llamada" integer, "_llamadas" integer) IS 'Trae un pedazo del historico chatter-modelo desde BLU. Idempotente: se guia por chatter_model_daily_sync, asi que se puede cortar y retomar. La captura diaria es higiene, no urgencia: BLU no borra el detalle (ver correccion_no_es_caducidad_es_migracion).';



CREATE OR REPLACE FUNCTION "public"."chatter_model_baseline"("_blu_model_id" bigint, "_hasta" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH v AS (
    SELECT ventana_desde, ventana_hasta, sum(sales) AS total,
           count(DISTINCT identity_id) AS chatters
    FROM public.chatter_model_window
    WHERE blu_model_id = _blu_model_id AND ventana_hasta <= _hasta
    GROUP BY ventana_desde, ventana_hasta
    ORDER BY ventana_hasta DESC
    LIMIT 1
  )
  -- Promedio diario de la modelo, repartido entre quienes la atienden: es el
  -- "1/3" de Jhon, pero calculado con los chatters que de verdad la cubrieron
  -- en la ventana en vez de asumir siempre tres turnos.
  SELECT CASE
           WHEN v.chatters = 0 THEN NULL
           ELSE (v.total / GREATEST(1, (v.ventana_hasta - v.ventana_desde) + 1)) / v.chatters
         END
  FROM v;
$$;


ALTER FUNCTION "public"."chatter_model_baseline"("_blu_model_id" bigint, "_hasta" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chatter_model_baseline"("_blu_model_id" bigint, "_hasta" "date") IS 'Vara de UN chatter en UNA modelo por dia: promedio diario de la modelo dividido entre los chatters que la atendieron. Exigirle el total seria cobrarle el trabajo de los otros turnos.';



CREATE OR REPLACE FUNCTION "public"."chatter_model_baseline"("_blu_model_id" bigint, "_hasta" "date", "_dias" integer DEFAULT 30) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH por_dia AS (
    SELECT c.dia,
           sum(c.sales) AS total_dia,
           count(DISTINCT c.identity_id) AS chatters_dia
    FROM public.chatter_model_daily c
    WHERE c.blu_model_id = _blu_model_id
      AND c.dia <= _hasta AND c.dia > _hasta - _dias
    GROUP BY c.dia
  )
  -- Promedio, entre los dias con registro, de lo que produjo UN chatter.
  SELECT AVG(total_dia / GREATEST(1, chatters_dia)) FROM por_dia;
$$;


ALTER FUNCTION "public"."chatter_model_baseline"("_blu_model_id" bigint, "_hasta" "date", "_dias" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chatter_model_baseline"("_blu_model_id" bigint, "_hasta" "date", "_dias" integer) IS 'Vara de UN chatter en UNA modelo por dia: promedio, sobre los dias CON REGISTRO, del total de la modelo repartido entre los chatters que la atendieron. OJO: mientras dure la migracion desde Infloww esta vara sale de pocos dias y pocas personas — es provisional, no sirve para evaluar.';



CREATE OR REPLACE FUNCTION "public"."chatter_model_baseline"("_blu_model_id" bigint, "_hasta" "date", "_dias" integer DEFAULT 30, "_agency" "text" DEFAULT NULL::"text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH por_dia AS (
    SELECT c.dia,
           sum(c.sales) AS total_dia,
           count(DISTINCT c.identity_id) AS chatters_dia
    FROM public.chatter_model_daily c
    WHERE c.blu_model_id = _blu_model_id
      AND c.dia <= _hasta AND c.dia > _hasta - _dias
      AND (_agency IS NULL OR c.agency = _agency)
    GROUP BY c.dia
  )
  -- Promedio, entre los dias con registro, de lo que produjo UN chatter.
  SELECT AVG(total_dia / GREATEST(1, chatters_dia)) FROM por_dia;
$$;


