CREATE OR REPLACE FUNCTION "public"."chatter_rest_days_copy_week"("_agency" "text", "_from_week" "date", "_to_week" "date", "_rotate" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  IF NOT public.chatter_horarios_gestiona(auth.uid()) THEN RAISE EXCEPTION 'Sin permiso para gestionar horarios'; END IF;
  IF EXISTS (SELECT 1 FROM public.chatter_rest_days WHERE agency = _agency AND week_start = _to_week) THEN
    RAISE EXCEPTION 'La semana destino ya tiene descansos cargados';
  END IF;
  INSERT INTO public.chatter_rest_days (week_start, agency, weekday, shift, identity_id, covered_by_identity_id, note, created_by)
  SELECT _to_week, agency,
         CASE WHEN _rotate AND identity_id IS NOT NULL THEN (weekday + 1) % 7 ELSE weekday END,
         shift, identity_id, covered_by_identity_id,
         CASE WHEN identity_id IS NULL THEN NULL ELSE note END, auth.uid()
  FROM public.chatter_rest_days WHERE agency = _agency AND week_start = _from_week AND identity_id IS NOT NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


