CREATE OR REPLACE FUNCTION "public"."chatter_score_from_scale"("_escala" "jsonb", "_ratio" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(
    (SELECT (e->>'nota')::numeric
     FROM jsonb_array_elements(_escala) e
     WHERE _ratio >= (e->>'ratio')::numeric
     ORDER BY (e->>'ratio')::numeric DESC
     LIMIT 1),
    0);
$$;


