CREATE OR REPLACE FUNCTION "public"."chatter_ventas_del_dia"("_identity" "uuid", "_dia" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    -- Tuvo actividad registrada ese dia: la suma es la verdad, incluso si es 0.
    (SELECT SUM(c.sales) FROM public.chatter_model_daily c
      WHERE c.identity_id = _identity AND c.dia = _dia
      HAVING count(*) > 0),
    -- Dia sin cruce ingerido: se cae al reporte de ventas de BLU.
    (SELECT SUM(d.total_sales) FROM public.chatter_daily_sales d
      JOIN public.chatter_identity_link l
        ON l.external_id = d.blu_employee_id::text
       AND l.source = 'blu' AND l.valid_to IS NULL
      WHERE l.identity_id = _identity AND d.date = _dia)
  );
$$;


ALTER FUNCTION "public"."chatter_ventas_del_dia"("_identity" "uuid", "_dia" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chatter_ventas_del_dia"("_identity" "uuid", "_dia" "date") IS 'Ventas de un chatter en un dia. Prefiere chatter_model_daily: BLU solo lista en su reporte de ventas a quien vendio, asi que quien trabajo y vendio cero no tiene fila y se leeria como "sin datos". NULL solo si no hay ninguna de las dos fuentes.';



CREATE OR REPLACE FUNCTION "public"."check_closer_contact_alerts"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  cadence int[] := ARRAY[1, 3, 5, 8, 15, 29];
  rec RECORD;
  contact_count int;
  last_contact date;
  next_idx int;
  gap int;
  deadline_date date;
  handle text;
BEGIN
  FOR rec IN
    SELECT cc.id, cc.assigned_to, cc.passed_date, cc.instagram_handle
    FROM public.closer_creators cc
    WHERE cc.stage = 'Asignada'
      AND cc.assigned_to IS NOT NULL
      AND cc.passed_date IS NOT NULL
  LOOP
    SELECT count(*), max(contact_date)::date INTO contact_count, last_contact
    FROM public.closer_contact_history
    WHERE creator_id = rec.id;

    handle := COALESCE(rec.instagram_handle, 'sin handle');

    IF contact_count >= 6 THEN
      INSERT INTO public.notifications (
        user_id, type, title, message, reference_id, reference_type,
        module_origin, priority, status, deep_link_url,
        required_permission_module, automation_key
      ) VALUES (
        rec.assigned_to,
        'closer_contact_decision',
        'Decisión pendiente',
        '6 contactos hechos a @' || handle || '. Sigues o marcas No interesada?',
        rec.id,
        'closer_creator',
        'closers',
        'medium',
        'new',
        '/closers?id=' || rec.id::text,
        'Closers',
        'closer_contact_decision:' || rec.id::text
      )
      ON CONFLICT (automation_key) WHERE automation_key IS NOT NULL DO NOTHING;
      CONTINUE;
    END IF;

    next_idx := contact_count + 1;
    IF contact_count = 0 THEN
      deadline_date := rec.passed_date + cadence[1];
    ELSE
      gap := cadence[next_idx] - cadence[contact_count];
      deadline_date := COALESCE(last_contact, rec.passed_date) + gap;
    END IF;

    IF current_date > deadline_date THEN
      INSERT INTO public.notifications (
        user_id, type, title, message, reference_id, reference_type,
        module_origin, priority, status, deep_link_url,
        required_permission_module, automation_key
      ) VALUES (
        rec.assigned_to,
        'closer_contact_overdue',
        'Contacto vencido',
        '@' || handle || ': contacto ' || next_idx::text ||
          ' venció ' || to_char(deadline_date, 'DD/MM') || '.',
        rec.id,
        'closer_creator',
        'closers',
        'high',
        'new',
        '/closers?id=' || rec.id::text,
        'Closers',
        'closer_contact_overdue:' || rec.id::text || ':' || next_idx::text
      )
      ON CONFLICT (automation_key) WHERE automation_key IS NOT NULL DO NOTHING;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."check_closer_contact_alerts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_whatsapp_verification_code"("p_code" "text", "p_lid" "text", "p_push_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_user_id uuid; v_code_id uuid;
BEGIN
  IF p_code IS NULL OR length(trim(p_code)) = 0 THEN RETURN NULL; END IF;
  SELECT id, user_id INTO v_code_id, v_user_id
  FROM public.whatsapp_verification_codes
  WHERE upper(code) = upper(trim(p_code)) AND used_at IS NULL AND expires_at > now()
  LIMIT 1;
  IF v_user_id IS NULL THEN RETURN NULL; END IF;
  UPDATE public.whatsapp_verification_codes SET used_at = now() WHERE id = v_code_id;
  UPDATE public.profiles
  SET whatsapp_lid = p_lid, whatsapp_push_name = p_push_name, whatsapp_verified_at = now()
  WHERE id = v_user_id;
  RETURN v_user_id;
END;
$$;


ALTER FUNCTION "public"."claim_whatsapp_verification_code"("p_code" "text", "p_lid" "text", "p_push_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clean_whatsapp_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare d text;
begin
  if new.whatsapp_number is null then return new; end if;
  d := regexp_replace(new.whatsapp_number, '[^0-9]', '', 'g');
  new.whatsapp_number := case when length(d) >= 8 then '+' || d else null end;
  return new;
end;
$$;


