CREATE OR REPLACE FUNCTION "public"."cleanup_duplicate_leadgen_entries"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  deleted_count integer;
  target_ids uuid[];
BEGIN
  -- 1) Identificar IDs a borrar: dups (no más recientes por handle),
  --    >7 días, no referenciados por closer_creators.
  SELECT array_agg(id) INTO target_ids
  FROM (
    SELECT id, model_handle, created_at,
      ROW_NUMBER() OVER (PARTITION BY model_handle ORDER BY created_at DESC) AS rn
    FROM leadgen_entries
  ) ranked
  WHERE rn > 1
    AND created_at < NOW() - INTERVAL '7 days'
    AND NOT EXISTS (
      SELECT 1 FROM closer_creators cc WHERE cc.leadgen_entry_id = ranked.id
    );

  IF target_ids IS NULL OR array_length(target_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;

  -- 2) Cleanup manual de hijos lógicos sin FK formal.
  DELETE FROM leadgen_alerts          WHERE entry_id          = ANY(target_ids);
  DELETE FROM leadgen_files           WHERE entry_id          = ANY(target_ids);
  DELETE FROM leadgen_notes           WHERE entry_id          = ANY(target_ids);
  DELETE FROM leadgen_qa              WHERE entry_id          = ANY(target_ids);
  DELETE FROM leadgen_qa_feedback     WHERE entry_id          = ANY(target_ids);
  DELETE FROM leadgen_evidence_files  WHERE leadgen_entry_id  = ANY(target_ids);

  -- 3) Borrar los entries. closers_contacts.leadgen_entry_id queda NULL
  --    (FK ON DELETE SET NULL).
  DELETE FROM leadgen_entries WHERE id = ANY(target_ids);
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_duplicate_leadgen_entries"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_duplicate_leadgen_entries"() IS 'Cleanup mensual de leadgen_entries duplicados >7 días. Mantiene el más reciente por model_handle. No toca entries vinculados a closer_creators.';



CREATE OR REPLACE FUNCTION "public"."cleanup_old_scouter_jobs"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM scouter_jobs
  WHERE status IN ('done', 'failed')
    AND COALESCE(completed_at, created_at) < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_scouter_jobs"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_old_scouter_jobs"() IS 'Borra scouter_jobs done/failed con >30 días para mantener la tabla chica. Llamado por cron mensual.';



CREATE OR REPLACE FUNCTION "public"."closer_calls_count"("p_closer_id" "uuid", "p_since" "date" DEFAULT (("now"() - '1 day'::interval))::"date") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COUNT(DISTINCT p.call_id)::integer
  FROM public.qa_call_participants p
  JOIN public.qa_calls c ON c.id = p.call_id
  WHERE p.closer_id = p_closer_id
    AND c.call_date >= p_since;
$$;


