CREATE OR REPLACE FUNCTION "public"."closer_scope_agent_ids"() RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select case
    -- Manager o superior: sin restricción (no toca nada de lo que ya existía).
    when exists (
      select 1 from public.user_roles ur
      join public.role_groups rg on rg.role_name = ur.role::text and rg.tenant_id = ur.tenant_id
      where ur.user_id = auth.uid() and rg.is_manager_or_above
    ) then null
    -- Closer Supervisor: él mismo + todos los que NO son supervisores
    -- (closers rasos, LLG, agents). Excluye a sus pares y a quien esté por encima.
    when exists (
      select 1 from public.user_roles ur
      where ur.user_id = auth.uid() and ur.role::text = 'Closer Supervisor'
    ) then (
      select array_agg(distinct p.id)
      from public.profiles p
      where p.id = auth.uid()
         or not exists (
              select 1 from public.user_roles ur2
              join public.role_groups rg2 on rg2.role_name = ur2.role::text and rg2.tenant_id = ur2.tenant_id
              where ur2.user_id = p.id and rg2.is_supervisor_or_above
            )
    )
    -- Cualquier otro rol: sin cambios respecto de lo que ya hacía el frontend.
    else null
  end
$$;


ALTER FUNCTION "public"."closer_scope_agent_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."closers_autolog_contact"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_lead uuid;
  v_channel text;
  v_cnt int;
begin
  if NEW.direction <> 'out' or NEW.sender_user_id is null then
    return NEW;
  end if;

  if TG_TABLE_NAME = 'wa_conversation_messages' then
    v_channel := 'WhatsApp';
    select wc.closer_creator_id into v_lead
    from public.wa_conversations conv
    join public.wa_contacts wc on wc.id = conv.contact_id
    where conv.id = NEW.conversation_id;
  else
    v_channel := 'Telegram';
    select tc.closer_creator_id into v_lead
    from public.tg_conversations tc
    where tc.id = NEW.conversation_id;
  end if;

  if v_lead is null then
    return NEW;
  end if;

  if exists (
    select 1 from public.closer_contact_history
    where creator_id = v_lead and channel = v_channel and contact_date::date = current_date
  ) then
    return NEW;
  end if;

  select count(*) into v_cnt from public.closer_contact_history where creator_id = v_lead;
  if v_cnt >= 6 then
    return NEW;
  end if;

  insert into public.closer_contact_history (creator_id, channel, result, notes, created_by)
  values (v_lead, v_channel, 'Pendiente', '(auto)', NEW.sender_user_id);

  return NEW;
exception when others then
  return NEW;
end;
$$;


ALTER FUNCTION "public"."closers_autolog_contact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."conexiones_estado"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'solo el dueño' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'crons', (
      with ultima as (
        select distinct on (d.jobid) d.jobid, d.status, d.start_time, left(d.return_message, 200) as mensaje
          from cron.job_run_details d
         where d.start_time > now() - interval '26 hours'
         order by d.jobid, d.start_time desc
      )
      select jsonb_build_object(
        'activos', (select count(*) from cron.job where active),
        'fallando', coalesce((
          select jsonb_agg(jsonb_build_object('job', j.jobname, 'mensaje', u.mensaje,
                   'hace_min', round(extract(epoch from now() - u.start_time) / 60)) order by j.jobname)
            from cron.job j join ultima u on u.jobid = j.jobid
           where j.active and u.status = 'failed'), '[]'::jsonb),
        'apagados', coalesce((select jsonb_agg(jobname order by jobname) from cron.job where not active), '[]'::jsonb)
      )),
    'correo_equipo', (
      select jsonb_build_object(
        'conectadas', count(*),
        'con_error', count(*) filter (where last_error is not null),
        'sin_sincronizar', count(*) filter (where last_sync_at is null or last_sync_at < now() - interval '30 minutes'))
        from public.mail_credentials where revoked_at is null),
    'backstage', jsonb_build_object(
      'llaves', (select count(*) from public.api_keys where 'equipo:write' = any(scopes)),
      'ultimo_envio', (select max(created_at) from public.integracion_equipo_syncs)),
    'llamadas', jsonb_build_object(
      'cortes_1h', (select count(*) from public.llamada_cortes where creado > now() - interval '1 hour' and fase not in ('reentrada_ok')),
      'midiendo_1h', (select count(distinct user_id) from public.llamada_salud where creado > now() - interval '1 hour')),
    'subidas', (
      select jsonb_build_object(
        'ok_24h', count(*) filter (where estado = 'ok'),
        'fallo_24h', count(*) filter (where estado = 'fallo'),
        'trabadas', count(*) filter (where estado in ('subiendo', 'pausado') and actualizado_at < now() - interval '15 minutes'))
        from public.drive_aportar_intentos where iniciado_at > now() - interval '24 hours'),
    'nas', (select to_jsonb(s) - 'id' from public.drive_nas_salud s where s.id = 1),
    'incidentes', coalesce((
      select jsonb_agg(jsonb_build_object('tipo', tipo, 'mensaje', mensaje, 'desde', abierto_at) order by abierto_at)
        from public.salud_incidentes where cerrado_at is null), '[]'::jsonb),
    'hubstaff', (select jsonb_build_object('activo', sync_enabled, 'ultimo', last_sync_at) from public.hubstaff_config limit 1)
  ) into v;
  return v;
end $$;


ALTER FUNCTION "public"."conexiones_estado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consejo_de_llamada"("_causa" "text", "_kbps" integer, "_rtt" integer, "_perdida" numeric) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case _causa
    when 'computador' then 'Tu computador no da abasto con la llamada y se traba. Cierra los programas y pestañas que no uses; si sigue, avísale a tu supervisor.'
    when 'internet_subida' then format('Tu internet de subida no alcanza%s. Acércate al router o conéctate por cable, y que nadie más en tu casa esté subiendo videos.',
                                       case when _kbps is not null then format(' (unos %s kbps)', _kbps) else '' end)
    when 'internet_inestable' then format('Tu internet está inestable%s. Acércate al router, conéctate por cable o reinicia el módem.',
                                          case when _rtt is not null then format(' (ping %s ms, pérdida %s %%)', _rtt, coalesce(_perdida, 0)) else '' end)
    when 'pestana_dormida' then 'Tu navegador está dejando dormida la pestaña de Maven. En Chrome: Configuración → Rendimiento → agrega app.maven-ai.me a «Mantener siempre activos estos sitios».'
    when 'recargas' then 'La página de Maven se te recargó varias veces. Cierra las otras pestañas de Maven y deja una sola abierta.'
    else 'Todavía no encontramos una causa clara. Si sigue, avísale a tu supervisor.'
  end;
$$;


ALTER FUNCTION "public"."consejo_de_llamada"("_causa" "text", "_kbps" integer, "_rtt" integer, "_perdida" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contact_filter_agents"() RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select c.created_by, max(p.full_name)
  from public.closers_contacts c
  join public.profiles p on p.id = c.created_by
  where c.created_by is not null
  group by c.created_by
  having max(p.full_name) is not null and btrim(max(p.full_name)) <> ''
  order by 2;
$$;


ALTER FUNCTION "public"."contact_filter_agents"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contact_filter_cities"() RETURNS SETOF "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select distinct btrim(cr.city)
  from public.closers_contacts cc
  join public.creadoras_de_mi_agencia() cr
    on lower(regexp_replace(coalesce(cr.instagram_handle,''),'^@','')) =
       lower(regexp_replace(coalesce(cc.handle,''),'^@',''))
  where cr.city is not null and btrim(cr.city) <> ''
    and cc.handle is not null and btrim(cc.handle) <> ''
  order by 1;
$$;


ALTER FUNCTION "public"."contact_filter_cities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contact_ids_by_city"("p_city" "text") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select cc.id
  from public.closers_contacts cc
  join public.creadoras_de_mi_agencia() cr
    on lower(regexp_replace(coalesce(cr.instagram_handle,''),'^@','')) =
       lower(regexp_replace(coalesce(cc.handle,''),'^@',''))
  where btrim(cr.city) = btrim(p_city)
    and cc.handle is not null and btrim(cc.handle) <> ''
    and cr.instagram_handle is not null and btrim(cr.instagram_handle) <> '';
$$;


ALTER FUNCTION "public"."contact_ids_by_city"("p_city" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_contact_to_creator"("p_contact_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_c   public.closers_contacts%rowtype;
  v_new uuid;
  v_norm text;
begin
  if v_uid is null then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v_c from public.closers_contacts where id = p_contact_id;
  if not found then raise exception 'contact_not_found'; end if;
  if v_c.handle is null or btrim(v_c.handle) = '' then raise exception 'missing_handle'; end if;
  v_norm := lower(regexp_replace(v_c.handle, '.*instagram\.com/|[@/ ]', '', 'gi'));
  if exists (
    select 1 from public.creadoras_de_mi_agencia()
    where status is distinct from 'terminated'
      and lower(regexp_replace(coalesce(instagram_handle,''), '.*instagram\.com/|[@/ ]', '', 'gi')) = v_norm
  ) then
    raise exception 'creator_already_exists'
      using errcode = '23505', hint = 'Ya existe una creadora con ese Instagram (' || v_c.handle || ').';
  end if;
  insert into public.creators (
    name, instagram_handle, country, category, phone, country_code, email,
    profile_photo_url, source, status, internal_notes, created_by
  ) values (
    v_c.name, v_c.handle, v_c.country_code, v_c.physical_appearance, v_c.phone,
    v_c.country_code, v_c.email, v_c.profile_picture_url, 'contacto', 'pendiente',
    case when v_c.company is not null then 'Compañía: ' || v_c.company else null end, v_uid
  ) returning id into v_new;
  update public.closers_contacts set status = 'converted' where id = p_contact_id;
  return v_new;
end; $$;


ALTER FUNCTION "public"."convert_contact_to_creator"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_scouter_lead"("p_lead_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_uid uuid := auth.uid(); l public.scouter_leads%rowtype; v_contact uuid;
begin
  if v_uid is null then raise exception 'forbidden' using errcode='42501'; end if;
  select * into l from public.scouter_leads
    where id = p_lead_id and tenant_id = public.current_tenant_id();
  if not found then raise exception 'lead_not_found'; end if;
  insert into public.closers_contacts (name, handle, platform, city, phone, onlyfans_url, profile_picture_url, source, ticket_number, created_by)
  values (coalesce(l.name, l.instagram_handle), l.instagram_handle, coalesce(l.platform,'instagram'), l.city,
          l.phone, l.onlyfans_url, l.photo_data_url, 'scouter', '#SC' || upper(right(l.id::text, 7)), v_uid)
  returning id into v_contact;
  update public.scouter_leads
    set converted_at = now(), converted_to_contact_id = v_contact, status = 'contacting'
    where id = p_lead_id;
  return v_contact;
end; $$;


ALTER FUNCTION "public"."convert_scouter_lead"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."correo_destinatarios_de_agencia"("p_quien" "uuid", "p_user_ids" "uuid"[], "p_correos" "text"[]) RETURNS TABLE("user_id" "uuid", "email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with agencia as (
    select tm.tenant_id from public.tenant_members tm
    where tm.user_id = p_quien
    order by tm.created_at asc
    limit 1
  ),
  pedidos as (
    select lower(btrim(c)) as correo from unnest(coalesce(p_correos, '{}'::text[])) as c
  )
  select distinct u.id, lower(u.email)::text
  from auth.users u
  join public.tenant_members tm on tm.user_id = u.id and tm.tenant_id = (select tenant_id from agencia)
  where u.email is not null
    and u.deleted_at is null
    and (u.id = any(coalesce(p_user_ids, '{}'::uuid[]))
         or lower(u.email) in (select correo from pedidos))
$$;


ALTER FUNCTION "public"."correo_destinatarios_de_agencia"("p_quien" "uuid", "p_user_ids" "uuid"[], "p_correos" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."correo_destinatarios_de_agencia"("p_quien" "uuid", "p_user_ids" "uuid"[], "p_correos" "text"[]) IS 'De esos ids y esas direcciones, las cuentas de Maven de la misma agencia que p_quien (id y correo). Solo service_role: la usa send-notification-email para no mandar nunca a una dirección suelta.';



CREATE OR REPLACE FUNCTION "public"."correo_navegador_turno"("p_user" "uuid", "p_plantilla" "text", "p_ref" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tope constant int := 5;
  v_recientes int;
begin
  if p_user is null then
    return false;
  end if;
  -- Un pedido a la vez por persona: sin esto, dos pedidos simultáneos cuentan
  -- los dos «4 en el último minuto» y pasan los dos.
  perform pg_advisory_xact_lock(hashtextextended('correo_navegador_turno:' || p_user::text, 0));
  select count(*) into v_recientes
  from public.correo_envios_navegador
  where user_id = p_user and created_at > now() - interval '1 minute';
  if v_recientes >= v_tope then
    return false;
  end if;
  insert into public.correo_envios_navegador (user_id, plantilla, ref) values (p_user, p_plantilla, p_ref);
  return true;
end
$$;


ALTER FUNCTION "public"."correo_navegador_turno"("p_user" "uuid", "p_plantilla" "text", "p_ref" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."correo_navegador_turno"("p_user" "uuid", "p_plantilla" "text", "p_ref" "text") IS 'Tope de correos de aviso pedidos desde el navegador: 5 por minuto por persona. true = puede mandar (y queda anotado). Solo service_role.';



CREATE OR REPLACE FUNCTION "public"."corte_cierre_prep"("p_group_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant uuid := '30869615-f579-4981-8a1f-dbebc61eae2d';
  v_hoy date := (now() at time zone 'America/Bogota')::date;
  v_ini timestamptz := (now() at time zone 'America/Bogota')::date::timestamp at time zone 'America/Bogota';
  v_es_viernes boolean := extract(dow from (now() at time zone 'America/Bogota'))::int = 5;
  v_es_sabado boolean := extract(dow from (now() at time zone 'America/Bogota'))::int = 6;
  v_fr_max int;
  v_hub_ref numeric;
  v_personas jsonb;
  v_equipo numeric;
  v_empresa numeric;
  v_semana jsonb;
begin
  v_fr_max := case when v_es_sabado then 2 else 5 end;
  v_hub_ref := case when v_es_sabado then 3.5 else 7.0 end;

  with grupos_corte as (
    select unnest(array[
      'a12d9f41-c962-4d98-b0bb-6b2d2573534c',
      '73a4414e-2546-4ca7-9289-7cbec70b0273',
      'd12ec56f-b324-4369-b72d-7540fb930ef6'
    ]::uuid[]) as gid
  ),
  todos_miembros as (
    select g.gid as group_id, p.id as pid,
           split_part(coalesce(nullif(p.full_name,''), min(m.display_name)),' ',1) as nombre,
           min(m.created_at) as member_since
    from grupos_corte g
    join whatsapp_members m on m.group_id = g.gid and coalesce(m.active, true)
    join profiles p on p.id = m.user_id
    where not public.has_role(p.id, 'admin'::app_role)
      and p.id not in (select profile_id from public.corte_notas_excluidos)
    group by 1, 2, p.full_name
  ),
  habla as (
    select w.group_id, mm.user_id as pid, count(*) as msgs
    from whatsapp_messages w
    join whatsapp_members mm on mm.group_id = w.group_id and mm.external_id = w.sender_external_id
    where w.group_id in (select gid from grupos_corte)
      and w.is_from_bot = false and w.sent_at >= v_ini
      and length(coalesce(nullif(w.body,''), w.transcribed_text, '')) > 15
    group by 1, 2
  ),
  casa as (
    select pid, group_id from (
      select tm.pid, tm.group_id,
             row_number() over (
               partition by tm.pid
               order by coalesce(h.msgs, 0) desc, tm.member_since asc, tm.group_id
             ) as rn
      from todos_miembros tm
      left join habla h on h.pid = tm.pid and h.group_id = tm.group_id
    ) z where rn = 1
  ),
  miembros as (
    select tm.group_id, tm.pid, tm.nombre
    from todos_miembros tm join casa c on c.pid = tm.pid and c.group_id = tm.group_id
  ),
  msgs as (
    select mi.pid,
           count(*) filter (where length(coalesce(nullif(w.body,''), w.transcribed_text, '')) > 15) as msgs_dia,
           count(distinct least(floor((extract(epoch from (w.sent_at at time zone 'America/Bogota') - v_hoy::timestamp) / 3600 - 10) / 2), v_fr_max - 1))
             filter (where (w.sent_at at time zone 'America/Bogota')::time between time '10:00' and time '19:00'
                       and length(coalesce(nullif(w.body,''), w.transcribed_text, '')) > 15) as franjas
    from miembros mi
    join whatsapp_members mm on mm.group_id = mi.group_id and mm.user_id = mi.pid
    join whatsapp_messages w on w.group_id = mi.group_id and w.sender_external_id = mm.external_id
      and w.is_from_bot = false and w.sent_at >= v_ini
    group by 1
  ),
  hub as (
    select hm.profile_id as pid,
           round(coalesce(sum(a.tracked_seconds),0) / 3600.0, 1) as horas,
           round(sum(a.overall_activity * a.tracked_seconds) filter (where a.overall_activity is not null)
                 / nullif(sum(a.tracked_seconds) filter (where a.overall_activity is not null), 0))::int as act
    from hubstaff_members hm
    join hubstaff_activities a on a.member_id = hm.id and a.starts_at >= v_ini
    group by 1
  ),
  rep as (
    select r.user_id as pid, r.contactados, r.respuestas, r.numeros_obtenidos,
           coalesce(r.videos_creados,0) + coalesce(r.fotos_creadas,0) as piezas,
           coalesce(r.posts_subidos,0) as posts, coalesce(r.cuentas_creadas,0) as cuentas
    from whatsapp_daily_reports r where r.report_date = v_hoy
  ),
  extra as (
    select mi.pid,
      (select count(*) from closers_contacts cc where cc.created_by = mi.pid and cc.phone is not null and cc.created_at >= v_ini) as numeros_maven,
      (select count(*) from closer_contact_history ch where ch.created_by = mi.pid and ch.created_at >= v_ini) as gestiones,
      (select count(*) from leadgen_entries le where le.lg_user_id = mi.pid and le.created_at >= v_ini) as perfiles,
      (select count(*) from closer_creators cc2 where cc2.assigned_to = mi.pid and cc2.confirmed_date >= v_ini) as confirmadas_hoy,
      (select count(*) from closer_creators cc3 where cc3.assigned_to = mi.pid and cc3.completed_date >= v_ini) as completadas_hoy,
      (select count(*) from monetization_opportunities mo where mo.assigned_to = mi.pid and mo.stage='won' and mo.won_at >= v_ini) as ventas_won_hoy
    from miembros mi
  ),
  linea as (select id from wa_channels where department='manager' and coalesce(active, true)),
  convs as (select id, contact_id from wa_conversations where channel_id in (select id from linea) and contact_id is not null),
  sal as (
    select c.contact_id, count(*)::int as msgs
    from wa_conversation_messages wm join convs c on c.id = wm.conversation_id
    where wm.direction = 'out' and wm.deleted_at is null and coalesce(wm.status,'') <> 'failed'
      and wm.sent_at >= v_ini
    group by 1
  ),
  cr_phone as (
    select cr.id, cr.assigned_manager_profile_id,
           right(public.canonical_phone(coalesce(cr.phone_e164, cr.whatsapp_number, cr.phone)), 10) as key10,
           right(regexp_replace(coalesce(cr.phone_e164, cr.whatsapp_number, cr.phone, ''), '\D', '', 'g'), 8) as key8
    from public.creadoras_de_mi_agencia() cr where cr.status = 'active'
  ),
  cr10 as (
    select distinct on (key10) key10, id from cr_phone where length(key10) = 10
    order by key10, (assigned_manager_profile_id is null)
  ),
  cr8 as (
    select key8, min(id::text)::uuid as id from cr_phone where length(key8) = 8
    group by key8 having count(distinct id) = 1
  ),
  matched as (
    select s.msgs, coalesce(c10.id, c8.id) as creator_id
    from sal s join wa_contacts ct on ct.id = s.contact_id
    left join cr10 c10 on c10.key10 = right(public.canonical_phone(ct.phone_e164), 10)
    left join cr8 c8 on c10.id is null and c8.key8 = right(regexp_replace(coalesce(ct.phone_e164,''), '\D', '', 'g'), 8)
  ),
  contactadas_mgr as (
    select split_part(coalesce(p.full_name,'-'),' ',1) as mgr,
           count(distinct m.creator_id)::int as contactadas
    from matched m
    join public.creadoras_de_mi_agencia() cr on cr.id = m.creator_id
    left join creator_business cb on cb.creator_id = m.creator_id
    left join profiles p on p.id = cr.assigned_manager_profile_id
    where m.creator_id is not null
    group by 1
  ),
  promos_mgr as (
    select split_part(p.full_name,' ',1) as mgr,
           count(*)::int as roster,
           count(*) filter (where exists (
             select 1 from promolog_entries e
             where e.creator_id = c.id and e.tenant_id = v_tenant
               and e.dia = v_hoy and e.promoted = 'true'))::int as con_promo
    from public.creadoras_de_mi_agencia() c join profiles p on p.id = c.assigned_manager_profile_id
    where c.status = 'active' group by 1
  ),
  calc as (
    select mi.group_id, mi.pid, mi.nombre,
      ob.metrica as objetivo, coalesce(ob.meta_diaria, 1) as meta,
      coalesce(ms.franjas, 0)::int as franjas,
      coalesce(ms.msgs_dia, 0)::int as msgs_dia,
      case when exists (select 1 from hubstaff_members hmx where hmx.profile_id = mi.pid)
        then coalesce(h.horas, 0) end as hub_h,
      h.act as hub_act,
      r.contactados, r.respuestas, r.numeros_obtenidos, coalesce(r.piezas,0) as piezas,
      coalesce(r.posts,0) as posts,
      x.numeros_maven, x.gestiones, x.perfiles, x.confirmadas_hoy, x.completadas_hoy, x.ventas_won_hoy,
      cm.contactadas, pm.roster, pm.con_promo,
      case
        when ob.metrica = 'numeros' then
          0.75 * least(coalesce(x.numeros_maven,0)::numeric
                       / nullif(ob.meta_diaria,0), 1)
          + 0.25 * greatest(
              least(coalesce(r.contactados,0) / 60.0, 1),
              least((coalesce(r.piezas,0) + coalesce(r.posts,0)) / 6.0, 1))
        when ob.metrica = 'contenido' then
          least((coalesce(r.piezas,0) + coalesce(r.posts,0))::numeric / nullif(ob.meta_diaria,0), 1)
        when ob.metrica = 'cierres' then
          case when x.ventas_won_hoy > 0 then 1.0
               when x.confirmadas_hoy > 0 or x.completadas_hoy > 0 then 0.85
               else 0.7 * least(coalesce(x.gestiones,0) / 15.0, 1) end
        when ob.metrica = 'promo' then
          0.2 * least(coalesce(cm.contactadas,0) / 8.0, 1)
          + 0.8 * (coalesce(pm.con_promo,0)::numeric / nullif(pm.roster,0))
        when ob.metrica = 'ninguna' then null
        when pm.roster is not null then
          0.2 * least(coalesce(cm.contactadas,0) / 8.0, 1) + 0.8 * (pm.con_promo::numeric / nullif(pm.roster,0))
        when x.ventas_won_hoy > 0 then 1.0
        when x.confirmadas_hoy > 0 or x.completadas_hoy > 0 then 0.85
        when coalesce(r.numeros_obtenidos, x.numeros_maven, 0) > 0 or coalesce(r.contactados,0) > 0 then
          0.6 * least(greatest(coalesce(r.numeros_obtenidos,0), x.numeros_maven) / 3.0, 1)
          + 0.4 * least(coalesce(r.contactados,0) / 60.0, 1)
        when x.gestiones >= 3 then 0.7 * least(x.gestiones / 15.0, 1)
        when coalesce(r.piezas,0) + coalesce(r.posts,0) > 0 then
          least((coalesce(r.piezas,0) + coalesce(r.posts,0)) / 6.0, 1)
        when x.perfiles > 0 then least(x.perfiles / 15.0, 1)
        else null
      end as avance
    from miembros mi
    left join corte_objetivos ob on ob.profile_id = mi.pid
    left join msgs ms on ms.pid = mi.pid
    left join hub h on h.pid = mi.pid
    left join rep r on r.pid = mi.pid
    left join extra x on x.pid = mi.pid
    left join contactadas_mgr cm on cm.mgr = mi.nombre
    left join promos_mgr pm on pm.mgr = mi.nombre
  ),
  notas as (
    select c.*,
      corte_nota_formula(c.franjas, v_fr_max, c.hub_h, v_hub_ref, c.hub_act, c.avance) as nota_sugerida,
      (c.avance is null) as sin_metricas_tabla
    from calc c
  ),
  limpiadas as (
    delete from corte_notas cn
    using casa c
    where cn.fecha = v_hoy and cn.profile_id = c.pid and cn.group_id <> c.group_id
      and cn.group_id in (select gid from grupos_corte)
    returning cn.profile_id
  ),
  guardadas as (
    insert into corte_notas (fecha, group_id, profile_id, nombre, nota_sugerida, componentes)
    select v_hoy, n.group_id, n.pid, n.nombre, n.nota_sugerida,
      jsonb_strip_nulls(jsonb_build_object(
        'franjas', n.franjas, 'franjas_max', v_fr_max, 'msgs_dia', n.msgs_dia,
        'hub_h', n.hub_h, 'hub_act', n.hub_act,
        'sin_cuenta_hubstaff', case when n.hub_h is null then true else null end,
        'textos', n.contactados, 'respuestas', n.respuestas,
        'objetivo', n.objetivo,
        'numeros', case when coalesce(n.objetivo,'numeros') <> 'numeros' or n.sin_metricas_tabla then null
                        else greatest(coalesce(n.numeros_obtenidos,0), coalesce(n.numeros_maven,0)) end,
        'numeros_auto_reportados', case when coalesce(n.objetivo,'numeros') = 'numeros'
                                          and coalesce(n.numeros_obtenidos,0) > coalesce(n.numeros_maven,0)
                                        then n.numeros_obtenidos end,
        'gestiones', nullif(n.gestiones,0),
        'perfiles', nullif(n.perfiles,0), 'piezas', nullif(n.piezas,0), 'posts', nullif(n.posts,0),
        'contactadas', n.contactadas, 'roster', n.roster, 'promos_roster', n.con_promo,
        'confirmadas', nullif(n.confirmadas_hoy,0), 'completadas', nullif(n.completadas_hoy,0),
        'ventas_won', nullif(n.ventas_won_hoy,0),
        'sin_metricas_tabla', case when n.sin_metricas_tabla then true else null end))
    from notas n
    on conflict (fecha, group_id, profile_id) do update
      set nota_sugerida = excluded.nota_sugerida, componentes = excluded.componentes, nombre = excluded.nombre
    returning group_id, profile_id, nombre, nota_sugerida, componentes
  )
  select
    jsonb_agg(jsonb_build_object('nombre', g.nombre, 'nota_sugerida', g.nota_sugerida, 'insumos', g.componentes)
              order by g.nota_sugerida desc nulls last) filter (where g.group_id = p_group_id),
    round(avg(g.nota_sugerida) filter (where g.group_id = p_group_id), 1),
    round(avg(g.nota_sugerida), 1)
  into v_personas, v_equipo, v_empresa
  from guardadas g;

  if v_es_viernes then
    select jsonb_agg(jsonb_build_object('nombre', s.nombre, 'promedio_7d', s.prom, 'dias_con_nota', s.dias, 'mejor', s.mejor, 'peor', s.peor)
                     order by s.prom desc)
    into v_semana
    from (
      select cn.nombre, round(avg(cn.nota_sugerida), 1) as prom, count(*) as dias,
             max(cn.nota_sugerida) as mejor, min(cn.nota_sugerida) as peor
      from corte_notas cn
      where cn.group_id = p_group_id and cn.fecha > v_hoy - 7
      group by cn.nombre
    ) s;
  end if;

  return jsonb_build_object(
    'personas', coalesce(v_personas, '[]'::jsonb),
    'equipo_promedio', v_equipo,
    'empresa_promedio', v_empresa,
    'semana', v_semana
  );
end;
$$;


ALTER FUNCTION "public"."corte_cierre_prep"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."corte_hubstaff_bloque"("p_group_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with grupos as (
    select * from (values
      ('a12d9f41-c962-4d98-b0bb-6b2d2573534c'::uuid, 'AI WARMING'),
      ('73a4414e-2546-4ca7-9289-7cbec70b0273'::uuid, 'MANAGERS'),
      ('d12ec56f-b324-4369-b72d-7540fb930ef6'::uuid, 'VENTAS')
    ) as g(id, nombre)
    where p_group_id is null or g.id = p_group_id
  ),
  v_start as (
    select ((now() at time zone 'America/Bogota')::date::timestamp at time zone 'America/Bogota') as t
  ),
  miembros as (
    select distinct g.nombre as grupo, p.id as pid,
           split_part(coalesce(nullif(p.full_name,''), m.display_name),' ',1) as nombre,
           exists (select 1 from hubstaff_members hmx where hmx.profile_id = p.id) as tiene_cuenta
    from grupos g
    join whatsapp_members m on m.group_id = g.id and coalesce(m.active, true)
    join profiles p on p.id = m.user_id
    where p.full_name not ilike '%lopez%' and p.full_name not ilike '%Alvaro%'
      -- Juan Pachas (socio) y Grace Gelves (RRHH/gerencia): sin presión de actividad.
      and p.id not in ('75bca8d9-ded5-4e86-b591-88209f6a5e6c','8b90f141-8546-4cfd-a358-56ff227623df','41b35cef-82a8-4991-9234-3514b0064767')
  ),
  horas as (
    select mi.grupo, mi.nombre, mi.tiene_cuenta,
           coalesce(sum(a.tracked_seconds),0)::bigint as secs,
           round(sum(a.overall_activity * a.tracked_seconds) filter (where a.overall_activity is not null)
                 / nullif(sum(a.tracked_seconds) filter (where a.overall_activity is not null), 0))::int as act
    from miembros mi
    left join hubstaff_members hm on hm.profile_id = mi.pid
    left join hubstaff_activities a on a.member_id = hm.id and a.starts_at >= (select t from v_start)
    group by 1, 2, 3
  ),
  lineas as (
    select grupo,
      string_agg(
        nombre || ' ' ||
        case when p_group_id is not null then
          coalesce(act::text || '%', 's/d') ||
          case when act is null then ''
               when act >= 60 then ' ✓'
               else ' (min 60)' end
        else
          (secs/3600)::int || 'h' || lpad(((secs%3600)/60)::int::text,2,'0')
          || coalesce(' (' || act || '%)', '')
        end,
        ' · ' order by coalesce(act, -1) desc, secs desc)
        filter (where secs > 0) as con_horas,
      string_agg(nombre, ', ' order by nombre) filter (where secs = 0 and tiene_cuenta) as sin_fichar,
      string_agg(nombre, ', ' order by nombre) filter (where not tiene_cuenta) as sin_cuenta
    from horas group by grupo
  )
  select string_agg(
      case when p_group_id is null then '· *' || grupo || '*: ' else '' end
      || coalesce(con_horas, 'nadie fichando')
      || case when sin_fichar is not null then E'\n   sin fichar hoy: ' || sin_fichar else '' end
      || case when sin_cuenta is not null then E'\n   sin cuenta de Hubstaff (no aplica): ' || sin_cuenta else '' end,
      E'\n' order by grupo)
    || case when (select max(starts_at) from hubstaff_activities) < now() - interval '30 minutes'
         then E'\n⚠️ feed de Hubstaff atrasado — los datos pueden no estar al día'
         else '' end
  from lineas;
$$;


ALTER FUNCTION "public"."corte_hubstaff_bloque"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."corte_jornada_bloque"("p_group_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with now_bog as (select now() at time zone 'America/Bogota' as t),
  hoy_dow as (select extract(dow from (select t from now_bog))::int as d),
  miembros as (
    select distinct p.id as pid,
           split_part(coalesce(nullif(p.full_name,''), m.display_name),' ',1) as nombre
    from whatsapp_members m join profiles p on p.id = m.user_id
    where m.group_id = p_group_id and coalesce(m.active, true)
      and p.full_name not ilike '%lopez%' and p.full_name not ilike '%Alvaro%'
      -- Juan Pachas (socio) y Grace Gelves (RRHH/gerencia): sin metas de jornada.
      and p.id not in ('75bca8d9-ded5-4e86-b591-88209f6a5e6c','8b90f141-8546-4cfd-a358-56ff227623df','41b35cef-82a8-4991-9234-3514b0064767')
  ),
  sched as (
    select s.user_id, min(s.start_time) as start_time, max(s.end_time) as end_time
    from whatsapp_user_schedules s, hoy_dow
    where s.weekday = hoy_dow.d
    group by s.user_id
  )
  select string_agg(
    mi.nombre || ': ' ||
    case
      when sc.user_id is null then 'sin horario cargado hoy'
      when (select t from now_bog)::time < sc.start_time
        then 'aún no arranca (entra ' || to_char(sc.start_time, 'HH24:MI') || ')'
      when (select t from now_bog)::time >= sc.end_time
        then 'turno terminado (salió ' || to_char(sc.end_time, 'HH24:MI') || ')'
      else 'van ' || to_char((select t from now_bog)::time - sc.start_time, 'HH24"h"MI')
        || ' de jornada · quedan ' || to_char(sc.end_time - (select t from now_bog)::time, 'HH24"h"MI')
        || ' (termina ' || to_char(sc.end_time, 'HH24:MI') || ')'
    end,
    E'\n' order by mi.nombre)
  from miembros mi
  left join sched sc on sc.user_id = mi.pid;
$$;


ALTER FUNCTION "public"."corte_jornada_bloque"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."corte_nota_formula"("p_franjas" integer, "p_franjas_max" integer, "p_hub_h" numeric, "p_hub_ref" numeric, "p_hub_act" integer, "p_avance" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select round(greatest(1.0, least(10.0,
    least(
      case when p_avance is null
           then 4.0 + 1.0 * (p_franjas::numeric / greatest(p_franjas_max, 1))
           else 10.0 end,
      1.0
      + 1.5 * (p_franjas::numeric / greatest(p_franjas_max, 1))
      + 1.5 * (case when p_hub_h is null then p_franjas::numeric / greatest(p_franjas_max, 1)
                    else 0.6 * least(p_hub_h / p_hub_ref, 1)
                       + 0.4 * least(coalesce(p_hub_act, 0) / 60.0, 1) end)
      + 6.0 * coalesce(p_avance, 0)
    )
    - case when p_hub_act is not null and p_hub_act < 60
           then least(1.0, (60 - p_hub_act) / 30.0)
           else 0 end
  ))::numeric, 1)
$$;


ALTER FUNCTION "public"."corte_nota_formula"("p_franjas" integer, "p_franjas_max" integer, "p_hub_h" numeric, "p_hub_ref" numeric, "p_hub_act" integer, "p_avance" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."corte_ventas_bloque"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with hoy as (select (now() at time zone 'America/Bogota')::date as d),
  ini as (select ((select d from hoy)::timestamp at time zone 'America/Bogota') as t),
  confirmadas as (
    select count(*) n, coalesce(sum(monthly_monetization),0)::int total
    from closer_creators where stage = 'Confirmada' and coalesce(lead_source,'maven') <> 'agencia'
  ),
  b2b as (
    select count(*) filter (where stage = 'Asignada') as trabajo,
           count(*) filter (where stage = 'Completada') as ganadas
    from closer_creators
    where coalesce(lead_source,'') = 'agencia' and assigned_to is not null
  ),
  abiertos as (
    select count(*) n, coalesce(sum(monthly_value_usd),0)::int total,
           count(*) filter (where monthly_value_usd is not null) con_valor
    from monetization_opportunities
    where stage in ('interested','offered','negotiating')
  ),
  won_hoy as (
    select mo.product, mo.creator_handle, mo.monthly_value_usd, mo.won_at,
           coalesce((select c.id::text from creators c
                     where lower(c.instagram_handle) = lower(mo.creator_handle)
                        or lower(coalesce(c.artistic_name,'')) = lower(mo.creator_handle)
                     limit 1), lower(coalesce(mo.creator_handle,'?'))) as clave_creadora
    from monetization_opportunities mo, ini
    where mo.stage = 'won' and mo.won_at >= ini.t
  ),
  ganado_dedup as (
    select distinct on (clave_creadora, product)
           product, creator_handle, monthly_value_usd, won_at
    from won_hoy
    order by clave_creadora, product, (monthly_value_usd is null), won_at
  ),
  compl_hoy as (
    select cc.instagram_handle, cc.completed_date
    from closer_creators cc, ini
    where cc.deal_type = 'venta_plataforma' and cc.completed_date >= ini.t
  ),
  compl_nuevas as (
    select ch.* from compl_hoy ch
    where not exists (
      select 1 from monetization_opportunities mo
      where mo.stage = 'won' and mo.won_at >= now() - interval '7 days'
        and lower(coalesce(mo.creator_handle,'')) = lower(ch.instagram_handle))
  ),
  compl_ya_contadas as (
    select ch.instagram_handle, ch.completed_date, mo.won_at, mo.monthly_value_usd
    from compl_hoy ch
    join monetization_opportunities mo
      on mo.stage = 'won'
     and lower(coalesce(mo.creator_handle,'')) = lower(ch.instagram_handle)
     and mo.won_at >= now() - interval '7 days'
    cross join ini
    where mo.won_at < ini.t
  ),
  ganado as (
    select string_agg(z.detalle, ' · ') as detalle,
           coalesce(sum(z.usd),0)::int as total_conocido, count(*) as n
    from (
      select replace(g.product,'_',' ') || ' a @' || coalesce(g.creator_handle,'?')
             || coalesce(' ($' || round(g.monthly_value_usd)::text, ' (monto por confirmar')
             || ', hoy ' || to_char(g.won_at at time zone 'America/Bogota','HH24:MI') || ')' as detalle,
             g.monthly_value_usd as usd
      from ganado_dedup g
      union all
      select 'venta plataforma a @' || cn.instagram_handle
             || ' (monto por confirmar, hoy '
             || to_char(cn.completed_date at time zone 'America/Bogota','HH24:MI') || ')', null
      from compl_nuevas cn
    ) z
  ),
  avisos as (
    select string_agg(
      '@' || ya.instagram_handle || ' pasó a Completada hoy '
      || to_char(ya.completed_date at time zone 'America/Bogota','HH24:MI')
      || ' pero su venta figura ganada el '
      || to_char(ya.won_at at time zone 'America/Bogota','DD/MM HH24:MI')
      || coalesce(' ($' || round(ya.monthly_value_usd)::text || ')', '')
      || ' — NO es venta nueva de hoy, no la sumes', E'\n· ') as detalle
    from compl_ya_contadas ya
  ),
  hitos_v as (
    select string_agg(distinct '· ' || m.title, E'\n') as detalle
    from creator_milestones m, hoy
    where m.occurred_on = hoy.d
      and m.kind in ('reunion_agendada','cierre','cerca_de_cierre','en_negociacion')
  )
  select
    '*En la mesa:* '
    || case when c.total > 0 then '$' || c.total || '/mes en ' || c.n || ' confirmadas por firmar'
            when c.n > 0 then c.n || ' confirmadas por firmar (montos sin cargar)'
            else '0 confirmadas por firmar' end
    || ' · ' || a.n || ' productos abiertos' || case when a.con_valor > 0 then ' ($' || a.total || '/mes valorizados)' else '' end
    || case when b.trabajo > 0 then ' · ' || b.trabajo || ' agencias B2B en trabajo' else '' end
    || E'\n*Ganado HOY (' || g.n || ' ventas):* ' || coalesce(g.detalle, 'sin ventas registradas aún')
    || case when g.total_conocido > 0 then ' — $' || g.total_conocido || ' en montos confirmados' else '' end
    || case when av.detalle is not null then E'\n*Ojo — stage movido HOY sobre ventas YA ganadas antes (no sumar):*\n· ' || av.detalle else '' end
    || case when h.detalle is not null then E'\n*Agenda/avances de hoy:*\n' || h.detalle else '' end
  from confirmadas c, abiertos a, b2b b, ganado g, avisos av, hitos_v h;
$_$;


ALTER FUNCTION "public"."corte_ventas_bloque"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."costo_mensual"("_monto" numeric, "_ciclo" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case when _monto is null then null when _ciclo = 'anual' then round(_monto / 12, 2) else _monto end;
$$;


ALTER FUNCTION "public"."costo_mensual"("_monto" numeric, "_ciclo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."costos_avisar_si_se_dispara"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_antes numeric;
  v_nombre text;
begin
  if new.avisado then return new; end if;
  select m.monto_usd into v_antes from public.costos_mensuales m
   where m.servicio_id = new.servicio_id and m.mes = (new.mes - interval '1 month')::date;
  if v_antes is null or v_antes < 1 or new.monto_usd <= v_antes * 1.2 then return new; end if;

  select nombre into v_nombre from public.costos_servicios where id = new.servicio_id;
  insert into public.notifications
    (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
  select o.user_id, 'costo_disparado',
         format('%s subió %s %%', coalesce(v_nombre, new.servicio_id), round((new.monto_usd / v_antes - 1) * 100)),
         format('Pasó de USD %s a USD %s al mes. Mira el detalle en Costos y conexiones.', v_antes, new.monto_usd),
         'costos', 'Oficina', 'high', 'new', 'personal', '/oficina/costos'
    from (select distinct user_id from public.tenant_owners) o;
  new.avisado := true;
  return new;
end $$;


ALTER FUNCTION "public"."costos_avisar_si_se_dispara"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."costos_casillas_de_maven"() RETURNS TABLE("email" "text", "viva" boolean, "ultima" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  with casillas as (
    select distinct on (lower(m.email_address))
           lower(m.email_address) as email, m.user_id, m.revoked_at, m.last_used_at
      from public.mail_credentials m
     order by lower(m.email_address), m.created_at desc
  )
  select c.email,
         (p.id is not null and p.deleted_at is null) as viva,
         case when c.revoked_at is not null then null
              else greatest(au.last_sign_in_at,
                            (select max(coalesce(s.refreshed_at, s.updated_at)) from auth.sessions s where s.user_id = c.user_id),
                            c.last_used_at)
         end as ultima
    from casillas c
    left join public.profiles p on p.id = c.user_id
    left join auth.users au on au.id = c.user_id;
$$;


ALTER FUNCTION "public"."costos_casillas_de_maven"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."costos_foto_del_mes"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n integer;
begin
  insert into public.costos_mensuales (mes, servicio_id, monto_usd)
  select date_trunc('month', now() at time zone 'America/Bogota')::date, s.id, public.costo_mensual(s.monto_usd, s.ciclo)
    from public.costos_servicios s
   where s.activo and s.monto_usd is not null
  on conflict (mes, servicio_id) do update set monto_usd = excluded.monto_usd
   where public.costos_mensuales.monto_usd is distinct from excluded.monto_usd;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "public"."costos_foto_del_mes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."costos_uso_del_mes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hoy date := (now() at time zone 'America/Bogota')::date;
  v_desde date := date_trunc('month', (now() at time zone 'America/Bogota'))::date;
  v_ini timestamptz := (date_trunc('month', (now() at time zone 'America/Bogota')) at time zone 'America/Bogota');
  v jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'solo el dueño' using errcode = '42501';
  end if;

  with fotos as (
    select (c.created_at at time zone 'America/Bogota')::date as dia,
           count(*) filter (where c.tipo = 'pantalla') as pantalla,
           count(*) filter (where c.tipo = 'camara') as camara,
           count(*) filter (where c.veredicto is not null) as juzgadas,
           count(*) filter (where c.en_nas) as al_nas
      from public.monitor_capturas c
     where c.created_at >= v_ini
     group by 1
  ), videos as (
    select (a.created_at at time zone 'America/Bogota')::date as dia,
           count(*) as videos,
           coalesce(sum(a.duracion_seg), 0) as segundos
      from public.argos_clips a
     where a.created_at >= v_ini
     group by 1
  ), dias as (
    select x::date as dia from generate_series(v_desde::timestamp, v_hoy::timestamp, interval '1 day') as x
  ), cubetas as (
    select o.bucket_id,
           round(sum(coalesce((o.metadata ->> 'size')::bigint, 0)) / 1073741824.0, 3) as gb,
           count(*) as archivos
      from storage.objects o
     group by o.bucket_id
  )
  select jsonb_build_object(
    'desde', v_desde,
    'hoy', v_hoy,
    'dias_del_mes', extract(day from (v_desde + interval '1 month' - interval '1 day'))::int,
    'calculado_at', now(),
    'dias', coalesce((
      select jsonb_agg(jsonb_build_object(
               'dia', d.dia,
               'pantalla', coalesce(f.pantalla, 0),
               'camara', coalesce(f.camara, 0),
               'juzgadas', coalesce(f.juzgadas, 0),
               'al_nas', coalesce(f.al_nas, 0),
               'videos', coalesce(vv.videos, 0),
               'video_seg', coalesce(vv.segundos, 0)) order by d.dia)
        from dias d
        left join fotos f on f.dia = d.dia
        left join videos vv on vv.dia = d.dia), '[]'::jsonb),
    'almacenamiento', coalesce((
      select jsonb_agg(jsonb_build_object('bucket', b.bucket_id, 'gb', b.gb, 'archivos', b.archivos) order by b.gb desc)
        from cubetas b), '[]'::jsonb)
  ) into v;
  return v;
end $$;


ALTER FUNCTION "public"."costos_uso_del_mes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_bano_consumido_hoy"("_user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "segundos" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select b.user_id,
         greatest(0, sum(
           coalesce(b.duration_seconds, extract(epoch from (b.ended_at - b.started_at)))
         ))::integer as segundos
  from public.cowork_breaks b
  where b.kind = 'bano'
    and b.user_id = any(_user_ids)
    -- Con sesión, solo gente de la propia agencia (20261001213000).
    and (auth.uid() is null or b.user_id in (select public.gente_de_mi_agencia()))
    and b.ended_at is not null
    and (b.started_at at time zone 'America/Bogota')::date
        = (now() at time zone 'America/Bogota')::date
  group by b.user_id;
$$;


