CREATE OR REPLACE FUNCTION "public"."cowork_llamados_no_encoger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.seconds := greatest(coalesce(new.seconds, 0), coalesce(old.seconds, 0));
  new.updated_at := now();

  -- Todo lo que describe el ORIGEN del llamado se congela en lo que se escribió
  -- la primera vez. Lo único que avanza es la duración.
  new.started_at := old.started_at;
  new.session_id := old.session_id;
  new.room_id    := coalesce(old.room_id, new.room_id);
  new.detail     := coalesce(old.detail, new.detail);
  new.created_at := old.created_at;

  if new.user_id is distinct from old.user_id
     or new.kind is distinct from old.kind
     or new.nonce is distinct from old.nonce then
    raise exception
      'cowork_llamados: user_id/kind/nonce identifican el llamado y no se cambian por UPDATE (era %/%/%, llegó %/%/%)',
      old.user_id, old.kind, old.nonce, new.user_id, new.kind, new.nonce;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."cowork_llamados_no_encoger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_meets_resumen"("_desde" "date" DEFAULT NULL::"date", "_hasta" "date" DEFAULT NULL::"date", "_session_id" "uuid" DEFAULT NULL::"uuid", "_user_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 2000, "_offset" integer DEFAULT 0) RETURNS TABLE("meet_id" "uuid", "session_id" "uuid", "session_name" "text", "created_by" "uuid", "creador" "text", "meet_started_at" timestamp with time zone, "meet_ended_at" timestamp with time zone, "meet_seconds" integer, "user_id" "uuid", "nombre" "text", "room_id" "uuid", "room_name" "text", "joined_at" timestamp with time zone, "left_at" timestamp with time zone, "is_open" boolean, "seconds" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    m.id as meet_id,
    m.session_id, cs.name as session_name,
    m.created_by, pc.full_name as creador,
    m.started_at as meet_started_at, m.ended_at as meet_ended_at,
    greatest(0, extract(epoch from (coalesce(m.ended_at, now()) - m.started_at)))::int as meet_seconds,
    p.user_id, pr.full_name as nombre,
    p.room_id, cr.name as room_name,
    p.joined_at, p.left_at, (p.left_at is null) as is_open,
    coalesce(p.duration_seconds, greatest(0, extract(epoch from (now() - p.joined_at)))::int) as seconds
  from public.cowork_meet_participants p
  join public.cowork_meets m on m.id = p.meet_id
  left join public.cowork_sessions cs on cs.id = m.session_id
  left join public.cowork_rooms cr on cr.id = p.room_id
  left join public.profiles pr on pr.id = p.user_id
  left join public.profiles pc on pc.id = m.created_by
  where (_desde is null or (p.joined_at at time zone 'America/Bogota')::date >= _desde)
    and (_hasta is null or (p.joined_at at time zone 'America/Bogota')::date <= _hasta)
    and (_session_id is null or p.session_id = _session_id)
    and (_user_id is null or p.user_id = _user_id)
    -- Sin sesión (service_role) pasa todo. Con sesión: lo propio, lo de las
    -- sesiones que uno hostea, o todo lo de su agencia si es supervisor o
    -- superior (20261001213000).
    and (
      auth.uid() is null
      or p.user_id = auth.uid()
      or public.is_cowork_host(auth.uid(), p.session_id)
      or (public.is_in_role_group(auth.uid(), 'supervisor_or_above')
          and cs.tenant_id = (select public.current_tenant_id()))
    )
  order by m.started_at desc, pr.full_name
  limit least(greatest(_limit, 1), 5000)
  offset greatest(_offset, 0)
$$;


ALTER FUNCTION "public"."cowork_meets_resumen"("_desde" "date", "_hasta" "date", "_session_id" "uuid", "_user_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cowork_meets_resumen"("_desde" "date", "_hasta" "date", "_session_id" "uuid", "_user_id" "uuid", "_limit" integer, "_offset" integer) IS 'Meets grupales de Cowork: una fila por persona y meet (quién lo invocó, de qué sala vino, cuánto estuvo). Incluye los abiertos con el tiempo hasta ahora.';



CREATE OR REPLACE FUNCTION "public"."cowork_mis_sesiones_activas"() RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "role" "text", "members" integer, "created_at" timestamp with time zone, "last_room_id" "uuid", "created_by" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH mias AS (
    SELECT m.session_id, m.role
    FROM public.cowork_memberships m
    WHERE m.user_id = auth.uid()
  )
  SELECT
    s.id, s.name, s.description, mias.role,
    (SELECT count(*)::integer FROM public.cowork_memberships t WHERE t.session_id = s.id),
    s.created_at,
    (SELECT a.room_id FROM public.cowork_room_assignments a
      WHERE a.session_id = s.id AND a.user_id = auth.uid()
      ORDER BY a.assigned_at DESC LIMIT 1),
    s.created_by
  FROM mias
  JOIN public.cowork_sessions s ON s.id = mias.session_id AND s.status = 'active'
  ORDER BY s.created_at DESC;
$$;


ALTER FUNCTION "public"."cowork_mis_sesiones_activas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_mis_sesiones_finalizadas"("_dias" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "name" "text", "ended_at" timestamp with time zone, "ended_by" "uuid", "ended_by_name" "text", "created_by" "uuid", "created_by_name" "text", "members" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id, s.name, s.ended_at, s.ended_by,
    pe.full_name as ended_by_name,
    s.created_by,
    pc.full_name as created_by_name,
    (select count(*)::integer from public.cowork_memberships t where t.session_id = s.id) as members
  from public.cowork_sessions s
  left join public.profiles pe on pe.id = s.ended_by
  left join public.profiles pc on pc.id = s.created_by
  where s.status = 'ended'
    and s.ended_at > now() - make_interval(days => greatest(1, least(coalesce(_dias, 10), 90)))
    and (
      -- Un admin ve las de su agencia (20261001213000).
      (public.has_role(auth.uid(), 'admin'::app_role) and s.tenant_id = (select public.current_tenant_id()))
      or exists (select 1 from public.cowork_memberships m where m.session_id = s.id and m.user_id = auth.uid())
    )
  order by s.ended_at desc
  limit 30;
$$;


ALTER FUNCTION "public"."cowork_mis_sesiones_finalizadas"("_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_misma_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_persona uuid := (to_jsonb(new) ->> tg_argv[0])::uuid;
  v_de_la_sesion uuid;
  v_de_la_persona uuid;
begin
  select s.tenant_id into v_de_la_sesion from public.cowork_sessions s where s.id = new.session_id;
  if v_de_la_sesion is null then
    return new;
  end if;
  select tm.tenant_id into v_de_la_persona from public.tenant_members tm where tm.user_id = v_persona;
  if v_de_la_persona is distinct from v_de_la_sesion then
    raise exception 'cowork_misma_agencia: % no es de la agencia de la sesión % (%)', v_persona, new.session_id, tg_table_name
      using errcode = '42501', hint = 'Cada persona entra solo a las sesiones de su agencia.';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."cowork_misma_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_pausas_abiertas"("_session_id" "uuid") RETURNS TABLE("user_id" "uuid", "room_id" "uuid", "kind" "text", "started_at" timestamp with time zone, "segundos" integer, "limite_segundos" integer, "excedida" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT b.user_id, b.room_id, b.kind, b.started_at,
         EXTRACT(EPOCH FROM (now() - b.started_at))::integer,
         (l.minutos * 60),
         EXTRACT(EPOCH FROM (now() - b.started_at))::integer > (l.minutos * 60)
  FROM public.cowork_breaks b
  JOIN public.cowork_sessions s ON s.id = b.session_id
  -- El tope es el de la agencia de la sesión (20261001213000).
  JOIN public.cowork_break_limits l ON l.kind = b.kind AND l.tenant_id = s.tenant_id
  WHERE b.session_id = _session_id AND b.ended_at IS NULL
    AND (
      (public.is_in_role_group(auth.uid(), 'supervisor_or_above')
       AND s.tenant_id = (SELECT public.current_tenant_id()))
      OR public.is_cowork_host(auth.uid(), b.session_id)
      OR b.user_id = auth.uid()
    );
$$;


ALTER FUNCTION "public"."cowork_pausas_abiertas"("_session_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cowork_pausas_abiertas"("_session_id" "uuid") IS 'Pausas en curso de una sesion, con el tiempo YA CONTADO POR EL SERVIDOR y si se paso del limite. El cliente no puede inflar ni acortar su propio reloj.';



CREATE OR REPLACE FUNCTION "public"."cowork_pausas_resumen"("_desde" "date" DEFAULT NULL::"date", "_hasta" "date" DEFAULT NULL::"date", "_session_id" "uuid" DEFAULT NULL::"uuid", "_user_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 500, "_offset" integer DEFAULT 0) RETURNS TABLE("dia" "date", "user_id" "uuid", "nombre" "text", "banos" integer, "seg_bano" integer, "bano_limite_seg" integer, "bano_excedido" boolean, "breaks" integer, "seg_break" integer, "break_limite_seg" integer, "breaks_excedidos" integer, "seg_break_de_mas" integer, "auto_cerradas" integer, "almuerzos" integer, "seg_almuerzo" integer, "almuerzo_limite_seg" integer, "almuerzos_excedidos" integer, "seg_almuerzo_de_mas" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with pausas as (
    select
      b.user_id,
      (b.started_at at time zone 'America/Bogota')::date as dia,
      b.kind,
      b.auto_closed,
      coalesce(b.duration_seconds, greatest(0, extract(epoch from (b.ended_at - b.started_at))::int)) as seg,
      coalesce(
        nullif(cs.alert_rules->'pausas'->>(case when b.kind = 'break' then 'breakMin' when b.kind = 'almuerzo' then 'almuerzoMin' else 'banoMin' end), '')::int,
        l.minutos
      ) * 60 as limite_seg
    from public.cowork_breaks b
    left join public.cowork_sessions cs on cs.id = b.session_id
    left join public.cowork_break_limits l on l.kind = b.kind and l.tenant_id = cs.tenant_id
    where b.ended_at is not null
      and (_desde is null or (b.started_at at time zone 'America/Bogota')::date >= _desde)
      and (_hasta is null or (b.started_at at time zone 'America/Bogota')::date <= _hasta)
      and (_session_id is null or b.session_id = _session_id)
      and (_user_id is null or b.user_id = _user_id)
      and (
        auth.uid() is null
        or b.user_id = auth.uid()
        or public.is_cowork_host(auth.uid(), b.session_id)
        or (public.is_in_role_group(auth.uid(), 'supervisor_or_above')
            and cs.tenant_id = (select public.current_tenant_id()))
      )
  ),
  sumas as (
    select
      p.dia, p.user_id,
      count(*) filter (where p.kind = 'bano' and not p.auto_closed)::int as banos,
      coalesce(sum(p.seg) filter (where p.kind = 'bano' and not p.auto_closed), 0)::int as seg_bano,
      max(p.limite_seg) filter (where p.kind = 'bano') as bano_limite_seg,
      count(*) filter (where p.kind = 'break' and not p.auto_closed)::int as breaks,
      coalesce(sum(p.seg) filter (where p.kind = 'break' and not p.auto_closed), 0)::int as seg_break,
      max(p.limite_seg) filter (where p.kind = 'break') as break_limite_seg,
      count(*) filter (where p.kind = 'break' and not p.auto_closed and p.limite_seg is not null and p.seg > p.limite_seg)::int as breaks_excedidos,
      coalesce(sum(greatest(0, p.seg - p.limite_seg)) filter (where p.kind = 'break' and not p.auto_closed and p.limite_seg is not null), 0)::int as seg_break_de_mas,
      count(*) filter (where p.auto_closed)::int as auto_cerradas,
      count(*) filter (where p.kind = 'almuerzo' and not p.auto_closed)::int as almuerzos,
      coalesce(sum(p.seg) filter (where p.kind = 'almuerzo' and not p.auto_closed), 0)::int as seg_almuerzo,
      max(p.limite_seg) filter (where p.kind = 'almuerzo') as almuerzo_limite_seg,
      count(*) filter (where p.kind = 'almuerzo' and not p.auto_closed and p.limite_seg is not null and p.seg > p.limite_seg)::int as almuerzos_excedidos,
      coalesce(sum(greatest(0, p.seg - p.limite_seg)) filter (where p.kind = 'almuerzo' and not p.auto_closed and p.limite_seg is not null), 0)::int as seg_almuerzo_de_mas
    from pausas p
    group by p.dia, p.user_id
  )
  select
    su.dia, su.user_id, pr.full_name as nombre,
    su.banos, su.seg_bano, su.bano_limite_seg,
    (su.bano_limite_seg is not null and su.seg_bano > su.bano_limite_seg) as bano_excedido,
    su.breaks, su.seg_break, su.break_limite_seg, su.breaks_excedidos, su.seg_break_de_mas,
    su.auto_cerradas,
    su.almuerzos, su.seg_almuerzo, su.almuerzo_limite_seg, su.almuerzos_excedidos, su.seg_almuerzo_de_mas
  from sumas su
  left join public.profiles pr on pr.id = su.user_id
  order by su.dia desc, pr.full_name
  limit least(greatest(_limit, 1), 2000)
  offset greatest(_offset, 0)
$$;


ALTER FUNCTION "public"."cowork_pausas_resumen"("_desde" "date", "_hasta" "date", "_session_id" "uuid", "_user_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_puede_supervisar"("_user_id" "uuid", "_session_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Solo sesiones de la propia agencia (20261001213000); el alcance de los
  -- roles ya es por agencia, pero sin esto miraba sesiones de cualquiera.
  select exists (
           select 1
           from public.cowork_sessions s0
           join public.tenant_members tm on tm.tenant_id = s0.tenant_id and tm.user_id = _user_id
           where s0.id = _session_id
         )
     and (
       public.has_cowork_global_scope(_user_id)
       or (
         public.has_cowork_team_scope(_user_id)
         and exists (
           select 1 from public.cowork_sessions s
           where s.id = _session_id
             and public.actor_level(s.created_by) < public.actor_level(_user_id)
         )
       )
     );
$$;


ALTER FUNCTION "public"."cowork_puede_supervisar"("_user_id" "uuid", "_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_reloj_de_sala"("_session_id" "uuid") RETURNS TABLE("user_id" "uuid", "seg_activo_hoy" integer, "ultimo_estado" "text", "ultimo_latido" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with dia as (
    select ((now() at time zone 'America/Bogota')::date)::timestamp at time zone 'America/Bogota' as ini
  ),
  gente as (
    select distinct a.user_id
    from public.cowork_room_assignments a
    where a.session_id = _session_id and a.is_active
  ),
  activo as (
    select s.user_id,
           sum(extract(epoch from (
             least(coalesce(s.ended_at, s.last_seen_at), now()) - greatest(s.started_at, d.ini)
           )))::int as seg
    from public.cowork_tiempo_segmentos s
    cross join dia d
    join gente g on g.user_id = s.user_id
    where s.estado in ('activo','meet','sin_conexion')
      and coalesce(s.ended_at, s.last_seen_at) > d.ini
    group by s.user_id
  ),
  ultimo as (
    select distinct on (s.user_id) s.user_id, s.estado, s.last_seen_at
    from public.cowork_tiempo_segmentos s
    join gente g on g.user_id = s.user_id
    where s.session_id = _session_id
    order by s.user_id, s.last_seen_at desc
  )
  select g.user_id,
         coalesce(a.seg, 0) as seg_activo_hoy,
         u.estado as ultimo_estado,
         u.last_seen_at as ultimo_latido
  from gente g
  left join activo a on a.user_id = g.user_id
  left join ultimo u on u.user_id = g.user_id
  where public.is_cowork_host(auth.uid(), _session_id)
$$;


ALTER FUNCTION "public"."cowork_reloj_de_sala"("_session_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cowork_reloj_de_sala"("_session_id" "uuid") IS 'Reloj de respaldo del tablero: segundos activos de HOY (Bogotá), último estado y último latido de cada persona asignada a la sesión. Para cuando la presencia de Realtime no llega. Solo hosts.';



CREATE OR REPLACE FUNCTION "public"."cowork_sesiones_activas_admin"() RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "members" integer, "rooms" integer, "created_at" timestamp with time zone, "host_name" "text", "my_role" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id, s.name, s.description,
    (select count(*)::integer from public.cowork_memberships m where m.session_id = s.id),
    (select count(*)::integer from public.cowork_rooms r where r.session_id = s.id),
    s.created_at,
    (select p.full_name from public.profiles p where p.id = s.created_by),
    (select m.role from public.cowork_memberships m
      where m.session_id = s.id and m.user_id = auth.uid() limit 1)
  from public.cowork_sessions s
  where s.status = 'active'
    -- Solo las de la agencia de quien mira (20261001213000).
    and s.tenant_id = (select public.current_tenant_id())
    and (
      public.has_cowork_global_scope(auth.uid())
      or (
        public.has_cowork_team_scope(auth.uid())
        and public.actor_level(s.created_by) < public.actor_level(auth.uid())
      )
    )
  order by s.created_at desc;
$$;


