ALTER FUNCTION "public"."cowork_sesiones_de_mi_agencia"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cowork_sesiones_de_mi_agencia"() IS 'Los id de las sesiones de Cowork de la agencia de quien llama. Para políticas y funciones.';



CREATE OR REPLACE FUNCTION "public"."cowork_sessions_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_del_creador uuid;
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id is distinct from old.tenant_id then
      raise exception 'cowork_sessions_agencia: la agencia de una sesión no se cambia' using errcode = '23514';
    end if;
    return new;
  end if;
  v_del_creador := (select tm.tenant_id from public.tenant_members tm where tm.user_id = new.created_by);
  if v_del_creador is null then
    raise exception 'cowork_sessions_agencia: % no es de ninguna agencia, no puede crear sesiones', new.created_by using errcode = '42501';
  end if;
  if new.tenant_id is null then
    new.tenant_id := v_del_creador;
  elsif new.tenant_id <> v_del_creador then
    raise exception 'cowork_sessions_agencia: la sesión tiene que ser de la agencia de quien la crea' using errcode = '42501';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."cowork_sessions_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_solo_anfitriones_designados"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_suya text;
begin
  if new.role = 'host' and not public.puede_ser_anfitrion(new.session_id, new.user_id) then
    new.role := 'participant';
  end if;

  if tg_op = 'INSERT' and new.role <> 'host' and public.debe_estar_en_cowork(new.user_id) then
    select s.name into v_suya
      from public.cowork_memberships cm
      join public.cowork_sessions s on s.id = cm.session_id and s.status = 'active'
     where cm.user_id = new.user_id and cm.role <> 'host' and cm.session_id <> new.session_id
     limit 1;
    if v_suya is not null then
      raise exception 'Tu Cowork es «%». Entra por ahí.', v_suya
        using errcode = 'P0001', hint = 'Cada persona trabaja solo en el Cowork de su departamento.';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."cowork_solo_anfitriones_designados"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cowork_tiempo_diario"("_desde" "date" DEFAULT NULL::"date", "_hasta" "date" DEFAULT NULL::"date", "_user_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 100, "_offset" integer DEFAULT 0) RETURNS TABLE("dia" "date", "user_id" "uuid", "nombre" "text", "seg_activo" integer, "seg_meet" integer, "seg_pausa" integer, "seg_sin_camara" integer, "seg_sin_pantalla" integer, "seg_fuera_de_camara" integer, "seg_en_sala" integer, "horas_activas" numeric, "sesiones" integer, "primer_ingreso" timestamp with time zone, "ultima_salida" timestamp with time zone, "seg_sin_conexion" integer, "seg_sin_conexion_larga" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with tramos as (
    select
      s.user_id,
      s.session_id,
      s.estado,
      greatest(s.started_at, d.dia_ini) as ini,
      least(coalesce(s.ended_at, s.last_seen_at), d.dia_fin) as fin,
      -- ¿Sigue EN SALA ahora? Sesión sin cerrar con latido fresco (< 5 min).
      (s.ended_at is null and s.last_seen_at > now() - interval '5 minutes') as abierto,
      d.dia
    from public.cowork_tiempo_segmentos s
    cross join lateral (
      select g::date as dia,
             ((g::date)::timestamp at time zone 'America/Bogota') as dia_ini,
             ((g::date + 1)::timestamp at time zone 'America/Bogota') as dia_fin
      from generate_series(
        ((s.started_at at time zone 'America/Bogota')::date)::timestamp,
        ((coalesce(s.ended_at, s.last_seen_at) at time zone 'America/Bogota')::date)::timestamp,
        interval '1 day'
      ) g
    ) d
    where (_desde is null or (coalesce(s.ended_at, s.last_seen_at) at time zone 'America/Bogota')::date >= _desde)
      and (_hasta is null or (s.started_at at time zone 'America/Bogota')::date <= _hasta)
      and (_user_id is null or s.user_id = _user_id)
      and ((select auth.uid()) is null or s.user_id = (select auth.uid())
           or (public.has_role((select auth.uid()), 'admin')
               and s.session_id in (select public.cowork_sesiones_de_mi_agencia()))
           or s.user_id in (select p.id from public.profiles p
                             where public.puede_vigilar_a((select auth.uid()), p.id)))
  ),
  sumas as (
    select
      t.dia, t.user_id,
      sum(case when t.estado in ('activo','meet','sin_conexion') then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_activo,
      sum(case when t.estado = 'meet' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_meet,
      sum(case when t.estado = 'pausa' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_pausa,
      sum(case when t.estado = 'sin_camara' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_sin_camara,
      sum(case when t.estado = 'sin_pantalla' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_sin_pantalla,
      sum(case when t.estado = 'fuera_de_camara' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_fuera_de_camara,
      sum(case when t.estado = 'sin_conexion' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_sin_conexion,
      sum(case when t.estado = 'sin_conexion_larga' then extract(epoch from (t.fin - t.ini)) else 0 end)::int as seg_sin_conexion_larga,
      sum(extract(epoch from (t.fin - t.ini)))::int as seg_en_sala,
      count(distinct t.session_id)::int as sesiones,
      min(t.ini) as primer_ingreso,
      -- Si sigue en sala ahora, no hay salida: NULL (aún no sale).
      case when bool_or(t.abierto) then null else max(t.fin) end as ultima_salida
    from tramos t
    where t.fin > t.ini
      and (_desde is null or t.dia >= _desde)
      and (_hasta is null or t.dia <= _hasta)
    group by t.dia, t.user_id
  )
  select
    su.dia, su.user_id, p.full_name as nombre,
    su.seg_activo, su.seg_meet, su.seg_pausa, su.seg_sin_camara, su.seg_sin_pantalla, su.seg_fuera_de_camara, su.seg_en_sala,
    round(su.seg_activo / 3600.0, 2) as horas_activas,
    su.sesiones, su.primer_ingreso, su.ultima_salida,
    su.seg_sin_conexion, su.seg_sin_conexion_larga
  from sumas su
  left join public.profiles p on p.id = su.user_id
  order by su.dia desc, p.full_name
  limit least(greatest(_limit, 1), 500)
  offset greatest(_offset, 0)
$$;


ALTER FUNCTION "public"."cowork_tiempo_diario"("_desde" "date", "_hasta" "date", "_user_id" "uuid", "_limit" integer, "_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."creadora_accesos_eventos_revisar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  select c.tenant_id into new.tenant_id from public.creators c where c.id = new.creator_id;
  if new.tenant_id is null then
    raise exception 'creadora_accesos_eventos: la creadora % no existe', new.creator_id using errcode = '23503';
  end if;
  new.en := now();
  return new;
end $$;


ALTER FUNCTION "public"."creadora_accesos_eventos_revisar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."creadora_accesos_revisar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  select c.tenant_id into new.tenant_id from public.creators c where c.id = new.creator_id;
  if new.tenant_id is null then
    raise exception 'creadora_accesos: la creadora % no existe', new.creator_id using errcode = '23503';
  end if;
  new.of_correo := nullif(lower(btrim(new.of_correo)), '');
  new.of_usuario := nullif(btrim(new.of_usuario), '');
  new.actualizado_en := now();
  if tg_op = 'INSERT' then
    new.clave_cambiada_en := case when new.of_clave_cifrada is not null then now() end;
  elsif new.of_clave_cifrada is distinct from old.of_clave_cifrada then
    new.clave_cambiada_en := case when new.of_clave_cifrada is not null then now() end;
  else
    new.clave_cambiada_en := old.clave_cambiada_en;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."creadora_accesos_revisar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."creadora_carpetas_revisar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  select c.tenant_id into new.tenant_id from public.creators c where c.id = new.creator_id;
  if new.tenant_id is null then
    raise exception 'creadora_carpetas: la creadora % no existe', new.creator_id using errcode = '23503';
  end if;
  if not exists (select 1 from public.drive_unidades u
                 where u.item_id = new.item_id and u.tipo = 'empresa' and u.tenant_id = new.tenant_id) then
    raise exception 'creadora_carpetas: la carpeta tiene que ser una unidad de la agencia de la creadora' using errcode = '23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."creadora_carpetas_revisar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."creadora_cuentas_revisar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  select c.tenant_id into new.tenant_id from public.creators c where c.id = new.creator_id;
  if new.tenant_id is null then
    raise exception 'creadora_cuentas: la creadora % no existe', new.creator_id using errcode = '23503';
  end if;
  if not exists (select 1 from auth.users u where u.id = new.user_id and (u.raw_app_meta_data ->> 'tipo') = 'creadora') then
    raise exception 'creadora_cuentas: la cuenta % no es de creadora', new.user_id using errcode = '42501';
  end if;
  if exists (select 1 from public.tenant_members tm where tm.user_id = new.user_id) then
    raise exception 'creadora_cuentas: la cuenta % es de alguien de una agencia', new.user_id using errcode = '42501';
  end if;
  if exists (select 1 from public.creadora_cuentas o
             where o.user_id = new.user_id and o.tenant_id = new.tenant_id and o.creator_id <> new.creator_id) then
    raise exception 'creadora_cuentas: esa cuenta ya es de otra creadora de la misma agencia' using errcode = '23505';
  end if;
  new.correo := lower(btrim(new.correo));
  return new;
end $$;


ALTER FUNCTION "public"."creadora_cuentas_revisar"() OWNER TO "postgres";


