CREATE OR REPLACE FUNCTION "public"."crear_link_subida"("_item_id" "uuid", "_nombre" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_tenant uuid; v_token text; v_nivel text; v_puede boolean;
begin
  select nivel into v_nivel from public.profiles where id = (select auth.uid());
  v_puede := coalesce(v_nivel in ('dueno','admin','manager','supervisor'), false)
    or exists (select 1 from public.user_roles ur
               where ur.user_id = (select auth.uid())
                 and ur.role in ('Coordinador','Coordinador Supervisor'));
  if not v_puede then raise exception 'sin permiso para crear links de subida'; end if;
  if public.drive_mi_rol(_item_id) is null and not public.es_dueno((select auth.uid())) then
    raise exception 'sin acceso a esa carpeta';
  end if;
  select tenant_id into v_tenant from public.drive_items where id = _item_id;
  if v_tenant is null then raise exception 'la carpeta no existe'; end if;
  insert into public.drive_upload_links(item_id, tenant_id, created_by, nombre)
    values (_item_id, v_tenant, (select auth.uid()), nullif(btrim(_nombre), ''))
    returning token into v_token;
  return v_token;
end
$$;


ALTER FUNCTION "public"."crear_link_subida"("_item_id" "uuid", "_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_platform_deal_for_contact"("p_contact_id" "uuid", "p_platform" "text", "p_subscription_amount" numeric, "p_closer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_contact public.closers_contacts%rowtype;
  v_deal_id uuid;
begin
  if not public.has_permission(auth.uid(), 'Closers', 'Asignar Closer') then
    raise exception 'Permiso denegado: Closers / Asignar Closer.' using errcode = '42501';
  end if;

  select * into v_contact from public.closers_contacts where id = p_contact_id;
  if not found then
    raise exception 'Contacto no encontrado.' using errcode = 'P0002';
  end if;

  if coalesce(trim(p_platform), '') = '' then
    raise exception 'Plataforma requerida.' using errcode = '22004';
  end if;

  select id into v_deal_id
  from public.closer_creators
  where deal_type = 'venta_plataforma'
    and stage not in ('Completada', 'No interesada')
    and source_contact_id = p_contact_id
    and lower(coalesce(main_platform, '')) = lower(p_platform)
  limit 1;

  if v_deal_id is not null then
    update public.closer_creators
      set subscription_amount = coalesce(p_subscription_amount, subscription_amount),
          assigned_to = coalesce(p_closer_id, assigned_to),
          stage = case when p_closer_id is not null and stage = 'Nuevo' then 'Asignada' else stage end,
          passed_date = case when p_closer_id is not null then coalesce(passed_date, current_date) else passed_date end
    where id = v_deal_id;
    return v_deal_id;
  end if;

  insert into public.closer_creators (
    instagram_handle, phone, category, main_platform,
    deal_type, subscription_amount, source_contact_id,
    assigned_to, stage, passed_date, created_by,
    estimated_monetization, agency_commission
  ) values (
    coalesce(nullif(v_contact.handle, ''), nullif(v_contact.name, ''), 'sin_handle'),
    v_contact.phone,
    v_contact.physical_appearance,
    p_platform,
    'venta_plataforma',
    p_subscription_amount,
    p_contact_id,
    p_closer_id,
    case when p_closer_id is not null then 'Asignada' else 'Nuevo' end,
    case when p_closer_id is not null then current_date else null end,
    auth.uid(),
    0, 0
  ) returning id into v_deal_id;

  return v_deal_id;
end;
$$;


ALTER FUNCTION "public"."create_platform_deal_for_contact"("p_contact_id" "uuid", "p_platform" "text", "p_subscription_amount" numeric, "p_closer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_platform_deal_for_creator"("p_creator_id" "uuid", "p_platform" "text", "p_subscription_amount" numeric, "p_closer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_creator public.creators%rowtype;
  v_deal_id uuid;
begin
  if not public.has_permission(auth.uid(), 'Closers', 'Asignar Closer') then
    raise exception 'Permiso denegado: Closers / Asignar Closer.' using errcode = '42501';
  end if;

  select * into v_creator from public.creadoras_de_mi_agencia() where id = p_creator_id;
  if not found then
    raise exception 'Creadora no encontrada.' using errcode = 'P0002';
  end if;

  if coalesce(trim(p_platform), '') = '' then
    raise exception 'Plataforma requerida.' using errcode = '22004';
  end if;

  select id into v_deal_id
  from public.closer_creators
  where deal_type = 'venta_plataforma'
    and stage not in ('Completada', 'No interesada')
    and lower(coalesce(main_platform, '')) = lower(p_platform)
    and (
      (v_creator.model_id is not null and model_id = v_creator.model_id)
      or lower(trim(both '@' from instagram_handle)) = lower(trim(both '@' from coalesce(v_creator.instagram_handle, '')))
    )
  limit 1;

  if v_deal_id is not null then
    update public.closer_creators
      set subscription_amount = coalesce(p_subscription_amount, subscription_amount),
          assigned_to = coalesce(p_closer_id, assigned_to),
          stage = case when p_closer_id is not null and stage = 'Nuevo' then 'Asignada' else stage end,
          passed_date = case when p_closer_id is not null then coalesce(passed_date, current_date) else passed_date end
    where id = v_deal_id;
    return v_deal_id;
  end if;

  insert into public.closer_creators (
    instagram_handle, phone, category, main_platform,
    deal_type, subscription_amount, model_id,
    assigned_to, stage, passed_date, created_by,
    estimated_monetization, agency_commission
  ) values (
    coalesce(nullif(v_creator.instagram_handle, ''), nullif(v_creator.name, ''), 'sin_handle'),
    coalesce(v_creator.phone_e164, v_creator.phone),
    v_creator.category,
    p_platform,
    'venta_plataforma',
    p_subscription_amount,
    v_creator.model_id,
    p_closer_id,
    case when p_closer_id is not null then 'Asignada' else 'Nuevo' end,
    case when p_closer_id is not null then current_date else null end,
    auth.uid(),
    0, 0
  ) returning id into v_deal_id;

  return v_deal_id;
end;
$$;


ALTER FUNCTION "public"."create_platform_deal_for_creator"("p_creator_id" "uuid", "p_platform" "text", "p_subscription_amount" numeric, "p_closer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_recruitment_deal_for_contact"("p_contact_id" "uuid", "p_closer_id" "uuid" DEFAULT NULL::"uuid", "p_estimated_monetization" numeric DEFAULT NULL::numeric, "p_agency_commission" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_contact public.closers_contacts%rowtype;
  v_handle text;
  v_kind text;
  v_lead_source text;
  v_deal_id uuid;
begin
  if not public.has_permission(auth.uid(), 'Closers', 'Asignar Closer') then
    raise exception 'Permiso denegado: Closers / Asignar Closer.' using errcode = '42501';
  end if;

  select * into v_contact from public.closers_contacts where id = p_contact_id;
  if not found then
    raise exception 'Contacto no encontrado.' using errcode = 'P0002';
  end if;

  v_kind := coalesce(v_contact.contact_kind, 'modelo');
  -- Una agencia es B2B: se le VENDE producto, no se la recluta como modelo.
  if v_kind = 'agencia' then
    raise exception 'Una agencia no se recluta para Kash: usa la venta de plataforma.'
      using errcode = '22023';
  end if;

  v_handle := coalesce(nullif(v_contact.handle, ''), nullif(v_contact.name, ''), 'sin_handle');
  -- Si ya fue creadora, el lead nace en la base Ex-creadores.
  v_lead_source := case when v_kind = 'ex_creadora' then 'ex_creadora' else 'maven' end;

  -- uq_closer_creators_open_handle: una sola fila ABIERTA por handle. Hay que
  -- PROMOVER la existente; insertar acá reventaría con violación de único.
  select id into v_deal_id
  from public.closer_creators
  where source_contact_id = p_contact_id and deal_type = 'reclutamiento'
  limit 1;

  if v_deal_id is null and lower(v_handle) <> 'sin_handle' then
    select id into v_deal_id
    from public.closer_creators
    where lower(instagram_handle) = lower(v_handle)
      and stage in ('Nuevo', 'Asignada', 'Confirmada')
    order by created_at asc
    limit 1;
  end if;

  if v_deal_id is not null then
    update public.closer_creators
    set deal_type   = 'reclutamiento',
        assigned_to = coalesce(p_closer_id, assigned_to),
        stage       = case when stage = 'Nuevo' and p_closer_id is not null then 'Asignada' else stage end,
        passed_date = coalesce(passed_date, current_date),
        source_contact_id = coalesce(source_contact_id, p_contact_id),
        phone       = coalesce(phone, v_contact.phone),
        estimated_monetization = coalesce(p_estimated_monetization, estimated_monetization),
        agency_commission      = coalesce(p_agency_commission, agency_commission),
        lead_source = case when lead_source = 'maven' then v_lead_source else lead_source end
    where id = v_deal_id;
  else
    insert into public.closer_creators (
      instagram_handle, phone, category, source_contact_id,
      assigned_to, stage, passed_date, created_by,
      lead_source, deal_type, city,
      estimated_monetization, agency_commission
    ) values (
      v_handle, v_contact.phone, v_contact.physical_appearance, p_contact_id,
      p_closer_id,
      case when p_closer_id is not null then 'Asignada' else 'Nuevo' end,
      case when p_closer_id is not null then current_date else null end,
      auth.uid(),
      v_lead_source, 'reclutamiento', v_contact.city,
      coalesce(p_estimated_monetization, 0), coalesce(p_agency_commission, 0)
    ) returning id into v_deal_id;
  end if;

  update public.closers_contacts set status = 'converted' where id = p_contact_id;
  return v_deal_id;
end;
$$;


ALTER FUNCTION "public"."create_recruitment_deal_for_contact"("p_contact_id" "uuid", "p_closer_id" "uuid", "p_estimated_monetization" numeric, "p_agency_commission" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_recruitment_deal_for_creator"("p_creator_id" "uuid", "p_closer_id" "uuid" DEFAULT NULL::"uuid", "p_estimated_monetization" numeric DEFAULT 0, "p_agency_commission" numeric DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_creator public.creators%rowtype;
  v_handle  text;
  v_deal_id uuid;
begin
  if not public.has_permission(auth.uid(), 'Closers', 'Asignar Closer') then
    raise exception 'Permiso denegado: Closers / Asignar Closer.' using errcode = '42501';
  end if;

  select * into v_creator from public.creadoras_de_mi_agencia() where id = p_creator_id;
  if not found then
    raise exception 'Creadora no encontrada.' using errcode = 'P0002';
  end if;

  v_handle := coalesce(
    nullif(
      lower(regexp_replace(
        regexp_replace(trim(coalesce(v_creator.instagram_handle, '')), '^https?://(www\.)?instagram\.com/', '', 'i'),
        '[/@?[:space:]]', '', 'g'
      )),
      ''
    ),
    nullif(trim(coalesce(v_creator.name, '')), ''),
    'sin_handle'
  );

  if lower(v_handle) <> 'sin_handle' then
    select id into v_deal_id
    from public.closer_creators
    where lower(regexp_replace(
            regexp_replace(trim(coalesce(instagram_handle, '')), '^https?://(www\.)?instagram\.com/', '', 'i'),
            '[/@?[:space:]]', '', 'g'
          )) = v_handle
      and stage in ('Nuevo', 'Asignada', 'Confirmada')
    order by created_at asc
    limit 1;
  end if;

  if v_deal_id is not null then
    update public.closer_creators
      set assigned_to = coalesce(p_closer_id, assigned_to),
          stage = case when p_closer_id is not null and stage = 'Nuevo' then 'Asignada' else stage end,
          passed_date = case when p_closer_id is not null then coalesce(passed_date, current_date) else passed_date end,
          estimated_monetization = case
            when coalesce(estimated_monetization, 0) = 0 and coalesce(p_estimated_monetization, 0) > 0
              then p_estimated_monetization else estimated_monetization end,
          agency_commission = case
            when coalesce(agency_commission, 0) = 0 and coalesce(p_agency_commission, 0) > 0
              then p_agency_commission else agency_commission end,
          model_id = coalesce(model_id, v_creator.model_id),
          lead_source = case when lead_source = 'maven' then 'ex_creadora' else lead_source end
    where id = v_deal_id;
    return v_deal_id;
  end if;

  insert into public.closer_creators (
    instagram_handle, phone, category, model_id,
    deal_type, lead_source,
    assigned_to, stage, passed_date, created_by,
    estimated_monetization, agency_commission
  ) values (
    v_handle,
    coalesce(v_creator.phone_e164, v_creator.phone),
    v_creator.category,
    v_creator.model_id,
    'reclutamiento',
    'ex_creadora',
    p_closer_id,
    case when p_closer_id is not null then 'Asignada' else 'Nuevo' end,
    case when p_closer_id is not null then current_date else null end,
    auth.uid(),
    coalesce(p_estimated_monetization, 0),
    coalesce(p_agency_commission, 0)
  ) returning id into v_deal_id;

  return v_deal_id;
end;
$$;


ALTER FUNCTION "public"."create_recruitment_deal_for_creator"("p_creator_id" "uuid", "p_closer_id" "uuid", "p_estimated_monetization" numeric, "p_agency_commission" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_recruitment_deal_for_creator"("p_creator_id" "uuid", "p_closer_id" "uuid", "p_estimated_monetization" numeric, "p_agency_commission" numeric) IS 'Manda una creadora EXISTENTE al pipeline como RECLUTAMIENTO (deal_type=reclutamiento, lead_source=ex_creadora). Lo dispara la opción "Kash" del carrito de Creadoras. Promueve la fila abierta del handle si existe (respeta uq_closer_creators_open_handle). Al cerrar usar reactivate_creator.';



CREATE TABLE IF NOT EXISTS "public"."tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "creator_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text",
    "priority" "text" DEFAULT 'medium'::"text" NOT NULL,
    "ticket_type" "text" DEFAULT 'technical'::"text" NOT NULL,
    "company" "text",
    "assigned_to" "text",
    "creator_notes" "text",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "form_id" "uuid",
    "ticket_code" "text",
    "answers" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);


ALTER TABLE "public"."tickets" OWNER TO "postgres";


COMMENT ON COLUMN "public"."tickets"."ticket_code" IS 'Codigo visible tipo TK-0001, entregado por next_ticket_code(). NULL en los tickets creados antes de las plantillas.';



COMMENT ON COLUMN "public"."tickets"."answers" IS 'Respuestas de los campos propios de la plantilla, por field_key. Las columnas reales (title/priority/...) se llenan via ticket_form_fields.maps_to.';



CREATE OR REPLACE FUNCTION "public"."create_ticket_from_form"("p_form_id" "uuid", "p_answers" "jsonb", "p_creator_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_form   public.ticket_forms;
  v_field  public.ticket_form_fields;
  v_code     text;
  v_ticket   public.tickets;
  v_val      jsonb;
  v_core     jsonb := '{}'::jsonb;
  v_title    text;
  v_priority text;
  v_creator  uuid := p_creator_id;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Se requiere sesion para crear un ticket';
  END IF;
  IF NOT public.has_permission(auth.uid(), 'Tickets', 'Crear Ticket') THEN
    RAISE EXCEPTION 'Sin permiso para crear tickets';
  END IF;
  SELECT * INTO v_form FROM public.ticket_forms WHERE id = p_form_id;
  IF v_form.id IS NULL THEN
    RAISE EXCEPTION 'Plantilla de ticket inexistente: %', p_form_id;
  END IF;
  IF NOT v_form.is_published OR v_form.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'La plantilla "%" no esta publicada', v_form.name;
  END IF;

  FOR v_field IN
    SELECT * FROM public.ticket_form_fields WHERE form_id = p_form_id ORDER BY position
  LOOP
    v_val := p_answers -> v_field.field_key;

    IF v_field.is_required AND (
         v_val IS NULL
      OR v_val = 'null'::jsonb
      OR (jsonb_typeof(v_val) = 'string' AND btrim(v_val #>> '{}') = '')
      OR (jsonb_typeof(v_val) = 'array'  AND jsonb_array_length(v_val) = 0)
    ) THEN
      RAISE EXCEPTION 'El campo "%" es obligatorio', v_field.label;
    END IF;

    -- La pregunta de tipo creadora es la fuente de tickets.creator_id.
    IF v_field.field_type = 'creator' AND v_val IS NOT NULL AND jsonb_typeof(v_val) = 'string' THEN
      BEGIN
        v_creator := (v_val #>> '{}')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'La respuesta de "%" no es una creadora valida', v_field.label;
      END;
    END IF;

    IF v_field.maps_to IS NOT NULL AND v_val IS NOT NULL THEN
      v_core := v_core || jsonb_build_object(v_field.maps_to, v_val);
    END IF;
  END LOOP;

  IF v_creator IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.creadoras_de_mi_agencia() c WHERE c.id = v_creator) THEN
    RAISE EXCEPTION 'La creadora indicada no existe';
  END IF;

  IF NULLIF(btrim(COALESCE(v_core #>> '{title}', '')), '') IS NULL THEN
    IF v_creator IS NOT NULL THEN
      SELECT COALESCE(NULLIF(btrim(c.artistic_name), ''), c.name)
        INTO v_title FROM public.creadoras_de_mi_agencia() c WHERE c.id = v_creator;
    END IF;
    v_title := COALESCE(NULLIF(btrim(COALESCE(v_title, '')), ''), v_form.name);
  ELSE
    v_title := btrim(v_core #>> '{title}');
  END IF;

  v_priority := lower(btrim(COALESCE(v_core #>> '{priority}', '')));
  IF v_priority NOT IN ('low', 'medium', 'high', 'urgent') THEN
    v_priority := 'medium';
  END IF;

  v_code := public.next_ticket_code(p_form_id);

  INSERT INTO public.tickets (
    form_id, ticket_code, creator_id, answers,
    title, description, priority, assigned_to, company, creator_notes,
    ticket_type, status
  )
  VALUES (
    p_form_id, v_code, v_creator, COALESCE(p_answers, '{}'::jsonb),
    v_title,
    NULLIF(btrim(COALESCE(v_core #>> '{description}', '')), ''),
    v_priority,
    NULLIF(btrim(COALESCE(v_core #>> '{assigned_to}', '')), ''),
    NULLIF(btrim(COALESCE(v_core #>> '{company}', '')), ''),
    NULLIF(btrim(COALESCE(v_core #>> '{creator_notes}', '')), ''),
    'general', 'open'
  )
  RETURNING * INTO v_ticket;

  RETURN v_ticket;
END;
$$;


ALTER FUNCTION "public"."create_ticket_from_form"("p_form_id" "uuid", "p_answers" "jsonb", "p_creator_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_ticket_from_form"("p_form_id" "uuid", "p_answers" "jsonb", "p_creator_id" "uuid") IS 'Crea un ticket desde una plantilla: valida permiso y campos obligatorios, asigna el consecutivo y hace el insert, todo en una transaccion. Gateada con el MISMO permiso que muestra el boton en la UI (Tickets / Crear Ticket).';



CREATE OR REPLACE FUNCTION "public"."creator_video_puede_editar"("p_creator_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  -- FOR KEY SHARE: la fila sale solo si pasa las políticas de SELECT y las de
  -- UPDATE (USING) de creators para quien llama. No escribe ni dispara nada.
  perform 1 from public.creators where id = p_creator_id for key share;
  return found;
exception when insufficient_privilege then
  -- Sin privilegio de UPDATE sobre la tabla, no puede editar.
  return false;
end
$$;


ALTER FUNCTION "public"."creator_video_puede_editar"("p_creator_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."creator_video_puede_editar"("p_creator_id" "uuid") IS '¿Quien llama puede EDITAR a esta creadora? Aplica las políticas de SELECT y UPDATE de creators (SELECT FOR KEY SHARE) sin copiarlas. Llamarla como la persona (con su JWT): con service_role la RLS no corre y da true para toda creadora que exista.';



CREATE OR REPLACE FUNCTION "public"."creators_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_mia uuid;
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id is distinct from old.tenant_id then
      raise exception 'creators_agencia: la agencia de una creadora no se cambia' using errcode = '42501';
    end if;
    return new;
  end if;

  -- Una persona (authenticated o anon): siempre la agencia de quien crea.
  if coalesce(auth.role(), 'service_role') <> 'service_role' then
    v_mia := public.current_tenant_id();
    if v_mia is null then
      raise exception 'creators_agencia: sin agencia no se crean creadoras' using errcode = '42501';
    end if;
    if new.tenant_id is null then
      new.tenant_id := v_mia;
    elsif new.tenant_id <> v_mia then
      raise exception 'creators_agencia: la creadora tiene que ser de tu agencia' using errcode = '42501';
    end if;
    return new;
  end if;

  -- service_role, cron o el editor: la que diga el pedido, o la de quien la creó.
  if new.tenant_id is null and new.created_by is not null then
    new.tenant_id := (select tm.tenant_id from public.tenant_members tm where tm.user_id = new.created_by);
  end if;
  if new.tenant_id is null then
    raise exception 'creators_agencia: falta la agencia de la creadora (tenant_id o un created_by con agencia)' using errcode = '23502';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."creators_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."creators_ficha_historial"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_quien uuid := (select auth.uid());
  v_antes jsonb;
  v_ahora jsonb;
  v_origen text;
  v_campo text;
begin
  if v_quien is null then
    return null;
  end if;
  v_antes := to_jsonb(old);
  v_ahora := to_jsonb(new);
  v_origen := case
    when exists (select 1 from public.creadora_cuentas cc where cc.user_id = v_quien and cc.creator_id = new.id) then 'portal'
    else 'ficha'
  end;
  foreach v_campo in array public.portal_campos_ficha() loop
    if (v_antes ->> v_campo) is distinct from (v_ahora ->> v_campo) then
      insert into public.creator_history (creator_id, user_id, action, old_value, new_value)
      values (new.id, v_quien, v_origen || ':' || v_campo, v_antes ->> v_campo, v_ahora ->> v_campo);
    end if;
  end loop;
  return null;
end $$;


ALTER FUNCTION "public"."creators_ficha_historial"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_movements_in_range"("p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH
    bounds AS (
      SELECT
        COALESCE(p_from, '1970-01-01'::timestamptz) AS p_from_eff,
        COALESCE(p_to,   NOW())                     AS p_to_eff
    ),
    per_creator AS (
      SELECT
        ch.creator_id,
        COALESCE(
          (SELECT h.new_state
             FROM public.creator_blu_history h, bounds
            WHERE h.creator_id = ch.creator_id
              AND h.changed_at < bounds.p_from_eff
            ORDER BY h.changed_at DESC
            LIMIT 1),
          false
        ) AS state_at_start,
        COALESCE(
          (SELECT h.new_state
             FROM public.creator_blu_history h, bounds
            WHERE h.creator_id = ch.creator_id
              AND h.changed_at <= bounds.p_to_eff
            ORDER BY h.changed_at DESC
            LIMIT 1),
          false
        ) AS state_at_end
      FROM (SELECT DISTINCT creator_id FROM public.creator_blu_history) ch
    )
  SELECT jsonb_build_object(
    'altas', (SELECT COUNT(*) FROM per_creator WHERE state_at_start = false AND state_at_end = true),
    'bajas', (SELECT COUNT(*) FROM per_creator WHERE state_at_start = true  AND state_at_end = false)
  );
$$;


ALTER FUNCTION "public"."crm_movements_in_range"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


