ALTER FUNCTION "public"."cuenta_externa_sin_rol"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cuenta_externa_sin_rol"() IS 'Cuando una cuenta de auth.users queda marcada como externa (app_metadata.tipo = creadora), le saca los roles de la agencia. GoTrue escribe app_metadata en un UPDATE después del INSERT.';



CREATE OR REPLACE FUNCTION "public"."current_tenant_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
