CREATE OR REPLACE FUNCTION "public"."delete_chat_message"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  m record;
begin
  if v_caller is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;

  select id, conversation_id, sender_id, content, content_rich, type, file_url, file_name, file_size, is_deleted,
         api_key_id, api_display_name
    into m
  from chat_messages
  where id = p_message_id;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if m.is_deleted then
    return jsonb_build_object('ok', true, 'already', true);
  end if;
  if m.sender_id <> v_caller then
    return jsonb_build_object('ok', false, 'error', 'not_author');
  end if;

  insert into chat_message_deletions (
    message_id, conversation_id, sender_id, deleted_by,
    content, content_rich, type, file_url, file_name, file_size,
    api_key_id, api_display_name
  ) values (
    m.id, m.conversation_id, m.sender_id, v_caller,
    m.content, m.content_rich, m.type, m.file_url, m.file_name, m.file_size,
    m.api_key_id, m.api_display_name
  )
  on conflict (message_id) do nothing;

  -- El permiso para pasar is_deleted a true vale para ESTE mensaje y se apaga
  -- enseguida (local a la transacción; PostgREST no expone set_config).
  perform set_config('maven.borrado_autorizado', m.id::text, true);
  update chat_messages
     set is_deleted = true, content = null, content_rich = null,
         file_url = null, file_name = null, file_size = null
   where id = m.id;
  perform set_config('maven.borrado_autorizado', '', true);

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."delete_chat_message"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_conversation_cascade"("_conversation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _msg_ids uuid[];
BEGIN
  IF (auth.jwt() ?| array['mvf', 'mvk']) IS TRUE THEN
    RAISE EXCEPTION USING ERRCODE = 'MV403',
      MESSAGE = 'api_sesion_fabricada_no_borra: una sesión fabricada no borra conversaciones',
      DETAIL = '{"error": "forbidden"}';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM chat_conversations c
    JOIN chat_participants p ON p.conversation_id = c.id AND p.user_id = auth.uid()
    WHERE c.id = _conversation_id
      AND (c.type = 'direct' OR p.role = 'admin')
  ) THEN
    RAISE EXCEPTION 'No autorizado para eliminar esta conversación';
  END IF;

  SELECT array_agg(id) INTO _msg_ids
  FROM chat_messages
  WHERE conversation_id = _conversation_id;

  IF _msg_ids IS NOT NULL AND array_length(_msg_ids, 1) > 0 THEN
    DELETE FROM chat_reactions WHERE message_id = ANY(_msg_ids);
    DELETE FROM chat_read_receipts WHERE message_id = ANY(_msg_ids);
  END IF;

  DELETE FROM chat_pinned WHERE conversation_id = _conversation_id;
  DELETE FROM chat_archived WHERE conversation_id = _conversation_id;
  DELETE FROM chat_space_conversations WHERE conversation_id = _conversation_id;
  DELETE FROM chat_messages WHERE conversation_id = _conversation_id;
  DELETE FROM chat_participants WHERE conversation_id = _conversation_id;
  DELETE FROM notifications WHERE reference_id = _conversation_id AND reference_type = 'conversation';
  DELETE FROM chat_conversations WHERE id = _conversation_id;
END;
$$;


ALTER FUNCTION "public"."delete_conversation_cascade"("_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."destinatarios_de_aviso"("_target" "uuid") RETURNS TABLE("user_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with t as (
    select (select m.tenant_id from public.tenant_members m where m.user_id = _target limit 1) as tenant_id,
           public.equipo_de(_target) as equipo,
           -- Avisos SOBRE un supervisor o jefe (Alvaro, 13/11/2026): solo dueño,
           -- admins y RR. HH.; no le llegan a sus pares.
           (coalesce((select p.nivel from public.profiles p where p.id = _target) in ('supervisor', 'manager', 'admin', 'dueno'), false)
             or exists (select 1 from public.equipos_a_cargo e where e.user_id = _target)) as es_jefe
  ),
  miembros as (
    select p.id
      from public.profiles p
      join public.tenant_members m on m.user_id = p.id
      join t on m.tenant_id = t.tenant_id
     where p.deleted_at is null
  )
  select distinct d.uid
    from (
      -- Dueño(s) de la empresa: todo.
      select o.user_id as uid from public.tenant_owners o, t where o.tenant_id = t.tenant_id
      union
      -- Admins: todo.
      select ur.user_id from public.user_roles ur
       where lower(ur.role) = 'admin' and ur.user_id in (select id from miembros)
      union
      -- RR. HH.: todo.
      select h.user_id from public.equipo_rrhh() h, t where h.tenant_id = t.tenant_id
      union
      -- Supervisores de su mismo equipo.
      select s.id from public.profiles s, t
       where not t.es_jefe
         and s.nivel = 'supervisor' and s.id in (select id from miembros)
         and t.equipo <> 'Otros' and public.equipo_de(s.id) = t.equipo
      union
      -- Jefes con ese equipo a cargo.
      select e.user_id from public.equipos_a_cargo e, t
       where not t.es_jefe
         and e.equipo = t.equipo and e.user_id in (select id from miembros)
    ) d
   where d.uid is not null and d.uid <> _target;
$$;


ALTER FUNCTION "public"."destinatarios_de_aviso"("_target" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."diagnostico_de_llamada"("_uid" "uuid", "_desde" timestamp with time zone) RETURNS TABLE("cortes" integer, "recargas" integer, "muestras" integer, "pct_computador" integer, "pct_subida" integer, "pct_inestable" integer, "pct_dormida" integer, "subida_kbps" integer, "rtt_ms" integer, "perdida_pct" numeric, "nucleos" integer, "nav" "text", "causa" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cortes int; v_recargas int; v_n int;
  v_cpu int; v_subida int; v_inestable int; v_dormida int;
  v_kbps int; v_rtt int; v_perdida numeric; v_nucleos int; v_nav text;
  v_causa text;
begin
  select count(*) filter (where c.fase in ('parpadeo_ok', 'caida', 'reentrada_agotada', 'recarga')),
         count(*) filter (where c.fase = 'recarga')
    into v_cortes, v_recargas
    from public.llamada_cortes c
   where c.user_id = _uid and c.creado >= _desde;

  with m as (
    select s.datos d from public.llamada_salud s where s.user_id = _uid and s.creado >= _desde
  )
  select count(*),
         count(*) filter (where d->>'limite_cam' = 'cpu' or d->>'limite_pant' = 'cpu'
                             or (d->>'vis' = 'visible' and coalesce(public.llamada_num(d, 'lag_ms'), 0) >= 1500)),
         count(*) filter (where d->>'limite_cam' = 'bandwidth' or d->>'limite_pant' = 'bandwidth'
                             or coalesce(public.llamada_num(d, 'subida_kbps'), 99999) < 800),
         count(*) filter (where d->>'calidad' in ('poor', 'lost')
                             or coalesce(public.llamada_num(d, 'rtt_ms'), 0) >= 400
                             or coalesce(public.llamada_num(d, 'perdida_pct'), 0) >= 5),
         count(*) filter (where d->>'vis' = 'hidden' and coalesce(public.llamada_num(d, 'lag_ms'), 0) >= 5000),
         percentile_cont(0.5) within group (order by public.llamada_num(d, 'subida_kbps'))::int,
         percentile_cont(0.5) within group (order by public.llamada_num(d, 'rtt_ms'))::int,
         round(avg(public.llamada_num(d, 'perdida_pct')), 1),
         max(public.llamada_num(d, 'nucleos'))::int,
         max(d->>'nav')
    into v_n, v_cpu, v_subida, v_inestable, v_dormida, v_kbps, v_rtt, v_perdida, v_nucleos, v_nav
    from m;

  if v_n > 0 then
    v_cpu := round(100.0 * v_cpu / v_n); v_subida := round(100.0 * v_subida / v_n);
    v_inestable := round(100.0 * v_inestable / v_n); v_dormida := round(100.0 * v_dormida / v_n);
  end if;

  v_causa := case
    when v_n = 0 and v_recargas >= 2 then 'recargas'
    when v_n = 0 then 'sin_datos'
    when greatest(v_cpu, v_subida, v_inestable, v_dormida) < 25 then
      case when v_recargas >= 2 then 'recargas' else 'sin_causa_clara' end
    when v_cpu = greatest(v_cpu, v_subida, v_inestable, v_dormida) then 'computador'
    when v_subida = greatest(v_cpu, v_subida, v_inestable, v_dormida) then 'internet_subida'
    when v_inestable = greatest(v_cpu, v_subida, v_inestable, v_dormida) then 'internet_inestable'
    else 'pestana_dormida'
  end;

  return query select v_cortes, v_recargas, v_n, v_cpu, v_subida, v_inestable, v_dormida,
                      v_kbps, v_rtt, v_perdida, v_nucleos, v_nav, v_causa;
end;
$$;


ALTER FUNCTION "public"."diagnostico_de_llamada"("_uid" "uuid", "_desde" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documento_de_quien"("_doc" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner uuid;
  v_nombre text;
begin
  select d.owner_id into v_owner
    from public.documents d
   where d.id = _doc and d.deleted_at is null;
  if v_owner is null then
    return jsonb_build_object('existe', false);
  end if;
  if not exists (
    select 1 from public.tenant_members a
      join public.tenant_members b on b.tenant_id = a.tenant_id
     where a.user_id = (select auth.uid()) and b.user_id = v_owner
  ) then
    return jsonb_build_object('existe', false);
  end if;
  select coalesce(nullif(trim(p.full_name), ''), 'su dueño') into v_nombre
    from public.profiles p where p.id = v_owner;
  return jsonb_build_object('existe', true, 'dueno', coalesce(v_nombre, 'su dueño'));
end
$$;


ALTER FUNCTION "public"."documento_de_quien"("_doc" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documento_pedir_acceso"("_doc" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_owner uuid;
  v_titulo text;
  v_nombre text;
  v_dueno text;
  v_ultimo timestamptz;
begin
  if v_yo is null then
    raise exception 'sin sesión' using errcode = '42501';
  end if;
  select d.owner_id, d.title into v_owner, v_titulo
    from public.documents d
   where d.id = _doc and d.deleted_at is null;
  if v_owner is null or not exists (
    select 1 from public.tenant_members a
      join public.tenant_members b on b.tenant_id = a.tenant_id
     where a.user_id = v_yo and b.user_id = v_owner
  ) then
    raise exception 'documento no encontrado' using errcode = 'P0002';
  end if;
  select coalesce(nullif(trim(p.full_name), ''), 'su dueño') into v_dueno from public.profiles p where p.id = v_owner;
  if v_owner = v_yo then
    return jsonb_build_object('avisado', false, 'dueno', v_dueno);
  end if;

  select pedido_at into v_ultimo
    from public.documento_pedidos_acceso
   where document_id = _doc and user_id = v_yo;
  if v_ultimo is not null and v_ultimo > now() - interval '1 hour' then
    return jsonb_build_object('avisado', false, 'ya_pedido', true, 'dueno', v_dueno);
  end if;
  insert into public.documento_pedidos_acceso (document_id, user_id, pedido_at)
  values (_doc, v_yo, now())
  on conflict (document_id, user_id) do update set pedido_at = excluded.pedido_at;

  select coalesce(nullif(trim(p.full_name), ''), 'Alguien del equipo') into v_nombre from public.profiles p where p.id = v_yo;
  insert into public.notifications
    (user_id, type, title, message, reference_id, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
  values
    (v_owner, 'documento_pedir_acceso',
     format('%s te pide acceso a «%s»', v_nombre, coalesce(nullif(trim(v_titulo), ''), 'tu documento')),
     'Ábrelo y, si corresponde, compártelo desde «Compartir».',
     _doc::text, 'document', 'Oficina', 'medium', 'new', 'personal',
     format('/oficina/%s', _doc));
  return jsonb_build_object('avisado', true, 'dueno', v_dueno);
end
$$;


ALTER FUNCTION "public"."documento_pedir_acceso"("_doc" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."donde_esta_cada_uno"() RETURNS TABLE("user_id" "uuid", "nombre" "text", "puesto" "text", "equipo" "text", "entrada" time without time zone, "salida" time without time zone, "en_turno" boolean, "estado" "text", "estado_desde" timestamp with time zone, "ultimo_latido" timestamp with time zone, "pantalla_at" timestamp with time zone, "pantalla_que" "text", "pantalla_fuera_de_lugar" boolean, "captura_at" timestamp with time zone, "fuera_hoy_veces" integer, "fuera_hoy_min" integer, "exento" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_uid uuid := (select auth.uid());
  v_tenant uuid := public.current_tenant_id();
  v_todos boolean;
  v_hoy timestamptz := date_trunc('day', now() at time zone 'America/Bogota') at time zone 'America/Bogota';
begin
  if v_uid is null then raise exception 'sin sesión' using errcode = '42501'; end if;
  v_todos := public.es_admin_o_dueno(v_uid) or coalesce(public.es_rh(v_uid), false);

  return query
  with gente as (
    select p.id, p.full_name
      from public.profiles p
      join public.tenant_members m on m.user_id = p.id and m.tenant_id = v_tenant
     where p.deleted_at is null
       and not public.es_admin_o_dueno(p.id)
       and (v_todos or p.id in (select s.user_id from public.mi_equipo_supervisado() s))
  )
  select g.id,
         g.full_name,
         (select string_agg(distinct ur.role, ' + ') from public.user_roles ur where ur.user_id = g.id),
         coalesce((select case s.name when 'CHATTERS KASH' then 'Chatters' when 'RR. HH.' then 'RR. HH.'
                                        when 'PR' then 'PR' when 'QA' then 'QA' else initcap(lower(s.name)) end
                     from public.cowork_memberships cm
                     join public.cowork_sessions s on s.id = cm.session_id and s.status = 'active'
                    where cm.user_id = g.id and cm.role <> 'host'
                    order by cm.joined_at desc limit 1),
                  public.equipo_de(g.id)),
         h.entrada, h.salida,
         (t.inicio is not null),
         case
           when seg.estado is not null then seg.estado
           when br.started_at is not null then 'pausa'
           when ll.last_seen_at is not null then 'en_llamada'
           when f.desde is not null then 'fuera_de_cowork'
           when t.inicio is not null and not public.entro_en_este_turno(g.id, t.inicio) then 'no_ha_entrado'
           when t.inicio is not null then 'fuera_de_cowork'
           else 'fuera_de_turno'
         end,
         coalesce(seg.started_at, br.started_at, f.desde),
         (select max(s3.last_seen_at) from public.cowork_tiempo_segmentos s3 where s3.user_id = g.id and s3.started_at > now() - interval '2 days'),
         cap.created_at, cap.veredicto, cap.fuera_de_lugar,
         capx.created_at,
         coalesce(fh.veces, 0), coalesce(fh.minutos, 0),
         coalesce(h.exento, false)
    from gente g
    left join lateral public.horario_de(g.id) h on true
    left join lateral public.turno_en_curso(g.id) t on true
    left join lateral (
      select s.estado, s.started_at from public.cowork_tiempo_segmentos s
       where s.user_id = g.id and s.ended_at is null and s.last_seen_at > now() - interval '90 seconds'
       order by s.started_at desc limit 1
    ) seg on true
    left join lateral (
      select b.started_at from public.cowork_breaks b
       where b.user_id = g.id and b.ended_at is null and b.started_at > now() - interval '4 hours'
       order by b.started_at desc limit 1
    ) br on true
    left join lateral (
      select x.desde from public.cowork_fuera x where x.user_id = g.id and x.hasta is null limit 1
    ) f on true
    left join lateral (
      select l.last_seen_at from public.llamada_maven_latido l
       where l.user_id = g.id and l.last_seen_at > now() - interval '90 seconds'
    ) ll on true
    left join lateral (
      select c.created_at, c.veredicto, c.fuera_de_lugar from public.monitor_capturas c
       where c.user_id = g.id and c.tipo = 'pantalla' and c.veredicto is not null and c.created_at > now() - interval '12 hours'
       order by c.created_at desc limit 1
    ) cap on true
    left join lateral (
      select c.created_at from public.monitor_capturas c
       where c.user_id = g.id and c.tipo = 'pantalla' and c.created_at > now() - interval '12 hours'
       order by c.created_at desc limit 1
    ) capx on true
    left join lateral (
      select count(*)::int as veces,
             coalesce(round(sum(extract(epoch from (coalesce(x.hasta, now()) - x.desde))) / 60), 0)::int as minutos
        from public.cowork_fuera x where x.user_id = g.id and x.desde >= v_hoy
    ) fh on true
   order by g.full_name;
end;
$$;


ALTER FUNCTION "public"."donde_esta_cada_uno"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_acceso_extra_set"("p_user" "uuid", "p_on" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not (
    public.es_dueno(auth.uid())
    or exists (select 1 from public.profiles p where p.id = auth.uid() and p.nivel in ('dueno', 'admin'))
  ) then
    raise exception 'Solo el dueño o un admin puede cambiar el acceso al Drive';
  end if;

  if p_on then
    insert into public.drive_acceso_extra (user_id, nota)
      values (p_user, 'Adendum dado desde /admin/usuarios')
      on conflict (user_id) do nothing;
  else
    delete from public.drive_acceso_extra where user_id = p_user;
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."drive_acceso_extra_set"("p_user" "uuid", "p_on" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_acceso_general"("p_item" "uuid") RETURNS TABLE("item_id" "uuid", "nombre" "text", "rol" "text", "nivel" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH RECURSIVE cadena AS (
    SELECT i.id, i.parent_id, i.nombre, 0 AS nivel
    FROM public.drive_items i WHERE i.id = p_item AND public.drive_mi_rol(p_item) IS NOT NULL
    UNION ALL
    SELECT p.id, p.parent_id, p.nombre, c.nivel + 1
    FROM public.drive_items p JOIN cadena c ON p.id = c.parent_id
    WHERE c.nivel < 50
  )
  SELECT c.id, c.nombre, a.rol, c.nivel
  FROM cadena c JOIN public.drive_compartido_agencia a ON a.item_id = c.id
  ORDER BY c.nivel
  LIMIT 1
$$;


ALTER FUNCTION "public"."drive_acceso_general"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_acceso_total"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.deleted_at is null
      and p.nivel in ('dueno', 'admin', 'manager')
  ) or exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.role in ('Coordinador', 'Coordinador Supervisor')
  ) or exists (
    select 1 from public.drive_acceso_extra e
    where e.user_id = auth.uid()
  )
$$;


ALTER FUNCTION "public"."drive_acceso_total"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_acceso_total_ids"() RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select p.id from public.profiles p
  where p.deleted_at is null and (
    p.nivel in ('dueno', 'admin', 'manager')
    or exists (select 1 from public.user_roles ur where ur.user_id = p.id and ur.role in ('Coordinador', 'Coordinador Supervisor'))
    or exists (select 1 from public.drive_acceso_extra e where e.user_id = p.id)
  )
$$;


ALTER FUNCTION "public"."drive_acceso_total_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_buscar"("p_q" "text", "p_extensiones" "text"[] DEFAULT NULL::"text"[], "p_limite" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "nombre" "text", "tipo" "text", "mime" "text", "size" bigint, "updated_at" timestamp with time zone, "owner_id" "uuid", "parent_id" "uuid", "ubicacion" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $_$
#variable_conflict use_column
DECLARE
  agencia uuid := public.current_tenant_id();
  yo uuid := auth.uid();
  q text := btrim(public.drive_nombre_buscable(coalesce(p_q, '')));
  q_inicio text;
  patrones text[];
  palabra text;
  ids uuid[];
  -- La palabra que va por el índice trigram (la más rara), o null si
  -- ninguna tiene 3 letras seguidas (el índice no ayuda).
  mas_rara text;
  exts text[];
  limite integer := least(greatest(coalesce(p_limite, 50), 1), 100);
  fin timestamptz := clock_timestamp() + interval '1.5 seconds';
  fin_recorrido timestamptz;
  -- Las de la palabra más rara, si son menos de 5000.
  candidatas uuid[];
  muchas boolean;
  fase text;
  c refcursor;
  r record;
  nombre_b text;
  empieza boolean;
  visibles integer;
  en_muestra integer;
  agotado boolean;
  -- Lo que la persona puede ver (null = no se armó: se mira cada una).
  con_acceso boolean := false;
  mis_raices uuid[];
  v_unidades uuid[];
  v_carpetas uuid[];
  -- La papelera de las carpetas de arriba, una vez por carpeta.
  vivas uuid[] := '{}';
  tiradas uuid[] := '{}';
  -- Lo encontrado: primero lo que empieza con lo buscado.
  con_inicio uuid[] := '{}';
  sin_inicio uuid[] := '{}';
BEGIN
  -- Sin sesión o sin agencia, nada. Con menos de 3 letras el índice trigram no
  -- sirve (y una letra encuentra medio Drive): el diálogo filtra lo que ve.
  IF agencia IS NULL OR yo IS NULL OR length(q) < 3 THEN
    RETURN;
  END IF;

  -- Cada palabra tiene que estar, en cualquier orden (como Google): «balance
  -- kash» encuentra «KASH · Balance 2026». Los comodines de LIKE se escapan.
  patrones := ARRAY(
    SELECT DISTINCT '%' || replace(replace(replace(w, '\', '\\'), '%', '\%'), '_', '\_') || '%'
    FROM regexp_split_to_table(q, '\s+') AS w
    WHERE w <> ''
    LIMIT 8
  );
  IF coalesce(array_length(patrones, 1), 0) = 0 THEN
    RETURN;
  END IF;
  q_inicio := replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  IF p_extensiones IS NOT NULL THEN
    exts := ARRAY(SELECT lower(e) FROM unnest(p_extensiones) AS e);
  END IF;

  -- ¿Cuál es la palabra más rara? Cada una (de 3 letras seguidas o más: con
  -- menos el trigram no tiene qué buscar) se cuenta por el índice, hasta
  -- 5000 y sin ordenar (se corta al llegar). Se guardan las de la más rara.
  FOREACH palabra IN ARRAY patrones LOOP
    CONTINUE WHEN palabra !~ '[[:alnum:]]{3}';
    ids := ARRAY(
      SELECT i.id FROM public.drive_items i
      WHERE i.tenant_id = agencia
        AND i.trashed_at IS NULL
        AND (i.tipo = 'carpeta' OR i.estado = 'listo')
        AND public.drive_nombre_buscable(i.nombre) LIKE palabra
      LIMIT 5000
    );
    IF mas_rara IS NULL OR cardinality(ids) < cardinality(candidatas) THEN
      mas_rara := palabra;
      candidatas := ids;
    END IF;
    EXIT WHEN cardinality(candidatas) = 0;
  END LOOP;
  -- Sin palabra para el índice, como si fueran muchas: se mira lo que ve.
  muchas := mas_rara IS NULL OR cardinality(candidatas) >= 5000;

  -- Lo que la persona puede ver, si hace falta (más de 50 para mirar).
  IF muchas OR cardinality(candidatas) > 50 THEN
    con_acceso := true;
    -- Lo compartido con ella y lo abierto a toda la agencia.
    mis_raices := ARRAY(
      SELECT s.item_id FROM public.drive_shares s JOIN public.drive_items i ON i.id = s.item_id
       WHERE s.user_id = yo AND i.tenant_id = agencia AND i.trashed_at IS NULL
      UNION
      SELECT a.item_id FROM public.drive_compartido_agencia a JOIN public.drive_items i ON i.id = a.item_id
       WHERE i.tenant_id = agencia AND i.trashed_at IS NULL
    );
    -- Las unidades compartidas que ve enteras. La raíz de una unidad cuelga
    -- de otra carpeta (lo importado de Google): drive_mi_rol sube por ella.
    v_unidades := ARRAY(
      SELECT u.item_id FROM public.drive_unidades u
      WHERE u.tenant_id = agencia AND u.tipo = 'empresa' AND public.drive_mi_rol(u.item_id) IS NOT NULL
    );
    -- Las carpetas que ve fuera de esas unidades: las compartidas, las
    -- abiertas a la agencia y las suyas, con todas las de abajo (sin entrar
    -- en una unidad que ya ve entera ni en la papelera).
    v_carpetas := ARRAY(
      WITH RECURSIVE abajo AS (
        SELECT i.id FROM public.drive_items i
        WHERE i.tenant_id = agencia AND i.tipo = 'carpeta' AND i.trashed_at IS NULL
          AND (i.id = ANY (mis_raices) OR i.owner_id = yo)
          AND (i.unidad_id IS NULL OR NOT (i.unidad_id = ANY (v_unidades)))
        UNION
        SELECT h.id FROM public.drive_items h JOIN abajo a ON h.parent_id = a.id
        WHERE h.tenant_id = agencia AND h.tipo = 'carpeta' AND h.trashed_at IS NULL
          AND (h.unidad_id IS NULL OR NOT (h.unidad_id = ANY (v_unidades)))
      )
      SELECT abajo.id FROM abajo
    );
  END IF;

  IF NOT muchas THEN
    fase := 'todas';
  ELSE
    -- Muchas: ¿cuánto ve la persona? Hasta 30.001.
    SELECT count(*) INTO visibles FROM (
      SELECT 1 FROM public.drive_items i
      WHERE i.tenant_id = agencia AND i.trashed_at IS NULL
        AND (i.unidad_id = ANY (v_unidades) OR i.parent_id = ANY (v_carpetas)
             OR i.id = ANY (mis_raices) OR i.owner_id = yo)
      LIMIT 30001
    ) s;
    IF visibles <= 30000 THEN
      fase := 'suyas';
    ELSE
      fase := 'recientes';
      -- Con más de una palabra puede que la rara sea común pero el conjunto
      -- no («contrato v2»): si en la muestra de 5000 hay menos de un cupo con
      -- todas, el recorrido por fecha casi no encontraría nada. Entonces, como
      -- antes: todas las de la palabra rara, ordenadas.
      IF mas_rara IS NOT NULL AND cardinality(patrones) > 1 THEN
        SELECT count(*) INTO en_muestra FROM public.drive_items i
        WHERE i.id = ANY (candidatas) AND public.drive_nombre_buscable(i.nombre) LIKE ALL (patrones);
        IF en_muestra < limite THEN
          fase := 'ordenadas';
        END IF;
      END IF;
    END IF;
  END IF;

  LOOP
    -- ⚠️ OPEN (y no FOR … IN): el plan de un cursor se arma para traer las
    -- primeras filas rápido, que es lo que hace usar el índice por fecha en el
    -- recorrido de 'recientes' en vez de leer y ordenar todo.
    IF fase = 'todas' THEN
      -- 1. Las de la palabra más rara (menos de 5000) que tienen todas las
      -- palabras, en el orden de siempre.
      OPEN c FOR
        SELECT i.id, i.nombre, i.tipo, i.estado, i.parent_id,
               public.drive_nombre_buscable(i.nombre) LIKE q_inicio AS empieza
        FROM public.drive_items i
        WHERE i.id = ANY (candidatas)
          AND i.trashed_at IS NULL
          AND (i.tipo = 'carpeta' OR i.estado = 'listo')
          AND public.drive_nombre_buscable(i.nombre) LIKE ALL (patrones)
          AND (exts IS NULL OR i.tipo = 'carpeta'
               OR lower(substring(i.nombre FROM '\.([A-Za-z0-9]+)$')) = ANY (exts))
          AND (NOT con_acceso
               OR i.unidad_id = ANY (v_unidades) OR i.parent_id = ANY (v_carpetas)
               OR i.id = ANY (mis_raices) OR i.owner_id = yo)
        ORDER BY 6 DESC, i.updated_at DESC;
    ELSIF fase = 'ordenadas' THEN
      -- 3c. Ve mucho y lo buscado entero es raro: todas las de la palabra
      -- rara que ve, en el orden de siempre (lo que hacía la función de antes).
      OPEN c FOR
        SELECT i.id, i.nombre, i.tipo, i.estado, i.parent_id,
               public.drive_nombre_buscable(i.nombre) LIKE q_inicio AS empieza
        FROM public.drive_items i
        WHERE i.tenant_id = agencia
          AND i.trashed_at IS NULL
          AND (i.tipo = 'carpeta' OR i.estado = 'listo')
          AND public.drive_nombre_buscable(i.nombre) LIKE mas_rara
          AND public.drive_nombre_buscable(i.nombre) LIKE ALL (patrones)
          AND (exts IS NULL OR i.tipo = 'carpeta'
               OR lower(substring(i.nombre FROM '\.([A-Za-z0-9]+)$')) = ANY (exts))
          AND (i.unidad_id = ANY (v_unidades) OR i.parent_id = ANY (v_carpetas)
               OR i.id = ANY (mis_raices) OR i.owner_id = yo)
        ORDER BY 6 DESC, i.updated_at DESC;
    ELSIF fase = 'suyas' THEN
      -- 2. Ve poco: lo suyo que tiene las palabras, en el orden de siempre.
      OPEN c FOR
        SELECT i.id, i.nombre, i.tipo, i.estado, i.parent_id,
               public.drive_nombre_buscable(i.nombre) LIKE q_inicio AS empieza
        FROM public.drive_items i
        WHERE i.tenant_id = agencia AND i.trashed_at IS NULL
          AND (i.tipo = 'carpeta' OR i.estado = 'listo')
          AND (i.unidad_id = ANY (v_unidades) OR i.parent_id = ANY (v_carpetas)
               OR i.id = ANY (mis_raices) OR i.owner_id = yo)
          AND public.drive_nombre_buscable(i.nombre) LIKE ALL (patrones)
          AND (exts IS NULL OR i.tipo = 'carpeta'
               OR lower(substring(i.nombre FROM '\.([A-Za-z0-9]+)$')) = ANY (exts))
        ORDER BY 6 DESC, i.updated_at DESC;
    ELSIF fase = 'recientes' THEN
      -- 3. Ve mucho: lo que ve, de lo más nuevo a lo más viejo; el nombre se
      -- mira en el bucle (empieza = null: «revisar el nombre aquí»). El LIMIT
      -- es un techo; lo que corta es el tiempo (fin_recorrido): 0,15 s si
      -- después están las ordenadas (3c) para completar; 0,6 s si no hay
      -- palabra para el índice y esto es todo.
      fin_recorrido := least(fin, clock_timestamp()
        + CASE WHEN mas_rara IS NULL THEN interval '0.6 seconds' ELSE interval '0.15 seconds' END);
      OPEN c FOR
        SELECT i.id, i.nombre, i.tipo, i.estado, i.parent_id, NULL::boolean AS empieza
        FROM public.drive_items i
        WHERE i.tenant_id = agencia AND i.trashed_at IS NULL
          AND (i.unidad_id = ANY (v_unidades) OR i.parent_id = ANY (v_carpetas)
               OR i.id = ANY (mis_raices) OR i.owner_id = yo)
        ORDER BY i.updated_at DESC
        LIMIT 300000;
    END IF;

    agotado := false;
    LOOP
      FETCH c INTO r;
      IF NOT FOUND THEN
        agotado := true;
        EXIT;
      END IF;
      EXIT WHEN clock_timestamp() > fin
        OR (fase = 'recientes' AND clock_timestamp() > fin_recorrido);

      -- En el recorrido, el nombre recién ahora.
      IF r.empieza IS NULL THEN
        CONTINUE WHEN NOT (r.tipo = 'carpeta' OR r.estado = 'listo');
        nombre_b := public.drive_nombre_buscable(r.nombre);
        CONTINUE WHEN NOT (nombre_b LIKE ALL (patrones));
        CONTINUE WHEN exts IS NOT NULL AND r.tipo <> 'carpeta'
          AND NOT coalesce(lower(substring(r.nombre FROM '\.([A-Za-z0-9]+)$')) = ANY (exts), false);
        empieza := nombre_b LIKE q_inicio;
      ELSE
        empieza := r.empieza;
      END IF;
      -- Lo que no empieza con lo buscado solo hace falta para completar.
      CONTINUE WHEN NOT empieza AND cardinality(sin_inicio) >= limite - cardinality(con_inicio);

      -- Lo que está dentro de una carpeta en la papelera también está en la
      -- papelera (la papelera marca solo la carpeta de arriba).
      IF r.parent_id IS NOT NULL THEN
        CONTINUE WHEN r.parent_id = ANY (tiradas);
        IF NOT (r.parent_id = ANY (vivas)) THEN
          IF EXISTS (
            WITH RECURSIVE arriba AS (
              SELECT p.id AS cid, p.parent_id AS madre, p.trashed_at AS tirada, 1 AS nivel
              FROM public.drive_items p WHERE p.id = r.parent_id
              UNION ALL
              SELECT p.id, p.parent_id, p.trashed_at, a.nivel + 1
              FROM public.drive_items p JOIN arriba a ON p.id = a.madre
              WHERE a.nivel < 50
            )
            SELECT 1 FROM arriba WHERE arriba.tirada IS NOT NULL
          ) THEN
            tiradas := tiradas || r.parent_id;
            CONTINUE;
          END IF;
          vivas := vivas || r.parent_id;
        END IF;
      END IF;

      -- El juez de siempre, sobre la ficha misma: nada sale sin él.
      CONTINUE WHEN public.drive_mi_rol(r.id) IS NULL;

      IF empieza THEN
        con_inicio := con_inicio || r.id;
      ELSE
        sin_inicio := sin_inicio || r.id;
      END IF;
      -- Ordenadas (1 y 2): con el cupo lleno, listo. En el recorrido se sigue
      -- hasta tener el cupo de las que empiezan con lo buscado (las demás ya
      -- quedaron guardadas si hacían falta).
      EXIT WHEN cardinality(con_inicio) >= limite
        OR (fase <> 'recientes' AND cardinality(con_inicio) + cardinality(sin_inicio) >= limite);
    END LOOP;
    CLOSE c;

    -- El recorrido se quedó corto de tiempo sin llenar el cupo (lo que la
    -- persona tiene con ese nombre es viejo o escaso): las ordenadas (3c), que
    -- son todas, en el orden de siempre, en vez de lo que juntó el recorrido.
    -- Si recorrió todo lo que ve, o no hay palabra para el índice (las
    -- ordenadas leerían la tabla entera), queda lo del recorrido.
    EXIT WHEN fase <> 'recientes' OR agotado OR mas_rara IS NULL
      OR cardinality(con_inicio) + cardinality(sin_inicio) >= limite
      OR clock_timestamp() > fin;
    fase := 'ordenadas';
    con_inicio := '{}';
    sin_inicio := '{}';
  END LOOP;

  RETURN QUERY
  SELECT i.id, i.nombre, i.tipo, i.mime, i.size, i.updated_at, i.owner_id, i.parent_id,
         -- Dónde está, para mostrarlo debajo del nombre (la carpeta madre).
         (SELECT p.nombre FROM public.drive_items p WHERE p.id = i.parent_id)
  FROM unnest(con_inicio || sin_inicio) WITH ORDINALITY AS e(eid, n)
  JOIN public.drive_items i ON i.id = e.eid
  ORDER BY e.n
  LIMIT limite;
END;
$_$;


ALTER FUNCTION "public"."drive_buscar"("p_q" "text", "p_extensiones" "text"[], "p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_carpeta_hija"("_padre" "uuid", "_nombre" "text", "_owner" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_tenant uuid;
  v_owner uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(_padre::text || '/' || lower(_nombre), 0));
  select id into v_id
    from public.drive_items
   where parent_id = _padre and tipo = 'carpeta' and trashed_at is null and lower(nombre) = lower(_nombre)
   order by created_at
   limit 1;
  if v_id is not null then return v_id; end if;

  select tenant_id, owner_id into v_tenant, v_owner
    from public.drive_items where id = _padre and tipo = 'carpeta' and trashed_at is null;
  if v_tenant is null then raise exception 'la carpeta no existe'; end if;

  insert into public.drive_items (tenant_id, owner_id, parent_id, tipo, nombre, estado)
  values (v_tenant, coalesce(_owner, v_owner), _padre, 'carpeta', _nombre, 'listo')
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."drive_carpeta_hija"("_padre" "uuid", "_nombre" "text", "_owner" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_compartido_agencia_cuidar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  SELECT i.tenant_id INTO NEW.tenant_id FROM public.drive_items i WHERE i.id = NEW.item_id;
  IF NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'La ficha no existe' USING ERRCODE = '23503';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.created_by IS NULL THEN
    NEW.created_by := auth.uid();
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."drive_compartido_agencia_cuidar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_corregir_tipos"("p_ids" "uuid"[], "p_mime" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n integer;
begin
  if p_mime is null or p_mime not in (
    'video/mp4', 'video/quicktime', 'video/webm', 'image/heic', 'image/avif', 'image/jpeg', 'image/png',
    'image/gif', 'image/webp', 'application/pdf', 'audio/mp4', 'audio/mpeg', 'audio/wav', 'audio/ogg'
  ) then
    raise exception 'Tipo no permitido: %', p_mime using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) > 2000 then
    raise exception 'Hasta 2000 por llamada' using errcode = '22023';
  end if;
  update public.drive_items i
     set mime = p_mime, updated_at = i.updated_at + interval '1 microsecond'
   where i.id = any(p_ids) and i.tipo = 'archivo'
     and (i.mime is null or i.mime in ('application/octet-stream', 'binary/octet-stream', 'application/x-binary', 'application/unknown'));
  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION "public"."drive_corregir_tipos"("p_ids" "uuid"[], "p_mime" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_crear_carpeta_creadora"("_creator" "uuid", "_dentro_de" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_nombre text;
  v_tenant uuid;
  v_id uuid;
begin
  if not public.puede_dar_links_subida(v_uid) then
    raise exception 'sin permiso' using errcode = '42501';
  end if;
  if public.drive_mi_rol(_dentro_de) not in ('dueno', 'editor') and not public.es_dueno(v_uid) then
    raise exception 'no puedes crear carpetas ahí' using errcode = '42501';
  end if;
  if exists (select 1 from public.drive_carpeta_creadora m
              join public.drive_items d on d.id = m.item_id and d.trashed_at is null
             where m.creator_id = _creator) then
    raise exception 'la creadora ya tiene carpeta';
  end if;
  select upper(regexp_replace(coalesce(nullif(trim(c.artistic_name), ''), c.name), '\s+', '', 'g'))
    into v_nombre from public.creators c where c.id = _creator and c.tenant_id = public.current_tenant_id();
  if v_nombre is null then raise exception 'la creadora no existe'; end if;
  select tenant_id into v_tenant from public.drive_items where id = _dentro_de and tipo = 'carpeta' and trashed_at is null;
  if v_tenant is null then raise exception 'la carpeta no existe'; end if;

  v_id := public.drive_carpeta_hija(_dentro_de, v_nombre, null);
  insert into public.drive_carpeta_creadora (creator_id, item_id, tenant_id, asignado_por)
  values (_creator, v_id, v_tenant, v_uid)
  on conflict (creator_id) do update set item_id = excluded.item_id, asignado_por = excluded.asignado_por;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."drive_crear_carpeta_creadora"("_creator" "uuid", "_dentro_de" "uuid") OWNER TO "postgres";


