CREATE OR REPLACE FUNCTION "public"."drive_de_toda_la_agencia"() RETURNS TABLE("item_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT a.item_id
  FROM public.drive_compartido_agencia a
  JOIN public.drive_items i ON i.id = a.item_id
  WHERE a.tenant_id = public.current_tenant_id()
    AND i.trashed_at IS NULL
    AND (i.parent_id IS NULL OR public.drive_mi_rol(i.parent_id) IS NULL)
$$;


ALTER FUNCTION "public"."drive_de_toda_la_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_dentro_de"("_item" "uuid", "_raiz" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actual uuid := _item;
  padre uuid;
  borrado timestamptz;
  pasos int := 0;
begin
  if _item is null or _raiz is null then return false; end if;
  loop
    select parent_id, trashed_at into padre, borrado from public.drive_items where id = actual;
    if not found or borrado is not null then return false; end if;
    if actual = _raiz then return true; end if;
    actual := padre;
    pasos := pasos + 1;
    if actual is null or pasos > 60 then return false; end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."drive_dentro_de"("_item" "uuid", "_raiz" "uuid") OWNER TO "postgres";


