    SET "search_path" TO ''
    AS $$
  SELECT lower(extensions.unaccent('extensions.unaccent'::regdictionary, p))
$$;


ALTER FUNCTION "public"."drive_nombre_buscable"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_registrar_actividad"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_accion   text;
  v_item     uuid;
  v_nombre   text;
  v_parent   uuid;
  v_tenant   uuid;
  v_actor    uuid;
  v_detalle  jsonb := null;
  v_via_link boolean := false;
  v_quien    text := null;
begin
  begin
    if tg_op = 'INSERT' then
      if new.tipo = 'carpeta' then
        v_accion := 'creo_carpeta';
      else
        return new;
      end if;
      v_item := new.id; v_nombre := new.nombre; v_parent := new.parent_id; v_tenant := new.tenant_id;

    elsif tg_op = 'UPDATE' then
      if new.estado = 'listo' and coalesce(old.estado,'') <> 'listo' and new.tipo = 'archivo' then
        v_accion := 'subio';
      elsif (old.trashed_at is null) and (new.trashed_at is not null) then
        v_accion := 'a_papelera';
      elsif (old.trashed_at is not null) and (new.trashed_at is null) then
        v_accion := 'restauro';
      elsif new.parent_id is distinct from old.parent_id then
        v_accion := 'movio';
        v_detalle := jsonb_build_object('de', old.parent_id, 'a', new.parent_id);
      elsif new.nombre is distinct from old.nombre then
        v_accion := 'renombro';
        v_detalle := jsonb_build_object('antes', old.nombre, 'despues', new.nombre);
      else
        return new;
      end if;
      v_item := new.id; v_nombre := new.nombre; v_parent := new.parent_id; v_tenant := new.tenant_id;

    elsif tg_op = 'DELETE' then
      v_accion := 'borro';
      v_item := old.id; v_nombre := old.nombre; v_parent := old.parent_id; v_tenant := old.tenant_id;

    else
      return null;
    end if;

    if v_accion = 'subio' then
      select a.quien into v_quien
      from public.drive_aportes a
      where a.nas_item_id = v_item or a.drive_item_id = v_item
      limit 1;
      if found then v_via_link := true; end if;
    end if;

    if v_via_link then
      v_actor := null;
      v_detalle := jsonb_build_object('via_link', true, 'quien', v_quien);
    else
      v_actor := coalesce(auth.uid(), case when tg_op = 'DELETE' then old.owner_id else new.owner_id end);
    end if;

    insert into public.drive_actividad (tenant_id, item_id, actor_id, accion, nombre, parent_id, detalle)
    values (
      v_tenant,
      case when tg_op = 'DELETE' then null else v_item end,
      v_actor, v_accion, v_nombre, v_parent, v_detalle
    );
  exception when others then
    null;
  end;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;


ALTER FUNCTION "public"."drive_registrar_actividad"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_rescatar_huerfanos"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  rescatados int := 0;
  huerfanos_viejos int := 0;
begin
  -- Huérfanos de más de 5 min (dejamos un rato para que el frontend confirme solo).
  with candidatos as (
    select o.name as storage_path,
           (o.metadata->>'size')::bigint as size_bytes,
           split_part(o.name, '/', 1) as token,
           -- Nombre bonito: el storage lo guarda "<token>/<uuid>-<nombre>"; nos quedamos con lo de después del primer guión del segundo fragmento.
           regexp_replace(split_part(o.name, '/', 2), '^[^-]+-', '') as nombre_archivo,
           l.item_id, l.tenant_id
    from storage.objects o
    join drive_upload_links l on l.token = split_part(o.name, '/', 1)
    where o.bucket_id = 'drive-aportes'
      and o.created_at < now() - interval '5 minutes'
      and o.created_at > now() - interval '7 days'
      and not exists (select 1 from drive_aportes a where a.storage_path = o.name)
  ),
  ins as (
    insert into drive_aportes (token, item_id, tenant_id, nombre_archivo, storage_path, size, quien, nas_item_id, nas_up, nas_parte)
    select token, item_id, tenant_id,
           coalesce(nullif(nombre_archivo, ''), 'archivo_rescatado.bin'),
           storage_path, size_bytes, null,
           gen_random_uuid(), gen_random_uuid(), 0
    from candidatos
    returning id
  )
  select count(*) into rescatados from ins;

  -- Si quedan huérfanos VIEJOS con token inválido, cuéntalos para la alerta.
  select count(*) into huerfanos_viejos
  from storage.objects o
  where o.bucket_id = 'drive-aportes'
    and o.created_at < now() - interval '10 minutes'
    and not exists (select 1 from drive_aportes a where a.storage_path = o.name)
    and not exists (select 1 from drive_upload_links l where l.token = split_part(o.name, '/', 1));

  return jsonb_build_object('rescatados', rescatados, 'sin_token', huerfanos_viejos);
end;
$$;


ALTER FUNCTION "public"."drive_rescatar_huerfanos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_shares_misma_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.drive_items i JOIN public.tenant_members m ON m.tenant_id = i.tenant_id AND m.user_id = NEW.user_id WHERE i.id = NEW.item_id) THEN
    RAISE EXCEPTION 'Solo se puede compartir con alguien de la misma agencia' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.drive_items WHERE id = NEW.item_id AND owner_id = NEW.user_id) THEN
    RAISE EXCEPTION 'Ya es el dueño' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."drive_shares_misma_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_sin_tipo"("p_desde" "uuid" DEFAULT NULL::"uuid", "p_limite" integer DEFAULT 1000) RETURNS TABLE("id" "uuid", "storage_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  -- ⚠️ Primero filtrar y DESPUÉS ordenar (materialized): con `order by id limit`
  -- directo, la base recorre las 891.000 fichas por el índice del id, una por
  -- una (32 s por página en prod, 06/10); así, una pasada y se ordenan las que
  -- quedan (0,8 s).
  with pendientes as materialized (
    select i.id, i.storage_key
      from public.drive_items i
     where i.tipo = 'archivo' and i.estado = 'listo' and i.storage_key is not null
       and (i.mime is null or i.mime in ('application/octet-stream', 'binary/octet-stream', 'application/x-binary', 'application/unknown'))
       and i.nombre !~ '\.[A-Za-z0-9]{1,5}$'
       and (p_desde is null or i.id > p_desde)
  )
  select id, storage_key from pendientes
   order by id
   limit least(greatest(coalesce(p_limite, 1000), 1), 2000);
$_$;


ALTER FUNCTION "public"."drive_sin_tipo"("p_desde" "uuid", "p_limite" integer) OWNER TO "postgres";


