CREATE OR REPLACE FUNCTION "public"."drive_sumar_carpeta"("p_item" "uuid", "p_agencia" "uuid", "p_hasta" timestamp with time zone) RETURNS TABLE("bytes" bigint, "archivos" bigint, "carpetas" bigint, "completo" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  nivel uuid[] := ARRAY[p_item];
  siguiente uuid[];
  vueltas integer := 0;
  b bigint;
  a bigint;
  c bigint;
BEGIN
  bytes := 0;
  archivos := 0;
  carpetas := 0;
  completo := true;
  WHILE cardinality(nivel) > 0 LOOP
    IF vueltas >= 60 OR clock_timestamp() > p_hasta THEN
      completo := false;
      EXIT;
    END IF;
    vueltas := vueltas + 1;
    SELECT coalesce(sum(i.size) FILTER (WHERE i.tipo = 'archivo' AND i.estado = 'listo'), 0),
           count(*) FILTER (WHERE i.tipo = 'archivo' AND i.estado = 'listo'),
           count(*) FILTER (WHERE i.tipo = 'carpeta'),
           coalesce(array_agg(i.id) FILTER (WHERE i.tipo = 'carpeta'), '{}'::uuid[])
      INTO b, a, c, siguiente
      FROM public.drive_items i
     WHERE i.tenant_id = p_agencia
       AND i.parent_id = ANY (nivel)
       AND i.trashed_at IS NULL;
    bytes := bytes + b;
    archivos := archivos + a;
    carpetas := carpetas + c;
    nivel := siguiente;
  END LOOP;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."drive_sumar_carpeta"("p_item" "uuid", "p_agencia" "uuid", "p_hasta" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_tamano_carpeta"("p_item" "uuid") RETURNS TABLE("bytes" bigint, "archivos" bigint, "carpetas" bigint, "completo" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  agencia uuid := public.current_tenant_id();
BEGIN
  -- Sin sesión, sin agencia o sin acceso a la carpeta: nada (ni siquiera si
  -- existe).
  IF agencia IS NULL OR auth.uid() IS NULL OR public.drive_mi_rol(p_item) IS NULL THEN
    RAISE EXCEPTION 'No tienes acceso a esa carpeta' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.drive_items i WHERE i.id = p_item AND i.tipo = 'carpeta') THEN
    RAISE EXCEPTION 'No es una carpeta' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT s.bytes, s.archivos, s.carpetas, s.completo
  FROM public.drive_sumar_carpeta(p_item, agencia, clock_timestamp() + interval '4 seconds') s;
END;
$$;


ALTER FUNCTION "public"."drive_tamano_carpeta"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."drive_tamano_carpeta"("p_item" "uuid") IS 'Detalles del Drive: bytes, archivos y carpetas dentro de una carpeta que la persona puede ver (sin papelera ni subidas a medias). completo = false si se cortó (60 niveles o ~4 s).';



CREATE OR REPLACE FUNCTION "public"."drive_tamanos"("p_ids" "uuid"[]) RETURNS TABLE("item_id" "uuid", "bytes" bigint, "archivos" bigint, "carpetas" bigint, "completo" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  agencia uuid := public.current_tenant_id();
  fin_de_tanda timestamptz := clock_timestamp() + interval '3 seconds';
  r record;
  s record;
BEGIN
  IF agencia IS NULL OR auth.uid() IS NULL OR p_ids IS NULL THEN
    RETURN;
  END IF;
  IF cardinality(p_ids) > 100 THEN
    RAISE EXCEPTION 'Se piden de a 100 carpetas como mucho' USING ERRCODE = '22023';
  END IF;
  FOR r IN
    SELECT i.id
    FROM public.drive_items i
    WHERE i.id = ANY (p_ids) AND i.tenant_id = agencia AND i.tipo = 'carpeta'
    ORDER BY array_position(p_ids, i.id)
  LOOP
    -- Las que no se alcanzan a empezar no vuelven: el navegador las vuelve a pedir.
    EXIT WHEN clock_timestamp() > fin_de_tanda;
    CONTINUE WHEN public.drive_mi_rol(r.id) IS NULL;
    SELECT * INTO s FROM public.drive_sumar_carpeta(r.id, agencia, clock_timestamp() + interval '2.5 seconds');
    item_id := r.id;
    bytes := s.bytes;
    archivos := s.archivos;
    carpetas := s.carpetas;
    completo := s.completo;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."drive_tamanos"("p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."drive_tamanos"("p_ids" "uuid"[]) IS 'Columna Tamaño del Drive: lo mismo que drive_tamano_carpeta para hasta 100 carpetas. Las que no se pueden ver o no se alcanzaron (~3 s por tanda) no vuelven.';



CREATE OR REPLACE FUNCTION "public"."drive_tiene_full"("_uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
