  select
    public.es_dueno(_uid)
    or exists (select 1 from public.profiles p where p.id = _uid and p.nivel in ('dueno','admin','manager'))
    or exists (select 1 from public.user_roles ur where ur.user_id = _uid and ur.role in ('Coordinador','Coordinador Supervisor'))
    or exists (select 1 from public.drive_acceso_extra x where x.user_id = _uid);
$$;


ALTER FUNCTION "public"."drive_tiene_full"("_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_unidad_al_subarbol"("p_raiz" "uuid", "p_unidad" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH RECURSIVE arbol AS (
    SELECT id, 0 AS nivel FROM public.drive_items WHERE parent_id = p_raiz
    UNION ALL
    SELECT d.id, a.nivel + 1 FROM public.drive_items d JOIN arbol a ON d.parent_id = a.id WHERE a.nivel < 60
  )
  UPDATE public.drive_items SET unidad_id = p_unidad
  WHERE id IN (SELECT id FROM arbol) AND unidad_id IS DISTINCT FROM p_unidad;
$$;


ALTER FUNCTION "public"."drive_unidad_al_subarbol"("p_raiz" "uuid", "p_unidad" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_unidad_de"("p_item" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE actual uuid := p_item; pasos int := 0;
BEGIN
  WHILE actual IS NOT NULL AND pasos <= 60 LOOP
    IF EXISTS (SELECT 1 FROM public.drive_unidades u WHERE u.item_id = actual AND u.tipo = 'empresa') THEN
      RETURN actual;
    END IF;
    SELECT parent_id INTO actual FROM public.drive_items WHERE id = actual;
    pasos := pasos + 1;
  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."drive_unidad_de"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_unidades_al_arbol"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE raiz uuid; unidad uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.tipo <> 'empresa' THEN RETURN NULL; END IF;
    raiz := OLD.item_id;
    unidad := public.drive_unidad_de((SELECT parent_id FROM public.drive_items WHERE id = OLD.item_id));
  ELSE
    IF NEW.tipo <> 'empresa' THEN RETURN NULL; END IF;
    raiz := NEW.item_id;
    unidad := NEW.item_id;
  END IF;
  UPDATE public.drive_items SET unidad_id = unidad WHERE id = raiz AND unidad_id IS DISTINCT FROM unidad;
  PERFORM public.drive_unidad_al_subarbol(raiz, unidad);
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."drive_unidades_al_arbol"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_unidades_cuidar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.drive_items i
                 WHERE i.id = NEW.item_id AND i.tipo = 'carpeta' AND i.owner_id IS NULL AND i.tenant_id = NEW.tenant_id) THEN
    RAISE EXCEPTION 'Una unidad es una carpeta sin dueño de la misma agencia' USING ERRCODE = '23514';
  END IF;
  IF NEW.persona IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.tenant_members m
                                             WHERE m.user_id = NEW.persona AND m.tenant_id = NEW.tenant_id) THEN
    RAISE EXCEPTION 'La persona de la unidad no es de esta agencia' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."drive_unidades_cuidar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_uso"("p_user" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("usado" bigint, "cupo" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  quien uuid := coalesce(p_user, auth.uid());
BEGIN
  IF quien <> auth.uid() AND NOT (
    public.drive_soy_admin()
    AND EXISTS (SELECT 1 FROM public.tenant_members m WHERE m.user_id = quien AND m.tenant_id = public.current_tenant_id())
  ) THEN
    RAISE EXCEPTION 'No puedes ver el uso de otra persona' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT
    coalesce((SELECT sum(i.size) FROM public.drive_items i WHERE i.owner_id = quien AND i.tipo = 'archivo' AND i.unidad_id IS NULL), 0)::bigint,
    coalesce((SELECT c.bytes_max FROM public.drive_cupos c WHERE c.user_id = quien), public.drive_cupo_por_defecto());
END;
$$;


ALTER FUNCTION "public"."drive_uso"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_uso_agencia"() RETURNS TABLE("usado" bigint, "cupo" bigint, "personas" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  agencia uuid := public.current_tenant_id();
  n integer;
  e public.drive_espacio_agencia%ROWTYPE;
BEGIN
  IF agencia IS NULL THEN
    RAISE EXCEPTION 'No encontré tu agencia' USING ERRCODE = '42501';
  END IF;
  SELECT count(*) INTO n FROM public.tenant_members m WHERE m.tenant_id = agencia;
  SELECT * INTO e FROM public.drive_espacio_agencia x WHERE x.tenant_id = agencia;
  RETURN QUERY SELECT
    coalesce((SELECT sum(i.size) FROM public.drive_items i
              WHERE i.tenant_id = agencia AND i.unidad_id IS NOT NULL AND i.tipo = 'archivo'), 0)::bigint,
    CASE
      WHEN e.tenant_id IS NOT NULL AND e.por_persona IS NULL THEN NULL
      ELSE coalesce(e.por_persona, public.drive_espacio_por_persona_por_defecto()) * n + coalesce(e.extra, 0)
    END::bigint,
    n;
END;
$$;


ALTER FUNCTION "public"."drive_uso_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drive_usos_de_mi_agencia"() RETURNS TABLE("user_id" "uuid", "nombre" "text", "usado" bigint, "cupo" bigint, "cupo_propio" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.drive_soy_admin() THEN
    RAISE EXCEPTION 'Solo para admins' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT m.user_id,
         coalesce(nullif(btrim(p.full_name), ''), u.email::text, ''),
         coalesce((SELECT sum(i.size) FROM public.drive_items i WHERE i.owner_id = m.user_id AND i.tipo = 'archivo' AND i.unidad_id IS NULL), 0)::bigint,
         coalesce(c.bytes_max, public.drive_cupo_por_defecto()),
         c.user_id IS NOT NULL
  FROM public.tenant_members m
  LEFT JOIN public.profiles p ON p.id = m.user_id
  LEFT JOIN auth.users u ON u.id = m.user_id
  LEFT JOIN public.drive_cupos c ON c.user_id = m.user_id
  WHERE m.tenant_id = public.current_tenant_id()
  ORDER BY 3 DESC, 2;
END;
$$;


ALTER FUNCTION "public"."drive_usos_de_mi_agencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_notify_enqueue"("p_kind" "text", "p_recipients" "uuid"[], "p_title" "text", "p_body" "text", "p_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_anon text;
  v_token text;
  v_base text;
  r record;
begin
  if p_recipients is null or array_length(p_recipients, 1) is null or coalesce(p_title, '') = '' then
    return;
  end if;

  for r in
    select distinct u.id, u.email
    from unnest(p_recipients) as d(uid)
    join auth.users u on u.id = d.uid
    where u.email is not null
      and public.notif_canal_activo(d.uid, p_kind, 'email')
      and not exists (
        select 1 from notification_settings ns
        where ns.user_id = d.uid and ns.notifications_enabled = false
      )
  loop
    begin
      if v_token is null then
        select decrypted_secret into v_token from vault.decrypted_secrets where name = 'cron_internal_token';
        select decrypted_secret into v_anon  from vault.decrypted_secrets where name = 'supabase_anon_key';
        select decrypted_secret into v_base  from vault.decrypted_secrets where name = 'project_url';
      end if;
      perform net.http_post(
        url := v_base || '/functions/v1/send-notification-email',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_anon,
          'apikey', v_anon,
          'X-Cron-Token', v_token
        ),
        body := jsonb_build_object(
          'to', jsonb_build_array(r.email),
          'subject', 'Maven · ' || p_title,
          'html', public.notif_email_html(p_title, p_body, p_url),
          'tag', 'aviso-' || regexp_replace(p_kind, '[^A-Za-z0-9_-]', '_', 'g')
        ),
        timeout_milliseconds := 10000
      );
    exception when others then
      raise warning 'email_notify_enqueue(%): % (usuario %)', p_kind, sqlerrm, r.id;
    end;
  end loop;
end
$$;


ALTER FUNCTION "public"."email_notify_enqueue"("p_kind" "text", "p_recipients" "uuid"[], "p_title" "text", "p_body" "text", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_expired_chatter_sessions"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  affected integer;
BEGIN
  UPDATE public.chatter_sessions
  SET status = 'ended', ended_at = now()
  WHERE status = 'active'
    AND started_at IS NOT NULL
    AND now() >= started_at + (duration_minutes::text || ' minutes')::interval;
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$;


ALTER FUNCTION "public"."end_expired_chatter_sessions"() OWNER TO "postgres";


