CREATE OR REPLACE FUNCTION "public"."equipo_agencia_que_administro"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _yo uuid := auth.uid();
  _t uuid := public.current_tenant_id();
begin
  if _yo is null or _t is null or not (
       exists (select 1 from public.tenant_owners o where o.tenant_id = _t and o.user_id = _yo)
       or exists (select 1 from public.user_roles ur
                   where ur.user_id = _yo and lower(ur.role) = 'admin' and ur.tenant_id = _t)) then
    raise exception using errcode = '42501',
      message = 'sin_permiso: solo el dueño o un admin de la agencia';
  end if;
  return _t;
end;
$$;


ALTER FUNCTION "public"."equipo_agencia_que_administro"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_clave"("_s" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
  select btrim(regexp_replace(
    translate(lower(_s), 'áàäâãéèëêíìïîóòöôõúùüûñç', 'aaaaaeeeeiiiiooooouuuunc'),
    '\s+', ' ', 'g'));
$$;


ALTER FUNCTION "public"."equipo_clave"("_s" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equipo_de"("_uid" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce((
    select m.equipo
    from public.user_roles ur
    join (values
      ('chatter', 'Chatters'), ('chatter supervisor', 'Chatters'),
      ('pr', 'PR'), ('warming', 'Warming'),
      ('coordinador', 'Editores'), ('coordinador supervisor', 'Editores'),
      ('finanzas', 'Finanzas'), ('closer', 'Closers'),
      ('operations sales', 'Operaciones'), ('admin', 'Admin'),
      ('hhrr', 'RRHH'), ('rrhh', 'RRHH')
    ) as m(rol, equipo) on m.rol = lower(ur.role)
    where ur.user_id = _uid
    order by m.equipo
    limit 1
  ), 'Otros');
$$;


