CREATE OR REPLACE FUNCTION "public"."equipo_evento_persona"("_uid" "uuid", "_con_papelera" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
           'correo', lower(u.email),
           'nombre', p.full_name,
           'rol', (select min(ur.role) from public.user_roles ur where ur.user_id = u.id),
           'nivel', p.nivel)
    from auth.users u
    join public.profiles p on p.id = u.id
   where u.id = _uid
     and coalesce(u.raw_app_meta_data ->> 'tipo', '') <> 'creadora'
     and (_con_papelera or p.deleted_at is null);
$$;


