    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  return case when nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'mvk' is not null then 'api' else 'maven' end;
exception when others then
  return 'maven';
end;
$$;


