CREATE OR REPLACE FUNCTION "public"."gen_cowork_join_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  candidate text;
BEGIN
  LOOP
    candidate := '';
    FOR _i IN 1..6 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.cowork_rooms WHERE join_code = candidate);
  END LOOP;
  RETURN candidate;
END;
$$;


ALTER FUNCTION "public"."gen_cowork_join_code"() OWNER TO "postgres";


