CREATE OR REPLACE FUNCTION "public"."generate_employee_code"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  dept_code text := 'EMP';
  next_num integer;
BEGIN
  IF NEW.department_id IS NOT NULL THEN
    SELECT code INTO dept_code FROM departments WHERE id = NEW.department_id;
  END IF;
  SELECT COALESCE(MAX(CAST(SPLIT_PART(employee_code, '-', 2) AS integer)), 0) + 1
    INTO next_num
    FROM employees
    WHERE employee_code LIKE dept_code || '-%';
  NEW.employee_code := dept_code || '-' || LPAD(next_num::text, 4, '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_employee_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_invoice_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  next_num integer;
BEGIN
  SELECT COALESCE(MAX(CAST(NULLIF(invoice_number, '') AS integer)), 0) + 1
    INTO next_num
    FROM invoices
    WHERE invoice_number ~ '^\d+$';
  NEW.invoice_number := LPAD(next_num::text, 6, '0');
  RETURN NEW;
END;
$_$;


