CREATE OR REPLACE FUNCTION "public"."get_blu_sales_summary"("p_tenant" "uuid", "p_kash" "text", "p_from" "date", "p_to" "date", "p_detalle" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select e.date::date as d, e.total_gross, e.creator_id,
           coalesce(cb.kash_type, '(sin cuenta)') as kash_type,
           coalesce(nullif(c.artistic_name,''), c.name) as creadora
    from creator_daily_earnings e
    join creators c on c.id = e.creator_id
    left join creator_business cb on cb.creator_id = e.creator_id
    where e.tenant_id = p_tenant
      and e.date::date between p_from and p_to
      and (lower(coalesce(p_kash,'both')) = 'both'
           or lower(coalesce(cb.kash_type,'')) = lower(p_kash))
  )
  select jsonb_build_object(
    'cuenta_pedida', lower(coalesce(p_kash,'both')),
    'rango', jsonb_build_object('desde', to_char(p_from,'DD/MM'), 'hasta', to_char(p_to,'DD/MM')),
    'total_gross_usd', (select round(coalesce(sum(total_gross),0)) from base),
    'por_cuenta', (select coalesce(jsonb_object_agg(kash_type, t), '{}'::jsonb)
                     from (select kash_type, round(sum(total_gross)) as t from base group by 1) s),
    'creadoras_con_ingreso', (select count(distinct creator_id) from base where total_gross > 0),
    'top5', (select coalesce(jsonb_agg(jsonb_build_object('creadora', creadora, 'cuenta', kash_type, 'gross_usd', g) order by g desc), '[]'::jsonb)
               from (select creadora, kash_type, round(sum(total_gross)) as g
                       from base group by 1,2 order by g desc limit 5) t),
    'ultima_importacion_blu', (select to_char(max(imported_at) at time zone 'America/Bogota','DD/MM HH24:MI')
                                 from creator_daily_earnings where tenant_id = p_tenant),
    'advertencia', 'La cifra de HOY es parcial (el día no cerró) y BLU puede ajustar días recientes. Plus y Massive son cuentas BLU; el manager de cada creadora es el de su ficha en Maven.'
  )
  || case when p_detalle then jsonb_build_object(
       'listado', (select coalesce(jsonb_agg(jsonb_build_object('creadora', creadora, 'cuenta', kash_type, 'gross_usd', g) order by g desc), '[]'::jsonb)
                     from (select creadora, kash_type, round(sum(total_gross)) as g
                             from base group by 1,2 having sum(total_gross) > 0) t),
       'nota_listado', 'Listado COMPLETO del rango (cuentas de la misma ficha sumadas). Entrégalo entero — no es una muestra.'
     ) else '{}'::jsonb end;
$$;


ALTER FUNCTION "public"."get_blu_sales_summary"("p_tenant" "uuid", "p_kash" "text", "p_from" "date", "p_to" "date", "p_detalle" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chatter_effort_range"("p_from" "date", "p_to" "date") RETURNS TABLE("blu_employee_id" integer, "name" "text", "days_tracked" bigint, "total_hours" numeric, "avg_activity_pct" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    cp.blu_employee_id,
    cp.name,
    count(*) as days_tracked,
    round(sum(d.tracked_seconds)::numeric / 3600.0, 1) as total_hours,
    round(avg(d.overall_activity))::integer as avg_activity_pct
  from hubstaff_daily_data d
    join hubstaff_members hm on hm.hubstaff_user_id = d.hubstaff_user_id
    join chatter_performance cp on lower(btrim(cp.email)) = lower(btrim(hm.email)) and cp.is_chatter = true
  where d.tracked_seconds > 0
    and cp.blu_employee_id is not null
    and has_role(hm.profile_id, 'Chatter'::text)
    and d.date >= p_from and d.date <= p_to
  group by cp.blu_employee_id, cp.name;
$$;


ALTER FUNCTION "public"."get_chatter_effort_range"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_chatter_sales_range"("p_from" "date", "p_to" "date") RETURNS TABLE("blu_employee_id" integer, "name" "text", "sales" numeric, "agency_revenue_usd" integer, "cost_usd" integer, "margin_usd" integer, "roi_x" numeric, "sin_venta_blu" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with cfg as (select fx_cop_per_usd fx, of_net_factor onf, effective_agency_rate rate, base_salary_cop base from public.chatter_cost_config limit 1),
  d as (select blu_employee_id, max(name) as name, sum(total_sales) as sales
        from public.chatter_daily_sales where date >= p_from and date <= p_to group by blu_employee_id),
  n as (select greatest((p_to - p_from + 1), 1)::numeric as ndays)
  select d.blu_employee_id, d.name, round(d.sales, 2) as sales,
    round(d.sales * c.onf * c.rate / 100.0)::integer as agency_revenue_usd,
    round((c.base / nullif(c.fx, 0)) * (n.ndays / 30.0))::integer as cost_usd,
    round(d.sales * c.onf * c.rate / 100.0 - (c.base / nullif(c.fx, 0)) * (n.ndays / 30.0))::integer as margin_usd,
    round((d.sales * c.onf * c.rate / 100.0) / nullif((c.base / nullif(c.fx, 0)) * (n.ndays / 30.0), 0), 2) as roi_x,
    (d.sales <= 0) as sin_venta_blu
  from d cross join cfg c cross join n;
$$;


ALTER FUNCTION "public"."get_chatter_sales_range"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_closer_activity"("p_from" "date", "p_to" "date") RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "total_contacts" bigint, "leads_touched" bigint, "auto_contacts" bigint, "manual_contacts" bigint, "leads_assigned" bigint, "leads_overdue" bigint, "by_channel" "jsonb", "by_result" "jsonb", "last_activity" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_super boolean;
begin
  if auth.uid() is null then raise exception 'forbidden' using errcode = '42501'; end if;
  v_super := public.is_in_role_group(auth.uid(), 'supervisor_or_above')
             or public.has_closer_global_scope(auth.uid());
  return query
  with roster as (
    select ur.user_id as emp from public.user_roles ur where ur.role = 'closer'
    union
    select h.created_by from public.closer_contact_history h
    where (h.contact_date at time zone 'America/Bogota')::date between p_from and p_to
      and h.created_by is not null
  ),
  roster_gated as (select emp from roster where emp is not null and (v_super or emp = auth.uid())),
  rows as (
    select h.created_by, h.creator_id, h.contact_date,
           coalesce(h.channel,'—') as channel, coalesce(h.result,'—') as result,
           (coalesce(h.notes,'')='(auto)') as is_auto
    from public.closer_contact_history h
    where (h.contact_date at time zone 'America/Bogota')::date between p_from and p_to
      and h.created_by is not null
  ),
  per_emp as (
    select r.created_by, count(*) as total, count(distinct r.creator_id) as leads,
           count(*) filter (where r.is_auto) as autoc, count(*) filter (where not r.is_auto) as manualc,
           max(r.contact_date) as last_at
    from rows r group by r.created_by
  ),
  by_chan as (
    select created_by, jsonb_object_agg(channel, n) as j
    from (select created_by, channel, count(*) n from rows group by created_by, channel) t group by created_by
  ),
  by_res as (
    select created_by, jsonb_object_agg(result, n) as j
    from (select created_by, result, count(*) n from rows group by created_by, result) t group by created_by
  ),
  assigned as (
    select cc.assigned_to as emp, cc.passed_date,
           (select count(*) from public.closer_contact_history h2 where h2.creator_id = cc.id) as done,
           (select max(h3.contact_date) from public.closer_contact_history h3 where h3.creator_id = cc.id) as last_contact
    from public.closer_creators cc
    where cc.stage='Asignada' and cc.assigned_to is not null and cc.passed_date is not null
  ),
  verdict as (
    select emp,
      case
        when done >= 6 then false
        when done = 0 then (now() at time zone 'America/Bogota')::date > assigned.passed_date + 1
        else (now() at time zone 'America/Bogota')::date >
             coalesce((last_contact at time zone 'America/Bogota')::date, assigned.passed_date)
             + ((array[1,3,5,8,15,29]::int[])[done+1] - (array[1,3,5,8,15,29]::int[])[done])
      end as is_overdue
    from assigned
  ),
  pipeline as (
    select verdict.emp, count(*) as n_assigned, count(*) filter (where is_overdue) as n_overdue
    from verdict group by verdict.emp
  )
  select rg.emp, coalesce(p.full_name,'—'),
         coalesce(e.total,0)::bigint, coalesce(e.leads,0)::bigint,
         coalesce(e.autoc,0)::bigint, coalesce(e.manualc,0)::bigint,
         coalesce(pl.n_assigned,0)::bigint, coalesce(pl.n_overdue,0)::bigint,
         coalesce(bc.j,'{}'::jsonb), coalesce(br.j,'{}'::jsonb), e.last_at
  from roster_gated rg
  left join public.profiles p on p.id = rg.emp
  left join per_emp e on e.created_by = rg.emp
  left join by_chan bc on bc.created_by = rg.emp
  left join by_res br on br.created_by = rg.emp
  left join pipeline pl on pl.emp = rg.emp
  order by coalesce(pl.n_overdue,0) desc, coalesce(e.total,0) desc, p.full_name asc;
end; $$;


ALTER FUNCTION "public"."get_closer_activity"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_closer_activity_detail"("p_from" "date", "p_to" "date", "p_employee" "uuid") RETURNS TABLE("contact_id" "uuid", "contact_date" timestamp with time zone, "lead_id" "uuid", "lead_handle" "text", "lead_stage" "text", "lead_category" "text", "lead_monetization" numeric, "channel" "text", "result" "text", "notes" "text", "is_auto" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_super boolean;
begin
  if auth.uid() is null then raise exception 'forbidden' using errcode = '42501'; end if;
  v_super := public.is_in_role_group(auth.uid(), 'supervisor_or_above')
             or public.has_closer_global_scope(auth.uid());
  if not v_super and p_employee is distinct from auth.uid() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return query
  select h.id, h.contact_date, h.creator_id, cc.instagram_handle,
         cc.stage, cc.category, cc.estimated_monetization,
         h.channel, h.result, h.notes, (coalesce(h.notes,'')='(auto)')
  from public.closer_contact_history h
  join public.closer_creators cc on cc.id = h.creator_id
  where (h.contact_date at time zone 'America/Bogota')::date between p_from and p_to
    and h.created_by = p_employee
  order by h.contact_date desc;
end; $$;


