CREATE OR REPLACE FUNCTION "public"."get_hr_person_card"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_is_mgmt boolean;
  v_name text;
  v_role text;
  v_huid text;
  v_in_hubstaff boolean;
begin
  select public.blu_is_management(auth.uid()) into v_is_mgmt;
  if not coalesce(v_is_mgmt, false) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select r.name, r.role, r.hubstaff_user_id, r.in_hubstaff
    into v_name, v_role, v_huid, v_in_hubstaff
  from public.v_hr_roster r
  where r.profile_id = p_profile_id;

  if v_name is null then
    return null;
  end if;

  return jsonb_build_object(
    'identity', jsonb_build_object(
      'profile_id', p_profile_id,
      'name', v_name,
      'role', v_role,
      'hubstaff_user_id', v_huid,
      'in_hubstaff', v_in_hubstaff
    ),
    'attendance', (
      select to_jsonb(a) from (
        select period, turno, shift_start, dias, checkin_prom_min, tardanzas,
               pct_a_tiempo, min_tarde_prom, horario_cargado
        from public.v_qa_attendance
        where hubstaff_user_id = v_huid
        order by period desc
        limit 1
      ) a
    ),
    'effort', (
      select to_jsonb(e) from (
        select period, dias, total_hours, avg_activity_pct
        from public.v_qa_effort
        where profile_id = p_profile_id
        order by period desc
        limit 1
      ) e
    ),
    'chatter', case when v_role = 'Chatter' then (
      select to_jsonb(c) from (
        select period, days_tracked, total_hours, avg_activity_pct, sales, sales_per_hour,
               avg_response_min, unlock_rate, sold_messages, fans_chatted, online_improductivo,
               cost_usd, agency_revenue_usd, margin_usd, roi_x, no_rentable, sin_venta_blu
        from public.v_chatter_hubstaff_effort
        where lower(name) = lower(v_name)
        order by period desc
        limit 1
      ) c
    ) else null end,
    'scorecard', case when v_role = 'Chatter' then (
      select to_jsonb(s) from (
        select total_sales, fan_conversion_rate, unlock_rate, avg_response_seconds,
               scheduled_hours, clocked_hours, creators_count, sold_messages, fans_chatted,
               snapshot_from, snapshot_to
        from public.chatter_performance
        where lower(name) = lower(v_name)
        order by snapshot_to desc nulls last
        limit 1
      ) s
    ) else null end,
    'closer', case when v_role = 'closer' then (
      select to_jsonb(cl) from (
        select period, dias, total_hours, avg_activity_pct, leads, cerradas,
               monetizacion_usd, usd_por_hora, qa_calls, avg_qa_score, sin_cierres
        from public.v_closer_hubstaff
        where lower(name) = lower(v_name)
        order by period desc
        limit 1
      ) cl
    ) else null end,
    'llg', case when v_role = 'LLG' then (
      select to_jsonb(l) from (
        select period, dias, total_hours, avg_activity_pct, leads, leads_por_hora
        from public.v_llg_hubstaff
        where lower(name) = lower(v_name)
        order by period desc
        limit 1
      ) l
    ) else null end
  );
end;
$$;


ALTER FUNCTION "public"."get_hr_person_card"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_karma_profile"("target" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller   uuid := auth.uid();
  v_is_admin boolean;
  v_role text; v_role_label text;
  v_name text; v_avatar text; v_seed text; v_created timestamptz;
  v_email text; v_viewer_can_mail boolean := false;
  s_constancia boolean := false;
  s_actividad boolean := false;
  s_productividad boolean := false;
  s_rendimiento boolean := false;
  s_companerismo boolean := false;
  v_sent int := 0; v_recv int := 0; v_active_days int := 0;
  v_hub_act int := null; v_hub_hours numeric := null;
  v_givers int := 0; v_eligible int := 0; v_vote_pct int := 0;
  v_viewer_sent boolean := false;
  v_special boolean := false;
  v_stars_count int := 0;
  result jsonb;
begin
  -- Solo gente de la propia agencia (20261001212100): el perfil de alguien de
  -- otra agencia es «no existe».
  if target is distinct from v_caller
     and target not in (select public.gente_de_mi_agencia()) then
    return jsonb_build_object('error','not_found');
  end if;

  v_is_admin := exists (
    select 1 from user_roles ur
    join role_groups rg on rg.role_name = ur.role and rg.tenant_id = ur.tenant_id
    where ur.user_id = v_caller and rg.is_admin = true
  );

  select full_name, avatar_url, avatar_seed, created_at
    into v_name, v_avatar, v_seed, v_created
  from profiles where id = target;
  if not found then
    return jsonb_build_object('error','not_found');
  end if;

  select coalesce(
    (select c.email_address from mail_credentials c where c.user_id = target and c.revoked_at is null limit 1),
    (select u.email from auth.users u where u.id = target)
  ) into v_email;

  v_viewer_can_mail :=
    exists (select 1 from mail_credentials c where c.user_id = v_caller and c.revoked_at is null)
    and public.has_permission(v_caller, 'Correo');

  select role into v_role from user_roles where user_id = target limit 1;
  v_role_label := case v_role
    when 'agent' then 'Chatter'
    when 'closer' then 'Closer'
    when 'manager' then 'Manager'
    when 'admin' then 'Admin'
    when 'supervisor' then 'Supervisor'
    when 'employee' then 'Empleado'
    when 'spammer' then 'Warming'
    else coalesce(v_role, 'Miembro')
  end;

  s_constancia := v_created is not null and v_created <= now() - interval '6 months';

  select count(*), count(distinct (created_at at time zone 'UTC')::date)
    into v_sent, v_active_days
  from chat_messages
  where sender_id = target and is_deleted = false and type <> 'system'
    and api_key_id is null
    and created_at >= now() - interval '30 days';
  s_actividad := v_sent >= 100 and v_active_days >= 10;

  select count(*) into v_recv
  from chat_messages m
  where m.sender_id <> target and m.is_deleted = false and m.type <> 'system'
    and m.created_at >= now() - interval '30 days'
    and m.conversation_id in (select conversation_id from chat_participants where user_id = target);

  select round(avg(d.overall_activity))::int, round(sum(d.tracked_seconds)/3600.0, 1)
    into v_hub_act, v_hub_hours
  from hubstaff_daily_data d
  join hubstaff_members hm on hm.hubstaff_user_id = d.hubstaff_user_id
  where hm.profile_id = target and d.tracked_seconds > 0
    and d.date >= current_date - 30;
  s_productividad := v_hub_act is not null and v_hub_act >= 65 and coalesce(v_hub_hours,0) >= 40;

  select (avg(qc.claude_score) / 10.0) >= 9 into s_rendimiento
  from qa_calls qc
  join qa_closers qcl on qcl.id = qc.closer_id
  where qcl.profile_id = target
    and qc.claude_score is not null
    and date_trunc('month', qc.call_date) = date_trunc('month', current_date - interval '1 month');
  s_rendimiento := coalesce(s_rendimiento, false);

  select count(distinct user_id) into v_eligible
  from user_roles
  where user_id <> target and role not in ('spammer','Warming')
    and user_id in (select public.gente_de_mi_agencia());

  select count(*) into v_givers from karma_sends where recipient_id = target;
  v_viewer_sent := exists(select 1 from karma_sends where recipient_id = target and giver_id = v_caller);
  if v_eligible > 0 then v_vote_pct := round(100.0 * v_givers / v_eligible); end if;

  s_companerismo := v_eligible > 0 and v_givers >= ceil(0.20 * v_eligible);
  v_special := v_eligible > 0 and v_givers > 0.70 * v_eligible;

  v_stars_count := s_rendimiento::int + s_actividad::int + s_constancia::int
                 + s_productividad::int + s_companerismo::int;

  result := jsonb_build_object(
    'user_id', target, 'name', v_name, 'avatar_url', v_avatar, 'avatar_seed', v_seed,
    'role', v_role_label,
    'email', v_email, 'viewer_can_mail', v_viewer_can_mail,
    'stars', jsonb_build_object(
      'rendimiento', s_rendimiento, 'actividad', s_actividad, 'constancia', s_constancia,
      'productividad', s_productividad, 'companerismo', s_companerismo
    ),
    'stars_count', v_stars_count, 'special', v_special, 'vote_pct', v_vote_pct,
    'viewer_has_sent', v_viewer_sent, 'is_self', target = v_caller, 'viewer_is_admin', v_is_admin
  );

  if v_is_admin then
    result := result || jsonb_build_object('admin', jsonb_build_object(
      'msgs_sent_30d', v_sent, 'msgs_recv_30d', v_recv, 'active_days_30d', v_active_days,
      'hub_activity_30d', v_hub_act, 'hub_hours_30d', v_hub_hours,
      'karma_givers', v_givers, 'eligible', v_eligible,
      'criteria', jsonb_build_object(
        'rendimiento',   jsonb_build_object('met', s_rendimiento,   'label','Rendimiento',  'rule','QA mensual >= 9'),
        'actividad',     jsonb_build_object('met', s_actividad,     'label','Actividad',    'rule','>= 100 msgs / 30 dias en >= 10 dias'),
        'constancia',    jsonb_build_object('met', s_constancia,    'label','Constancia',   'rule','>= 6 meses en el equipo'),
        'productividad', jsonb_build_object('met', s_productividad, 'label','Productividad','rule','Hubstaff >= 65% act. y >= 40h'),
        'companerismo',  jsonb_build_object('met', s_companerismo,  'label','Companerismo', 'rule','karma de >= 20% del equipo')
      )
    ));
  end if;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_karma_profile"("target" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."chat_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "sender_id" "uuid" NOT NULL,
    "content" "text",
    "type" "text" DEFAULT 'text'::"text" NOT NULL,
    "file_url" "text",
    "file_name" "text",
    "file_size" bigint,
    "reply_to_id" "uuid",
    "is_edited" boolean DEFAULT false NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "album_id" "uuid",
    "is_thread_reply" boolean DEFAULT false NOT NULL,
    "content_rich" "jsonb",
    "api_key_id" "uuid",
    "api_display_name" "text",
    CONSTRAINT "chat_messages_api_coherente" CHECK (((("api_key_id" IS NULL) = ("api_display_name" IS NULL)) AND (("api_key_id" IS NULL) OR (("type" = 'text'::"text") AND ("file_url" IS NULL) AND ("file_name" IS NULL) AND ("file_size" IS NULL) AND ("album_id" IS NULL) AND ("content_rich" IS NULL) AND ("is_deleted" OR ((COALESCE("char_length"("content"), 0) >= 1) AND (COALESCE("char_length"("content"), 0) <= 4000))))))),
    CONSTRAINT "chat_messages_type_check" CHECK (("type" = ANY (ARRAY['text'::"text", 'image'::"text", 'file'::"text", 'system'::"text"])))
);

ALTER TABLE ONLY "public"."chat_messages" REPLICA IDENTITY FULL;


ALTER TABLE "public"."chat_messages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."chat_messages"."content_rich" IS 'Documento TipTap (JSON) con el formato del mensaje. NULL = mensaje de texto plano. El texto plano vive siempre en content.';



CREATE OR REPLACE FUNCTION "public"."get_last_messages"("_user_id" "uuid") RETURNS SETOF "public"."chat_messages"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT cm.*
  FROM chat_participants cp
  CROSS JOIN LATERAL (
    SELECT m.*
    FROM chat_messages m
    WHERE m.conversation_id = cp.conversation_id
    ORDER BY m.created_at DESC, m.id DESC
    LIMIT 1
  ) cm
  WHERE cp.user_id = _user_id
    AND _user_id = auth.uid();
$$;


ALTER FUNCTION "public"."get_last_messages"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_outcomes_de_origen"("p_tenant" "uuid", "p_query" "text", "p_days" integer DEFAULT 21) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with quien as (
    select id, full_name from profiles
    where full_name ilike '%' || p_query || '%'
    order by (full_name ilike p_query || '%') desc limit 1
  ),
  contactos as (
    select cc.id from closers_contacts cc, quien q
    where cc.created_by = q.id and cc.phone is not null
      and cc.created_at >= current_date - p_days
  ),
  perfiles as (
    select le.id from leadgen_entries le, quien q
    where le.lg_user_id = q.id and le.created_at >= current_date - p_days
  ),
  pipeline as (
    select distinct cr.id, cr.instagram_handle, cr.stage,
           split_part(coalesce(p.full_name, '(sin asignar)'), ' ', 1) as closer,
           cr.last_contact_date, cr.rejection_reason, cr.confirmed_date, cr.completed_date
    from closer_creators cr
    left join profiles p on p.id = cr.assigned_to
    where cr.source_contact_id in (select id from contactos)
       or cr.leadgen_entry_id in (select id from perfiles)
  )
  select case when not exists (select 1 from quien) then jsonb_build_object('not_found', true, 'member', p_query)
  else jsonb_build_object(
    'member', (select full_name from quien),
    'ventana_dias', p_days,
    'numeros_cargados', (select count(*) from contactos),
    'perfiles_cargados', (select count(*) from perfiles),
    'en_pipeline', (select count(*) from pipeline),
    'por_stage', coalesce((select jsonb_object_agg(stage, n) from (
       select stage, count(*) n from pipeline group by stage) s), '{}'::jsonb),
    'leads', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
       'handle', pi.instagram_handle, 'stage', pi.stage, 'closer', pi.closer,
       'ultimo_contacto', to_char(pi.last_contact_date, 'DD/MM'),
       'confirmada', to_char(pi.confirmed_date, 'DD/MM'),
       'completada', to_char(pi.completed_date, 'DD/MM'),
       'rechazo', pi.rejection_reason))
       order by pi.last_contact_date desc nulls last)
     from (select * from pipeline limit 30) pi), '[]'::jsonb),
    'nota', 'Resultados de NEGOCIO de sus números/perfiles (pipeline de closers). Un lead sin fila aquí aún no fue tomado. NO incluye conversaciones del grupo de closers — eso es de ese equipo.'
  ) end;
$$;


ALTER FUNCTION "public"."get_lead_outcomes_de_origen"("p_tenant" "uuid", "p_query" "text", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_manager_contact_stats"("p_from" "date", "p_to" "date", "p_tenant" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("creator_id" "uuid", "name" "text", "instagram_handle" "text", "manager_profile_id" "uuid", "phone_ok" boolean, "last_contact_at" timestamp with time zone, "contact_days_in_range" integer, "msgs_in_range" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not (
    coalesce(current_setting('request.jwt.claims', true), '') = ''
    or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role'
    or exists (select 1 from public.user_roles ur
               where ur.user_id = auth.uid() and ur.role in ('admin','manager','owner'))
  ) then
    raise exception 'forbidden: métricas de managers solo para management' using errcode = '42501';
  end if;

  return query
  with mgr_lines as (
    select ch.id from public.wa_channels ch
    where ch.department = 'manager' and ch.active
      and (p_tenant is null or ch.tenant_id = p_tenant)
  ),
  outbound as (
    select right(regexp_replace(coalesce(ct.phone_e164,''),'\D','','g'),10) as d10,
           msg.sent_at,
           ((msg.sent_at at time zone 'America/Bogota')::date) as dia_bog
    from public.wa_conversations conv
    join public.wa_contacts ct on ct.id = conv.contact_id
    join public.wa_conversation_messages msg
      on msg.conversation_id = conv.id
     and msg.deleted_at is null
     and msg.direction = 'out'
     and coalesce(msg.status,'') <> 'failed'
    where conv.channel_id in (select id from mgr_lines)
  ),
  per_phone as (
    select d10,
           max(sent_at) as last_out_at,
           count(distinct dia_bog) filter (where dia_bog between p_from and p_to)::int as contact_days,
           count(*) filter (where dia_bog between p_from and p_to)::int as msgs
    from outbound
    group by d10
  ),
  models as (
    select c.id,
           coalesce(nullif(c.artistic_name,''), c.name) as cname,
           c.instagram_handle as ig,
           c.assigned_manager_profile_id as mgr,
           right(regexp_replace(coalesce(c.phone_e164, c.whatsapp_number, c.phone, ''),'\D','','g'),10) as d10
    from public.creadoras_de_mi_agencia() c
    where c.status = 'active' and c.assigned_manager_profile_id is not null
  )
  select m.id, m.cname, m.ig, m.mgr,
         (length(m.d10) = 10) as phone_ok,
         pp.last_out_at,
         coalesce(pp.contact_days, 0),
         coalesce(pp.msgs, 0)
  from models m
  left join per_phone pp on length(m.d10) = 10 and pp.d10 = m.d10;
end;
$$;


ALTER FUNCTION "public"."get_manager_contact_stats"("p_from" "date", "p_to" "date", "p_tenant" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_manager_growth_feed"("p_tenant" "uuid", "p_low_promo_rate" numeric DEFAULT 0.40, "p_income_drop_pct" numeric DEFAULT 15) RETURNS TABLE("creator_id" "uuid", "name" "text", "instagram_handle" "text", "category" "text", "manager_profile_id" "uuid", "manager_name" "text", "manager_phone" "text", "promo_days" integer, "covered_days" integer, "mtd_day" integer, "income_mtd" numeric, "income_prev_mtd" numeric, "income_trend_pct" numeric, "quadrant" "text", "priority" integer, "diagnosis" "text", "promo_networks" "text", "ig_has_data" boolean, "ig_promo_days" integer, "ig_read_days" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with b0 as (
    select
      date_trunc('month', (now() at time zone 'America/Bogota')::date)::date as this_start,
      extract(day from (now() at time zone 'America/Bogota')::date)::int as mtd_day,
      greatest(date_trunc('month', (now() at time zone 'America/Bogota')::date)::date, (now() at time zone 'America/Bogota')::date - 2)::date as inc_cutoff,
      (date_trunc('month', (now() at time zone 'America/Bogota')::date) - interval '1 month')::date as prev_start
  ),
  bounds as (
    select this_start, mtd_day, inc_cutoff,
      extract(day from inc_cutoff)::int as income_day,
      prev_start,
      least(prev_start + (inc_cutoff - this_start), this_start - 1) as prev_cutoff
    from b0
  ),
  active_models as (
    select c.id, coalesce(nullif(c.artistic_name,''), c.name) as name, c.instagram_handle,
           c.category, c.assigned_manager_profile_id as mgr
    from creators c
    where c.status = 'active' and c.assigned_manager_profile_id is not null
  ),
  promo as (
    select e.creator_id,
      count(distinct e.dia) filter (where e.promoted in ('true','yes','partial')) as promo_days,
      count(distinct e.dia) filter (where coalesce(e.promoted,'') <> 'pending') as covered_days
    from promolog_entries e cross join bounds b
    where e.tenant_id = p_tenant and e.dia >= b.this_start
    group by e.creator_id
  ),
  net_days as (
    select e.creator_id, e.network,
      count(distinct e.dia) filter (where e.promoted in ('true','yes','partial')) as d
    from promolog_entries e cross join bounds b
    where e.tenant_id = p_tenant and e.dia >= b.this_start
    group by e.creator_id, e.network
  ),
  nets as (
    select creator_id,
      string_agg(network || ':' || d || 'd', ', ' order by d desc, network) as promo_networks
    from net_days where d > 0 group by creator_id
  ),
  ig as (
    select e.creator_id,
      count(distinct e.dia) filter (where e.promoted in ('true','yes','partial')) as ig_promo_days,
      count(distinct e.dia) filter (where coalesce(e.promoted,'') <> 'pending') as ig_read_days
    from promolog_entries e cross join bounds b
    where e.tenant_id = p_tenant and e.dia >= b.this_start and e.network = 'instagram'
    group by e.creator_id
  ),
  inc as (
    select e.creator_id,
      coalesce(sum(e.total_gross) filter (where e.date >= b.this_start and e.date <= b.inc_cutoff), 0) as income_mtd,
      coalesce(sum(e.total_gross) filter (where e.date >= b.prev_start and e.date <= b.prev_cutoff), 0) as income_prev_mtd
    from creator_daily_earnings e cross join bounds b
    where e.date >= b.prev_start
    group by e.creator_id
  ),
  scored as (
    select a.id, a.name, a.instagram_handle, a.category, a.mgr,
      m.full_name as manager_name, m.phone_e164 as manager_phone,
      coalesce(p.promo_days,0) as promo_days, coalesce(p.covered_days,0) as covered_days,
      b.mtd_day, b.income_day,
      coalesce(i.income_mtd,0) as income_mtd, coalesce(i.income_prev_mtd,0) as income_prev_mtd,
      n.promo_networks,
      coalesce(g.ig_promo_days,0) as ig_promo_days,
      coalesce(g.ig_read_days,0) as ig_read_days,
      (coalesce(g.ig_promo_days,0) > 0
        and coalesce(g.ig_promo_days,0) * 10 >= coalesce(p.promo_days,0) * 3) as ig_is_channel,
      (coalesce(p.covered_days,0) >= 5 and coalesce(p.promo_days,0) < p_low_promo_rate * coalesce(p.covered_days,0)) as low_promo,
      (coalesce(i.income_prev_mtd,0) > 0 and coalesce(i.income_mtd,0) < coalesce(i.income_prev_mtd,0) * (1 - p_income_drop_pct/100.0)) as income_down,
      case when coalesce(i.income_prev_mtd,0) > 0
           then round(((coalesce(i.income_mtd,0) - i.income_prev_mtd) / i.income_prev_mtd * 100)::numeric)
           else null end as income_trend_pct
    from active_models a
    cross join bounds b
    left join profiles m on m.id = a.mgr
    left join promo p on p.creator_id = a.id
    left join nets n on n.creator_id = a.id
    left join ig g on g.creator_id = a.id
    left join inc i on i.creator_id = a.id
  )
  select s.id, s.name, s.instagram_handle, s.category, s.mgr, s.manager_name, s.manager_phone,
    s.promo_days, s.covered_days, s.mtd_day, s.income_mtd, s.income_prev_mtd, s.income_trend_pct,
    case when s.low_promo and s.income_down then 'critico'
         when (not s.low_promo) and s.income_down then 'calidad'
         when s.low_promo and (not s.income_down) then 'riesgo'
         else 'sana' end as quadrant,
    case when s.low_promo and s.income_down then 1
         when (not s.low_promo) and s.income_down then 2
         when s.low_promo and (not s.income_down) then 3
         else 4 end as priority,
    case
      when s.low_promo and s.income_down then
        format('Promociona %s de %s días leídos este mes y sus ingresos caen %s%% (al día %s: $%s vs $%s el mes pasado) → empujar promo YA%s',
               s.promo_days, s.covered_days, abs(s.income_trend_pct), s.income_day, round(s.income_mtd), round(s.income_prev_mtd),
               case when s.promo_networks is null then '' else format(' [promo en %s]', s.promo_networks) end)
      when (not s.low_promo) and s.income_down then
        case
          when s.covered_days < 5 then
            format('⚠️ DATOS INSUFICIENTES este mes (solo %s días leídos): no alcanza para juzgar promo ni calidad. Su ingreso cae %s%% (al día %s) → revisar cobertura del scan/handles antes de sacar conclusiones%s',
                   s.covered_days, abs(s.income_trend_pct), s.income_day,
                   case when s.promo_networks is null then '' else format(' [promo en %s]', s.promo_networks) end)
          when s.promo_networks is null then
            format('⚠️ SIN promo registrada en NINGUNA red este mes (%s días leídos) y su ingreso cae %s%% (al día %s) → NO es un problema de calidad: verifica si realmente está promocionando y que el scan la esté cubriendo',
                   s.covered_days, abs(s.income_trend_pct), s.income_day)
          when s.ig_is_channel then
            format('Promociona bien (%s/%s días leídos) pero sus ingresos caen %s%% (al día %s vs mismo tramo del mes pasado) → revisar CALIDAD/estrategia [promo en %s]',
                   s.promo_days, s.covered_days, abs(s.income_trend_pct), s.income_day, s.promo_networks)
          else
            format('Promociona bien (%s/%s días leídos) pero sus ingresos caen %s%% (al día %s vs mismo tramo del mes pasado) → revisar CALIDAD/estrategia ⚠️ INSTAGRAM NO ES SU CANAL (IG: %s días de promo / %s leídos) — su promo es en %s: NO atribuyas la caída a las historias de IG, revisa la calidad EN ESAS REDES',
                   s.promo_days, s.covered_days, abs(s.income_trend_pct), s.income_day,
                   s.ig_promo_days, s.ig_read_days, s.promo_networks)
        end
      when s.low_promo and (not s.income_down) then
        format('Promociona poco (%s/%s días leídos este mes) — ingreso aún ok, pero riesgo a futuro → sumar promo/otra red%s',
               s.promo_days, s.covered_days,
               case when s.promo_networks is null then '' else format(' [promo en %s]', s.promo_networks) end)
      else 'Sana' end as diagnosis,
    s.promo_networks,
    (s.ig_read_days > 0) as ig_has_data,
    s.ig_promo_days,
    s.ig_read_days
  from scored s
  where s.covered_days >= 5 and not (s.low_promo = false and s.income_down = false)
  order by priority, s.income_mtd desc;
$_$;


ALTER FUNCTION "public"."get_manager_growth_feed"("p_tenant" "uuid", "p_low_promo_rate" numeric, "p_income_drop_pct" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_manager_growth_feed"("p_tenant" "uuid", "p_low_promo_rate" numeric, "p_income_drop_pct" numeric) IS 'Radar promo×ingreso por creadora en alerta. ig_promo_days/ig_read_days/promo_networks: si IG no es su canal de promo, el veredicto de calidad NO debe atribuirse a historias de IG.';



CREATE OR REPLACE FUNCTION "public"."get_manager_growth_stats"("p_from" "date", "p_to" "date", "p_tenant" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("creator_id" "uuid", "name" "text", "instagram_handle" "text", "manager_profile_id" "uuid", "new_fans" integer, "new_sub_gross" numeric, "recurring_sub_gross" numeric, "total_gross" numeric, "prev_new_fans" integer, "prev_new_sub_gross" numeric, "prev_total_gross" numeric, "days_with_data" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_len int := (p_to - p_from) + 1;
  v_prev_from date := p_from - v_len;
  v_prev_to date := p_from - 1;
begin
  if not (
    coalesce(current_setting('request.jwt.claims', true), '') = ''
    or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role'
    or exists (select 1 from public.user_roles ur
               where ur.user_id = auth.uid() and ur.role in ('admin','manager','owner'))
  ) then
    raise exception 'forbidden: métricas de managers solo para management' using errcode = '42501';
  end if;

  return query
  with models as (
    select c.id,
           coalesce(nullif(c.artistic_name,''), c.name) as cname,
           c.instagram_handle as ig,
           c.assigned_manager_profile_id as mgr
    from public.creadoras_de_mi_agencia() c
    where c.status = 'active' and c.assigned_manager_profile_id is not null
  ),
  cur as (
    select e.creator_id,
           sum(coalesce(e.new_fans,0))::int as new_fans,
           sum(coalesce(e.new_sub_gross,0)) as new_sub,
           sum(coalesce(e.recurring_sub_gross,0)) as rec_sub,
           sum(coalesce(e.total_gross,0)) as total,
           count(distinct e.date)::int as days_with_data
    from public.creator_daily_earnings e
    where e.date between p_from and p_to
      and (p_tenant is null or e.tenant_id = p_tenant)
    group by e.creator_id
  ),
  prev as (
    select e.creator_id,
           sum(coalesce(e.new_fans,0))::int as new_fans,
           sum(coalesce(e.new_sub_gross,0)) as new_sub,
           sum(coalesce(e.total_gross,0)) as total
    from public.creator_daily_earnings e
    where e.date between v_prev_from and v_prev_to
      and (p_tenant is null or e.tenant_id = p_tenant)
    group by e.creator_id
  )
  select m.id, m.cname, m.ig, m.mgr,
         coalesce(cur.new_fans, 0),
         coalesce(cur.new_sub, 0),
         coalesce(cur.rec_sub, 0),
         coalesce(cur.total, 0),
         coalesce(prev.new_fans, 0),
         coalesce(prev.new_sub, 0),
         coalesce(prev.total, 0),
         coalesce(cur.days_with_data, 0)
  from models m
  left join cur on cur.creator_id = m.id
  left join prev on prev.creator_id = m.id;
end;
$$;


ALTER FUNCTION "public"."get_manager_growth_stats"("p_from" "date", "p_to" "date", "p_tenant" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_manager_roster_stats"("p_tenant" "uuid", "p_date" "date" DEFAULT NULL::"date") RETURNS TABLE("manager_profile_id" "uuid", "manager_name" "text", "kash_types" "text", "effective_date" "date", "is_partial_day" boolean, "total_active" integer, "scannable_count" integer, "reachable_count" integer, "covered_count" integer, "promoted_count" integer, "promoted_pct" numeric, "contacted_count" integer, "contacted_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with d as (
    select coalesce(p_date, (now() at time zone 'America/Bogota')::date) as day,
           (now() at time zone 'America/Bogota')::date as today_bog
  ),
  roster as (
    select c.id,
           c.assigned_manager_profile_id as mgr,
           cb.kash_type,
           (coalesce(nullif(trim(c.instagram_handle),''), nullif(trim(c.telegram_handle),'')) is not null) as scannable,
           right(public.canonical_phone(coalesce(c.phone_e164, c.whatsapp_number, c.phone)),10) as k10,
           right(regexp_replace(coalesce(c.phone_e164, c.whatsapp_number, c.phone, ''),'\D','','g'),8) as k8
    from public.creadoras_de_mi_agencia() c
    left join public.creator_business cb on cb.creator_id = c.id
    where c.status = 'active'
  ),
  promo as (
    select e.creator_id,
      bool_or(e.promoted in ('true','yes','partial')) as promoted,
      bool_or(coalesce(e.promoted,'') <> 'pending') as covered
    from public.promolog_entries e cross join d
    where e.tenant_id = p_tenant
      and e.dia = d.day
    group by 1
  ),
  mgr_lines as (
    select id from public.wa_channels
    where tenant_id = p_tenant and department = 'manager' and active
  ),
  contact_out as (
    select right(public.canonical_phone(ct.phone_e164),10) as k10,
           right(regexp_replace(coalesce(ct.phone_e164,''),'\D','','g'),8) as k8
    from public.wa_conversations conv
    join public.wa_contacts ct on ct.id = conv.contact_id
    join public.wa_conversation_messages msg
      on msg.conversation_id = conv.id and msg.deleted_at is null
         and msg.direction = 'out' and coalesce(msg.status,'') <> 'failed'
    cross join d
    where conv.channel_id in (select id from mgr_lines)
      and msg.sent_at >= (d.day::timestamp at time zone 'America/Bogota')
      and msg.sent_at <  ((d.day + 1)::timestamp at time zone 'America/Bogota')
    group by 1, 2
  ),
  by_canon as (select k10 from contact_out where length(k10) = 10 group by k10),
  by_k8 as (select k8, count(distinct k10) as n_canon from contact_out where length(k8) = 8 group by k8),
  roster_k8 as (select k8, count(*) as n_roster from roster where length(k8) = 8 group by k8),
  resolved as (
    select r.mgr, r.kash_type, r.scannable,
      (length(r.k10) = 10 or length(r.k8) = 8) as reachable,
      coalesce(p.promoted, false) as promoted,
      coalesce(p.covered, false) as covered,
      (
        exists (select 1 from by_canon bc where length(r.k10) = 10 and bc.k10 = r.k10)
        or exists (
          select 1 from by_k8 bk join roster_k8 rk on rk.k8 = bk.k8
          where length(r.k8) = 8 and bk.k8 = r.k8 and bk.n_canon = 1 and rk.n_roster = 1
        )
      ) as contacted
    from roster r
    left join promo p on p.creator_id = r.id
  )
  select r.mgr,
         m.full_name,
         string_agg(distinct r.kash_type, '/' order by r.kash_type),
         (select day from d),
         (select day = today_bog from d),
         count(*)::int,
         count(*) filter (where r.scannable)::int,
         count(*) filter (where r.reachable)::int,
         count(*) filter (where r.covered)::int,
         count(*) filter (where r.promoted)::int,
         round(100.0 * count(*) filter (where r.promoted) / nullif(count(*), 0)),
         count(*) filter (where r.contacted)::int,
         round(100.0 * count(*) filter (where r.contacted) / nullif(count(*) filter (where r.reachable), 0))
  from resolved r
  left join public.profiles m on m.id = r.mgr
  group by r.mgr, m.full_name
  order by m.full_name nulls last;
$$;


ALTER FUNCTION "public"."get_manager_roster_stats"("p_tenant" "uuid", "p_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_manager_roster_stats"("p_tenant" "uuid", "p_date" "date") IS 'Roster por manager + promo/contacto del día y sus %. El día se resuelve en Bogotá (effective_date); is_partial_day=true ⇒ el % es un PISO. promoted_pct va sobre total_active, contacted_pct sobre reachable_count.';



CREATE OR REPLACE FUNCTION "public"."get_manager_silent_creators"("p_tenant" "uuid", "p_days" integer DEFAULT 3) RETURNS TABLE("creator_id" "uuid", "name" "text", "instagram_handle" "text", "manager_profile_id" "uuid", "manager_name" "text", "last_contact_at" timestamp with time zone, "days_since_contact" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with mgr_lines as (
    select id from public.wa_channels where tenant_id = p_tenant and department = 'manager' and active
  ),
  contact_out as (
    select right(public.canonical_phone(ct.phone_e164),10) as k10,
           right(regexp_replace(coalesce(ct.phone_e164,''),'\D','','g'),8) as k8,
           max(msg.sent_at) as last_out
    from public.wa_conversations conv
    join public.wa_contacts ct on ct.id = conv.contact_id
    join public.wa_conversation_messages msg
      on msg.conversation_id = conv.id and msg.deleted_at is null and msg.direction = 'out' and coalesce(msg.status,'') <> 'failed'
    where conv.channel_id in (select id from mgr_lines)
    group by 1, 2
  ),
  by_canon as (select k10, max(last_out) as last_out from contact_out where length(k10) = 10 group by k10),
  by_k8 as (select k8, count(distinct k10) as n_canon, max(last_out) as last_out from contact_out where length(k8) = 8 group by k8),
  active_models as (
    select c.id, coalesce(nullif(c.artistic_name,''), c.name) as name, c.instagram_handle,
           c.assigned_manager_profile_id as mgr,
           right(public.canonical_phone(coalesce(c.phone_e164, c.whatsapp_number, c.phone)),10) as k10,
           right(regexp_replace(coalesce(c.phone_e164, c.whatsapp_number, c.phone, ''),'\D','','g'),8) as k8
    from public.creadoras_de_mi_agencia() c where c.status = 'active' and c.assigned_manager_profile_id is not null
  ),
  resolved as (
    select a.id, a.name, a.instagram_handle, a.mgr,
           coalesce(
             (select bc.last_out from by_canon bc where length(a.k10) = 10 and bc.k10 = a.k10),
             (select bk.last_out from by_k8 bk where length(a.k8) = 8 and bk.k8 = a.k8 and bk.n_canon = 1)
           ) as last_out
    from active_models a where length(a.k10) = 10
  )
  select r.id, r.name, r.instagram_handle, r.mgr, m.full_name,
         r.last_out as last_contact_at,
         case when r.last_out is null then null else extract(day from (now() - r.last_out))::int end as days_since_contact
  from resolved r left join public.profiles m on m.id = r.mgr
  where r.last_out is null or r.last_out < now() - make_interval(days => p_days)
  order by m.full_name nulls last, r.last_out asc nulls first;
$$;


ALTER FUNCTION "public"."get_manager_silent_creators"("p_tenant" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_manager_silent_no_promo"("p_tenant" "uuid", "p_days" integer DEFAULT 3, "p_low_promo_rate" numeric DEFAULT 0.40) RETURNS TABLE("creator_id" "uuid", "name" "text", "instagram_handle" "text", "manager_profile_id" "uuid", "manager_name" "text", "manager_phone" "text", "promo_days" integer, "mtd_day" integer, "days_since_contact" integer, "last_contact_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with bounds as (select date_trunc('month', (now() at time zone 'America/Bogota')::date)::date as this_start, extract(day from (now() at time zone 'America/Bogota')::date)::int as mtd_day),
  mgr_lines as (select id from public.wa_channels where tenant_id = p_tenant and department = 'manager' and active),
  contact_out as (
    select right(public.canonical_phone(ct.phone_e164),10) as k10,
           right(regexp_replace(coalesce(ct.phone_e164,''),'\D','','g'),8) as k8,
           max(msg.sent_at) as last_out
    from public.wa_conversations conv
    join public.wa_contacts ct on ct.id = conv.contact_id
    join public.wa_conversation_messages msg on msg.conversation_id = conv.id and msg.deleted_at is null and msg.direction = 'out'
    where conv.channel_id in (select id from mgr_lines)
    group by 1, 2
  ),
  by_canon as (select k10, max(last_out) as last_out from contact_out where length(k10) = 10 group by k10),
  by_k8 as (select k8, count(distinct k10) as n_canon, max(last_out) as last_out from contact_out where length(k8) = 8 group by k8),
  active_models as (
    select c.id, coalesce(nullif(c.artistic_name,''), c.name) as name, c.instagram_handle,
           c.assigned_manager_profile_id as mgr,
           right(public.canonical_phone(coalesce(c.phone_e164, c.whatsapp_number, c.phone)),10) as k10,
           right(regexp_replace(coalesce(c.phone_e164, c.whatsapp_number, c.phone, ''),'\D','','g'),8) as k8
    from public.creadoras_de_mi_agencia() c where c.status = 'active' and c.assigned_manager_profile_id is not null
  ),
  promo as (
    -- promo_days incluye 'partial' (antes quedaba afuera y subcontaba la promo real).
    -- covered_days = días efectivamente LEÍDOS (excluye 'pending' = scan fallido), que
    -- es el denominador honesto: un día que no se pudo leer no prueba que no promocionó.
    select e.creator_id,
           count(distinct e.dia) filter (where e.promoted in ('true','yes','partial')) as promo_days,
           count(distinct e.dia) filter (where e.promoted in ('true','yes','partial','false')) as covered_days
    from public.promolog_entries e cross join bounds b
    where e.tenant_id = p_tenant and e.dia >= b.this_start group by e.creator_id
  ),
  resolved as (
    select a.id, a.name, a.instagram_handle, a.mgr,
      coalesce(
        (select bc.last_out from by_canon bc where length(a.k10) = 10 and bc.k10 = a.k10),
        (select bk.last_out from by_k8 bk where length(a.k8) = 8 and bk.k8 = a.k8 and bk.n_canon = 1)
      ) as last_out
    from active_models a where length(a.k10) = 10
  )
  select r.id, r.name, r.instagram_handle, r.mgr, m.full_name, m.phone_e164,
         coalesce(p.promo_days, 0)::int as promo_days,
         -- se devuelve en la columna mtd_day para no tocar el TS que la imprime: ahora
         -- el "x/y" del mensaje muestra días LEÍDOS, que es contra lo que se compara.
         coalesce(p.covered_days, 0)::int as mtd_day,
         extract(day from (now() - r.last_out))::int as days_since_contact, r.last_out as last_contact_at
  from resolved r
  left join public.profiles m on m.id = r.mgr
  left join promo p on p.creator_id = r.id
  where r.last_out is not null and r.last_out < now() - make_interval(days => p_days)
    and coalesce(p.covered_days, 0) >= 5
    and coalesce(p.promo_days, 0) < p_low_promo_rate * coalesce(p.covered_days, 0)
  order by r.last_out asc;
$$;


ALTER FUNCTION "public"."get_manager_silent_no_promo"("p_tenant" "uuid", "p_days" integer, "p_low_promo_rate" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_mentioned_conversations"("_user_id" "uuid", "_nombre" "text", "_nombre_pila" "text") RETURNS TABLE("conversation_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT cp.conversation_id
  FROM chat_participants cp
  JOIN chat_messages cm ON cm.conversation_id = cp.conversation_id
  WHERE cp.user_id = _user_id
    AND _user_id = auth.uid()
    AND cm.is_deleted = false
    AND cm.sender_id <> _user_id
    AND (cp.last_read_at IS NULL OR cm.created_at > cp.last_read_at)
    AND (
      position(lower('@' || _nombre) in lower(cm.content)) > 0
      OR position(lower('@' || _nombre_pila) in lower(cm.content)) > 0
    );
$$;


ALTER FUNCTION "public"."get_mentioned_conversations"("_user_id" "uuid", "_nombre" "text", "_nombre_pila" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_promo_day_breakdown"("p_tenant" "uuid", "p_date" "date" DEFAULT NULL::"date", "p_manager_name" "text" DEFAULT NULL::"text") RETURNS TABLE("manager_name" "text", "creator_id" "uuid", "creadora" "text", "handle" "text", "cuentas" "text", "promo_stories" integer, "networks" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with d as (
    select coalesce(p_date, (now() at time zone 'America/Bogota')::date) as day
  )
  select
    m.full_name as manager_name,
    c.id as creator_id,
    coalesce(nullif(c.artistic_name,''), nullif(c.instagram_handle,''), c.name) as creadora,
    coalesce(nullif(c.instagram_handle,''), nullif(c.artistic_name,''), c.name) as handle,
    nullif(string_agg(distinct lower(coalesce(nullif(e.source_handle,''), '')), ', ') filter (
      where coalesce(e.source_handle,'') <> ''
    ), '') as cuentas,
    greatest(max(coalesce(e.story_count, 1)), 1)::int as promo_stories,
    nullif(string_agg(distinct lower(coalesce(e.network, e.platform, '')), ', ') filter (
      where coalesce(e.network, e.platform, '') <> ''
    ), '') as networks
  from promolog_entries e
  cross join d
  join public.creadoras_de_mi_agencia() c on c.id = e.creator_id and c.status = 'active'
  left join profiles m on m.id = c.assigned_manager_profile_id
  where e.tenant_id = p_tenant
    and e.dia = d.day
    and e.promoted = 'true'
    and (p_manager_name is null or m.full_name ilike '%' || p_manager_name || '%')
  group by m.full_name, c.id, c.instagram_handle, c.artistic_name, c.name
  order by m.full_name nulls last, promo_stories desc;
$$;


ALTER FUNCTION "public"."get_promo_day_breakdown"("p_tenant" "uuid", "p_date" "date", "p_manager_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_promo_day_faltantes"("p_tenant" "uuid", "p_date" "date" DEFAULT NULL::"date", "p_manager_name" "text" DEFAULT NULL::"text") RETURNS TABLE("manager_name" "text", "creadora" "text", "estado" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with d as (
    select coalesce(p_date, (now() at time zone 'America/Bogota')::date) as day
  ),
  hoy as (
    select e.creator_id,
           bool_or(e.promoted = 'true') as promo,
           bool_or(e.promoted = 'false') as leida
    from promolog_entries e cross join d
    where e.tenant_id = p_tenant and e.dia = d.day
    group by e.creator_id
  )
  select
    m.full_name as manager_name,
    coalesce(nullif(c.artistic_name,''), nullif(c.instagram_handle,''), c.name) as creadora,
    case when coalesce(h.leida, false) then 'leida_sin_promo' else 'sin_leer' end as estado
  from public.creadoras_de_mi_agencia() c
  left join profiles m on m.id = c.assigned_manager_profile_id
  left join hoy h on h.creator_id = c.id
  where c.status = 'active'
    and not coalesce(h.promo, false)
    and (p_manager_name is null or m.full_name ilike '%' || p_manager_name || '%')
  order by m.full_name nulls last, estado, creadora;
$$;


ALTER FUNCTION "public"."get_promo_day_faltantes"("p_tenant" "uuid", "p_date" "date", "p_manager_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_promo_month_comparison"("p_tenant" "uuid", "p_months_back" integer DEFAULT 1, "p_manager_name" "text" DEFAULT NULL::"text") RETURNS TABLE("creator_id" "uuid", "name" "text", "instagram_handle" "text", "manager_name" "text", "current_from" "date", "current_to" "date", "prev_from" "date", "prev_to" "date", "window_days" integer, "promo_days_current" integer, "promo_days_prev" integer, "delta" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with bounds as (
    select
      date_trunc('month', (now() at time zone 'America/Bogota')::date)::date as this_start,
      (now() at time zone 'America/Bogota')::date as this_end,
      (date_trunc('month', (now() at time zone 'America/Bogota')::date) - make_interval(months => p_months_back))::date as prev_start,
      least(
        (date_trunc('month', (now() at time zone 'America/Bogota')::date) - make_interval(months => p_months_back))::date
          + ((now() at time zone 'America/Bogota')::date - date_trunc('month', (now() at time zone 'America/Bogota')::date)::date),
        (date_trunc('month', (now() at time zone 'America/Bogota')::date) - make_interval(months => p_months_back)
          + interval '1 month' - interval '1 day')::date
      ) as prev_cutoff
  ),
  active_models as (
    select c.id, coalesce(nullif(c.artistic_name,''), c.name) as name, c.instagram_handle,
           m.full_name as manager_name
    from public.creadoras_de_mi_agencia() c
    left join profiles m on m.id = c.assigned_manager_profile_id
    where c.status = 'active' and c.assigned_manager_profile_id is not null
      and (p_manager_name is null or m.full_name ilike '%' || p_manager_name || '%')
  ),
  promo as (
    select e.creator_id,
      count(distinct e.dia) filter (
        where e.promoted in ('true','yes') and e.dia >= b.this_start and e.dia <= b.this_end
      ) as cur_days,
      count(distinct e.dia) filter (
        where e.promoted in ('true','yes') and e.dia >= b.prev_start and e.dia <= b.prev_cutoff
      ) as prev_days
    from promolog_entries e cross join bounds b
    where e.tenant_id = p_tenant and e.dia >= b.prev_start
    group by e.creator_id
  )
  select a.id, a.name, a.instagram_handle, a.manager_name,
         b.this_start, b.this_end, b.prev_start, b.prev_cutoff,
         (b.prev_cutoff - b.prev_start + 1) as window_days,
         coalesce(p.cur_days, 0)::int, coalesce(p.prev_days, 0)::int,
         (coalesce(p.cur_days, 0) - coalesce(p.prev_days, 0))::int as delta
  from active_models a
  cross join bounds b
  left join promo p on p.creator_id = a.id
  order by (coalesce(p.cur_days, 0) - coalesce(p.prev_days, 0)) asc, a.name;
$$;


ALTER FUNCTION "public"."get_promo_month_comparison"("p_tenant" "uuid", "p_months_back" integer, "p_manager_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_promolog_action_feed"("p_tenant" "uuid") RETURNS TABLE("kind" "text", "priority" integer, "creator_id" "uuid", "name" "text", "category" "text", "instagram_handle" "text", "reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH promoted_today AS (
    SELECT creator_id, array_agg(DISTINCT lower(network)) AS nets
    FROM promolog_entries
    WHERE tenant_id = p_tenant AND dia = (now() at time zone 'America/Bogota')::date
      AND promoted IN ('true', 'yes') AND creator_id IS NOT NULL
    GROUP BY creator_id
  ),
  read_today AS (
    SELECT DISTINCT creator_id
    FROM promolog_entries
    WHERE tenant_id = p_tenant AND dia = (now() at time zone 'America/Bogota')::date
      AND creator_id IS NOT NULL
      AND coalesce(error_reason, '') <> 'scrape_no_media'
      AND coalesce(story_count, 0) > 0
  ),
  active AS (
    SELECT id, coalesce(NULLIF(artistic_name, ''), name) AS name, category, instagram_handle
    FROM public.creadoras_de_mi_agencia() WHERE status = 'active'
  )
  SELECT 'tier_sin_promo'::text, 1, a.id, a.name, a.category, a.instagram_handle,
         'Tier alto sin promocionar hoy — empujar promo'::text
  FROM active a
    JOIN read_today r ON r.creator_id = a.id
    LEFT JOIN promoted_today p ON p.creator_id = a.id
  WHERE a.category IN ('Elite', 'A+') AND p.creator_id IS NULL
  UNION ALL
  SELECT 'solo_ig'::text, 3, a.id, a.name, a.category, a.instagram_handle,
         'Solo promociona en IG hoy — empujar otra red'::text
  FROM active a JOIN promoted_today p ON p.creator_id = a.id
  WHERE p.nets = ARRAY['instagram']
  ORDER BY 2, 4;
$$;


ALTER FUNCTION "public"."get_promolog_action_feed"("p_tenant" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_promolog_stale_creators"("p_days" integer DEFAULT 7) RETURNS TABLE("creator_id" "uuid", "name" "text", "handle" "text", "days_empty" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select c.id, coalesce(nullif(c.artistic_name,''),c.name),
         lower(regexp_replace(coalesce(c.instagram_handle,''),'.*instagram\.com/|[@/ ]','','gi')),
         p_days
  from public.creadoras_de_mi_agencia() c
  where c.status='active' and nullif(trim(c.instagram_handle),'') is not null
    and not exists (
      select 1 from promolog_entries e
      where e.creator_id=c.id and e.network ilike 'instagram'
        and e.story_count>0 and e.dia >= (now() at time zone 'America/Bogota')::date - p_days
    );
$$;


ALTER FUNCTION "public"."get_promolog_stale_creators"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sales_daily_totals"("p_from" "date", "p_to" "date") RETURNS TABLE("date" "date", "total_gross" numeric, "subscription_gross" numeric, "tips_gross" numeric, "message_gross" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not coalesce(public.blu_is_management(auth.uid()), false) then
    raise exception 'forbidden: management only' using errcode = '42501';
  end if;
  return query
  select
    e.date                                          as date,
    coalesce(sum(e.total_gross), 0)::numeric        as total_gross,
    coalesce(sum(e.subscription_gross), 0)::numeric as subscription_gross,
    coalesce(sum(e.tips_gross), 0)::numeric         as tips_gross,
    coalesce(sum(e.message_gross), 0)::numeric      as message_gross
  from public.creator_daily_earnings e
  where e.date >= p_from and e.date <= p_to
  group by e.date
  order by e.date;
end;
$$;


ALTER FUNCTION "public"."get_sales_daily_totals"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sales_monthly_totals"("p_months" integer) RETURNS TABLE("month" "date", "total_gross" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_first_month date;
begin
  if not coalesce(public.blu_is_management(auth.uid()), false) then
    raise exception 'forbidden: management only' using errcode = '42501';
  end if;
  if p_months is null or p_months < 1 or p_months > 60 then
    raise exception 'p_months debe estar entre 1 y 60';
  end if;
  v_first_month := (date_trunc('month', timezone('America/Bogota', now()))
                    - make_interval(months => p_months - 1))::date;
  return query
  select
    date_trunc('month', e.date)::date        as month,
    coalesce(sum(e.total_gross), 0)::numeric as total_gross
  from public.creator_daily_earnings e
  where e.date >= v_first_month
  group by 1
  order by 1;
end;
$$;


ALTER FUNCTION "public"."get_sales_monthly_totals"("p_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sub_pricing"("p_tenant" "uuid", "p_query" "text" DEFAULT NULL::"text", "p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with base as (
    select c.id, coalesce(nullif(c.artistic_name,''), c.name) as creadora, c.instagram_handle,
           coalesce(sum(e.new_fans),0)::int as fans_nuevos,
           round(coalesce(sum(e.new_sub_gross),0)::numeric, 0) as plata_subs_nuevas,
           case when sum(e.new_fans) > 0
             then round((sum(e.new_sub_gross) / sum(e.new_fans))::numeric, 2) end as precio_efectivo,
           round(coalesce(sum(e.recurring_sub_gross),0)::numeric, 0) as renovaciones_usd,
           round(coalesce(sum(e.total_gross),0)::numeric, 0) as ingreso_total,
           case when sum(e.new_fans) >= 5 and coalesce(sum(e.new_sub_gross),0) < 1 then 'gratis'
                when sum(e.new_fans) > 0 then 'paga'
                else 'sin_subs_nuevas_en_ventana' end as tipo
    from creators c
    left join creator_daily_earnings e on e.creator_id = c.id
      and e.date >= current_date - p_days and e.tenant_id = p_tenant
    where c.status = 'active'
    group by c.id, creadora, c.instagram_handle
  )
  select case
    when p_query is not null then
      coalesce((select to_jsonb(b) - 'id' || jsonb_build_object('ventana_dias', p_days,
         'nota', 'precio_efectivo = plata de subs NUEVAS / fans nuevos (BLU). Es el promedio REAL cobrado (descuentos/trials incluidos), NO el precio de lista del panel de OF.')
       from base b
       where lower(coalesce(b.instagram_handle,'')) = lower(regexp_replace(trim(p_query), '^@', ''))
          or b.creadora ilike '%' || p_query || '%'
       order by (lower(coalesce(b.instagram_handle,'')) = lower(regexp_replace(trim(p_query), '^@', ''))) desc
       limit 1), jsonb_build_object('not_found', true, 'creator', p_query))
    else jsonb_build_object(
      'ventana_dias', p_days,
      'nota', 'precio_efectivo = plata de subs NUEVAS / fans nuevos (BLU). NO es precio de lista; cuentas gratis salen en ~$0. Ordenado de mayor a menor precio.',
      'creadoras', (select jsonb_agg((to_jsonb(b) - 'id') order by b.precio_efectivo desc nulls last)
                    from base b where b.fans_nuevos > 0),
      'sin_fans_nuevos_en_ventana', (select count(*) from base where fans_nuevos = 0),
      'bandas', (select jsonb_agg(to_jsonb(x) order by x.precio_min) from (
         select case when precio_efectivo < 1 then 'gratis (~$0)'
                     when precio_efectivo < 4 then 'baja (<$4)'
                     when precio_efectivo <= 6 then 'media ($4-6)'
                     else 'alta (>$6)' end as banda,
                min(precio_efectivo) as precio_min,
                count(*) as creadoras,
                round(avg(precio_efectivo), 2) as precio_prom,
                round(avg(ingreso_total), 0) as ingreso_total_prom,
                sum(fans_nuevos) as fans_nuevos_suma
         from base where precio_efectivo is not null
         group by 1
      ) x)
    )
  end;
$_$;


ALTER FUNCTION "public"."get_sub_pricing"("p_tenant" "uuid", "p_query" "text", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sub_pricing"("p_tenant" "uuid", "p_query" "text" DEFAULT NULL::"text", "p_days" integer DEFAULT 30, "p_manager" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with base as (
    select c.id, coalesce(nullif(c.artistic_name,''), c.name) as creadora, c.instagram_handle,
           coalesce(sum(e.new_fans),0)::int as fans_nuevos,
           round(coalesce(sum(e.new_sub_gross),0)::numeric, 0) as plata_subs_nuevas,
           case when sum(e.new_fans) > 0
             then round((sum(e.new_sub_gross) / sum(e.new_fans))::numeric, 2) end as precio_efectivo,
           round(coalesce(sum(e.recurring_sub_gross),0)::numeric, 0) as renovaciones_usd,
           round(coalesce(sum(e.total_gross),0)::numeric, 0) as ingreso_total,
           case when sum(e.new_fans) >= 5 and coalesce(sum(e.new_sub_gross),0) < 1 then 'gratis'
                when sum(e.new_fans) > 0 then 'paga'
                else 'sin_subs_nuevas_en_ventana' end as tipo
    from creators c
    left join creator_daily_earnings e on e.creator_id = c.id
      and e.date >= current_date - p_days and e.tenant_id = p_tenant
    left join profiles pm on pm.id = c.assigned_manager_profile_id
    left join creator_business cb on cb.creator_id = c.id
    where c.status = 'active'
      and (p_manager is null
           or pm.full_name ilike p_manager || '%')
    group by c.id, creadora, c.instagram_handle
  )
  select case
    when p_query is not null then
      coalesce((select to_jsonb(b) - 'id' || jsonb_build_object('ventana_dias', p_days,
         'nota', 'precio_efectivo = plata de subs NUEVAS / fans nuevos (BLU). Es el promedio REAL cobrado (descuentos/trials incluidos), NO el precio de lista del panel de OF.')
       from base b
       where lower(coalesce(b.instagram_handle,'')) = lower(regexp_replace(trim(p_query), '^@', ''))
          or b.creadora ilike '%' || p_query || '%'
       order by (lower(coalesce(b.instagram_handle,'')) = lower(regexp_replace(trim(p_query), '^@', ''))) desc
       limit 1), jsonb_build_object('not_found', true, 'creator', p_query))
    else jsonb_build_object(
      'ventana_dias', p_days,
      'manager', coalesce(p_manager, 'todas'),
      'nota', 'precio_efectivo = plata de subs NUEVAS / fans nuevos (BLU). NO es precio de lista; gratis ~$0. Ordenado de mayor a menor precio.',
      'creadoras', (select jsonb_agg(jsonb_build_object(
            'creadora', b.creadora, 'precio', b.precio_efectivo, 'tipo', b.tipo, 'fans_nuevos', b.fans_nuevos)
            order by b.precio_efectivo desc nulls last)
          from base b where b.fans_nuevos > 0),
      'sin_fans_nuevos_en_ventana', (select count(*) from base where fans_nuevos = 0),
      'bandas', (select jsonb_agg(to_jsonb(x) order by x.precio_min) from (
         select case when precio_efectivo < 1 then 'gratis (~$0)'
                     when precio_efectivo < 4 then 'baja (<$4)'
                     when precio_efectivo <= 6 then 'media ($4-6)'
                     else 'alta (>$6)' end as banda,
                min(precio_efectivo) as precio_min,
                count(*) as creadoras,
                round(avg(precio_efectivo), 2) as precio_prom,
                round(avg(ingreso_total), 0) as ingreso_total_prom
         from base where precio_efectivo is not null
         group by 1
      ) x)
    )
  end;
$_$;


ALTER FUNCTION "public"."get_sub_pricing"("p_tenant" "uuid", "p_query" "text", "p_days" integer, "p_manager" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tg_contact_ig"("p_conversation_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with ct as (
    select closer_creator_id,
           right(regexp_replace(coalesce(peer_phone, ''), '\D', '', 'g'), 10) as d10
    from public.tg_conversations
    where id = p_conversation_id
      and tenant_id = public.current_tenant_id()
      and (
        public.has_tg_inbox_global_scope(auth.uid())
        or assigned_to = auth.uid()
        or public.is_tg_assignee(id, auth.uid())
      )
  )
  select ig from (
    -- 1) FK directo al lead del pipeline (sin ambigüedad; no depende del teléfono)
    select 1 as pri, cc.instagram_handle as ig
      from ct join public.closer_creators cc on cc.id = ct.closer_creator_id
     where coalesce(cc.instagram_handle, '') <> ''
    union all
    -- 2) lead del pipeline por teléfono (últimos 10 dígitos)
    select 2, cc.instagram_handle
      from ct join public.closer_creators cc
        on length(ct.d10) = 10
       and right(regexp_replace(coalesce(cc.phone, ''), '\D', '', 'g'), 10) = ct.d10
     where coalesce(cc.instagram_handle, '') <> ''
    union all
    -- 3) creadora firmada por teléfono
    select 3, cr.instagram_handle
      from ct join public.creadoras_de_mi_agencia() cr
        on length(ct.d10) = 10
       and right(regexp_replace(coalesce(cr.phone_e164, cr.whatsapp_number, cr.phone, ''), '\D', '', 'g'), 10) = ct.d10
     where coalesce(cr.instagram_handle, '') <> ''
  ) t
  order by pri
  limit 1;
$$;


ALTER FUNCTION "public"."get_tg_contact_ig"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unread_counts"("_user_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "unread_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT cp.conversation_id, u.n AS unread_count
  FROM chat_participants cp
  CROSS JOIN LATERAL (
    SELECT count(*) AS n
    FROM (SELECT 1
            FROM chat_messages cm
           WHERE cm.conversation_id = cp.conversation_id
             AND cm.created_at > coalesce(cp.last_read_at, '-infinity'::timestamptz)
             AND cm.sender_id <> _user_id
             AND NOT cm.is_deleted
           LIMIT 101) x
  ) u
  WHERE cp.user_id = _user_id AND _user_id = (SELECT auth.uid());
$$;


ALTER FUNCTION "public"."get_unread_counts"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_wa_contact_ig"("p_contact_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with ct as (
    select closer_creator_id,
           right(regexp_replace(coalesce(phone_e164, ''), '\D', '', 'g'), 10) as d10
    from public.wa_contacts
    where id = p_contact_id
      -- SECURITY DEFINER bypassa RLS → gateamos a mano igual que wa_contacts_select
      -- (tenant + scope global / conversación asignada o co-asignada) para no
      -- filtrar el @IG de contactos que el caller no puede ver, ni cruzar tenants.
      and tenant_id = public.current_tenant_id()
      and (
        public.has_wa_inbox_global_scope(auth.uid())
        or exists (
          select 1 from public.wa_conversations c
          where c.contact_id = wa_contacts.id
            and (c.assigned_to = auth.uid() or public.is_wa_assignee(c.id, auth.uid()))
        )
      )
  )
  select ig from (
    -- 1) FK directo al lead del pipeline (sin ambigüedad)
    select 1 as pri, cc.instagram_handle as ig
      from ct join public.closer_creators cc on cc.id = ct.closer_creator_id
     where coalesce(cc.instagram_handle, '') <> ''
    union all
    -- 2) lead del pipeline por teléfono (últimos 10 dígitos)
    select 2, cc.instagram_handle
      from ct join public.closer_creators cc
        on length(ct.d10) = 10
       and right(regexp_replace(coalesce(cc.phone, ''), '\D', '', 'g'), 10) = ct.d10
     where coalesce(cc.instagram_handle, '') <> ''
    union all
    -- 3) creadora firmada por teléfono
    select 3, cr.instagram_handle
      from ct join public.creadoras_de_mi_agencia() cr
        on length(ct.d10) = 10
       and right(regexp_replace(coalesce(cr.phone_e164, cr.whatsapp_number, cr.phone, ''), '\D', '', 'g'), 10) = ct.d10
     where coalesce(cr.instagram_handle, '') <> ''
  ) t
  order by pri
  limit 1;
$$;


ALTER FUNCTION "public"."get_wa_contact_ig"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_wa_inbox_sla"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  result jsonb;
  v_from timestamptz := coalesce(p_from, (now() - interval '30 days')::date)::timestamptz;
  v_to   timestamptz := (coalesce(p_to, now()::date) + 1)::timestamptz;  -- fin de día exclusivo
begin
  if not public.blu_is_management(auth.uid()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  with msgs as (
    select m.conversation_id, m.direction, m.sender_user_id, m.sent_at
    from public.wa_conversation_messages m
    where m.sent_at >= v_from and m.sent_at < v_to and m.deleted_at is null
  ),
  vol as (
    select
      count(*) filter (where direction='in') as entrantes,
      count(*) filter (where direction='out' and sender_user_id is not null) as sal_humano,
      count(*) filter (where direction='out' and sender_user_id is null) as sal_bot
    from msgs
  ),
  conv_first_in as (
    select conversation_id, min(sent_at) as first_in
    from msgs where direction='in' group by conversation_id
  ),
  conv_resp as (
    select ci.conversation_id, ci.first_in, c.assigned_to, c.channel_id,
      (select min(o.sent_at) from public.wa_conversation_messages o
        where o.conversation_id = ci.conversation_id
          and o.direction='out' and o.sender_user_id is not null
          and o.sent_at > ci.first_in) as first_out
    from conv_first_in ci
    join public.wa_conversations c on c.id = ci.conversation_id
  ),
  fin as (
    select assigned_to, channel_id,
      case when first_out is not null then round(extract(epoch from (first_out-first_in))/60.0)::int end as resp_min,
      (first_out is not null) as responded
    from conv_resp
  )
  select jsonb_build_object(
    'overall', jsonb_build_object(
      'convos', (select count(*) from fin),
      'entrantes', (select entrantes from vol),
      'sal_humano', (select sal_humano from vol),
      'sal_bot', (select sal_bot from vol),
      'respondidas', (select count(*) from fin where responded),
      'sin_responder', (select count(*) from fin where not responded),
      'pct_respondidas', (select case when count(*)>0 then round(100.0*count(*) filter (where responded)/count(*),1) else 0 end from fin),
      'resp_prom_min', (select round(avg(resp_min))::int from fin),
      'resp_median_min', (select round(percentile_cont(0.5) within group (order by resp_min))::int from fin)
    ),
    'by_agent', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'user_id', assigned_to,
        'respondidas', respondidas, 'sin_responder', sin_responder,
        'resp_prom_min', resp_prom_min, 'resp_median_min', resp_median_min
      ) order by (respondidas + sin_responder) desc), '[]'::jsonb)
      from (
        select assigned_to,
          count(*) filter (where responded) as respondidas,
          count(*) filter (where not responded) as sin_responder,
          round(avg(resp_min))::int as resp_prom_min,
          round(percentile_cont(0.5) within group (order by resp_min))::int as resp_median_min
        from fin group by assigned_to
      ) a
    ),
    'by_channel', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'channel_id', channel_id,
        'respondidas', respondidas, 'sin_responder', sin_responder,
        'resp_prom_min', resp_prom_min
      ) order by (respondidas + sin_responder) desc), '[]'::jsonb)
      from (
        select channel_id,
          count(*) filter (where responded) as respondidas,
          count(*) filter (where not responded) as sin_responder,
          round(avg(resp_min))::int as resp_prom_min
        from fin group by channel_id
      ) ch
    )
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION "public"."get_wa_inbox_sla"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grabacion_misma_agencia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_de_la_grabacion uuid;
begin
  select r.tenant_id into v_de_la_grabacion from public.meeting_recordings r where r.id = new.recording_id;
  if v_de_la_grabacion is null then
    return new;   -- no existe: decide la FK
  end if;
  if not exists (select 1 from public.tenant_members tm where tm.user_id = new.user_id and tm.tenant_id = v_de_la_grabacion) then
    raise exception 'grabacion_misma_agencia: % no es de la agencia de la grabación %', new.user_id, new.recording_id
      using errcode = '42501', hint = 'Una grabación se comparte solo con gente de su agencia.';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."grabacion_misma_agencia"() OWNER TO "postgres";


