CREATE OR REPLACE FUNCTION "public"."guard_chat_conversation_meta"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (NEW.name        IS DISTINCT FROM OLD.name
      OR NEW.description IS DISTINCT FROM OLD.description
      OR NEW.avatar_url  IS DISTINCT FROM OLD.avatar_url)
     AND auth.uid() IS NOT NULL
     AND NOT is_chat_admin(auth.uid(), OLD.id)
     AND OLD.created_by <> auth.uid()
  THEN
    RAISE EXCEPTION 'Solo un admin del grupo puede editar sus datos';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_chat_conversation_meta"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_chat_conversation_perms"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (NEW.msg_permission     IS DISTINCT FROM OLD.msg_permission
      OR NEW.members_visibility IS DISTINCT FROM OLD.members_visibility
      OR NEW.info_permission  IS DISTINCT FROM OLD.info_permission
      OR NEW.add_permission   IS DISTINCT FROM OLD.add_permission
      OR NEW.require_approval IS DISTINCT FROM OLD.require_approval)
     AND NOT public.is_chat_admin(auth.uid(), OLD.id) THEN
    RAISE EXCEPTION 'Solo un admin puede cambiar los permisos del grupo';
  END IF;
  IF (NEW.name IS DISTINCT FROM OLD.name
      OR NEW.description IS DISTINCT FROM OLD.description
      OR NEW.avatar_url IS DISTINCT FROM OLD.avatar_url)
     AND OLD.type = 'group'
     AND coalesce(OLD.info_permission, 'admins') = 'admins'
     AND NOT public.is_chat_admin(auth.uid(), OLD.id) THEN
    RAISE EXCEPTION 'Solo un admin puede editar la información del grupo';
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."guard_chat_conversation_perms"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_chat_message_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;
  IF NEW.conversation_id IS DISTINCT FROM OLD.conversation_id OR NEW.sender_id IS DISTINCT FROM OLD.sender_id
  THEN RAISE EXCEPTION 'No autorizado: no se puede mover un mensaje ni cambiar su autor'; END IF;

  IF NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.type IS DISTINCT FROM OLD.type
     OR NEW.album_id IS DISTINCT FROM OLD.album_id
     OR NEW.is_thread_reply IS DISTINCT FROM OLD.is_thread_reply
  THEN RAISE EXCEPTION 'chat_mensaje_inmutable: la fecha, el tipo, el álbum y el hilo de un mensaje no cambian'; END IF;

  IF (NEW.reply_to_id IS DISTINCT FROM OLD.reply_to_id AND NEW.reply_to_id IS NOT NULL)
     OR (NEW.file_url IS DISTINCT FROM OLD.file_url AND NEW.file_url IS NOT NULL)
     OR (NEW.file_name IS DISTINCT FROM OLD.file_name AND NEW.file_name IS NOT NULL)
     OR (NEW.file_size IS DISTINCT FROM OLD.file_size AND NEW.file_size IS NOT NULL)
  THEN RAISE EXCEPTION 'chat_mensaje_inmutable: la cita y el archivo de un mensaje no se cambian por otros'; END IF;

  -- Reescribir un mensaje sin que se note: la marca de editado no se quita.
  IF OLD.is_edited AND NOT NEW.is_edited THEN
    RAISE EXCEPTION 'chat_mensaje_inmutable: la marca de editado de un mensaje no se quita';
  END IF;

  IF OLD.is_deleted THEN
    IF NOT NEW.is_deleted THEN
      RAISE EXCEPTION 'chat_mensaje_borrado: un mensaje borrado no vuelve';
    END IF;
    IF (NEW.content IS DISTINCT FROM OLD.content AND NEW.content IS NOT NULL)
       OR (NEW.content_rich IS DISTINCT FROM OLD.content_rich AND NEW.content_rich IS NOT NULL) THEN
      RAISE EXCEPTION 'chat_mensaje_borrado: un mensaje borrado no se edita';
    END IF;
  ELSIF NEW.is_deleted THEN
    -- Solo delete_chat_message, que archiva antes y deja el GUC con ESTE id.
    IF current_setting('maven.borrado_autorizado', true) IS DISTINCT FROM OLD.id::text THEN
      RAISE EXCEPTION 'chat_borrado_sin_archivo: un mensaje se borra con delete_chat_message';
    END IF;
    IF NEW.content IS NOT NULL OR NEW.content_rich IS NOT NULL
       OR NEW.file_url IS NOT NULL OR NEW.file_name IS NOT NULL OR NEW.file_size IS NOT NULL THEN
      RAISE EXCEPTION 'chat_borrado_sin_archivo: un mensaje borrado queda vacío';
    END IF;
  ELSIF NEW.content IS DISTINCT FROM OLD.content OR NEW.content_rich IS DISTINCT FROM OLD.content_rich THEN
    -- Todo cambio de texto queda a la vista, lo mande o no quien edita.
    NEW.is_edited := true;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."guard_chat_message_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_chat_participant_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;
  IF (NEW.role IS DISTINCT FROM OLD.role
      OR NEW.user_id IS DISTINCT FROM OLD.user_id
      OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id)
     AND NOT public.is_chat_admin(auth.uid(), OLD.conversation_id)
  THEN RAISE EXCEPTION 'No autorizado: solo un admin del grupo puede cambiar el rol o la membresia'; END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."guard_chat_participant_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- 1. Perfil
  insert into public.profiles (id, full_name)
  values (new.id, new.raw_user_meta_data->>'full_name')
  on conflict (id) do nothing;

  -- 2. Rol: solo las cuentas de la agencia. Una cuenta externa (app_metadata.tipo
  --    'creadora', que pone solo el servidor) no lleva rol de empleado. GoTrue
  --    escribe app_metadata después del INSERT: ese caso lo cubre
  --    cuenta_externa_sin_rol (20261005140100).
  if coalesce(new.raw_app_meta_data->>'tipo', '') <> 'creadora' then
    insert into public.user_roles (user_id, role)
    values (new.id, 'employee')
    on conflict do nothing;
  end if;

  -- 3. La agencia NO se pone aquí: la pone admin-user-actions (la de quien crea
  --    la cuenta). Ver la cabecera de 20261001210000_agencias_base.
  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_chatter_evaluator_access"("_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    exists (select 1 from public.user_roles ur where ur.user_id = _user_id and ur.role = 'admin')
    or (
      (
        exists (
          select 1
          from public.user_roles ur
          join public.roles_config rc on rc.name = ur.role and rc.tenant_id = ur.tenant_id
          join public.role_permissions rp on rp.role_id = rc.id
          where ur.user_id = _user_id
            and rp.module = 'Chatters'
            and (rp.submodule = 'Evaluator' or rp.submodule is null)
            and rp.can_access = true
        )
        or exists (select 1 from public.chatter_examinadores x where x.user_id = _user_id and x.permitido)
      )
      and not exists (select 1 from public.chatter_examinadores x where x.user_id = _user_id and not x.permitido)
    );
$$;


ALTER FUNCTION "public"."has_chatter_evaluator_access"("_user_id" "uuid") OWNER TO "postgres";


