CREATE OR REPLACE FUNCTION "public"."has_role"("_user_id" "uuid", "_role" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.user_roles
    where user_id = _user_id and role = _role
  )
  or case _role
    when 'admin'      then public.is_in_role_group(_user_id, 'admin')
    when 'manager'    then public.is_in_role_group(_user_id, 'manager_or_above')
    when 'supervisor' then public.is_in_role_group(_user_id, 'supervisor_or_above')
    else exists (
      select 1
      from public.user_roles ur
      join public.role_base_grants g on g.role_name = ur.role and g.tenant_id = ur.tenant_id
      where ur.user_id = _user_id and g.base_role = _role
    )
  end
$$;


ALTER FUNCTION "public"."has_role"("_user_id" "uuid", "_role" "text") OWNER TO "postgres";


