CREATE OR REPLACE FUNCTION "public"."horario_de"("_uid" "uuid") RETURNS TABLE("entrada" time without time zone, "salida" time without time zone, "exento" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select case when sem.tiene then sem.entrada else coalesce(p.hora_entrada, t.hora_entrada, rc.hora_entrada) end,
         case when sem.tiene then sem.salida else coalesce(p.hora_salida, t.hora_salida, rc.hora_salida) end,
         coalesce(p.exonera_camara_pantalla, false) or coalesce(rc.exonera_camara_pantalla, false)
    from public.profiles p
    left join public.rol_turnos t on t.id = p.turno_id
    left join lateral (
      select c.hora_entrada, c.hora_salida, c.exonera_camara_pantalla
        from public.user_roles ur
        join public.roles_config c on lower(c.name) = lower(ur.role) and c.is_active
                                  and (c.tenant_id = ur.tenant_id or ur.tenant_id is null)
       where ur.user_id = p.id
       order by (c.hora_entrada is null), c.level desc nulls last
       limit 1
    ) rc on true
    left join lateral (
      select exists (select 1 from public.horario_semanal w where w.user_id = p.id) as tiene,
             hs.entrada, hs.salida
        from (select 1) as uno
        left join public.horario_semanal hs
               on hs.user_id = p.id
              and hs.dia = extract(dow from (now() at time zone 'America/Bogota'))::smallint
    ) sem on true
   where p.id = _uid;
$$;


ALTER FUNCTION "public"."horario_de"("_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hubstaff_activity_summary"("p_from" "date", "p_to" "date", "p_person" "text" DEFAULT NULL::"text") RETURNS TABLE("hubstaff_user_id" "text", "name" "text", "hubstaff_role" "text", "profile_id" "uuid", "mapped_to_maven" boolean, "total_hours" numeric, "avg_activity_pct" numeric, "days_worked" integer, "last_day" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    d.hubstaff_user_id,
    coalesce(m.name, p.full_name, 'Hubstaff '||d.hubstaff_user_id) as name,
    m.hubstaff_role,
    m.profile_id,
    (m.profile_id is not null) as mapped_to_maven,
    round(sum(d.tracked_seconds)::numeric/3600, 2) as total_hours,
    round(sum(d.overall_activity::numeric*d.tracked_seconds)/nullif(sum(d.tracked_seconds),0), 0) as avg_activity_pct,
    count(distinct d.date)::int as days_worked,
    max(d.date) as last_day
  from hubstaff_daily_data d
  left join hubstaff_members m on m.hubstaff_user_id = d.hubstaff_user_id
  left join profiles p on p.id = m.profile_id
  where d.date >= p_from and d.date <= p_to
    and (p_person is null
      or coalesce(m.name,'') ilike '%'||p_person||'%'
      or coalesce(p.full_name,'') ilike '%'||p_person||'%')
  group by d.hubstaff_user_id, m.name, p.full_name, m.hubstaff_role, m.profile_id
  order by total_hours desc
$$;


ALTER FUNCTION "public"."hubstaff_activity_summary"("p_from" "date", "p_to" "date", "p_person" "text") OWNER TO "postgres";


