CREATE OR REPLACE FUNCTION "public"."hubstaff_entry_exit"("p_from" "date", "p_to" "date", "p_person" "text" DEFAULT NULL::"text") RETURNS TABLE("name" "text", "dia" "date", "entrada" "text", "ultimo_ping" "text", "horas" numeric, "actividad_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT m.name,
         (a.starts_at AT TIME ZONE 'America/Bogota')::date AS dia,
         to_char(min(a.starts_at) AT TIME ZONE 'America/Bogota', 'HH24:MI') AS entrada,
         to_char(max(a.starts_at) AT TIME ZONE 'America/Bogota', 'HH24:MI') AS ultimo_ping,
         round(sum(a.tracked_seconds)::numeric / 3600, 2) AS horas,
         round(sum(a.overall_activity::numeric * a.tracked_seconds)
               / nullif(sum(a.tracked_seconds), 0), 0) AS actividad_pct
  FROM hubstaff_activities a
  JOIN hubstaff_members m ON m.id = a.member_id
  WHERE (a.starts_at AT TIME ZONE 'America/Bogota')::date BETWEEN p_from AND p_to
    AND (p_person IS NULL OR m.name ILIKE '%' || p_person || '%')
  GROUP BY m.name, (a.starts_at AT TIME ZONE 'America/Bogota')::date
  ORDER BY dia DESC, m.name;
$$;


ALTER FUNCTION "public"."hubstaff_entry_exit"("p_from" "date", "p_to" "date", "p_person" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hubstaff_live_today"("p_person" "text" DEFAULT NULL::"text") RETURNS TABLE("hubstaff_user_id" "text", "name" "text", "hubstaff_role" "text", "full_name_maven" "text", "mapped_to_maven" boolean, "seconds_today" bigint, "hours_today" numeric, "first_ping" timestamp with time zone, "last_ping" timestamp with time zone, "activity_pct" numeric, "feed_last_ping" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with feed as (
    select max(starts_at) as feed_last from hubstaff_activities
  ),
  today as (
    select a.member_id,
           sum(a.tracked_seconds) as secs,
           min(a.starts_at) as first_ping,
           max(a.starts_at) as last_ping,
           round(sum(a.overall_activity::numeric * a.tracked_seconds) / nullif(sum(a.tracked_seconds), 0), 0) as act
    from hubstaff_activities a
    where a.starts_at >= ((now() at time zone 'America/Bogota')::date::timestamp at time zone 'America/Bogota')
    group by a.member_id
  )
  select m.hubstaff_user_id,
         coalesce(m.name, p.full_name, 'Hubstaff ' || m.hubstaff_user_id) as name,
         m.hubstaff_role,
         p.full_name as full_name_maven,
         (m.profile_id is not null) as mapped_to_maven,
         coalesce(t.secs, 0)::bigint as seconds_today,
         round(coalesce(t.secs, 0)::numeric / 3600, 2) as hours_today,
         t.first_ping,
         t.last_ping,
         t.act as activity_pct,
         (select feed_last from feed) as feed_last_ping
  from hubstaff_members m
  left join profiles p on p.id = m.profile_id
  left join today t on t.member_id = m.id
  where coalesce(m.is_active, true)
    and (p_person is null
      or coalesce(m.name, '') ilike '%' || p_person || '%'
      or coalesce(p.full_name, '') ilike '%' || p_person || '%')
  order by coalesce(t.secs, 0) desc, 2;
$$;


ALTER FUNCTION "public"."hubstaff_live_today"("p_person" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hubstaff_projects_by_member"("p_from" "date", "p_to" "date") RETURNS TABLE("hubstaff_user_id" "text", "project_name" "text", "tracked_seconds" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select hm.hubstaff_user_id,
         a.project_name,
         sum(a.tracked_seconds)::bigint
  from hubstaff_activities a
  join hubstaff_members hm on hm.id = a.member_id
  where a.project_name is not null
    -- Rango en hora de Bogotá (UTC-5): el turno de madrugada cruza medianoche UTC
    -- y con el corte en UTC se caía del día que le corresponde.
    and a.starts_at >= (p_from::timestamp + interval '5 hours')
    and a.starts_at <  ((p_to + 1)::timestamp + interval '5 hours')
  group by 1, 2;
$$;


ALTER FUNCTION "public"."hubstaff_projects_by_member"("p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hubstaff_projects_by_member"("p_from" "date", "p_to" "date") IS 'Proyectos de Hubstaff por persona en un rango (hora Bogotá). Agrega en la base para no chocar con el límite de 1000 filas de PostgREST, que truncaba en silencio y hacía aparecer gente "sin proyecto".';



CREATE OR REPLACE FUNCTION "public"."ia_saldo_anotar"("_saldo" numeric, "_recarga" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'solo el dueño' using errcode = '42501';
  end if;
  if _saldo is null or _saldo <= -1000 or _saldo >= 100000 then
    raise exception 'saldo fuera de rango' using errcode = '22023';
  end if;
  insert into public.costos_saldo (servicio_id, saldo_usd, origen, nota, anotado_por)
  values ('google_ia', round(_saldo, 2), case when _recarga then 'recarga' else 'lectura' end,
          case when _recarga then 'Recarga anotada en Costos' else 'Saldo leído en AI Studio' end,
          (select auth.uid()));
  return public.ia_saldo_calculo();
end
$$;


ALTER FUNCTION "public"."ia_saldo_anotar"("_saldo" numeric, "_recarga" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ia_saldo_calculo"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  p record;
  v_precio numeric;
  v_juzgadas integer := 0;
  v_gastado numeric := 0;
  v_saldo numeric;
  v_promedio numeric;
  v_ultimas24 integer;
  v_ultimas3 integer;
  v_ritmo numeric;
  v_dias numeric;
  v_ultimo_ok timestamptz;
  v_sin_saldo_at timestamptz;
  v_sin_saldo_id bigint;
  v_activo boolean;
  v_pocos numeric;
  v_hoy numeric;
  v_estado text;
begin
  select s.id, s.saldo_usd, s.medido_at, s.origen into p
    from public.costos_saldo s
   where s.servicio_id = 'google_ia'
   order by s.medido_at desc, s.id desc
   limit 1;
  select coalesce(c.precio_unitario_usd, 0.0022) into v_precio from public.costos_servicios c where c.id = 'google_ia';
  v_precio := coalesce(v_precio, 0.0022);

  if p.id is not null then
    select count(*) into v_juzgadas
      from public.monitor_capturas c
     where c.created_at >= p.medido_at and c.veredicto is not null;
    v_gastado := round(v_juzgadas * v_precio, 2);
    v_saldo := p.saldo_usd - v_gastado;
  end if;

  select avg(x.n) into v_promedio from (
    select count(*) as n
      from public.monitor_capturas c
     where c.veredicto is not null
       and c.created_at >= (date_trunc('day', now() at time zone 'America/Bogota') - interval '10 days') at time zone 'America/Bogota'
       and c.created_at < date_trunc('day', now() at time zone 'America/Bogota') at time zone 'America/Bogota'
     group by (c.created_at at time zone 'America/Bogota')::date
    having count(*) >= 200
     order by (c.created_at at time zone 'America/Bogota')::date desc
     limit 3
  ) x;
  select count(*) filter (where c.created_at >= now() - interval '24 hours'),
         count(*) filter (where c.created_at >= now() - interval '3 hours')
    into v_ultimas24, v_ultimas3
    from public.monitor_capturas c
   where c.veredicto is not null and c.created_at >= now() - interval '24 hours';
  v_ritmo := round(greatest(coalesce(v_promedio, 0), v_ultimas24, v_ultimas3 * 16.0 / 3) * v_precio, 2);

  select max(d.at) into v_ultimo_ok
    from public.argos_diag d
   where d.paso = 'ok' and d.at > now() - interval '3 days' and d.detalle ->> 'proveedor' = 'gemini';
  select d.at, d.id into v_sin_saldo_at, v_sin_saldo_id
    from public.argos_diag d
   where d.paso in ('fin', 'vision_error') and d.at > now() - interval '3 days'
     and ((d.detalle -> 'fallas' ->> 'gemini') like '402%'
          or (d.detalle -> 'fallas' ->> 'gemini') ilike '%prepayment credits%')
   order by d.at desc
   limit 1;

  select coalesce((select m.activo from public.monitor_config m where m.id = 1), true) into v_activo;

  v_pocos := greatest(2 * v_ritmo, 8);
  v_hoy := greatest(v_ritmo, 4);
  v_dias := case when v_saldo is not null and v_ritmo > 0 then round(greatest(v_saldo, 0) / v_ritmo, 1) end;

  v_estado := case
    when v_sin_saldo_at is not null and v_sin_saldo_at > coalesce(v_ultimo_ok, '-infinity'::timestamptz) then 'sin_saldo'
    when p.id is null then 'sin_dato'
    when v_saldo <= -greatest(v_ritmo / 2, 3) then 'anotar'
    when v_saldo <= v_hoy then 'se_acaba_hoy'
    when v_saldo <= v_pocos then 'pocos_dias'
    else 'bien'
  end;

  return jsonb_build_object(
    'estado', v_estado,
    'saldo_usd', case when v_saldo is null then null else round(v_saldo, 2) end,
    'punto', case when p.id is null then null else jsonb_build_object(
      'id', p.id, 'saldo_usd', p.saldo_usd, 'medido_at', p.medido_at, 'origen', p.origen) end,
    'juzgadas_desde', v_juzgadas,
    'gastado_usd', v_gastado,
    'precio_foto_usd', v_precio,
    'ritmo_dia_usd', v_ritmo,
    'dias_restantes', v_dias,
    'se_acaba_at', case when v_dias is null then null else now() + make_interval(secs => (v_dias * 86400)::double precision) end,
    'umbral_pocos_usd', v_pocos,
    'umbral_hoy_usd', v_hoy,
    'ultimo_ok', v_ultimo_ok,
    'sin_saldo_at', v_sin_saldo_at,
    'sin_saldo_id', v_sin_saldo_id,
    'argos_activo', v_activo,
    'calculado_at', now()
  );
end
$$;


ALTER FUNCTION "public"."ia_saldo_calculo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ia_saldo_estado"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'solo el dueño' using errcode = '42501';
  end if;
  return public.ia_saldo_calculo();
end
$$;


