CREATE OR REPLACE FUNCTION "public"."import_blu_chatter_daily"("p_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_count integer;
begin
  insert into public.chatter_daily_sales (blu_employee_id, date, name, total_sales, sold_messages, fans_chatted, updated_at)
  select (r->>'blu_employee_id')::int,
         (r->>'date')::date,
         r->>'name',
         coalesce((r->>'total_sales')::numeric, 0),
         coalesce((r->>'sold_messages')::int, 0),
         coalesce((r->>'fans_chatted')::int, 0),
         now()
  from jsonb_array_elements(p_rows) r
  where r ? 'blu_employee_id' and r ? 'date'
  on conflict (blu_employee_id, date) do update set
    total_sales = excluded.total_sales,
    sold_messages = excluded.sold_messages,
    fans_chatted = excluded.fans_chatted,
    name = coalesce(excluded.name, public.chatter_daily_sales.name),
    updated_at = now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."import_blu_chatter_daily"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_blu_chatters"("p_rows" "jsonb", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r jsonb; v_total int := 0;
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role)' using errcode = '42501';
  end if;

  delete from public.chatter_performance where blu_employee_id is not null;  -- snapshot completo (WHERE = todas)

  for r in select value from jsonb_array_elements(p_rows) loop
    if r->>'blu_employee_id' is null then continue; end if;
    insert into public.chatter_performance
      (blu_employee_id, name, email, group_name, is_chatter, total_sales, sold_messages, direct_messages,
       fans_chatted, fans_spent_money, fans_who_didnt_spend, fan_conversion_rate, avg_earnings_per_paying_fan,
       unlock_rate, avg_response_seconds, scheduled_hours, clocked_hours, characters_sent, creators_count,
       delta_total_sales, metrics, deltas, snapshot_from, snapshot_to)
    values
      ((r->>'blu_employee_id')::int, r->>'name', r->>'email', r->>'group_name',
       case when r->>'is_chatter' is null then null else (r->>'is_chatter')::boolean end,
       coalesce((r->>'total_sales')::numeric,0), coalesce((r->>'sold_messages')::numeric,0),
       coalesce((r->>'direct_messages')::numeric,0), coalesce((r->>'fans_chatted')::int,0),
       coalesce((r->>'fans_spent_money')::int,0), coalesce((r->>'fans_who_didnt_spend')::int,0),
       nullif(r->>'fan_conversion_rate','')::numeric, nullif(r->>'avg_earnings_per_paying_fan','')::numeric,
       nullif(r->>'unlock_rate','')::numeric, nullif(r->>'avg_response_seconds','')::numeric,
       nullif(r->>'scheduled_hours','')::numeric, nullif(r->>'clocked_hours','')::numeric,
       nullif(r->>'characters_sent','')::bigint, nullif(r->>'creators_count','')::int,
       nullif(r->>'delta_total_sales','')::numeric, r->'metrics', r->'deltas',
       p_from, p_to);
    v_total := v_total + 1;
  end loop;

  return jsonb_build_object('rows', v_total);
end;
$$;


ALTER FUNCTION "public"."import_blu_chatters"("p_rows" "jsonb", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_blu_earnings"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r jsonb;
  v_cid uuid;
  v_status text;
  v_found boolean;
  v_total int := 0; v_matched int := 0; v_ignored int := 0;
  v_unmatched text[] := '{}';
  v_relink jsonb;
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role) puede importar ingresos' using errcode = '42501';
  end if;

  for r in select value from jsonb_array_elements(p_rows) loop
    if coalesce(r->>'blu_name', '') = '' or coalesce(r->>'date', '') = '' then continue; end if;

    select bm.creator_id, bm.status into v_cid, v_status
      from public.blu_creator_map bm
     where lower(trim(bm.blu_name)) = lower(trim(r->>'blu_name'));
    v_found := found;
    if not v_found then
      v_cid := public.blu_match_creator(r->>'blu_name');
      v_status := null;
    end if;

    insert into public.creator_daily_earnings
      (creator_id, blu_creator_name, date, subscription_gross, tips_gross, message_gross,
       post_gross, referral_gross, stream_gross, total_gross,
       new_sub_gross, recurring_sub_gross, chargebacks_gross, contribution_pct,
       source, imported_by)
    values
      (v_cid, trim(r->>'blu_name'), (r->>'date')::date,
       coalesce((r->>'subscription')::numeric, 0), coalesce((r->>'tips')::numeric, 0),
       coalesce((r->>'message')::numeric, 0), coalesce((r->>'post')::numeric, 0),
       coalesce((r->>'referral')::numeric, 0), coalesce((r->>'stream')::numeric, 0),
       coalesce((r->>'total')::numeric, 0),
       coalesce((r->>'new_sub')::numeric, 0), coalesce((r->>'recurring_sub')::numeric, 0),
       coalesce((r->>'chargebacks')::numeric, 0), coalesce((r->>'contribution_pct')::numeric, 0),
       'blu_export', auth.uid())
    on conflict (lower(trim(blu_creator_name)), date) do update set
      creator_id = coalesce(excluded.creator_id, creator_daily_earnings.creator_id),
      subscription_gross = excluded.subscription_gross, tips_gross = excluded.tips_gross,
      message_gross = excluded.message_gross, post_gross = excluded.post_gross,
      referral_gross = excluded.referral_gross, stream_gross = excluded.stream_gross,
      total_gross = excluded.total_gross,
      new_sub_gross = excluded.new_sub_gross,
      recurring_sub_gross = excluded.recurring_sub_gross,
      chargebacks_gross = excluded.chargebacks_gross,
      contribution_pct = excluded.contribution_pct,
      imported_by = excluded.imported_by, imported_at = now();

    v_total := v_total + 1;
    if v_cid is not null then v_matched := v_matched + 1;
    elsif v_status = 'ignored' then v_ignored := v_ignored + 1;
    elsif not ((r->>'blu_name') = any(v_unmatched)) then
      v_unmatched := array_append(v_unmatched, r->>'blu_name');
    end if;
  end loop;

  v_relink := public.blu_relink_orphans();

  return jsonb_build_object(
    'rows', v_total, 'matched_rows', v_matched, 'ignored_rows', v_ignored,
    'unmatched_names', to_jsonb(v_unmatched),
    'relinked', v_relink);
end;
$$;


ALTER FUNCTION "public"."import_blu_earnings"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_blu_fan_retention"("p_rows" "jsonb", "p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r jsonb; v_cid uuid; v_models int[]; v_total int := 0;
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role)' using errcode = '42501';
  end if;

  select array_agg(distinct (value->>'blu_model_id')::int)
    into v_models from jsonb_array_elements(p_rows) where value->>'blu_model_id' is not null;
  if v_models is not null then
    delete from public.creator_fan_retention where blu_model_id = any(v_models);
  end if;

  for r in select value from jsonb_array_elements(p_rows) loop
    if r->>'blu_model_id' is null or r->>'cohort_date' is null then continue; end if;
    select bm.creator_id into v_cid from public.blu_creator_map bm where bm.blu_name = (r->>'blu_name');
    if not found then v_cid := public.blu_match_creator(r->>'blu_name'); end if;

    insert into public.creator_fan_retention
      (blu_model_id, blu_name, creator_id, cohort_date, new_fans, observed_days, after_days, snapshot_from, snapshot_to)
    values
      ((r->>'blu_model_id')::int, r->>'blu_name', v_cid, (r->>'cohort_date')::date,
       coalesce((r->>'new_fans')::int, 0), coalesce((r->>'observed_days')::int, 0),
       r->'after_days', p_from, p_to)
    on conflict (blu_model_id, cohort_date) do update set
      new_fans=excluded.new_fans, observed_days=excluded.observed_days, after_days=excluded.after_days,
      creator_id=coalesce(excluded.creator_id, public.creator_fan_retention.creator_id),
      blu_name=excluded.blu_name, snapshot_from=excluded.snapshot_from, snapshot_to=excluded.snapshot_to, imported_at=now();
    v_total := v_total + 1;
  end loop;

  return jsonb_build_object('rows', v_total, 'models', coalesce(array_length(v_models, 1), 0));
end;
$$;


ALTER FUNCTION "public"."import_blu_fan_retention"("p_rows" "jsonb", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_blu_fans"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r jsonb; v_cid uuid; v_total int := 0; v_matched int := 0;
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role) puede importar fans' using errcode = '42501';
  end if;

  for r in select value from jsonb_array_elements(p_rows) loop
    if coalesce(r->>'blu_name', '') = '' or coalesce(r->>'date', '') = '' then continue; end if;

    select bm.creator_id into v_cid
      from public.blu_creator_map bm
     where lower(trim(bm.blu_name)) = lower(trim(r->>'blu_name'));
    if not found then v_cid := public.blu_match_creator(r->>'blu_name'); end if;

    insert into public.creator_daily_earnings
      (creator_id, blu_creator_name, date, active_fans, new_fans, source, imported_by)
    values
      (v_cid, trim(r->>'blu_name'), (r->>'date')::date,
       nullif(r->>'active_fans','')::int, nullif(r->>'new_fans','')::int,
       'blu_export', auth.uid())
    on conflict (lower(trim(blu_creator_name)), date) do update set
      active_fans = coalesce(excluded.active_fans, creator_daily_earnings.active_fans),
      new_fans    = coalesce(excluded.new_fans,    creator_daily_earnings.new_fans),
      creator_id  = coalesce(excluded.creator_id,  creator_daily_earnings.creator_id),
      imported_at = now();

    v_total := v_total + 1;
    if v_cid is not null then v_matched := v_matched + 1; end if;
  end loop;

  return jsonb_build_object('rows', v_total, 'matched_rows', v_matched);
end;
$$;


