CREATE OR REPLACE FUNCTION "public"."import_blu_top_fans"("p_rows" "jsonb", "p_from" "date", "p_to" "date", "p_period_kind" "text" DEFAULT 'window'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r jsonb; v_cid uuid; v_models int[]; v_total int := 0;
  v_kind text := coalesce(nullif(p_period_kind,''), 'window');
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role)' using errcode = '42501';
  end if;
  if v_kind not in ('month','alltime','window') then
    raise exception 'period_kind inválido: %', v_kind;
  end if;

  select array_agg(distinct (value->>'blu_model_id')::int)
    into v_models from jsonb_array_elements(p_rows) where value->>'blu_model_id' is not null;
  -- ⚠️ el delete va scopeado al PERÍODO: importar el mensual ya no borra el histórico.
  if v_models is not null then
    delete from public.creator_top_fans
     where blu_model_id = any(v_models) and period_kind = v_kind;
  end if;

  for r in select value from jsonb_array_elements(p_rows) loop
    if r->>'blu_model_id' is null or r->>'fan_user_id' is null then continue; end if;
    select bm.creator_id into v_cid from public.blu_creator_map bm where bm.blu_name = (r->>'blu_name');
    if not found then v_cid := public.blu_match_creator(r->>'blu_name'); end if;

    insert into public.creator_top_fans
      (blu_model_id, blu_name, creator_id, fan_user_id, rank, fan_name, fan_username,
       spent_gross, transactions, messages_gross, tips_gross, subscriptions_gross, ppv_gross,
       subscribed_at, expires_at, is_active, subscription_length_days, snapshot_from, snapshot_to, period_kind)
    values
      ((r->>'blu_model_id')::int, r->>'blu_name', v_cid, (r->>'fan_user_id')::bigint, nullif(r->>'rank','')::int,
       r->>'fan_name', r->>'fan_username',
       coalesce((r->>'spent_gross')::numeric, 0), coalesce((r->>'transactions')::int, 0),
       coalesce((r->>'messages_gross')::numeric, 0), coalesce((r->>'tips_gross')::numeric, 0),
       coalesce((r->>'subscriptions_gross')::numeric, 0), coalesce((r->>'ppv_gross')::numeric, 0),
       nullif(r->>'subscribed_at','')::timestamptz, nullif(r->>'expires_at','')::timestamptz,
       case when r->>'is_active' is null then null else (r->>'is_active')::boolean end,
       nullif(r->>'subscription_length_days','')::int, p_from, p_to, v_kind)
    on conflict (blu_model_id, fan_user_id, period_kind) do update set
      rank=excluded.rank, fan_name=excluded.fan_name, fan_username=excluded.fan_username,
      spent_gross=excluded.spent_gross, transactions=excluded.transactions,
      messages_gross=excluded.messages_gross, tips_gross=excluded.tips_gross,
      subscriptions_gross=excluded.subscriptions_gross, ppv_gross=excluded.ppv_gross,
      subscribed_at=excluded.subscribed_at, expires_at=excluded.expires_at,
      is_active=excluded.is_active, subscription_length_days=excluded.subscription_length_days,
      creator_id=coalesce(excluded.creator_id, public.creator_top_fans.creator_id),
      snapshot_from=excluded.snapshot_from, snapshot_to=excluded.snapshot_to, imported_at=now();
    v_total := v_total + 1;
  end loop;

  return jsonb_build_object('rows', v_total, 'models', coalesce(array_length(v_models, 1), 0), 'period_kind', v_kind);
end;
$$;


