CREATE OR REPLACE FUNCTION "public"."is_in_role_group"("_user_id" "uuid", "_group" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.role_groups rg ON rg.role_name = ur.role and rg.tenant_id = ur.tenant_id
    WHERE ur.user_id = _user_id
      AND CASE _group
        WHEN 'admin'               THEN rg.is_admin
        WHEN 'manager_or_above'    THEN rg.is_manager_or_above
        WHEN 'supervisor_or_above' THEN rg.is_supervisor_or_above
        WHEN 'member'              THEN rg.is_member
        ELSE false
      END
  );
$$;


ALTER FUNCTION "public"."is_in_role_group"("_user_id" "uuid", "_group" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_in_role_group"("_user_id" "uuid", "_group" "text") IS 'Para RLS: chequea si user_id tiene un rol asignado en user_roles que esté marcado en role_groups con la capacidad solicitada. Reemplaza has_role(..., enum) para soportar roles custom.';



CREATE OR REPLACE FUNCTION "public"."is_livekit_room_owner"("_user_id" "uuid", "_room" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN _user_id IS NULL OR _room IS NULL THEN false
    -- Dueño solo de una sala de su agencia (20261003120000).
    WHEN NOT EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.user_id = _user_id AND tm.tenant_id = public.agencia_de_sala_livekit(_room)
    ) THEN false
    WHEN _room LIKE 'meet\_%' THEN EXISTS (
      SELECT 1 FROM public.meet_rooms mr
      WHERE mr.livekit_room_name = _room AND mr.created_by = _user_id
    )
    WHEN _room LIKE 'call-%' THEN EXISTS (
      SELECT 1 FROM public.calls c
      WHERE c.room_id = _room AND c.caller_id = _user_id
    )
    ELSE false
  END;
$$;


ALTER FUNCTION "public"."is_livekit_room_owner"("_user_id" "uuid", "_room" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_livekit_room_owner"("_user_id" "uuid", "_room" "text") IS 'Dueno original de la sala. Se usa para que un co-anfitrion no pueda expulsarlo.';



