CREATE OR REPLACE FUNCTION "public"."last_sync_for"("p_table" "text") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    AS $$
  SELECT COALESCE(
    (SELECT synced_through
       FROM public.sync_log
      WHERE table_name = p_table
        AND status = 'ok'
      ORDER BY ran_at DESC
      LIMIT 1),
    'epoch'::timestamptz
  );
$$;


ALTER FUNCTION "public"."last_sync_for"("p_table" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."latir_llamada_maven"("_sala" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  insert into public.llamada_maven_latido (user_id, sala, last_seen_at)
