CREATE OR REPLACE FUNCTION "public"."leadgen_agent_stats"("p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH filtered AS (
    SELECT lg_user_id, quality, created_at, record_type
    FROM public.leadgen_entries
    WHERE (p_date_from IS NULL OR p_date_to IS NULL
           OR entry_date BETWEEN p_date_from AND p_date_to)
      AND lg_user_id IS NOT NULL
  ),
  agent_quality_counts AS (
    SELECT lg_user_id,
           COALESCE(LOWER(quality), 'c') AS ql,
           COUNT(*) AS ct
    FROM filtered
    GROUP BY lg_user_id, COALESCE(LOWER(quality), 'c')
  ),
  per_agent_quality AS (
    SELECT lg_user_id,
           jsonb_object_agg(ql, ct) AS by_quality
    FROM agent_quality_counts
    GROUP BY lg_user_id
  ),
  totals AS (
    SELECT lg_user_id,
           COUNT(*) AS total,
           MIN(created_at) AS first_lead,
           COUNT(*) FILTER (WHERE record_type = 'reactivado') AS recuperacion,
           COUNT(*) FILTER (WHERE record_type <> 'reactivado' OR record_type IS NULL) AS nuevos
    FROM filtered
    GROUP BY lg_user_id
  ),
  phones AS (
    SELECT cc.created_by AS lg_user_id,
           COUNT(*) AS phones_count
    FROM public.closers_contacts cc
    WHERE cc.phone IS NOT NULL
      AND cc.phone <> ''
      AND (
        p_date_from IS NULL OR p_date_to IS NULL
        OR (cc.created_at >= p_date_from::timestamptz
            AND cc.created_at < (p_date_to + 1)::timestamptz)
      )
      AND cc.created_by IS NOT NULL
    GROUP BY cc.created_by
  ),
  all_agents AS (
    SELECT lg_user_id FROM totals
    UNION
    SELECT lg_user_id FROM phones
  )
  SELECT COALESCE(
    jsonb_object_agg(
      a.lg_user_id::text,
      jsonb_build_object(
        'total',        COALESCE(t.total, 0),
        'byQuality',    COALESCE(paq.by_quality, '{}'::jsonb),
        'firstLead',    t.first_lead,
        'phones',       COALESCE(ph.phones_count, 0),
        'nuevos',       COALESCE(t.nuevos, 0),
        'recuperacion', COALESCE(t.recuperacion, 0)
      )
    ),
    '{}'::jsonb
  )
  FROM all_agents a
  LEFT JOIN totals t ON t.lg_user_id = a.lg_user_id
  LEFT JOIN per_agent_quality paq ON paq.lg_user_id = a.lg_user_id
  LEFT JOIN phones ph ON ph.lg_user_id = a.lg_user_id;
$$;


ALTER FUNCTION "public"."leadgen_agent_stats"("p_date_from" "date", "p_date_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leadgen_search_fuzzy"("p_query" "text", "p_limit" integer DEFAULT 20, "p_min_similarity" real DEFAULT 0.2) RETURNS TABLE("id" "uuid", "model_handle" "text", "ticket_number" "text", "phone_raw" "text", "phone_e164" "text", "country_code" "text", "city" "text", "company" "text", "platform" "text", "onlyfans_url" "text", "notes" "text", "lg_user_id" "uuid", "status" "text", "created_at" timestamp with time zone, "similarity_score" real)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  q text := lower(trim(p_query));
  v_uid uuid := auth.uid();
  v_global boolean := public.has_leadgen_global_scope(auth.uid());
BEGIN
  IF q IS NULL OR length(q) < 2 THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH scored AS (
    SELECT
      le.id, le.model_handle, le.ticket_number, le.phone_raw, le.phone_e164,
      le.country_code, le.city, le.company, le.platform, le.onlyfans_url,
      le.notes, le.lg_user_id, le.status, le.created_at,
      GREATEST(
        COALESCE(similarity(lower(le.model_handle), q), 0),
        COALESCE(similarity(lower(le.ticket_number), q), 0),
        COALESCE(similarity(lower(le.notes), q), 0),
        COALESCE(similarity(lower(le.phone_e164), q), 0)
      )::real AS similarity_score
    FROM public.leadgen_entries le
    WHERE
      (
        lower(le.model_handle) % q
        OR lower(le.ticket_number) % q
        OR lower(le.notes) % q
        OR lower(le.phone_e164) % q
      )
      -- Replica EXACTA de la policy restrictiva leadgen_entries_scope_select,
      -- evaluada una sola vez (v_global) en vez de por fila.
      AND (v_global OR le.lg_user_id = v_uid)
  ),
  deduped AS (
    SELECT DISTINCT ON (lower(s.model_handle)) s.*
    FROM scored s
    ORDER BY lower(s.model_handle), s.similarity_score DESC, s.created_at DESC
  )
  SELECT
    d.id, d.model_handle, d.ticket_number, d.phone_raw, d.phone_e164,
    d.country_code, d.city, d.company, d.platform, d.onlyfans_url,
    d.notes, d.lg_user_id, d.status, d.created_at, d.similarity_score
  FROM deduped d
  ORDER BY d.similarity_score DESC, d.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."leadgen_search_fuzzy"("p_query" "text", "p_limit" integer, "p_min_similarity" real) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leadgen_summary_stats"("p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH filtered AS (
    SELECT quality, phone_raw, phone_e164 FROM public.leadgen_entries
    WHERE (p_date_from IS NULL OR p_date_to IS NULL OR entry_date BETWEEN p_date_from AND p_date_to) AND (p_user_id IS NULL OR lg_user_id = p_user_id)
  ), buckets AS (
    SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE phone_raw IS NOT NULL OR phone_e164 IS NOT NULL) AS qa,
      COUNT(*) FILTER (WHERE LOWER(quality) = 'a+') AS q_aplus,
      COUNT(*) FILTER (WHERE LOWER(quality) = 'a') AS q_a,
      COUNT(*) FILTER (WHERE LOWER(quality) = 'b+') AS q_bplus,
      COUNT(*) FILTER (WHERE LOWER(quality) = 'b') AS q_b,
      COUNT(*) FILTER (WHERE quality IS NULL OR LOWER(quality) NOT IN ('a+','a','b+','b')) AS q_c
    FROM filtered
  )
  SELECT jsonb_build_object('total', total, 'qa', qa, 'byQuality', jsonb_build_object('a+', q_aplus, 'a', q_a, 'b+', q_bplus, 'b', q_b, 'c', q_c)) FROM buckets;
$$;


ALTER FUNCTION "public"."leadgen_summary_stats"("p_date_from" "date", "p_date_to" "date", "p_user_id" "uuid") OWNER TO "postgres";


