CREATE OR REPLACE FUNCTION "public"."limpieza_storage_filas"("_regla" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  a integer := 0;
  b integer := 0;
begin
  if _regla = 'monitor_faltas_7d' then
    update public.monitor_eventos e
       set captura_path = null
     where e.captura_path is not null
       and e.created_at < now() - interval '7 days'
       and not exists (select 1 from storage.objects o
                        where o.bucket_id = 'monitor-capturas' and o.name = e.captura_path);
    get diagnostics a = row_count;
    delete from public.monitor_rondas where last_at < now() - interval '2 days';
    get diagnostics b = row_count;
    return jsonb_build_object('faltas_sin_foto', a, 'rondas_podadas', b);

  elsif _regla = 'monitor_capturas_30d' then
    delete from public.monitor_capturas c
     where c.created_at < now() - interval '30 days'
       and c.nas_path is null
       and not exists (select 1 from storage.objects o
                        where o.bucket_id = 'monitor-capturas' and o.name = c.path);
    get diagnostics a = row_count;
    return jsonb_build_object('capturas_borradas', a);

  elsif _regla = 'argos_clips_30d' then
    delete from public.argos_clips k
     where k.started_at < now() - interval '30 days'
       and k.nas_path is null
       and not exists (select 1 from storage.objects o
                        where o.bucket_id = 'argos-clips' and o.name = k.path);
    get diagnostics a = row_count;
    return jsonb_build_object('clips_borrados', a);

  else
    raise exception 'limpieza_storage_filas: regla desconocida %', _regla using errcode = '22023';
  end if;
end
$$;


ALTER FUNCTION "public"."limpieza_storage_filas"("_regla" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."limpieza_storage_vencidos"("_regla" "text", "_limite" integer DEFAULT 1000) RETURNS TABLE("nombre" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limite integer := least(greatest(coalesce(_limite, 1000), 1), 1000);
begin
  if _regla = 'monitor_faltas_7d' then
    return query
      select o.name::text
        from storage.objects o
       where o.bucket_id = 'monitor-capturas'
         and o.created_at < now() - interval '7 days'
         and not exists (select 1 from public.monitor_capturas c where c.path = o.name and not c.en_nas)
       order by o.created_at
       limit v_limite;
  elsif _regla = 'monitor_capturas_30d' then
    return query
      select o.name::text
        from storage.objects o
       where o.bucket_id = 'monitor-capturas'
         and o.created_at < now() - interval '30 days'
       order by o.created_at
       limit v_limite;
  elsif _regla = 'argos_clips_30d' then
    return query
      select o.name::text
        from storage.objects o
       where o.bucket_id = 'argos-clips'
         and o.created_at < now() - interval '30 days'
       order by o.created_at
       limit v_limite;
  else
    raise exception 'limpieza_storage_vencidos: regla desconocida %', _regla using errcode = '22023';
  end if;
end
$$;


ALTER FUNCTION "public"."limpieza_storage_vencidos"("_regla" "text", "_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_subida_de_carpeta"("_item_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_tenant uuid;
  v_token text;
  v_creadora uuid;
begin
  if v_uid is null then raise exception 'sin sesión' using errcode = '42501'; end if;
  if not public.puede_dar_links_subida(v_uid) then
    raise exception 'sin permiso para crear links de subida' using errcode = '42501';
  end if;
  if public.drive_mi_rol(_item_id) is null and not public.es_dueno(v_uid) then
    raise exception 'sin acceso a esa carpeta' using errcode = '42501';
  end if;
  select tenant_id into v_tenant from public.drive_items
   where id = _item_id and tipo = 'carpeta' and trashed_at is null;
  if v_tenant is null then raise exception 'la carpeta no existe'; end if;

  select m.creator_id into v_creadora from public.drive_carpeta_creadora m where m.item_id = _item_id limit 1;
  if v_creadora is not null then return public.drive_link_personal(v_creadora); end if;

  select l.token into v_token
    from public.drive_upload_links l
   where l.item_id = _item_id and l.activo and l.tipo in ('subir', 'personal')
   order by (l.tipo = 'personal') desc,
            (select count(*) from public.drive_aportes a where a.token = l.token) desc,
            l.created_at desc
   limit 1;
  if v_token is not null then return v_token; end if;

  insert into public.drive_upload_links (item_id, tenant_id, created_by, nombre)
  values (_item_id, v_tenant, v_uid, null)
  returning token into v_token;
  return v_token;
end;
$$;


ALTER FUNCTION "public"."link_subida_de_carpeta"("_item_id" "uuid") OWNER TO "postgres";


