    AS $$
  select p.id, p.full_name
  from profiles p
  join user_roles ur on ur.user_id = p.id
  where ur.role in ('Chatter', 'agent')
    and p.full_name is not null and trim(p.full_name) <> ''
  group by p.id, p.full_name
