CREATE OR REPLACE FUNCTION "public"."log_contact_category_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  hours_diff double precision;
BEGIN
  IF upper(btrim(COALESCE(OLD.physical_appearance, ''))) IS DISTINCT FROM upper(btrim(COALESCE(NEW.physical_appearance, ''))) THEN
    hours_diff := EXTRACT(EPOCH FROM (now() - COALESCE(OLD.created_at, now()))) / 3600.0;
    INSERT INTO public.contact_category_changes (
      contact_id, contact_name, contact_handle,
      old_category, new_category, changed_by,
      contact_created_at, hours_since_creation
    ) VALUES (
      NEW.id, NEW.name, NEW.handle,
      OLD.physical_appearance, NEW.physical_appearance,
      auth.uid(),
      OLD.created_at, hours_diff
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_contact_category_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_creator_manager_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.assigned_manager_profile_id is not distinct from old.assigned_manager_profile_id then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.assigned_manager_profile_id is not null then
    update creator_manager_history set unassigned_at = now()
    where creator_id = new.id
      and manager_profile_id = old.assigned_manager_profile_id
      and unassigned_at is null;
  end if;
  if new.assigned_manager_profile_id is not null
     and not exists (
       select 1 from creator_manager_history
       where creator_id = new.id
         and manager_profile_id = new.assigned_manager_profile_id
         and unassigned_at is null
     ) then
    insert into creator_manager_history (creator_id, manager_profile_id)
    values (new.id, new.assigned_manager_profile_id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."log_creator_manager_change"() OWNER TO "postgres";


