BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO event_attendance_log (event_guest_id, event_id, old_status, new_status, changed_by)
    VALUES (NEW.id, NEW.event_id, OLD.status, NEW.status, NEW.status_changed_by);
    NEW.status_updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_guest_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_role_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    insert into public.audit_log (user_id, action, target_type, target_id, details)
    values (NEW.user_id, 'role_assigned', 'user', NEW.user_id::text,
            jsonb_build_object('role', NEW.role));
    return NEW;
  elsif TG_OP = 'DELETE' then
    insert into public.audit_log (user_id, action, target_type, target_id, details)
    values (OLD.user_id, 'role_removed', 'user', OLD.user_id::text,
            jsonb_build_object('role', OLD.role));
    return OLD;
  elsif TG_OP = 'UPDATE' then
    -- Que la base ponga la agencia (user_roles_agencia) no es un cambio de rol.
    if NEW.role is not distinct from OLD.role then
      return NEW;
    end if;
    insert into public.audit_log (user_id, action, target_type, target_id, details)
    values (NEW.user_id, 'role_changed', 'user', NEW.user_id::text,
            jsonb_build_object('old_role', OLD.role, 'new_role', NEW.role));
    return NEW;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."log_role_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mail_labels_valida_padre"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  actual uuid := NEW.parent_id;
  pasos int := 0;
BEGIN
  IF NEW.parent_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.mail_labels WHERE id = NEW.parent_id AND user_id = NEW.user_id
  ) THEN
    RAISE EXCEPTION 'La etiqueta madre no existe en este buzón' USING ERRCODE = '23503';
  END IF;
  WHILE actual IS NOT NULL LOOP
    IF actual = NEW.id THEN
      RAISE EXCEPTION 'Una etiqueta no puede quedar dentro de sí misma' USING ERRCODE = '23514';
    END IF;
    pasos := pasos + 1;
    IF pasos > 50 THEN
      RAISE EXCEPTION 'Demasiados niveles de subetiquetas' USING ERRCODE = '23514';
    END IF;
    SELECT parent_id INTO actual FROM public.mail_labels WHERE id = actual;
  END LOOP;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."mail_labels_valida_padre"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mail_programado_cancelar"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r public.mail_programados;
begin
  update public.mail_programados
     set estado = 'cancelado', cerrado_en = now()
   where id = p_id and user_id = (select auth.uid()) and estado in ('pendiente', 'fallido')
  returning * into r;
  if r.id is null then return null; end if;
  return jsonb_build_object(
    'id', r.id, 'para', r.para, 'cc', r.cc, 'cco', r.cco, 'asunto', r.asunto,
    'enviar_en', r.enviar_en, 'correo', r.correo
  );
end $$;


ALTER FUNCTION "public"."mail_programado_cancelar"("p_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."mail_programados" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "enviar_en" timestamp with time zone NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "para" "text"[] NOT NULL,
    "cc" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "cco" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "asunto" "text" DEFAULT ''::"text" NOT NULL,
    "resumen" "text" DEFAULT ''::"text" NOT NULL,
    "adjuntos_meta" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "correo" "jsonb" NOT NULL,
    "intentos" smallint DEFAULT 0 NOT NULL,
    "ultimo_error" "text",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tomado_en" timestamp with time zone,
    "cerrado_en" timestamp with time zone,
    CONSTRAINT "mail_programados_estado" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'enviando'::"text", 'enviado'::"text", 'fallido'::"text", 'cancelado'::"text"]))),
    CONSTRAINT "mail_programados_para" CHECK (("cardinality"("para") > 0))
);


ALTER TABLE "public"."mail_programados" OWNER TO "postgres";


COMMENT ON TABLE "public"."mail_programados" IS 'Correos programados («Programar envío» del Correo). Los crea y los manda la edge mail-fetch; la persona ve la lista y cancela. Ver 20261008160000.';



CREATE OR REPLACE FUNCTION "public"."mail_programados_tomar"("p_limite" integer DEFAULT 20) RETURNS SETOF "public"."mail_programados"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- ⚠️ Uno que quedó «enviando» más de 15 minutos es una función que se murió a
  -- mitad de camino: PUEDE haber salido. No se reintenta solo (un correo
  -- duplicado a un cliente es peor que uno que no salió); se marca fallido para
  -- que la persona mire Enviados y decida.
  update public.mail_programados
     set estado = 'fallido',
         ultimo_error = 'se cortó mientras salía: revisa Enviados antes de volver a mandarlo',
         cerrado_en = now()
   where estado = 'enviando' and tomado_en < now() - interval '15 minutes';

  -- Lo que ya cumplió no se guarda para siempre. Un cancelado todavía tiene el
  -- correo entero (se le devolvió a la persona para editarlo; si esa respuesta
  -- se perdió, el contenido sigue acá): dos días y se va.
  delete from public.mail_programados
   where (estado = 'enviado' and cerrado_en < now() - interval '30 days')
      or (estado = 'cancelado' and cerrado_en < now() - interval '2 days');

  return query
  update public.mail_programados m
     set estado = 'enviando', tomado_en = now(), intentos = m.intentos + 1
   where m.id in (
     select p.id from public.mail_programados p
      where p.estado = 'pendiente' and p.enviar_en <= now()
      order by p.enviar_en
      limit greatest(1, least(coalesce(p_limite, 20), 50))
      for update skip locked
   )
  returning m.*;
end $$;


ALTER FUNCTION "public"."mail_programados_tomar"("p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mail_recipient_directory"() RETURNS TABLE("email" "text", "nombre" "text", "tipo" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with permitido as (
    select 1 from public.mail_credentials
    where user_id = auth.uid() and revoked_at is null
    limit 1
  )
  -- Compañeros (excluye al que llama: uno no se escribe a sí mismo desde el "Para")
  select lower(u.email)::text,
         coalesce(nullif(btrim(p.full_name), ''), split_part(u.email, '@', 1))::text,
         'persona'::text
  from auth.users u
  join public.profiles p on p.id = u.id
  where exists (select 1 from permitido)
    and u.deleted_at is null
    and u.email is not null
    and (lower(u.email) like '%@maven-ai.me' or lower(u.email) like '%@unlok.me')
    and u.id <> auth.uid()
    and u.id in (select public.gente_de_mi_agencia())
  union all
  -- Listas de distribución por rol, solo las que existen de verdad en Zoho
  select lower(g.group_email)::text, g.group_name::text, 'grupo'::text
  from public.email_role_groups g
  where exists (select 1 from permitido)
    and g.enabled
    and g.zgid is not null
$$;


ALTER FUNCTION "public"."mail_recipient_directory"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manager_promo_rolling14"("p_tenant" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select coalesce(nullif(c.artistic_name,''), c.name) as creadora,
           split_part(p.full_name,' ',1) as manager,
           count(distinct e.dia) filter (where coalesce(e.promoted,'') <> 'pending') as dias_leidos_14d,
           count(distinct e.dia) filter (where e.promoted = 'true') as dias_con_promo_14d,
           round(coalesce((select sum(d.total_gross) from creator_daily_earnings d
                   where d.creator_id = c.id and d.date > current_date - 14),0)::numeric, 0) as ingreso_14d,
           round(coalesce((select sum(d.total_gross) from creator_daily_earnings d
                   where d.creator_id = c.id and d.date > current_date - 28 and d.date <= current_date - 14),0)::numeric, 0) as ingreso_prev_14d
    from creators c
    join profiles p on p.id = c.assigned_manager_profile_id
    left join promolog_entries e on e.creator_id = c.id and e.tenant_id = p_tenant
      and e.dia > current_date - 14
    where c.status = 'active'
    group by c.id, creadora, manager
  )
  select jsonb_build_object(
    'ventana', 'últimos 14 días (móvil — cruza el cambio de mes)',
    'creadoras', coalesce((select jsonb_agg(to_jsonb(b) order by
        (case when b.ingreso_prev_14d > 0 then (b.ingreso_14d - b.ingreso_prev_14d) / b.ingreso_prev_14d else 0 end) asc)
      from base b where b.dias_leidos_14d >= 5), '[]'::jsonb),
    'sin_lectura_suficiente', (select count(*) from base where dias_leidos_14d < 5),
    'nota', 'dias_con_promo/dias_leidos = tasa de promo REAL sobre días LEÍDOS (regla #956). Ingreso 14d vs los 14 previos. Solo aparecen creadoras con ≥5 días leídos en la ventana.'
  );
$$;


ALTER FUNCTION "public"."manager_promo_rolling14"("p_tenant" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mask_email"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p is null then null
    when position('@' in p) = 0 then repeat(chr(8226), 4)
    else left(p, 1) || repeat(chr(8226), 3) || substring(p from position('@' in p))
  end
$$;


ALTER FUNCTION "public"."mask_email"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mask_phone"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$ select case when p is null then null when length(regexp_replace(p, '[^0-9]', '', 'g')) <= 4 then repeat(chr(8226), 4) else repeat(chr(8226), length(regexp_replace(p, '[^0-9]', '', 'g')) - 4) || right(regexp_replace(p, '[^0-9]', '', 'g'), 4) end $$;


ALTER FUNCTION "public"."mask_phone"("p" "text") OWNER TO "postgres";


