     and nullif(btrim(p_full_name), '') is not null
     and p_content ~* ('(^|[^[:alnum:]_])@' || regexp_replace(btrim(p_full_name), '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '($|[^[:alnum:]_])');
$_$;


