CREATE OR REPLACE FUNCTION "public"."messenger_directorio"("_q" "text" DEFAULT NULL::"text", "_limite" integer DEFAULT 50, "_desde" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name" "text", "avatar_url" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _k jsonb := public.api_llave_del_pedido(true);
  _agencia uuid := (_k ->> 'tenant_id')::uuid;
  _lim integer := least(greatest(coalesce(_limite, 50), 1), 100);
  _patron text;
begin
  if nullif(btrim(coalesce(_q, '')), '') is not null then
    _patron := '%' || replace(replace(replace(public.api_sin_acentos(btrim(_q)), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;
  return query
  select p.id, p.full_name, p.avatar_url
    from public.profiles p
    join public.tenant_members tm on tm.user_id = p.id and tm.tenant_id = _agencia
   where p.id <> auth.uid()
     and public.api_persona_alcanzable(p.id, _agencia)
     and (_patron is null or public.api_sin_acentos(p.full_name) like _patron)
   order by p.full_name nulls last, p.id
   limit _lim + 1 offset greatest(coalesce(_desde, 0), 0);
end;
$$;


ALTER FUNCTION "public"."messenger_directorio"("_q" "text", "_limite" integer, "_desde" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."messenger_metricas_del_dia"() RETURNS TABLE("conversaciones_activas" integer, "mensajes_hoy" integer, "respuesta_promedio_s" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with inicio as (
    select ((now() at time zone 'America/New_York')::date)::timestamp at time zone 'America/New_York' as hoy
  ),
  de_hoy as (
    select m.conversation_id, m.sender_id, m.created_at,
           lag(m.sender_id)  over w as sender_previo,
           lag(m.created_at) over w as fecha_previa
      from chat_messages m
      join chat_conversations c on c.id = m.conversation_id
     where has_role((select auth.uid()), 'admin')
       and c.tenant_id = current_tenant_id()
       and m.created_at >= (select hoy from inicio)
       and not m.is_deleted
       and m.type <> 'system'
       and m.api_key_id is null
    window w as (partition by m.conversation_id order by m.created_at, m.id)
  )
  select count(distinct conversation_id)::int,
         count(*)::int,
         avg(extract(epoch from created_at - fecha_previa))
           filter (where sender_previo is not null
                     and sender_previo <> sender_id
                     and created_at - fecha_previa <= interval '4 hours')
    from de_hoy;
$$;


ALTER FUNCTION "public"."messenger_metricas_del_dia"() OWNER TO "postgres";


