CREATE OR REPLACE FUNCTION "public"."metric_category_breakdown"("p_metric" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("category" "text", "count" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_metric = 'totalGenerated' THEN
    RETURN QUERY
    SELECT u.cat::text, sum(u.c)::bigint
    FROM (
      SELECT COALESCE(le.category_code, 'Sin categoría') AS cat, count(*) AS c
      FROM leadgen_entries le
      WHERE le.created_at >= p_start AND le.created_at < p_end
      GROUP BY 1
      UNION ALL
      SELECT COALESCE(sl.category, 'Sin categoría'), count(*)
      FROM scouter_leads sl
      WHERE sl.created_at >= p_start AND sl.created_at < p_end
      GROUP BY 1
    ) u
    GROUP BY u.cat;
  ELSIF p_metric = 'totalLeads' THEN
    RETURN QUERY
    SELECT u.cat::text, sum(u.c)::bigint
    FROM (
      SELECT COALESCE(le.category_code, 'Sin categoría') AS cat, count(*) AS c
      FROM leadgen_entries le
      WHERE le.created_at >= p_start AND le.created_at < p_end
      GROUP BY 1
      UNION ALL
      SELECT COALESCE(sl.category, 'Sin categoría'), count(*)
      FROM scouter_leads sl
      WHERE sl.first_scouter_contact_at >= p_start
        AND sl.first_scouter_contact_at < p_end
      GROUP BY 1
    ) u
    GROUP BY u.cat;
  ELSIF p_metric = 'contacted' THEN
    RETURN QUERY
    SELECT COALESCE(le.category_code, 'Sin categoría')::text, count(*)::bigint
    FROM leadgen_entries le
    WHERE le.created_at >= p_start AND le.created_at < p_end
    GROUP BY 1;
  ELSE
    RETURN;
  END IF;
END;
$$;


ALTER FUNCTION "public"."metric_category_breakdown"("p_metric" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


