CREATE OR REPLACE FUNCTION "public"."mi_equipo_supervisado"() RETURNS TABLE("user_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with yo as (
    select p.id, public.equipo_de(p.id) as equipo
    from public.profiles p
    where p.id = (select auth.uid())
      and p.nivel = 'supervisor'
      and p.deleted_at is null
  )
  select t.id
  from public.profiles t, yo
  where yo.equipo <> 'Otros'
    and t.id <> yo.id
    and t.deleted_at is null
    and t.nivel = 'agente'
    and public.equipo_de(t.id) = yo.equipo
    and exists (
      select 1
      from public.user_roles a
      join public.user_roles b on b.tenant_id = a.tenant_id
      where a.user_id = yo.id and b.user_id = t.id
    )
  union
  -- Jefes con equipos a cargo (Luis → Chatters, PR, Editores): todos los de esos
  -- equipos que no son admin ni dueño, de su misma agencia.
  select t.id
  from public.profiles t
  where t.deleted_at is null
    and t.id <> (select auth.uid())
    and not public.es_admin_o_dueno(t.id)
    and public.equipo_de(t.id) in (select e.equipo from public.equipos_a_cargo e where e.user_id = (select auth.uid()))
    and exists (
      select 1
      from public.user_roles a
      join public.user_roles b on b.tenant_id = a.tenant_id
      where a.user_id = (select auth.uid()) and b.user_id = t.id
    );
$$;


ALTER FUNCTION "public"."mi_equipo_supervisado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mi_fuera_de_cowork"() RETURNS TABLE("desde" timestamp with time zone, "llamados" integer, "nunca_entro" boolean, "reportado" boolean, "entrada" time without time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  (select f.desde, f.llamados, false, f.reportado_at is not null, null::time
     from public.cowork_fuera f
    where f.user_id = (select auth.uid()) and f.hasta is null and f.llamados > 0
    limit 1)
  union all
  (select null::timestamptz, n.llamados, true, n.reportado_at is not null, (select h.entrada from public.horario_de(n.user_id) h)
     from public.argos_no_entro n
    where n.user_id = (select auth.uid())
      and n.ultimo_llamado_at > now() - interval '4 minutes'
      and not public.presente_en_cowork(n.user_id, now())
    limit 1)
  limit 1;
$$;


