CREATE OR REPLACE FUNCTION "public"."nas_buscar"("_texto" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  patron text;
  resultado jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;
  if length(btrim(coalesce(_texto, ''))) < 2 then
    return jsonb_build_object('carpetas', '[]'::jsonb, 'archivos', '[]'::jsonb);
  end if;
  patron := '%' || replace(replace(replace(public.drive_nombre_buscable(btrim(_texto)), '\', '\\'), '%', '\%'), '_', '\_') || '%';

  with recursive encontradas as (
    select id, parent_id, nombre from public.drive_items
     where trashed_at is null and tipo = 'carpeta' and public.drive_nombre_buscable(nombre) like patron
     order by length(nombre), nombre limit 40
  ), baja as (
    select id as raiz, id from encontradas
    union all
    select b.raiz, c.id from baja b join public.drive_items c on c.parent_id = b.id and c.tipo = 'carpeta' and c.trashed_at is null
  ), peso as (
    select b.raiz, coalesce(sum(f.size), 0)::bigint as bytes, count(f.id) as archivos
      from baja b left join public.drive_items f on f.parent_id = b.id and f.tipo = 'archivo' and f.trashed_at is null
     group by b.raiz
  ), archivos as (
    select id, nombre, size, parent_id from public.drive_items
     where trashed_at is null and tipo = 'archivo' and public.drive_nombre_buscable(nombre) like patron
     order by size desc nulls last limit 40
  )
  select jsonb_build_object(
    'carpetas', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'nombre', e.nombre, 'padre', pc.nombre,
                                                               'bytes', p.bytes, 'archivos', p.archivos) order by p.bytes desc, e.nombre), '[]'::jsonb)
                   from encontradas e join peso p on p.raiz = e.id left join public.drive_items pc on pc.id = e.parent_id),
    'archivos', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'nombre', a.nombre, 'size', a.size,
                                                               'carpeta_id', a.parent_id, 'carpeta', pc.nombre) order by a.size desc nulls last), '[]'::jsonb)
                   from archivos a left join public.drive_items pc on pc.id = a.parent_id)
  ) into resultado;

  return resultado;
end;
$$;


ALTER FUNCTION "public"."nas_buscar"("_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_entro_semana"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  desde timestamptz := now() - interval '7 days';
  total jsonb;
  por_dia jsonb;
  por_persona jsonb;
  por_modelo jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  select jsonb_build_object('bytes', coalesce(sum(i.size), 0), 'archivos', count(*))
    into total
    from public.drive_items i
   where i.tipo = 'archivo' and i.trashed_at is null and i.created_at > desde;

  select coalesce(jsonb_agg(jsonb_build_object('dia', d.dia, 'bytes', d.bytes, 'archivos', d.archivos) order by d.dia), '[]'::jsonb)
    into por_dia
    from (
      select (i.created_at at time zone 'America/Bogota')::date as dia, sum(i.size)::bigint as bytes, count(*) as archivos
        from public.drive_items i
       where i.tipo = 'archivo' and i.trashed_at is null and i.created_at > desde
       group by 1
    ) d;

  select coalesce(jsonb_agg(jsonb_build_object('nombre', x.nombre, 'bytes', x.bytes, 'archivos', x.archivos) order by x.bytes desc), '[]'::jsonb)
    into por_persona
    from (
      select p.full_name as nombre, sum(i.size)::bigint as bytes, count(*) as archivos
        from public.drive_items i
        left join public.profiles p on p.id = i.owner_id
       where i.tipo = 'archivo' and i.trashed_at is null and i.created_at > desde
         and not exists (select 1 from public.drive_aportes a where a.drive_item_id = i.id)
       group by p.full_name
       order by sum(i.size) desc nulls last
       limit 10
    ) x;

  select coalesce(jsonb_agg(jsonb_build_object('nombre', x.nombre, 'padre', x.padre, 'carpeta_id', x.carpeta_id, 'bytes', x.bytes, 'archivos', x.archivos, 'pidio', x.pidio) order by x.bytes desc), '[]'::jsonb)
    into por_modelo
    from (
      select d.id as carpeta_id, d.nombre, pd.nombre as padre, sum(a.size)::bigint as bytes, count(*) as archivos, max(p.full_name) as pidio
        from public.drive_aportes a
        join public.drive_upload_links l on l.token = a.token
        join public.drive_items d on d.id = l.item_id
        left join public.drive_items pd on pd.id = d.parent_id
        left join public.profiles p on p.id = l.created_by
       where a.created_at > desde
       group by d.id, d.nombre, pd.nombre
       order by sum(a.size) desc nulls last
       limit 10
    ) x;

  return jsonb_build_object('total', total, 'por_dia', por_dia, 'por_persona', por_persona, 'por_modelo', por_modelo);
end;
$$;


ALTER FUNCTION "public"."nas_entro_semana"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_espacio_resumen"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  ult public.nas_espacio%rowtype;
  viejo public.nas_espacio%rowtype;
  usado bigint;
  util bigint;
  dias numeric;
  ritmo_anual numeric;
  ritmo_disco numeric;
  ritmo numeric;
  fuente text;
  semanas numeric;
  que jsonb;
  alertas jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  select * into ult from public.nas_espacio order by medido_at desc limit 1;
  if not found then
    return jsonb_build_object('sin_muestras', true);
  end if;

  usado := ult.total_bytes - ult.libre_bytes;
  util := greatest(0, floor(ult.total_bytes * 0.95)::bigint - usado);

  select coalesce(sum(i.size), 0) / 52.18 into ritmo_anual
    from public.drive_items i
   where i.tipo = 'archivo' and i.trashed_at is null and i.created_at > now() - interval '365 days';

  select * into viejo from public.nas_espacio
   where medido_at >= ult.medido_at - interval '90 days'
   order by medido_at asc limit 1;
  dias := extract(epoch from (ult.medido_at - viejo.medido_at)) / 86400.0;
  if dias >= 30 then
    ritmo_disco := ((ult.total_bytes - ult.libre_bytes) - (viejo.total_bytes - viejo.libre_bytes)) / dias * 7;
  end if;

  if ritmo_disco is not null and ritmo_disco > ritmo_anual then
    ritmo := ritmo_disco; fuente := 'disco';
  else
    ritmo := ritmo_anual; fuente := 'anual';
  end if;
  semanas := case when ritmo > 0 then util / ritmo end;

  select coalesce(jsonb_agg(jsonb_build_object('unidad', x.unidad, 'bytes', x.bytes, 'archivos', x.archivos) order by x.bytes desc), '[]'::jsonb)
    into que
    from (
      select u.nombre as unidad, sum(i.size)::bigint as bytes, count(*) as archivos
        from public.drive_items i
        left join public.drive_items u on u.id = i.unidad_id
       where i.tipo = 'archivo' and i.trashed_at is null
       group by u.nombre
       order by sum(i.size) desc nulls last
       limit 8
    ) x;

  select coalesce(jsonb_agg(jsonb_build_object('nivel', a.nivel, 'avisado_at', a.avisado_at) order by a.nivel), '[]'::jsonb)
    into alertas from public.nas_espacio_alertas a;

  return jsonb_build_object(
    'medido_at', ult.medido_at,
    'total', ult.total_bytes,
    'libre', ult.libre_bytes,
    'usado', usado,
    'util_restante', util,
    'discos', ult.discos,
    'ritmo_semana', round(ritmo),
    'ritmo_fuente', fuente,
    'ritmo_anual', round(ritmo_anual),
    'ritmo_disco', round(ritmo_disco),
    'dias_medidos', round(dias),
    'semanas_para_llenarse', round(semanas, 1),
    'fecha_llena', case when semanas is not null then (ult.medido_at + make_interval(days => least(semanas * 7, 36500)::int))::date end,
    'que_ocupa', que,
    'alertas', alertas
  );
end;
$$;


ALTER FUNCTION "public"."nas_espacio_resumen"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_explorar"("_carpeta" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resultado jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  with recursive carpetas as materialized (
    select id, parent_id, nombre from public.drive_items
     where tipo = 'carpeta' and trashed_at is null
  ), hijos as (
    select id, nombre from carpetas where parent_id is not distinct from _carpeta
  ), baja as (
    select id as raiz, id from hijos
    union all
    select b.raiz, c.id from baja b join carpetas c on c.parent_id = b.id
  ), directo as (
    select f.parent_id as carpeta, sum(f.size)::bigint as bytes, count(*) as archivos, max(f.created_at) as ultimo
      from public.drive_items f
     where f.tipo = 'archivo' and f.trashed_at is null
       and f.parent_id in (select id from baja)
     group by f.parent_id
  ), peso as (
    select b.raiz, coalesce(sum(d.bytes), 0)::bigint as bytes, coalesce(sum(d.archivos), 0)::bigint as archivos,
           count(*) - 1 as carpetas, max(d.ultimo) as ultimo
      from baja b left join directo d on d.carpeta = b.id
     group by b.raiz
  ), sueltos as (
    select f.id, f.nombre, f.size, f.mime, f.created_at
      from public.drive_items f
     where f.tipo = 'archivo' and f.trashed_at is null and f.parent_id is not distinct from _carpeta
  ), ruta as (
    select id, parent_id, nombre, 0 as nivel from carpetas where id = _carpeta
    union all
    select c.id, c.parent_id, c.nombre, r.nivel + 1 from ruta r join carpetas c on c.id = r.parent_id
  )
  select jsonb_build_object(
    'carpeta', (select jsonb_build_object('id', id, 'nombre', nombre) from carpetas where id = _carpeta),
    'ruta', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'nombre', nombre) order by nivel desc), '[]'::jsonb) from ruta),
    'hijos', (select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'nombre', h.nombre, 'bytes', p.bytes, 'archivos', p.archivos,
                                                            'carpetas', p.carpetas, 'ultimo', p.ultimo) order by p.bytes desc, h.nombre), '[]'::jsonb)
                from hijos h join peso p on p.raiz = h.id),
    'sueltos', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'nombre', s.nombre, 'size', s.size, 'mime', s.mime,
                                                              'creado', s.created_at) order by s.size desc nulls last), '[]'::jsonb)
                  from (select * from sueltos order by size desc nulls last limit 100) s),
    'sueltos_total', (select jsonb_build_object('bytes', coalesce(sum(size), 0), 'archivos', count(*)) from sueltos),
    'total', jsonb_build_object(
      'bytes', (select coalesce(sum(bytes), 0) from peso) + (select coalesce(sum(size), 0) from sueltos),
      'archivos', (select coalesce(sum(archivos), 0) from peso) + (select count(*) from sueltos))
  ) into resultado;

  return resultado;
end;
$$;


ALTER FUNCTION "public"."nas_explorar"("_carpeta" "uuid") OWNER TO "postgres";


