CREATE OR REPLACE FUNCTION "public"."nas_ficha"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'archivos', (select count(*) from public.drive_items where tipo = 'archivo' and trashed_at is null),
    'carpetas', (select count(*) from public.drive_items where tipo = 'carpeta' and trashed_at is null),
    'unidades', (select count(distinct unidad_id) from public.drive_items where unidad_id is not null and trashed_at is null),
    'personas', (select count(distinct owner_id) from public.drive_items where tipo = 'archivo' and trashed_at is null and owner_id is not null),
    'desde', (select min(created_at) from public.drive_items where tipo = 'archivo' and trashed_at is null and created_at > '2010-01-01'),
    'links_modelos', (select count(*) from public.drive_upload_links where activo),
    'aportes_esperando', (select count(*) from public.drive_aportes where not en_nas),
    'nas', (select jsonb_build_object('caido', caido, 'desde', desde, 'actualizado', actualizado) from public.drive_nas_salud where id = 1)
  ) into r;

  return r;
end;
$$;


ALTER FUNCTION "public"."nas_ficha"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_historia"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  meses jsonb;
  muestras jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  with por_mes as (
    select date_trunc('month', i.created_at at time zone 'America/Bogota')::date as mes, sum(i.size)::bigint as bytes
      from public.drive_items i
     where i.tipo = 'archivo' and i.trashed_at is null and i.size > 0
     group by 1
  ), acumulado as (
    select mes, bytes, sum(bytes) over (order by mes)::bigint as total from por_mes
  )
  select coalesce(jsonb_agg(jsonb_build_object('mes', to_char(mes, 'YYYY-MM'), 'bytes', bytes, 'total', total) order by mes), '[]'::jsonb)
    into meses
    from acumulado
   where mes >= (date_trunc('month', now() at time zone 'America/Bogota') - interval '23 months')::date;

  select coalesce(jsonb_agg(jsonb_build_object('dia', dia, 'usado', usado, 'total', total) order by dia), '[]'::jsonb)
    into muestras
    from (
      select (medido_at at time zone 'America/Bogota')::date as dia,
             max(total_bytes - libre_bytes) as usado, max(total_bytes) as total
        from public.nas_espacio
       where medido_at > now() - interval '120 days'
       group by 1
    ) d;

  return jsonb_build_object('meses', meses, 'muestras', muestras);
end;
$$;


ALTER FUNCTION "public"."nas_historia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_mas_pesados"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  with recursive carpetas as materialized (
    select id, parent_id from public.drive_items where tipo = 'carpeta'
  ), en_papelera as (
    select id from public.drive_items where tipo = 'carpeta' and trashed_at is not null
    union
    select c.id from en_papelera p join carpetas c on c.parent_id = p.id
  ), x as (
    select id, nombre, size, parent_id, unidad_id, owner_id, created_at, mime
      from public.drive_items
     where tipo = 'archivo' and trashed_at is null and size is not null
     order by size desc limit 50
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', x.id, 'nombre', x.nombre, 'size', x.size, 'carpeta_id', x.parent_id, 'carpeta', pc.nombre,
           'unidad', u.nombre, 'dueno', p.full_name, 'creado', x.created_at, 'tipo', public.nas_tipo_de_archivo(x.mime, x.nombre),
           'en_papelera', exists (select 1 from en_papelera e where e.id = x.parent_id))
         order by x.size desc), '[]'::jsonb)
    into r
    from x
    left join public.drive_items pc on pc.id = x.parent_id
    left join public.drive_items u on u.id = x.unidad_id
    left join public.profiles p on p.id = x.owner_id;

  return jsonb_build_object('archivos', r);
end;
$$;


ALTER FUNCTION "public"."nas_mas_pesados"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_por_modelo"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resultado jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  with recursive llaves as (
    select distinct public.llave_de_modelo(k) as k
      from (
        select creator_handle as k from public.chatter_group_creators
        union all select blu_name from public.blu_creator_map
        union all select instagram_handle from public.creators
        union all select artistic_name from public.creators
      ) x
     where length(public.llave_de_modelo(k)) >= 4
  ), raiz as (
    select d.id, l.k, d.nombre
      from public.drive_items d
      join llaves l on l.k = public.llave_de_modelo(d.nombre)
     where d.tipo = 'carpeta' and d.trashed_at is null
  ), arbol as (
    select id, k from raiz
    union
    select c.id, a.k from arbol a
      join public.drive_items c on c.parent_id = a.id and c.tipo = 'carpeta' and c.trashed_at is null
  ), suma as (
    select a.k, sum(f.size)::bigint as bytes, count(*) as archivos
      from (select distinct id, k from arbol) a
      join public.drive_items f on f.parent_id = a.id and f.tipo = 'archivo' and f.trashed_at is null
     group by a.k
  ), todo as (
    select s.k,
           (select mode() within group (order by r.nombre) from raiz r where r.k = s.k) as nombre,
           (select count(*) from raiz r where r.k = s.k) as carpetas,
           s.bytes, s.archivos
      from suma s
  )
  select jsonb_build_object(
    'modelos', (select coalesce(jsonb_agg(jsonb_build_object('nombre', m.nombre, 'carpetas', m.carpetas, 'bytes', m.bytes, 'archivos', m.archivos) order by m.bytes desc), '[]'::jsonb)
                  from (select * from todo order by bytes desc limit 25) m),
    'cuantas', (select count(*) from todo),
    'atribuido', (select coalesce(sum(bytes), 0) from todo),
    'usado', (select coalesce(sum(size), 0) from public.drive_items where tipo = 'archivo' and trashed_at is null)
  ) into resultado;

  return resultado;
end;
$$;


ALTER FUNCTION "public"."nas_por_modelo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_por_tipo"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  tipos jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  with g as (
    select mime, case when length(e) between 1 and 8 and position(' ' in e) = 0 then e end as ext,
           sum(size)::bigint as bytes, count(*) as archivos
      from (select mime, size, lower(case when position('.' in nombre) > 0 then reverse(split_part(reverse(nombre), '.', 1)) end) as e
              from public.drive_items
             where tipo = 'archivo' and trashed_at is null) x
     group by 1, 2
  ), t as (
    select public.nas_tipo_por_ext(mime, ext) as tipo, coalesce(ext, '—') as ext, bytes, archivos from g
  ), por_tipo as (
    select tipo, sum(bytes)::bigint as bytes, sum(archivos)::bigint as archivos from t group by tipo
  ), por_ext as (
    select tipo, ext, sum(bytes)::bigint as bytes, sum(archivos)::bigint as archivos,
           row_number() over (partition by tipo order by sum(bytes) desc nulls last) as n
      from t group by tipo, ext
  )
  select coalesce(jsonb_agg(jsonb_build_object('tipo', p.tipo, 'bytes', p.bytes, 'archivos', p.archivos,
           'extensiones', (select coalesce(jsonb_agg(jsonb_build_object('ext', e.ext, 'bytes', e.bytes, 'archivos', e.archivos) order by e.bytes desc nulls last), '[]'::jsonb)
                             from por_ext e where e.tipo = p.tipo and e.n <= 5)) order by p.bytes desc nulls last), '[]'::jsonb)
    into tipos
    from por_tipo p;

  return jsonb_build_object('tipos', tipos);
end;
$$;


ALTER FUNCTION "public"."nas_por_tipo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_que_liberar"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resumen jsonb;
  top jsonb;
  papelera jsonb;
  tiradas jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'Solo admin o dueño' using errcode = '42501';
  end if;

  with grupos as (
    select lower(nombre) as nombre, size, count(*) as copias
      from public.drive_items
     where tipo = 'archivo' and trashed_at is null and size > 1000000
     group by lower(nombre), size
    having count(*) > 1
  ), quince as (
    select * from grupos order by (copias - 1) * size desc limit 15
  ), donde as (
    select q.nombre, q.size, array_agg(distinct coalesce(u.nombre, '')) as unidades
      from quince q
      join public.drive_items i on i.size = q.size and lower(i.nombre) = q.nombre and i.tipo = 'archivo' and i.trashed_at is null
      left join public.drive_items u on u.id = i.unidad_id
     group by q.nombre, q.size
  )
  select jsonb_build_object('grupos', (select count(*) from grupos),
                            'copias_de_mas', (select coalesce(sum(copias - 1), 0) from grupos),
                            'bytes', (select coalesce(sum((copias - 1) * size), 0) from grupos)),
         (select coalesce(jsonb_agg(jsonb_build_object('nombre', q.nombre, 'size', q.size, 'copias', q.copias,
                                                        'recupera', (q.copias - 1) * q.size, 'unidades', coalesce(d.unidades, array[]::text[]))
                                    order by (q.copias - 1) * q.size desc), '[]'::jsonb)
            from quince q left join donde d on d.nombre = q.nombre and d.size = q.size)
    into resumen, top;

  with recursive carpetas as materialized (
    select id, parent_id from public.drive_items where tipo = 'carpeta'
  ), tiradas_ids as (
    select id from public.drive_items where tipo = 'carpeta' and trashed_at is not null
  ), bajo as (
    select t.id as raiz, t.id from tiradas_ids t
    union all
    select b.raiz, c.id from bajo b join carpetas c on c.parent_id = b.id
  ), dentro as (
    select distinct id from bajo
  ), por_carpeta as (
    select f.parent_id as carpeta, sum(f.size)::bigint as bytes, count(*) as archivos
      from public.drive_items f
     where f.tipo = 'archivo' and f.parent_id in (select id from dentro)
     group by f.parent_id
  ), sueltos_tirados as (
    select coalesce(sum(f.size), 0)::bigint as bytes, count(*) as archivos
      from public.drive_items f
     where f.tipo = 'archivo' and f.trashed_at is not null
       and not exists (select 1 from dentro d where d.id = f.parent_id)
  ), total as (
    select (select coalesce(sum(bytes), 0) from por_carpeta) + s.bytes as bytes,
           (select coalesce(sum(archivos), 0) from por_carpeta) + s.archivos as archivos
      from sueltos_tirados s
  ), lista as (
    select b.raiz, coalesce(sum(pc.bytes), 0)::bigint as bytes, coalesce(sum(pc.archivos), 0)::bigint as archivos
      from bajo b left join por_carpeta pc on pc.carpeta = b.id
     group by b.raiz
  )
  select (select jsonb_build_object('bytes', bytes, 'archivos', archivos) from total),
         (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', d.id, 'nombre', d.nombre, 'padre', pd.nombre, 'tirada', d.trashed_at, 'por', p.full_name,
                   'bytes', l.bytes, 'archivos', l.archivos) order by l.bytes desc), '[]'::jsonb)
            from (select * from lista order by bytes desc limit 10) l
            join public.drive_items d on d.id = l.raiz
            left join public.drive_items pd on pd.id = d.parent_id
            left join public.profiles p on p.id = d.trashed_by
           where l.bytes > 0)
    into papelera, tiradas;

  return jsonb_build_object('copias', resumen, 'top', top, 'papelera', papelera, 'carpetas_tiradas', tiradas);
end;
$$;


ALTER FUNCTION "public"."nas_que_liberar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_tipo_de_archivo"("_mime" "text", "_nombre" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select public.nas_tipo_por_ext(_mime, public.nas_extension(_nombre))
$$;


ALTER FUNCTION "public"."nas_tipo_de_archivo"("_mime" "text", "_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nas_tipo_por_ext"("_mime" "text", "_ext" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when _mime like 'video/%' or _ext in ('mp4','mov','m4v','mkv','avi','webm','mts','m2ts','braw','r3d','wmv','flv','3gp') then 'video'
    when _mime like 'image/%' or _ext in ('jpg','jpeg','png','heic','heif','webp','gif','tif','tiff','bmp','cr2','cr3','nef','arw','dng','raf','orf','raw','psd','svg') then 'foto'
    when _mime like 'audio/%' or _ext in ('mp3','wav','m4a','aac','flac','ogg','aif','aiff') then 'audio'
    when _ext in ('zip','rar','7z','tar','gz','tgz','dmg','iso') then 'comprimido'
    when _mime in ('application/pdf', 'text/plain', 'text/csv')
      or _mime like 'application/vnd.openxmlformats%' or _mime like 'application/vnd.ms-%' or _mime like 'application/msword%'
      or _ext in ('pdf','doc','docx','xls','xlsx','ppt','pptx','txt','csv','pages','numbers','key','rtf','odt','ods') then 'documento'
    else 'otro'
  end
$$;


ALTER FUNCTION "public"."nas_tipo_por_ext"("_mime" "text", "_ext" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_ticket_code"("p_form_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prefix text;
  v_num    integer;
BEGIN
  UPDATE public.ticket_forms
     SET next_number = next_number + 1
   WHERE id = p_form_id
  RETURNING code_prefix, next_number - 1 INTO v_prefix, v_num;
  IF v_prefix IS NULL THEN
    RAISE EXCEPTION 'Plantilla de ticket inexistente: %', p_form_id;
  END IF;
  RETURN v_prefix || '-' || lpad(v_num::text, 4, '0');
END;
$$;


ALTER FUNCTION "public"."next_ticket_code"("p_form_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."next_ticket_code"("p_form_id" "uuid") IS 'Entrega el proximo codigo de una plantilla (TK-0001, TK-0002, ...) incrementando el contador de forma atomica.';



