CREATE OR REPLACE FUNCTION "public"."normalize_contact_phone"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
declare e164 text; cc text; nat text;
begin
  -- (0) country_code ISO alpha-2 ("CO") → código de marcación ("+57").
  if new.country_code ~ '^[A-Za-z]{2}$' then
    new.country_code := case upper(new.country_code)
      when 'CO' then '+57'  when 'MX' then '+52'  when 'US' then '+1'   when 'CA' then '+1'
      when 'ES' then '+34'  when 'AR' then '+54'  when 'BR' then '+55'  when 'EC' then '+593'
      when 'VE' then '+58'  when 'CL' then '+56'  when 'PE' then '+51'  when 'PA' then '+507'
      when 'HN' then '+504' when 'SV' then '+503' when 'GT' then '+502' when 'CR' then '+506'
      when 'NI' then '+505' when 'DO' then '+1'   when 'PY' then '+595' when 'UY' then '+598'
      when 'BO' then '+591' when 'IT' then '+39'  when 'GB' then '+44'  when 'FR' then '+33'
      when 'DE' then '+49'  when 'PT' then '+351' when 'TH' then '+66'
      else new.country_code end;
  end if;
  -- (1) caso "phone trae un +E.164 completo": split a country_code + nacional (lógica previa).
  if new.phone is null or new.phone !~ '\+' then return new; end if;
  e164 := regexp_replace(public.normalize_wa_e164(regexp_replace(new.phone,'[^0-9]','','g')), '[^0-9]','','g');
  if e164 is null then return new; end if;
  cc := case
    when e164 ~ '^(593|595|591|598|502|503|504|505|506|507)' then left(e164,3)
    when e164 ~ '^(52|57|58|51|54|56|34)' then left(e164,2)
    when e164 ~ '^1[0-9]{10}$' then '1'
    else null end;
  if cc is not null then
    nat := substr(e164, length(cc)+1);
    if length(nat) between 8 and 11 then
      new.country_code := '+' || cc;
      new.phone := nat;
    end if;
  end if;
  return new;
end $_$;


ALTER FUNCTION "public"."normalize_contact_phone"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_wa_e164"("raw" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare d text;
begin
  if raw is null then return null; end if;
  d := regexp_replace(raw, '[^0-9]', '', 'g');
  if length(d) < 8 then return null; end if;

  -- MX legacy "521"+10 dígitos → "52"+10
  if d ~ '^521[0-9]{10}$' then d := '52' || substring(d from 4); end if;

  -- doble código de país de 2 dígitos pegado (5757..., 5858...) — solo 13d+
  if length(d) >= 13 and substring(d from 1 for 2) = substring(d from 3 for 2)
     and substring(d from 1 for 2) in ('52','57','58','51','56','54','55','34') then
    d := substring(d from 3);
  end if;

  -- "57" mal prepended a un número con su propio código (57|593..., 57|58...) — solo 13d+
  if length(d) >= 13 and substring(d from 1 for 2) = '57'
     and substring(d from 3) ~ '^(593|595|591|58|54|52|51|56)' then
    d := substring(d from 3);
  end if;

  -- Venezuela: troncal "0" después de 58 (58 0 4XX... → 58 4XX...)
  if d ~ '^580' then d := '58' || substring(d from 4); end if;

  return '+' || d;
end; $_$;


ALTER FUNCTION "public"."normalize_wa_e164"("raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notif_canal_activo"("p_user" "uuid", "p_type" "text", "p_canal" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce((
    select coalesce(np.is_enabled, true)
       and case p_canal
             when 'push'   then coalesce(np.channel_push, true)
             when 'in_app' then coalesce(np.channel_in_app, true)
             when 'email'  then coalesce(np.channel_email, false)
             else true
           end
    from notification_preferences np
    where np.user_id = p_user and np.notification_type = p_type
    order by np.updated_at desc nulls last
    limit 1
  ), p_canal <> 'email');  -- sin fila: in_app y push encendidos, correo apagado
$$;


ALTER FUNCTION "public"."notif_canal_activo"("p_user" "uuid", "p_type" "text", "p_canal" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notif_email_html"("p_title" "text", "p_body" "text", "p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with e as (
    select replace(replace(replace(coalesce(p_title, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;') as t,
           replace(replace(replace(coalesce(p_body, ''),  '&', '&amp;'), '<', '&lt;'), '>', '&gt;') as b,
           'https://app.maven-ai.me'
             || case when coalesce(p_url, '') like '/%' and p_url not like '//%' and p_url not like '%"%'
                     then p_url else '/notificaciones' end as u
  )
  select '<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#111">'
      || '<p style="margin:0 0 16px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#888">Maven</p>'
      || '<h2 style="margin:0 0 8px;font-size:18px;line-height:1.3">' || t || '</h2>'
      || case when b <> '' then '<p style="margin:0 0 20px;font-size:15px;line-height:1.5;color:#333">' || b || '</p>' else '' end
      || '<p style="margin:0 0 28px"><a href="' || u || '" style="display:inline-block;background:#111;color:#fff;text-decoration:none;padding:10px 16px;border-radius:8px;font-size:14px">Abrir en Maven</a></p>'
      || '<p style="margin:0;font-size:12px;color:#888">Recibes este correo porque activaste el aviso por correo de este evento en Maven → Ajustes → Notificaciones → Eventos. Ahí mismo lo puedes apagar.</p>'
      || '</div>'
  from e;
$$;


ALTER FUNCTION "public"."notif_email_html"("p_title" "text", "p_body" "text", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notificar_supervisores_monitor"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_avisar boolean;
  v_nombre text;
  v_titulo text;
  v_detalle text;
  sup record;
begin
  if new.tipo not in ('camara_apagada', 'se_fue', 'celular', 'distraido', 'no_mira') then
    return new;
  end if;

  select avisar_supervisor into v_avisar from public.monitor_config where id = 1;
  if coalesce(v_avisar, false) = false then
    return new;
  end if;

  if exists (
    select 1 from public.notifications n
    where n.type = 'monitor_ia'
      and n.reference_id = new.user_id::text
      and n.created_at > now() - interval '15 minutes'
  ) then
    return new;
  end if;

  select full_name into v_nombre from public.profiles where id = new.user_id;
  v_detalle := case new.tipo
    when 'camara_apagada' then 'tiene la cámara apagada'
    when 'se_fue'         then 'no está frente a la cámara'
    when 'celular'        then 'parece estar en el celular'
    when 'distraido'      then 'se ve distraído'
    when 'no_mira'        then 'no está mirando la pantalla'
    else new.tipo
  end;
  v_titulo := coalesce(v_nombre, 'Alguien') || ' ' || v_detalle;

  for sup in
    select d.user_id from public.destinatarios_de_aviso(new.user_id) d
  loop
    insert into public.notifications
      (user_id, type, title, message, reference_id, reference_type, module_origin, deep_link_url, priority)
    values
      (sup.user_id, 'monitor_ia', 'Monitor de cámara', v_titulo,
       new.user_id::text, 'monitor_evento', 'HR', format('/hr/en-vivo/%s', new.user_id), 'high');
  end loop;

  return new;
exception
  when others then
    return new;
end;
$$;


ALTER FUNCTION "public"."notificar_supervisores_monitor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_chat_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  participant record;
  sender_name text;
  conv_name text;
  msg_preview text;
  es_mencion boolean;
begin
  if new.api_key_id is not null then
    sender_name := new.api_display_name || ' (API)';
  else
    select full_name into sender_name from profiles where id = new.sender_id;
    sender_name := coalesce(sender_name, 'Alguien');
  end if;

  select name into conv_name from chat_conversations where id = new.conversation_id;

  if new.content is not null and new.content != '' then
    msg_preview := left(new.content, 100);
  else
    msg_preview := '📎 Archivo';
  end if;

  for participant in
    select cp.user_id, p.full_name
    from chat_participants cp
    left join profiles p on p.id = cp.user_id
    where cp.conversation_id = new.conversation_id
      and cp.user_id != new.sender_id
      and cp.is_muted = false
  loop
    es_mencion := public.menciona_a(new.content, participant.full_name);
    insert into notifications (
      user_id, type, title, message, reference_id, reference_type,
      module_origin, priority, status, deep_link_url, required_permission_module
    ) values (
      participant.user_id,
      case when es_mencion then 'chat_mention' else 'chat_message' end,
      case
        when es_mencion and conv_name is not null then sender_name || ' te mencionó en ' || conv_name
        when es_mencion then sender_name || ' te mencionó'
        when conv_name is not null then sender_name || ' en ' || conv_name
        else sender_name
      end,
      msg_preview,
      new.conversation_id,
      'conversation',
      'messenger',
      case when es_mencion then 'high' else 'low' end,
      'new',
      '/messenger?c=' || new.conversation_id || '&m=' || new.id,
      'Messenger'
    );
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_chat_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_closer_on_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  handle text;
BEGIN
  IF NEW.assigned_to IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.assigned_to IS NOT DISTINCT FROM NEW.assigned_to THEN
    RETURN NEW;
  END IF;

  handle := COALESCE(NEW.instagram_handle, 'sin handle');

  INSERT INTO notifications (
    user_id, type, title, message, reference_id, reference_type,
    module_origin, priority, status, deep_link_url,
    required_permission_module, automation_key
  ) VALUES (
    NEW.assigned_to,
    'closer_assigned',
    'Nueva lead asignada',
    '@' || handle || ' asignada. Primer contacto en 1 día.',
    NEW.id,
    'closer_creator',
    'closers',
    'medium',
    'new',
    '/closers?id=' || NEW.id::text,
    'Closers',
    'closer_assigned:' || NEW.id::text || ':' || NEW.assigned_to::text
  )
  ON CONFLICT (automation_key) WHERE automation_key IS NOT NULL DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_closer_on_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_of_earnings_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        DECLARE
          request_id bigint;
        BEGIN
          -- Use net.http_post from pg_net extension to send the entire record
          SELECT net.http_post(
            url := 'https://sincronizacion-externa-de-kash.invalid/functions/v1/sync-of-earnings-external'::text,
            body := jsonb_build_object(
              'type', TG_OP,
              'table', TG_TABLE_NAME,
              'record', row_to_json(NEW)::jsonb,
              'timestamp', NOW()
            ),
            headers := jsonb_build_object(
              'Content-Type', 'application/json',
              'Authorization', 'Basic SIN-CREDENCIAL'
            )
          ) INTO request_id;
          
          RAISE NOTICE 'Webhook request sent with id: %', request_id;
          RETURN NEW;
        EXCEPTION WHEN OTHERS THEN
          -- Log error but don't fail the transaction
          RAISE WARNING 'Webhook notification failed: %', SQLERRM;
          RETURN NEW;
        END;
        $$;


ALTER FUNCTION "public"."notify_of_earnings_webhook"() OWNER TO "postgres";


