CREATE OR REPLACE FUNCTION "public"."portal_cuenta_por_correo"("p_correo" "text") RETURNS TABLE("user_id" "uuid", "tipo" "text", "es_de_agencia" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select u.id,
         coalesce(u.raw_app_meta_data ->> 'tipo', ''),
         exists (select 1 from public.tenant_members tm where tm.user_id = u.id)
