CREATE OR REPLACE FUNCTION "public"."promolog_fallos_bloque"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with hoy as (select (now() at time zone 'America/Bogota')::date as d),
  fallos as (
    select e.creator_id, e.network, e.error_reason, max(e.scraped_at) as ultimo
    from promolog_entries e, hoy
    where e.dia = hoy.d
      and e.error_reason is not null
      and e.error_reason <> 'unconfirmed_empty'
    group by 1, 2, 3
  ),
  con_datos as (
    select f.network,
           case
             when f.error_reason = 'throttled' then 'IG nos frenó (rate-limit) — se reintenta solo'
             when f.error_reason = 'no_ig_id' then 'el handle no resuelve (¿cambió o está rota?)'
             when f.error_reason = 'follow_pending' then 'perfil personal de FB — falta amistad'
             when f.error_reason like 'json_parse%' then 'error de lectura del bot'
             else f.error_reason
           end as motivo,
           coalesce(c.artistic_name, c.instagram_handle, '?') as creadora,
           split_part(coalesce(p.full_name, '—'), ' ', 1) as manager,
           (select n.reason || ' (' || split_part(coalesce(pn.full_name,'?'),' ',1)
                   || ' ' || to_char(n.created_at at time zone 'America/Bogota','DD/MM') || ')'
            from promolog_scan_notes n
            left join profiles pn on pn.id = n.set_by
            where n.creator_id = f.creator_id and n.active
              and (n.network is null or n.network = f.network)
            order by n.created_at desc limit 1) as explicacion
    from fallos f
    join public.creadoras_de_mi_agencia() c on c.id = f.creator_id
    left join profiles p on p.id = c.assigned_manager_profile_id
  ),
  sin_explicar as (
    select motivo, string_agg(creadora || ' (' || manager || ')', ', ' order by creadora) as lista, count(*) n
    from con_datos where explicacion is null group by motivo
  ),
  explicadas as (
    select string_agg(creadora || ' — ' || explicacion, E'\n· ' order by creadora) as lista, count(*) n
    from con_datos where explicacion is not null
  )
  select
    case when (select count(*) from con_datos) = 0
      then 'Sin fallos reales de lectura hoy ✓ (0 historias NO es un fallo: es lectura válida sin promo)'
      else
        coalesce((select string_agg('⚠️ ' || s.motivo || ' (' || s.n || '): ' || s.lista, E'\n') from sin_explicar s), '')
        || case when (select n from explicadas) > 0
             then E'\nCon razón ya conocida (no alarmar):\n· ' || (select lista from explicadas)
             else '' end
    end;
$$;


ALTER FUNCTION "public"."promolog_fallos_bloque"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promolog_ig_scan_state_today"() RETURNS TABLE("creator_id" "uuid", "source_handle" "text", "has_definitive" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select e.creator_id,
         lower(e.source_handle) as source_handle,
         bool_or(e.promoted in ('true','false')) as has_definitive
  from promolog_entries e
  where lower(e.network) = 'instagram'
    and e.creator_id is not null
    and e.source_handle is not null
    and (e.date at time zone 'America/New_York')::date
        = (now() at time zone 'America/New_York')::date
  group by e.creator_id, lower(e.source_handle);
$$;


ALTER FUNCTION "public"."promolog_ig_scan_state_today"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promolog_normalize_network"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.network IS NOT NULL THEN
    NEW.network := CASE lower(btrim(NEW.network))
      WHEN 'ig' THEN 'instagram'
      WHEN 'tg' THEN 'telegram'
      WHEN 'tt' THEN 'tiktok'
      WHEN 'fb' THEN 'facebook'
      WHEN 'twitter' THEN 'x'
      ELSE lower(btrim(NEW.network))
    END;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."promolog_normalize_network"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promolog_purgar_evidencia"("_creator" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_n integer;
begin
  update promolog_entries
     set evidence_url = null,
         notes = case
                   when notes is null or trim(notes) = '' then 'Evidencia purgada: la creadora dejó de estar activa.'
                   when notes like '%Evidencia purgada%' then notes
                   else notes || E'\n' || 'Evidencia purgada: la creadora dejó de estar activa.'
                 end,
         updated_at = now()
   where creator_id = _creator and evidence_url is not null;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."promolog_purgar_evidencia"("_creator" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promolog_upsert_handle_status"("p_creator_id" "uuid", "p_handle" "text", "p_status" "text", "p_error" "text", "p_days" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into promolog_handle_status(creator_id, handle, status, ig_error, days_empty, checked_at, first_broken_at)
  values (p_creator_id, p_handle, p_status, p_error, p_days, now(),
          case when p_status='broken' then now() else null end)
  on conflict (creator_id) do update set
    handle = excluded.handle,
    status = excluded.status,
    ig_error = excluded.ig_error,
    days_empty = excluded.days_empty,
    checked_at = now(),
    first_broken_at = case
      when excluded.status='broken' and promolog_handle_status.first_broken_at is null then now()
      when excluded.status <> 'broken' then null
      else promolog_handle_status.first_broken_at end,
    resolved_at = case
      when excluded.status <> 'broken' and promolog_handle_status.status = 'broken' then now()
      when excluded.status = 'broken' then null
      else promolog_handle_status.resolved_at end;
end; $$;


ALTER FUNCTION "public"."promolog_upsert_handle_status"("p_creator_id" "uuid", "p_handle" "text", "p_status" "text", "p_error" "text", "p_days" integer) OWNER TO "postgres";


