CREATE OR REPLACE FUNCTION "public"."push_chat_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_recipients uuid[];
  v_token text;
begin
  if new.type = 'system' or new.is_deleted then
    return null;
  end if;

  select array_agg(cp.user_id) into v_recipients
  from chat_participants cp
  join notification_settings ns
    on ns.user_id = cp.user_id
   and ns.push_enabled
   and ns.notifications_enabled
  where cp.conversation_id = new.conversation_id
    and cp.user_id <> new.sender_id
    and not cp.is_muted
    and cp.notifications_mode <> 'none'
    and public.notif_canal_activo(cp.user_id, 'chat_message', 'push')
    and exists (select 1 from push_subscriptions ps where ps.user_id = cp.user_id);

  if v_recipients is null then
    return null;
  end if;

  begin
    select decrypted_secret into v_token
      from vault.decrypted_secrets
     where name = 'cron_internal_token';

    perform net.http_post(
      url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/web-push',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'X-Cron-Token', v_token
      ),
      body := jsonb_build_object(
        'action', 'notify',
        'kind', 'chat_message',
        'recipient_ids', to_jsonb(v_recipients),
        'ref', jsonb_build_object(
          'message_id', new.id,
          'conversation_id', new.conversation_id,
          'sender_id', new.sender_id
        )
      ),
      timeout_milliseconds := 10000
    );
  exception when others then
    raise warning 'push_chat_message: % (mensaje %)', sqlerrm, new.id;
  end;

  return null;
end
$$;


ALTER FUNCTION "public"."push_chat_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_correo_nuevo"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_de text;
begin
  if new.folder <> 'INBOX' or not coalesce(new.unread, true) then
    return null;
  end if;
  if new.date is null or new.date < now() - interval '30 minutes' or new.date > now() + interval '5 minutes' then
    return null;
  end if;
  if exists (
       select 1 from mail_credentials c
       where c.user_id = new.user_id and c.revoked_at is null
         and new.from_addr ilike '%' || c.email_address || '%'
     ) or exists (
       select 1 from mail_connections c
       where c.user_id = new.user_id and c.revoked_at is null
         and new.from_addr ilike '%' || c.email_address || '%'
     ) then
    return null;
  end if;

  -- "Nombre Apellido <correo@x>" → "Nombre Apellido"; si no hay nombre, el correo.
  v_de := nullif(trim(both ' "''' from split_part(new.from_addr, '<', 1)), '');
  if v_de is null or v_de = '' then
    v_de := coalesce(nullif(trim(both ' <>' from new.from_addr), ''), 'Correo nuevo');
  end if;

  perform public.push_notify_enqueue(
    'correo_nuevo',
    array[new.user_id],
    jsonb_build_object('mail_id', new.id, 'folder', new.folder, 'uid', new.uid),
    v_de,
    coalesce(nullif(new.subject, ''), '(sin asunto)'),
    '/correo',
    'correo-' || new.user_id,
    'low'
  );
  return null;
end
$$;


ALTER FUNCTION "public"."push_correo_nuevo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_cowork_llamado"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hosts uuid[];
  v_nombre text;
  v_sesion text;
  v_que text;
begin
  select array_agg(m.user_id) into v_hosts
  from cowork_memberships m
  where m.session_id = new.session_id
    and m.role = 'host'
    and m.user_id <> new.user_id;
  if v_hosts is null then
    return null;
  end if;
  select p.full_name into v_nombre from profiles p where p.id = new.user_id;
  select s.name into v_sesion from cowork_sessions s where s.id = new.session_id;
  v_que := case new.kind
    when 'camara'   then 'Cámara apagada'
    when 'encuadre' then 'Mal encuadre'
    when 'luz'      then 'Sin luz'
    when 'pantalla' then 'No comparte pantalla'
    else new.kind
  end;
  perform public.push_notify_enqueue(
    'cowork_llamado_' || new.kind,
    v_hosts,
    jsonb_build_object('llamado_id', new.id, 'session_id', new.session_id, 'user_id', new.user_id, 'kind', new.kind),
    v_que || ' · Cowork',
    coalesce(nullif(v_nombre, ''), 'Alguien') || coalesce(' · ' || nullif(v_sesion, ''), ''),
    '/cowork?session=' || new.session_id,
    'cowork-llamado-' || new.session_id || '-' || new.kind,
    'normal'
  );
  return null;
end
$$;


ALTER FUNCTION "public"."push_cowork_llamado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_cowork_pedido_host"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hosts uuid[];
  v_nombre text;
  v_sala text;
begin
  if coalesce(new.status, 'open') <> 'open' then
    return null;
  end if;
  select array_agg(m.user_id) into v_hosts
  from cowork_memberships m
  where m.session_id = new.session_id
    and m.role = 'host'
    and m.user_id <> new.user_id;
  if v_hosts is null then
    return null;
  end if;
  select p.full_name into v_nombre from profiles p where p.id = new.user_id;
  if new.room_id is not null then
    select r.name into v_sala from cowork_rooms r where r.id = new.room_id;
  end if;
  perform public.push_notify_enqueue(
    'cowork_pedido_host',
    v_hosts,
    jsonb_build_object('request_id', new.id, 'session_id', new.session_id, 'user_id', new.user_id),
    coalesce(nullif(v_nombre, ''), 'Alguien') || ' pide supervisor',
    coalesce('Sala ' || nullif(v_sala, ''), 'Cowork') || coalesce(' · ' || nullif(new.message, ''), ''),
    '/cowork?session=' || new.session_id,
    'cowork-pedido-' || new.id,
    'normal'
  );
  return null;
end
$$;


ALTER FUNCTION "public"."push_cowork_pedido_host"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_desde_notificacion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.user_id is null or new.type is null or new.type in ('chat_message', 'chat_mention') then
    return null;
  end if;
  if new.required_permission_module is not null
     and not public.puede_ver_modulo(new.user_id, new.required_permission_module, new.required_permission_submodule) then
    return null;
  end if;
  if exists (
    select 1 from notifications n
    where n.user_id = new.user_id and n.type = new.type
      and date_trunc('minute', n.created_at) = date_trunc('minute', new.created_at)
      and (n.created_at, n.id) < (new.created_at, new.id)
  ) then
    return null;
  end if;
  perform public.push_notify_enqueue(
    new.type,
    array[new.user_id],
    jsonb_build_object('notification_id', new.id, 'reference_type', new.reference_type, 'reference_id', new.reference_id),
    coalesce(nullif(new.title, ''), 'Maven'),
    coalesce(new.message, ''),
    coalesce(nullif(new.deep_link_url, ''), '/notificaciones'),
    'notif-' || new.id,
    case when new.priority in ('critical', 'high') then 'normal' else 'low' end
  );
  return null;
end
$$;


ALTER FUNCTION "public"."push_desde_notificacion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_notify_enqueue"("p_kind" "text", "p_recipients" "uuid"[], "p_ref" "jsonb", "p_title" "text", "p_body" "text", "p_url" "text", "p_tag" "text", "p_priority" "text" DEFAULT 'low'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_recipients uuid[];
  v_token text;
begin
  if p_recipients is null or array_length(p_recipients, 1) is null then
    return;
  end if;

  -- Canal correo (opt-in por evento). Va antes del filtro de push: no depende
  -- de push_enabled ni de tener un dispositivo suscrito.
  perform public.email_notify_enqueue(p_kind, p_recipients, p_title, p_body, p_url);

  select array_agg(distinct r) into v_recipients
  from unnest(p_recipients) as r
  join notification_settings ns
    on ns.user_id = r and ns.push_enabled and ns.notifications_enabled
  where exists (select 1 from push_subscriptions ps where ps.user_id = r)
    and public.notif_canal_activo(r, p_kind, 'push');

  if v_recipients is null then
    return;
  end if;

  begin
    select decrypted_secret into v_token
      from vault.decrypted_secrets
     where name = 'cron_internal_token';

    perform net.http_post(
      url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/web-push',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'X-Cron-Token', v_token
      ),
      body := jsonb_build_object(
        'action', 'notify',
        'kind', p_kind,
        'recipient_ids', to_jsonb(v_recipients),
        'ref', coalesce(p_ref, '{}'::jsonb),
        'title', p_title,
        'body', p_body,
        'url', p_url,
        'tag', p_tag,
        'priority', coalesce(p_priority, 'low')
      ),
      timeout_milliseconds := 10000
    );
  exception when others then
    raise warning 'push_notify_enqueue(%): %', p_kind, sqlerrm;
  end;
end
$$;


ALTER FUNCTION "public"."push_notify_enqueue"("p_kind" "text", "p_recipients" "uuid"[], "p_ref" "jsonb", "p_title" "text", "p_body" "text", "p_url" "text", "p_tag" "text", "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_tg_asignacion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_quien text;
begin
  if new.assigned_by is null or new.assigned_by = new.user_id then
    return null;
  end if;
  if not public.puede_ver_modulo(new.user_id, 'Telegram', null) then
    return null;
  end if;

  select coalesce(nullif(t.peer_name, ''), nullif('@' || t.peer_username, '@')) into v_quien
  from tg_conversations t
  where t.id = new.conversation_id;

  perform public.push_notify_enqueue(
    'inbox_asignacion',
    array[new.user_id],
    jsonb_build_object('conversation_id', new.conversation_id, 'assigned_by', new.assigned_by, 'channel', 'tg'),
    'Te asignaron una conversación',
    coalesce(v_quien, 'Un contacto de Telegram'),
    '/telegram/bandeja?c=' || new.conversation_id,
    'inbox-tg-' || new.conversation_id,
    'normal'
  );
  return null;
end
$$;


ALTER FUNCTION "public"."push_tg_asignacion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_wa_asignacion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_quien text;
begin
  if new.assigned_by is null or new.assigned_by = new.user_id then
    return null;
  end if;
  if not public.puede_ver_modulo(new.user_id, 'WhatsApp', null) then
    return null;
