CREATE OR REPLACE FUNCTION "public"."reactivate_creator"("p_creator_id" "uuid", "p_closer_responsible" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "status" "text", "rejoined_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not (public.has_role(auth.uid(), 'closer'::app_role)
          or public.is_in_role_group(auth.uid(), 'supervisor_or_above')
          or public.has_creators_global_scope(auth.uid())) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  update public.creators c
     set status = 'onboarding',
         rejoined_at = now(),
         closer_responsible_id = coalesce(p_closer_responsible, auth.uid())
   where c.id = p_creator_id and c.tenant_id = public.current_tenant_id()
     and c.status in ('terminated', 'leaving', 'paused')
  returning c.id, c.status, c.rejoined_at;
end $$;


