CREATE OR REPLACE FUNCTION "public"."recalc_chatter_c1_puntualidad"("p_period" "date", "p_min_days" integer DEFAULT 5, "p_tolerance_min" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n int;
begin
  if not (coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role','') = 'service_role'
          or public.blu_is_management(auth.uid())) then
    raise exception 'forbidden: solo service_role/management' using errcode = '42501';
  end if;
  with base as (
    select cp.blu_employee_id,
      (extract(hour from (d.first_activity_at at time zone 'America/Bogota'))*60
       + extract(minute from (d.first_activity_at at time zone 'America/Bogota')))::int as mod
    from public.hubstaff_daily_data d
    join public.hubstaff_members hm on hm.hubstaff_user_id = d.hubstaff_user_id
    join public.chatter_performance cp on lower(btrim(cp.email)) = lower(btrim(hm.email)) and cp.is_chatter = true
    where d.first_activity_at is not null and date_trunc('month', d.date)::date = p_period and cp.blu_employee_id is not null
  ),
  perday as (
    select blu_employee_id, mod,
      case when least(mod,1440-mod) <= abs(mod-480) and least(mod,1440-mod) <= abs(mod-960) then 0
           when abs(mod-480) <= abs(mod-960) then 480 else 960 end as shift_start
    from base
  ),
  perday2 as (select *, (((mod - shift_start + 720) % 1440) - 720) as dev from perday),
  agg as (
    select blu_employee_id, count(*) as dias,
      round(100.0 * count(*) filter (where dev <= p_tolerance_min) / count(*))::int as pct
    from perday2 group by blu_employee_id
  )
  update public.chatter_scorecards sc
  set c1_puntualidad = case
        when a.pct >= 100 then 5 when a.pct >= 90 then 4 when a.pct >= 80 then 3
        when a.pct >= 65 then 2 when a.pct >= 50 then 1 else 0 end
  from agg a
  where sc.blu_employee_id = a.blu_employee_id and sc.period = p_period and a.dias >= p_min_days;
  get diagnostics n = row_count;
  return jsonb_build_object('period', p_period, 'rows_updated', n, 'min_days', p_min_days, 'tolerance_min', p_tolerance_min);
end $$;


ALTER FUNCTION "public"."recalc_chatter_c1_puntualidad"("p_period" "date", "p_min_days" integer, "p_tolerance_min" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalc_chatter_scorecard_hubstaff"("p_period" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n int;
begin
  if not (coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role','') = 'service_role'
          or public.blu_is_management(auth.uid())) then
    raise exception 'forbidden: solo service_role/management' using errcode = '42501';
  end if;
  with src as (
    select blu_employee_id, avg_activity_pct
    from public.v_chatter_hubstaff_monthly
    where period = p_period and blu_employee_id is not null
  )
  update public.chatter_scorecards sc
  set c4_productividad_hubstaff = case
        when s.avg_activity_pct >= 75 then 5
        when s.avg_activity_pct >= 65 then 4
        when s.avg_activity_pct >= 55 then 3
        when s.avg_activity_pct >= 45 then 2
        when s.avg_activity_pct >= 35 then 1
        else 0 end
  from src s
  where sc.blu_employee_id = s.blu_employee_id and sc.period = p_period;
  get diagnostics n = row_count;
  return jsonb_build_object('period', p_period, 'rows_updated', n);
end $$;


ALTER FUNCTION "public"."recalc_chatter_scorecard_hubstaff"("p_period" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_qa_call_participants"("p_call_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count int;
  v_speakers jsonb;
  v_closer_speaker text;
  v_model_speaker text;
  v_total_closer_ratio numeric := 0;
  v_supports_count int;
  v_speakers_for_support text[];
  rec RECORD;
BEGIN
  SELECT COUNT(*) INTO v_count FROM public.qa_call_participants WHERE call_id = p_call_id;
  IF v_count = 0 THEN RETURN; END IF;

  -- Si solo hay 1 participant, siempre 1.0.
  IF v_count = 1 THEN
    UPDATE public.qa_call_participants SET participation_pct = 1.0 WHERE call_id = p_call_id;
    RETURN;
  END IF;

  SELECT
    c.audio_metrics->'speakers',
    c.claude_analysis->>'closer_speaker_label'
  INTO v_speakers, v_closer_speaker
  FROM public.qa_calls c
  WHERE c.id = p_call_id;

  -- Fallback simple: division 1/N si no hay audio metrics o claude analysis.
  IF v_speakers IS NULL OR jsonb_array_length(v_speakers) = 0 OR v_closer_speaker IS NULL THEN
    UPDATE public.qa_call_participants
      SET participation_pct = 1.0 / v_count
      WHERE call_id = p_call_id;
    RETURN;
  END IF;

  -- Asignar speaker_label al primary (= closer_speaker_label de claude).
  UPDATE public.qa_call_participants
    SET speaker_label = v_closer_speaker
    WHERE call_id = p_call_id AND role = 'primary';

  -- Detectar el modelo: speaker con mayor talk_ratio que NO sea el primary.
  SELECT s.label INTO v_model_speaker
  FROM jsonb_to_recordset(v_speakers) AS s(label text, talk_ratio numeric)
  WHERE s.label != v_closer_speaker
  ORDER BY s.talk_ratio DESC NULLS LAST
  LIMIT 1;

  -- Lista de speakers candidatos para support: todos menos el primary y el
  -- modelo, ordenados por talk_ratio descendente.
  SELECT array_agg(label ORDER BY talk_ratio DESC NULLS LAST) INTO v_speakers_for_support
  FROM jsonb_to_recordset(v_speakers) AS s(label text, talk_ratio numeric)
  WHERE s.label != v_closer_speaker
    AND s.label IS DISTINCT FROM v_model_speaker
    AND s.talk_ratio > 0.05;

  -- Asignar speaker_label a los supports en orden de created_at.
  IF v_speakers_for_support IS NOT NULL AND array_length(v_speakers_for_support, 1) > 0 THEN
    WITH ranked AS (
      SELECT call_id, closer_id,
        ROW_NUMBER() OVER (ORDER BY created_at ASC) AS rn
      FROM public.qa_call_participants
      WHERE call_id = p_call_id AND role = 'support'
    )
    UPDATE public.qa_call_participants p
      SET speaker_label = v_speakers_for_support[r.rn]
      FROM ranked r
      WHERE p.call_id = r.call_id
        AND p.closer_id = r.closer_id
        AND r.rn <= array_length(v_speakers_for_support, 1);
  END IF;

  -- Sumar talk_ratio de todos los participants que tienen speaker_label.
  SELECT SUM(s.talk_ratio) INTO v_total_closer_ratio
  FROM public.qa_call_participants p
  JOIN jsonb_to_recordset(v_speakers) AS s(label text, talk_ratio numeric)
    ON s.label = p.speaker_label
  WHERE p.call_id = p_call_id;

  -- Fallback: si por alguna razón no hay ratio (todos NULL o 0), 1/N.
  IF v_total_closer_ratio IS NULL OR v_total_closer_ratio <= 0 THEN
    UPDATE public.qa_call_participants
      SET participation_pct = 1.0 / v_count
      WHERE call_id = p_call_id;
    RETURN;
  END IF;

  -- Asignar pct = talk_ratio / total_closer_ratio para cada participant.
  -- Si un support no tiene speaker_label (más closers que speakers detectados),
  -- queda con pct=0 (no se le cuenta).
  UPDATE public.qa_call_participants p
    SET participation_pct = COALESCE(s.talk_ratio / v_total_closer_ratio, 0)
    FROM (
      SELECT label, talk_ratio
      FROM jsonb_to_recordset(v_speakers) AS x(label text, talk_ratio numeric)
    ) s
    WHERE p.call_id = p_call_id
      AND p.speaker_label = s.label;

  -- Los que quedaron sin match → pct=0.
  UPDATE public.qa_call_participants
    SET participation_pct = 0
    WHERE call_id = p_call_id
      AND (speaker_label IS NULL OR speaker_label NOT IN (
        SELECT label FROM jsonb_to_recordset(v_speakers) AS x(label text, talk_ratio numeric)
      ));
END;
$$;


ALTER FUNCTION "public"."recalculate_qa_call_participants"("p_call_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recordar_horarios_pendientes"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant uuid := '30869615-f579-4981-8a1f-dbebc61eae2d';
  v_hora int := extract(hour from now() at time zone 'America/Bogota')::int;
  v_dow int := extract(dow from now() at time zone 'America/Bogota')::int;
  v_creador uuid := (select id from profiles where full_name = 'Jhon Lopez' limit 1);
  v_grupo record;
  v_faltan text;
  v_body text;
  v_insertados int := 0;
begin
  if v_dow = 0 then return 'skip: domingo'; end if;
  if v_dow = 6 and v_hora >= 14 then return 'skip: sábado post-jornada'; end if;
  if v_hora < 9 or v_hora >= 19 then return 'skip: fuera de jornada'; end if;

  for v_grupo in
    select * from (values
      ('a12d9f41-c962-4d98-b0bb-6b2d2573534c'::uuid),
      ('73a4414e-2546-4ca7-9289-7cbec70b0273'::uuid),
      ('d12ec56f-b324-4369-b72d-7540fb930ef6'::uuid)
    ) g(gid)
  loop
    -- Quiénes de ESTE grupo siguen sin horario. Solo empleados operativos:
    -- el horario no es cosa de dueño/gerencia (admin) ni de managers de cuentas.
    select string_agg(distinct split_part(p.full_name, ' ', 1), ', ')
    into v_faltan
    from whatsapp_members m
    join profiles p on p.id = m.user_id
    where m.group_id = v_grupo.gid and coalesce(m.active, true)
      and p.full_name not ilike '%lopez%'
      and p.full_name not in ('Alvaro Mejía', 'Juan Pachas')
      and p.full_name not ilike '%alvaro mej%'
      and not exists (
        select 1 from user_roles ur
        where ur.user_id = p.id and ur.role::text in ('admin', 'manager')
      )
      and not exists (select 1 from whatsapp_user_schedules s where s.user_id = p.id);
    if v_faltan is null then continue; end if;

    -- Anti-spam: nada si hay uno pendiente o se envió otro hace <3h30 en el grupo.
    if exists (
      select 1 from whatsapp_reminders r
      where r.group_id = v_grupo.gid
        and (r.body ilike '%horario%' and (r.status = 'pending' or r.sent_at > now() - interval '3 hours 30 minutes'))
    ) then continue; end if;

    v_body := case v_hora % 3
      when 0 then '⏰ Sigo sin el horario de: ' || v_faltan || '. Respondan por aquí con días y horas (ej: "L-V 10am a 7pm, sáb 10 a 2") y lo dejo registrado.'
      when 1 then 'Recordatorio rápido 📋 me falta registrar el horario de ' || v_faltan || ' — un mensaje con días y horas y quedan al día.'
      else v_faltan || ': sin su horario no puedo afinarles los check-ins ni contarlos bien en el reporte. ¿Me lo pasan? (ej: "L-V 10 a 7")'
    end;

    insert into whatsapp_reminders (tenant_id, group_id, kind, trigger_at, body, status, created_by)
    values (v_tenant, v_grupo.gid, 'manual', now(), v_body, 'pending', v_creador);
    v_insertados := v_insertados + 1;
  end loop;

  return 'recordatorios: ' || v_insertados;
end;
$$;


ALTER FUNCTION "public"."recordar_horarios_pendientes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_stuck_spammer_scans"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_unreadable_count integer;
  v_failed_count integer;
BEGIN
  -- Stuck con TODOS los campos null → no pudimos leer la cuenta. Va a
  -- awaiting_screenshot para que el user reintente o suba capturas.
  -- NO se marca is_restricted (antes lo hacía → falsos positivos).
  UPDATE public.scouter_spammer_accounts
  SET scan_status = 'awaiting_screenshot',
      scan_error = 'No pudimos leer el perfil automáticamente (cuenta muy nueva o IG bloqueó la lectura). Reintenta el scan o sube un screenshot del perfil.',
      last_scanned_at = now()
  WHERE scan_status IN ('scanning','pending')
    AND created_at < now() - interval '5 minutes'
    AND (last_scanned_at IS NULL OR last_scanned_at < now() - interval '5 minutes')
    AND bio IS NULL
    AND followers_count IS NULL
    AND posts_count IS NULL
    AND profile_pic_url IS NULL;
  GET DIAGNOSTICS v_unreadable_count = ROW_COUNT;

  -- Stuck con algún dato → error técnico real (timeout, excepción, etc).
  -- Marcar como failed con mensaje para que el user re-dispare.
  UPDATE public.scouter_spammer_accounts
  SET scan_status = 'failed',
      scan_error = 'Scan se quedó colgado más de 5 minutos. Haz clic en "Re-scan" para reintentar.',
      last_scanned_at = now()
  WHERE scan_status IN ('scanning','pending')
    AND created_at < now() - interval '5 minutes'
    AND (last_scanned_at IS NULL OR last_scanned_at < now() - interval '5 minutes');
  GET DIAGNOSTICS v_failed_count = ROW_COUNT;

  RETURN v_unreadable_count + v_failed_count;
END;
$$;


ALTER FUNCTION "public"."recover_stuck_spammer_scans"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recover_stuck_spammer_scans"() IS 'Cleanup de rows con scan_status stuck. Si todos los campos están vacios -> no se pudo leer -> awaiting_screenshot (SIN marcar restricted). Si tiene algun dato -> failed. is_restricted solo lo setea la senal confirmada del scan.';



CREATE TABLE IF NOT EXISTS "public"."chatter_cost_config" (
    "id" boolean DEFAULT true NOT NULL,
    "base_salary_cop" numeric(14,2) DEFAULT 2000000 NOT NULL,
    "fx_cop_per_usd" numeric(12,4) DEFAULT 4000 NOT NULL,
    "of_net_factor" numeric(5,4) DEFAULT 0.80 NOT NULL,
    "effective_agency_rate" numeric(6,4) DEFAULT 30 NOT NULL,
    "fx_updated_at" timestamp with time zone,
    "rate_updated_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chatter_cost_config_singleton" CHECK (("id" = true))
);


ALTER TABLE "public"."chatter_cost_config" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_chatter_cost_config"("p_fx" numeric DEFAULT NULL::numeric) RETURNS "public"."chatter_cost_config"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rate numeric;
  v_row  public.chatter_cost_config;
begin
  if not public.hubstaff_can_write() then
    raise exception 'forbidden';
  end if;

  select round((sum(g.gross * coalesce(g.pct, 30)) / nullif(sum(g.gross), 0))::numeric, 4)
    into v_rate
  from (
    select cde.creator_id,
           sum(cde.total_gross) as gross,
           max(cb.agency_percentage) as pct
    from public.creator_daily_earnings cde
    left join public.creator_business cb on cb.creator_id = cde.creator_id
    where cde.date >= date_trunc('month', current_date)
    group by cde.creator_id
  ) g;

  update public.chatter_cost_config
     set fx_cop_per_usd        = coalesce(p_fx, fx_cop_per_usd),
         fx_updated_at         = case when p_fx   is not null then now() else fx_updated_at end,
         effective_agency_rate = coalesce(v_rate, effective_agency_rate),
         rate_updated_at       = case when v_rate is not null then now() else rate_updated_at end,
         updated_at            = now()
   where id = true
   returning * into v_row;

  return v_row;
end $$;


ALTER FUNCTION "public"."refresh_chatter_cost_config"("p_fx" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reporte_baja_actividad_texto"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hoy       text := to_char(now() at time zone 'America/Bogota', 'DD/MM');
  v_feed_last timestamptz;
  v_feed_min  int;
  v_lineas    text;
  v_total     int;
begin
  select max(l.feed_last_ping) into v_feed_last from hubstaff_live_today(null) l;
  v_feed_min := case when v_feed_last is null then null
                     else floor(extract(epoch from (now() - v_feed_last)) / 60)::int end;

  -- Feed viejo: NO afirmar nada de nadie. Misma regla que ya tenia el prompt del bot
  -- ("PROHIBIDO afirmar 0h o no arranco de NADIE").
  if v_feed_last is null or v_feed_min > 45 then
    return format(
      '⚠️ Reporte de baja actividad (%s) — NO disponible.%s'
      || 'El feed de Hubstaff no reporta desde %s (hace %s min), así que no puedo afirmar horas ni actividad de nadie. Esto es lo último que se sabe.',
      v_hoy, E'\n\n',
      coalesce(to_char(v_feed_last at time zone 'America/Bogota', 'HH24:MI'), 'desconocido'),
      coalesce(v_feed_min::text, '?'));
  end if;

  with banda as (
    select coalesce(l.full_name_maven, l.name) as nombre,
           l.activity_pct::int                 as pct,
           l.seconds_today                     as segs,
           to_char((l.first_ping at time zone 'America/Bogota'), 'HH24:MI') as arranco,
           to_char((l.last_ping  at time zone 'America/Bogota'), 'HH24:MI') as ultimo
    from hubstaff_live_today(null) l
    left join hubstaff_members hm on hm.hubstaff_user_id::text = l.hubstaff_user_id::text
    where l.seconds_today > 0
      and l.activity_pct is not null
      and l.activity_pct::int <= 25
      and not coalesce(public.has_role(hm.profile_id, 'admin'::app_role), false)
      and (hm.profile_id is null
           or hm.profile_id not in (select e.profile_id from public.hubstaff_reporte_exentos e))
  )
  select count(*)::int,
         string_agg(
           format('• %s — %sh%s, %s%% · %s → %s',
                  nombre,
                  (segs / 3600)::int,
                  lpad((((segs % 3600) / 60)::int)::text, 2, '0'),
                  pct, coalesce(arranco, '?'), coalesce(ultimo, '?')),
           E'\n' order by pct asc, segs desc)
  into v_total, v_lineas
  from banda;

  if coalesce(v_total, 0) = 0 then
    return format('✅ Baja actividad (%s): nadie por debajo del 25%% hoy.', v_hoy);
  end if;

  return format(
    '📊 Baja actividad de hoy (%s) — %s %s por debajo del 25%%%s%s%s%s',
    v_hoy, v_total,
    case when v_total = 1 then 'persona' else 'personas' end,
    E'\n\n', v_lineas, E'\n\n',
    'Criterio: fichó hoy y actividad del día ≤25%. Dirección excluida. Lista completa.');
end;
$$;


ALTER FUNCTION "public"."reporte_baja_actividad_texto"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reporte_baja_actividad_texto"() IS 'Arma el texto del reporte diario de baja actividad SIN LLM. Devuelve el mensaje listo para whatsapp-send. Reemplaza un reminder de ~$0.70 por disparo que solo transcribia datos ya calculados.';



CREATE OR REPLACE FUNCTION "public"."reporte_horas_mes"("_desde" "date", "_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resultado jsonb;
  _tz text := 'America/Bogota';
begin
  if not es_admin_o_dueno((select auth.uid())) then
    raise exception 'solo admin/dueño';
  end if;

  with seg_estado as (
    select user_id,
           (started_at at time zone _tz)::date as dia,
           estado,
           sum(coalesce(seconds, 0))::int as seg
    from cowork_tiempo_segmentos
    where started_at >= _desde::timestamptz and started_at < (_hasta + 1)::timestamptz
    group by user_id, dia, estado
  ),
  seg_breaks as (
    select user_id,
           (started_at at time zone _tz)::date as dia,
           kind,
           sum(coalesce(duration_seconds, 0))::int as seg
    from cowork_breaks
    where started_at >= _desde::timestamptz and started_at < (_hasta + 1)::timestamptz
    group by user_id, dia, kind
  ),
  personas as (
    select distinct p.id as user_id, p.full_name, p.nivel, ur.role
    from profiles p
    left join user_roles ur on ur.user_id = p.id
    where p.deleted_at is null
      and (exists (select 1 from seg_estado s where s.user_id = p.id)
           or exists (select 1 from seg_breaks b where b.user_id = p.id))
  ),
  por_persona as (
    select p.user_id, p.full_name, p.nivel, p.role,
           (select jsonb_object_agg(estado, seg) from (select estado, sum(seg)::int as seg from seg_estado where user_id = p.user_id group by estado) t) as totales_estado,
           (select jsonb_object_agg(kind, seg)   from (select kind,   sum(seg)::int as seg from seg_breaks where user_id = p.user_id group by kind) t) as totales_breaks,
           (select jsonb_agg(jsonb_build_object(
             'dia', d.dia,
             'estados', (select jsonb_object_agg(estado, seg) from seg_estado where user_id = p.user_id and dia = d.dia),
             'breaks',  (select jsonb_object_agg(kind, seg)   from seg_breaks where user_id = p.user_id and dia = d.dia)
           ) order by d.dia)
           from (
             select dia from seg_estado where user_id = p.user_id
             union select dia from seg_breaks where user_id = p.user_id
           ) d) as dias
    from personas p
  )
  select jsonb_build_object(
    'desde', _desde,
    'hasta', _hasta,
    'generado_at', now(),
    'tz', _tz,
    'personas', coalesce((select jsonb_agg(to_jsonb(por_persona) order by full_name) from por_persona), '[]'::jsonb)
  ) into resultado;

  return resultado;
end;
$$;


ALTER FUNCTION "public"."reporte_horas_mes"("_desde" "date", "_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_wa_member"("p_group_id" "uuid", "p_name" "text") RETURNS TABLE("member_id" "uuid", "display_name" "text", "user_id" "uuid", "member_role" "text", "full_name" "text", "last_seen_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  with q as (select extensions.unaccent(lower(btrim(p_name))) as n)
  -- (1) miembros del grupo cuyo display_name matchea (accent/case-insensitive)
  select m.id, m.display_name, m.user_id, m.role, p.full_name, m.last_seen_at
    from whatsapp_members m
    left join profiles p on p.id = m.user_id
    cross join q
   where m.group_id = p_group_id
     and m.display_name is not null
     and extensions.unaccent(lower(m.display_name)) like '%' || q.n || '%'
  union
  -- (2) perfiles cuyo full_name matchea (cross-group) + su member del grupo si existe
  select m.id, coalesce(m.display_name, pr.full_name), pr.id, m.role, pr.full_name, m.last_seen_at
    from profiles pr
    cross join q
    left join whatsapp_members m on m.user_id = pr.id and m.group_id = p_group_id
   where pr.full_name is not null
     and extensions.unaccent(lower(pr.full_name)) like '%' || q.n || '%'
  limit 12;
$$;


