CREATE OR REPLACE FUNCTION "public"."resolve_wa_name"("p_closer_creator_id" "uuid", "p_phone" "text") RETURNS TABLE("name" "text", "source" "text", "entity_id" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with t as (
    select p_closer_creator_id as ccid,
           right(regexp_replace(coalesce(p_phone,''),'\D','','g'),10) as d10
  ),
  cand as (
    select 1 pri, 'pipeline_link'::text source, cc.id::text entity_id,
           coalesce(nullif(btrim(co.name),''), nullif(btrim(mo.display_name),''), cc.instagram_handle) name
      from t join public.closer_creators cc on cc.id = t.ccid
      left join public.closers_contacts co on co.id = cc.source_contact_id
      left join public.models mo on mo.id = cc.model_id
      where coalesce(nullif(btrim(co.name),''), nullif(btrim(mo.display_name),''), cc.instagram_handle) is not null
    union all
    select 2, 'creator', cr.id::text, cr.name from t join public.creators cr
      on length(t.d10) = 10
     and right(regexp_replace(coalesce(cr.phone_e164, cr.whatsapp_number, cr.phone, ''),'\D','','g'),10) = t.d10
      where nullif(btrim(cr.name),'') is not null
    union all
    select 3, 'closers_contact', co.id::text, co.name from t join public.closers_contacts co
      on length(t.d10) = 10
     and right(regexp_replace(coalesce(co.country_code,'') || coalesce(co.phone,''),'\D','','g'),10) = t.d10
      where nullif(btrim(co.name),'') is not null
    union all
    select 4, 'pipeline_phone', cc.id::text,
           coalesce(nullif(btrim(co.name),''), nullif(btrim(mo.display_name),''), cc.instagram_handle)
      from t join public.closer_creators cc
        on length(t.d10) = 10 and right(regexp_replace(coalesce(cc.phone,''),'\D','','g'),10) = t.d10
      left join public.closers_contacts co on co.id = cc.source_contact_id
      left join public.models mo on mo.id = cc.model_id
      where coalesce(nullif(btrim(co.name),''), nullif(btrim(mo.display_name),''), cc.instagram_handle) is not null
    union all
    select 5, 'scouter_lead', sl.id::text, sl.name from t join public.scouter_leads sl
      on length(t.d10) = 10 and right(regexp_replace(coalesce(sl.phone,''),'\D','','g'),10) = t.d10
      where nullif(btrim(sl.name),'') is not null
    union all
    select 6, 'staff', p.id::text, p.full_name from t join public.profiles p
      on length(t.d10) = 10 and right(regexp_replace(coalesce(p.phone_e164,''),'\D','','g'),10) = t.d10
      where nullif(btrim(p.full_name),'') is not null
  )
  select name, source, entity_id from cand order by pri limit 1;
$$;


ALTER FUNCTION "public"."resolve_wa_name"("p_closer_creator_id" "uuid", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_pending_qa_report_emails"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_url   text;
  v_token text;
  v_call  record;
  v_count int := 0;
begin
  select decrypted_secret into v_token from vault.decrypted_secrets where name = 'cron_internal_token' limit 1;
  if v_token is null then
    raise warning 'retry_pending_qa_report_emails: falta cron_internal_token en Vault';
    return;
  end if;
  v_url := 'https://lsagslbkliprespbyhts.supabase.co/functions/v1/qa-analyze';

  for v_call in
    select id
    from public.qa_calls
    where report_email_sent_at is null
      and claude_analysis <> '{}'::jsonb
      and claude_score > 0
      and created_at < now() - interval '5 minutes'
      and created_at > now() - interval '24 hours'
    order by created_at asc
    limit 10
  loop
    perform net.http_post(
      url     := v_url,
      headers := jsonb_build_object('Content-Type', 'application/json', 'X-Cron-Token', v_token),
      body    := jsonb_build_object('call_id', v_call.id, 'email_only', true),
      timeout_milliseconds := 60000
    );
    v_count := v_count + 1;
  end loop;

  if v_count > 0 then
    raise notice 'retry_pending_qa_report_emails: % correos de QA reencolados', v_count;
  end if;
end;
$$;


ALTER FUNCTION "public"."retry_pending_qa_report_emails"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."retry_pending_qa_report_emails"() IS 'Cada 10 min: QAs ya analizadas cuyo correo de reporte nunca salió (report_email_sent_at IS NULL) → invoca qa-analyze con email_only=true (manda el correo sin re-llamar a Claude). Cubre el caso "el closer cerró la pestaña y el worker se canceló antes del envío". Cap 10 por corrida.';



CREATE OR REPLACE FUNCTION "public"."retry_stuck_qa_analyses"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_call RECORD;
  v_count integer := 0;
  v_url text;
  v_token text;
BEGIN
  -- Vault lookups una sola vez por ejecución.
  SELECT decrypted_secret INTO v_url
  FROM vault.decrypted_secrets WHERE name = 'project_url';
  SELECT decrypted_secret INTO v_token
  FROM vault.decrypted_secrets WHERE name = 'cron_internal_token';

  IF v_url IS NULL OR v_token IS NULL THEN
    RAISE WARNING 'retry_stuck_qa_analyses: faltan secrets project_url o cron_internal_token en vault';
    RETURN 0;
  END IF;

  FOR v_call IN
    SELECT id
    FROM public.qa_calls
    WHERE claude_analysis = '{}'::jsonb
      AND transcript IS NOT NULL
      AND length(transcript) > 100
      AND created_at < now() - interval '10 minutes'
      AND created_at > now() - interval '24 hours'
    ORDER BY created_at DESC
    LIMIT 10  -- Cap para no abusar de la edge function si hay backlog
  LOOP
    PERFORM net.http_post(
      url := v_url || '/functions/v1/qa-analyze',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-token', v_token
      ),
      body := jsonb_build_object('call_id', v_call.id)
    );
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."retry_stuck_qa_analyses"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."retry_stuck_qa_analyses"() IS 'Cada 10 min busca qa_calls con claude_analysis vacío + transcript presente, y dispara la edge function qa-analyze para retry. Cap de 10 por corrida para no saturar. Skip rows muy viejas (>24h) que probablemente son problemáticas.';



