CREATE OR REPLACE FUNCTION "public"."salud_sistema"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r jsonb;
begin
  if not public.es_dueno((select auth.uid())) then
    raise exception 'solo admin/dueño';
  end if;
  select jsonb_build_object(
    'nas', (select jsonb_build_object('caido', caido, 'desde', desde, 'pendientes', pendientes, 'actualizado', actualizado)
            from drive_nas_salud where id = 1),
    'cron_tardanzas', (select jsonb_build_object(
      'activo', (exists (select 1 from cron.job where jobname = 'detectar-tardanzas' and active)),
      'ultima_corrida', (select max(end_time) from cron.job_run_details jrd
                        join cron.job j on j.jobid = jrd.jobid
                        where j.jobname = 'detectar-tardanzas'),
      'ultimo_status', (select status from cron.job_run_details jrd
                        join cron.job j on j.jobid = jrd.jobid
                        where j.jobname = 'detectar-tardanzas'
                        order by end_time desc nulls last limit 1)
    )),
    'cron_nas', (select jsonb_build_object(
      'activo', (exists (select 1 from cron.job where jobname = 'drive-aporte-nas' and active)),
      'ultima_corrida', (select max(end_time) from cron.job_run_details jrd
                        join cron.job j on j.jobid = jrd.jobid
                        where j.jobname = 'drive-aporte-nas')
    )),
    'tardanzas_hoy', (select jsonb_build_object(
      'total', (select count(*) from tardanzas_registro where dia = (now() at time zone 'America/Bogota')::date),
      'con_correo', (select count(*) from tardanzas_registro where dia = (now() at time zone 'America/Bogota')::date and correo_enviado),
      'ultimo_correo', (select max(correo_enviado_at) from tardanzas_registro where correo_enviado)
    )),
    'argos_ia', (select jsonb_build_object(
      'ultima_captura_juzgada', (select max(created_at) from monitor_capturas where veredicto is not null),
      'juzgadas_hoy', (select count(*) from monitor_capturas
                       where veredicto is not null
                         and created_at >= date_trunc('day', now() at time zone 'America/Bogota') at time zone 'America/Bogota')
    )),
    'drive_full_count', (select count(*) from drive_acceso_extra)
  ) into r;
  return r;
end;
$$;


