CREATE OR REPLACE FUNCTION "public"."scouter_autopilot_state"() RETURNS TABLE("active" boolean, "paused_reason" "text", "paused_at" timestamp with time zone, "last_tick_at" timestamp with time zone, "companies_filter" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant uuid := current_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN; END IF;

  INSERT INTO scouter_autopilot (tenant_id, active)
  VALUES (v_tenant, true)
  ON CONFLICT (tenant_id) DO NOTHING;

  RETURN QUERY
  SELECT sa.active, sa.paused_reason, sa.paused_at, sa.last_tick_at, sa.companies_filter
  FROM scouter_autopilot sa
  WHERE sa.tenant_id = v_tenant;
END;
$$;


