CREATE OR REPLACE FUNCTION "public"."scouter_enqueue_autopilot_batch"("p_tenant_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count       int := 0;
  v_company     record;
  v_seeds       text[];
  v_hashtags    text[];
  v_high_fit_seeds text[];
  v_mined_tags  text[];
  v_tag         text;
  v_paused      text;
  v_filter      uuid[];
  v_today_runs  int;
  v_cap         int := 870;
BEGIN
  SELECT paused_reason, companies_filter
  INTO v_paused, v_filter
  FROM scouter_autopilot
  WHERE tenant_id = p_tenant_id;
  IF v_paused = 'budget' THEN RETURN 0; END IF;

  SELECT runs_count INTO v_today_runs
  FROM scouter_apify_budget
  WHERE day = CURRENT_DATE AND tenant_id = p_tenant_id;
  IF COALESCE(v_today_runs, 0) >= v_cap THEN
    UPDATE scouter_autopilot
    SET paused_reason = 'budget', paused_at = NOW(), updated_at = NOW()
    WHERE tenant_id = p_tenant_id;
    RETURN 0;
  END IF;

  FOR v_company IN
    SELECT id, name, search_config
    FROM scouter_companies
    WHERE tenant_id = p_tenant_id
      AND active = true
      AND (v_filter IS NULL OR id = ANY(v_filter))
  LOOP
    SELECT array_agg(DISTINCT lower(regexp_replace(trim(value), '^[@#]+', '')))
    INTO v_seeds
    FROM jsonb_array_elements_text(
      COALESCE(v_company.search_config->'seed_accounts', '[]'::jsonb)
    ) AS t(value)
    WHERE trim(value) <> '';

    SELECT array_agg(DISTINCT lower(regexp_replace(trim(value), '^[@#]+', '')))
    INTO v_hashtags
    FROM jsonb_array_elements_text(
      COALESCE(v_company.search_config->'hashtags', '[]'::jsonb)
    ) AS t(value)
    WHERE trim(value) <> '';

    SELECT array_agg(DISTINCT lower(instagram_handle))
    INTO v_high_fit_seeds
    FROM (
      SELECT instagram_handle
      FROM scouter_leads
      WHERE tenant_id = p_tenant_id
        AND company_id = v_company.id
        AND ai_status = 'high_fit'
        AND COALESCE(ai_score, 0) >= 7
      ORDER BY updated_at ASC
      LIMIT 20
    ) sub;

    SELECT array_agg(DISTINCT tag_lower)
    INTO v_mined_tags
    FROM (
      SELECT lower(substring(match[1] FROM 2)) AS tag_lower
      FROM scouter_leads
      CROSS JOIN LATERAL regexp_matches(
        COALESCE(bio, '') || ' ' || COALESCE(name, ''),
        '(#[A-Za-z0-9_]{3,30})',
        'g'
      ) AS match
      WHERE tenant_id = p_tenant_id
        AND company_id = v_company.id
        AND ai_status = 'high_fit'
        AND COALESCE(ai_score, 0) >= 7
    ) mined
    WHERE NOT (v_hashtags @> ARRAY[tag_lower])
    LIMIT 10;

    v_seeds := COALESCE(v_seeds, ARRAY[]::text[]) ||
               COALESCE(v_high_fit_seeds, ARRAY[]::text[]);
    SELECT array_agg(DISTINCT s) INTO v_seeds FROM unnest(v_seeds) s;

    v_hashtags := COALESCE(v_hashtags, ARRAY[]::text[]) ||
                  COALESCE(v_mined_tags, ARRAY[]::text[]);
    SELECT array_agg(DISTINCT s) INTO v_hashtags FROM unnest(v_hashtags) s;

    IF v_seeds IS NOT NULL AND array_length(v_seeds, 1) > 0 THEN
      INSERT INTO scouter_jobs (kind, status, tenant_id, company_id, payload, priority)
      VALUES (
        'discover_seed', 'queued', p_tenant_id, v_company.id,
        jsonb_build_object('seeds', to_jsonb(v_seeds), 'maxLeads', array_length(v_seeds, 1)),
        7
      );
      v_count := v_count + 1;
    END IF;

    IF v_hashtags IS NOT NULL THEN
      FOREACH v_tag IN ARRAY v_hashtags LOOP
        INSERT INTO scouter_jobs (kind, status, tenant_id, company_id, payload, priority)
        VALUES (
          'discover_hashtag', 'queued', p_tenant_id, v_company.id,
          jsonb_build_object('hashtag', v_tag, 'maxLeads', 30),
          7
        );
        v_count := v_count + 1;
      END LOOP;
    END IF;
  END LOOP;

  UPDATE scouter_autopilot
  SET last_tick_at = NOW(),
      updated_at = NOW(),
      paused_reason = CASE
        WHEN v_count > 0 AND paused_reason IS DISTINCT FROM 'budget' THEN NULL
        ELSE paused_reason
      END
  WHERE tenant_id = p_tenant_id;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."scouter_enqueue_autopilot_batch"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."scouter_enqueue_autopilot_batch"("p_tenant_id" "uuid") IS 'Encola batch de discovery para todas las compañías activas del tenant. Combina seeds/hashtags de Settings + AUTO-FEED: top-20 handles high_fit como seeds (refresh natural) + hasta 10 hashtags minados de las bios de high_fit que aún no están en Settings.';



CREATE OR REPLACE FUNCTION "public"."scouter_rank_leads_for_spammer"("p_tenant_id" "uuid", "p_spammer_id" "uuid", "p_cooldown_days" integer DEFAULT 3, "p_batch_size" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "instagram_handle" "text", "ai_score" numeric, "followers" integer, "bio" "text", "country" "text", "status" "text", "interaction_count" bigint, "days_since_assigned" integer, "rank_score" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH lead_scores AS (
    SELECT
      l.id,
      l.instagram_handle,
      l.ai_score::numeric AS ai_score,
      l.followers,
      l.bio,
      l.country,
      l.status::text AS status,
      COUNT(DISTINCT ih.id)::bigint AS interaction_count,
      COALESCE((CURRENT_DATE - MAX(da.assigned_date)::date)::int, 999) AS days_since_assigned,
      (
        COALESCE(l.ai_score, 0) * 10
        + LEAST(COALESCE((CURRENT_DATE - MAX(da.assigned_date)::date)::int, 30), 30)
        - COUNT(DISTINCT ih.id) * 2
        + CASE l.status::text
            WHEN 'candidate'  THEN 15
            WHEN 'discovery'  THEN 10
            WHEN 'contacting' THEN 5
            ELSE 0
          END
      )::numeric AS rank_score
    FROM public.scouter_leads l
    LEFT JOIN public.scouter_daily_assignments da ON da.lead_id = l.id
    LEFT JOIN public.scouter_interaction_history ih ON ih.lead_id = l.id
    WHERE l.tenant_id = p_tenant_id
      AND l.ai_status::text IN ('high_fit', 'medium_fit', 'approved')
      AND l.status::text NOT IN ('active', 'rejected', 'discarded')
    GROUP BY l.id
    HAVING COALESCE((CURRENT_DATE - MAX(da.assigned_date)::date)::int, 999) >= p_cooldown_days
  ),
  cross_blocked AS (
    SELECT DISTINCT da.lead_id
    FROM public.scouter_daily_assignments da
    WHERE da.tenant_id = p_tenant_id
      AND da.assigned_date >= CURRENT_DATE - p_cooldown_days
  )
  SELECT ls.*
  FROM lead_scores ls
  WHERE ls.id NOT IN (SELECT lead_id FROM cross_blocked)
  ORDER BY ls.rank_score DESC
  LIMIT p_batch_size;
END;
$$;


ALTER FUNCTION "public"."scouter_rank_leads_for_spammer"("p_tenant_id" "uuid", "p_spammer_id" "uuid", "p_cooldown_days" integer, "p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scouter_route_lead"("p_lead_id" "uuid") RETURNS TABLE("company_id" "uuid", "company_slug" "text", "score" numeric, "method" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant     uuid;
  v_emb        vector(768);
  v_bio        text;
  v_name       text;
  v_followers  int;
  v_country    text;
BEGIN
  SELECT tenant_id, embedding, bio, name, followers, country
  INTO v_tenant, v_emb, v_bio, v_name, v_followers, v_country
  FROM scouter_leads
  WHERE id = p_lead_id;

  IF v_tenant IS NULL THEN RETURN; END IF;

  RETURN QUERY
  WITH companies AS (
    SELECT
      c.id,
      c.slug,
      c.search_config
    FROM scouter_companies c
    WHERE c.tenant_id = v_tenant AND c.active = true
  ),
  -- Hard filters: descartamos compañías que tienen restricción
  -- explícita y el lead no cumple.
  filtered AS (
    SELECT *
    FROM companies c
    WHERE
      -- followers_max
      (COALESCE((c.search_config->>'followers_max')::int, 999999999) >= COALESCE(v_followers, 0))
      -- followers_min
      AND (COALESCE((c.search_config->>'followers_min')::int, 0) <= COALESCE(v_followers, 999999999))
      -- target_countries: si está seteado y el lead tiene país conocido,
      -- debe estar en la lista. Si lead.country es null, pasa (permisivo,
      -- mismo approach que discovery).
      AND (
        c.search_config->'target_countries' IS NULL
        OR jsonb_array_length(c.search_config->'target_countries') = 0
        OR v_country IS NULL
        OR (c.search_config->'target_countries') @> to_jsonb(v_country)
      )
  ),
  -- Embedding-based similarity: mejor seed de la compañía vs el lead.
  -- Si la compañía no tiene seeds con embedding, similarity_emb = NULL.
  emb_scores AS (
    SELECT
      f.id AS company_id,
      f.slug AS company_slug,
      MAX(1 - (s.embedding <=> v_emb))::numeric AS sim
    FROM filtered f
    LEFT JOIN scouter_leads s
      ON s.company_id = f.id
      AND s.embedding IS NOT NULL
      AND (s.discovery_source LIKE 'seed:%' OR s.manual_company_assignment = true)
      AND s.id <> p_lead_id
    WHERE v_emb IS NOT NULL
    GROUP BY f.id, f.slug
  ),
  -- Heurística keywords: count(bio_keywords matched) - count(exclude_keywords matched).
  -- Normaliza a 0..1 dividiendo por # de keywords totales de la compañía.
  -- Se aplica como fallback cuando NO hay embedding o la compañía no tiene seeds.
  kw_scores AS (
    SELECT
      f.id AS company_id,
      f.slug AS company_slug,
      (
        -- Matches positivos
        (
          SELECT COUNT(*)::numeric
          FROM jsonb_array_elements_text(
            COALESCE(f.search_config->'bio_keywords', '[]'::jsonb)
          ) AS kw
          WHERE COALESCE(v_bio, '') || ' ' || COALESCE(v_name, '') ILIKE '%' || kw || '%'
        )
        -
        -- Penalizar excludes (cada match resta 2 — más punitivo)
        2 * (
          SELECT COUNT(*)::numeric
          FROM jsonb_array_elements_text(
            COALESCE(f.search_config->'exclude_keywords', '[]'::jsonb)
          ) AS kw
          WHERE COALESCE(v_bio, '') || ' ' || COALESCE(v_name, '') ILIKE '%' || kw || '%'
        )
      ) /
      GREATEST(
        jsonb_array_length(COALESCE(f.search_config->'bio_keywords', '[]'::jsonb)) +
        jsonb_array_length(COALESCE(f.search_config->'exclude_keywords', '[]'::jsonb)),
        1
      ) AS sim
    FROM filtered f
  ),
  -- Mergeo: si hay similarity por embedding (y > 0), usamos esa.
  -- Si no, usamos keyword. Marcamos el método para debugging.
  combined AS (
    SELECT
      f.id AS company_id,
      f.slug AS company_slug,
      CASE
        WHEN e.sim IS NOT NULL AND e.sim > 0 THEN e.sim
        ELSE GREATEST(k.sim, 0)
      END AS score,
      CASE
        WHEN e.sim IS NOT NULL AND e.sim > 0 THEN 'embedding'
        ELSE 'keywords'
      END AS method
    FROM filtered f
    LEFT JOIN emb_scores e ON e.company_id = f.id
    LEFT JOIN kw_scores k ON k.company_id = f.id
  )
  SELECT c.company_id, c.company_slug, c.score::numeric(4, 3), c.method
  FROM combined c
  ORDER BY c.score DESC NULLS LAST, c.company_slug;
END;
$$;


ALTER FUNCTION "public"."scouter_route_lead"("p_lead_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."scouter_route_lead"("p_lead_id" "uuid") IS 'Rankea compañías activas del tenant por fit con el lead. Hard filters: target_countries, followers_min/max. Score: embedding cosine vs seeds (si hay) o heurística bio_keywords - exclude_keywords (fallback). El worker usa la primera fila como company_id y entradas con score>=0.55 como target_companies.';



CREATE OR REPLACE FUNCTION "public"."scouter_top_seed_match"("p_lead_id" "uuid") RETURNS TABLE("seed_handle" "text", "similarity" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_company uuid;
  v_emb vector(768);
BEGIN
  SELECT company_id, embedding INTO v_company, v_emb
  FROM public.scouter_leads
  WHERE id = p_lead_id;
  IF v_company IS NULL OR v_emb IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    s.instagram_handle AS seed_handle,
    (1 - (s.embedding <=> v_emb))::numeric(4, 3) AS similarity
  FROM public.scouter_leads s
  WHERE s.company_id = v_company
    AND (s.discovery_source LIKE 'seed:%' OR s.manual_company_assignment = true)
    AND s.embedding IS NOT NULL
    AND s.id <> p_lead_id
  ORDER BY s.embedding <=> v_emb
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."scouter_top_seed_match"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_creators_fuzzy"("p_q" "text") RETURNS TABLE("id" "uuid", "instagram_handle" "text", "artistic_name" "text", "name" "text", "status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with n as (
    select lower(translate(replace(coalesce(p_q,''),' ',''),'áéíóúüñÁÉÍÓÚÜÑ','aeiouunAEIOUUN')) as q
  )
  select c.id, c.instagram_handle, c.artistic_name, c.name, c.status
  from creators c, n
  where length(n.q) >= 4 and (
    lower(translate(replace(coalesce(c.instagram_handle,''),' ',''),'áéíóúüñÁÉÍÓÚÜÑ','aeiouunAEIOUUN')) like '%'||n.q||'%'
    or lower(translate(replace(coalesce(c.artistic_name,''),' ',''),'áéíóúüñÁÉÍÓÚÜÑ','aeiouunAEIOUUN')) like '%'||n.q||'%'
    or lower(translate(replace(coalesce(c.name,''),' ',''),'áéíóúüñÁÉÍÓÚÜÑ','aeiouunAEIOUUN')) like '%'||n.q||'%'
  )
  order by (c.status = 'active') desc, c.artistic_name nulls last
  limit 8;
$$;


ALTER FUNCTION "public"."search_creators_fuzzy"("p_q" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_models"("p_query" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_has_phone" boolean DEFAULT NULL::boolean, "p_has_onlyfans" boolean DEFAULT NULL::boolean, "p_is_verified" boolean DEFAULT NULL::boolean, "p_min_followers" integer DEFAULT NULL::integer, "p_max_followers" integer DEFAULT NULL::integer, "p_signed" boolean DEFAULT NULL::boolean, "p_in_leadgen" boolean DEFAULT NULL::boolean, "p_in_scouter" boolean DEFAULT NULL::boolean, "p_in_closers" boolean DEFAULT NULL::boolean, "p_order_by" "text" DEFAULT 'followers'::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "instagram_handle" "text", "display_name" "text", "avatar_url" "text", "bio" "text", "country" "text", "city" "text", "state" "text", "is_verified" boolean, "onlyfans_url" "text", "tiktok_handle" "text", "twitter_handle" "text", "followers_count" integer, "primary_phone" "text", "total_phones" integer, "is_in_leadgen" boolean, "is_in_scouter" boolean, "is_in_closers_contacts" boolean, "is_in_closer_creators" boolean, "is_signed" boolean, "last_scraped_at" timestamp with time zone, "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone_norm text := regexp_replace(coalesce(p_phone, ''), '[^0-9+]', '', 'g');
BEGIN
  RETURN QUERY
  WITH filtered AS (
    SELECT
      m.id, m.instagram_handle, m.display_name, m.avatar_url, m.bio,
      m.country, m.city, m.state, m.is_verified, m.onlyfans_url,
      m.tiktok_handle, m.twitter_handle, m.followers_count,
      m.last_scraped_at, m.created_at,
      (SELECT phone_e164 FROM model_phones
        WHERE model_id = m.id AND is_primary LIMIT 1) AS primary_phone,
      (SELECT count(*)::int FROM model_phones
        WHERE model_id = m.id) AS total_phones,
      EXISTS (SELECT 1 FROM leadgen_entries WHERE model_id = m.id) AS in_leadgen,
      EXISTS (SELECT 1 FROM scouter_leads WHERE model_id = m.id) AS in_scouter,
      EXISTS (SELECT 1 FROM closers_contacts WHERE model_id = m.id) AS in_cc,
      EXISTS (SELECT 1 FROM closer_creators WHERE model_id = m.id) AS in_ccr,
      EXISTS (SELECT 1 FROM creators WHERE model_id = m.id) AS in_creators
    FROM models m
    WHERE
      (p_query IS NULL OR
        m.instagram_handle ILIKE '%' || p_query || '%' OR
        m.display_name     ILIKE '%' || p_query || '%')
      AND (p_country  IS NULL OR m.country = p_country)
      AND (p_city     IS NULL OR m.city ILIKE '%' || p_city || '%')
      AND (p_has_onlyfans IS NULL OR (p_has_onlyfans = (m.onlyfans_url IS NOT NULL)))
      AND (p_is_verified IS NULL OR m.is_verified = p_is_verified)
      AND (p_min_followers IS NULL OR coalesce(m.followers_count, 0) >= p_min_followers)
      AND (p_max_followers IS NULL OR coalesce(m.followers_count, 0) <= p_max_followers)
  ),
  with_phone_filter AS (
    SELECT * FROM filtered f
    WHERE
      (p_has_phone IS NULL OR (p_has_phone = (f.primary_phone IS NOT NULL)))
      AND (v_phone_norm = '' OR EXISTS (
        SELECT 1 FROM model_phones mp
         WHERE mp.model_id = f.id
           AND mp.phone_e164 LIKE '%' || v_phone_norm || '%'
      ))
  ),
  with_table_filter AS (
    SELECT * FROM with_phone_filter f
    WHERE
      (p_signed     IS NULL OR p_signed     = f.in_creators)
      AND (p_in_leadgen IS NULL OR p_in_leadgen = f.in_leadgen)
      AND (p_in_scouter IS NULL OR p_in_scouter = f.in_scouter)
      AND (p_in_closers IS NULL OR p_in_closers = (f.in_cc OR f.in_ccr))
  ),
  total AS (SELECT count(*)::bigint AS n FROM with_table_filter)
  SELECT
    f.id, f.instagram_handle, f.display_name, f.avatar_url, f.bio,
    f.country, f.city, f.state, f.is_verified, f.onlyfans_url,
    f.tiktok_handle, f.twitter_handle, f.followers_count,
    f.primary_phone, f.total_phones,
    f.in_leadgen, f.in_scouter, f.in_cc, f.in_ccr, f.in_creators,
    f.last_scraped_at, f.created_at,
    total.n
  FROM with_table_filter f, total
  ORDER BY
    CASE WHEN p_order_by = 'followers' THEN f.followers_count END DESC NULLS LAST,
    CASE WHEN p_order_by = 'recent'    THEN f.created_at END DESC NULLS LAST,
    CASE WHEN p_order_by = 'name'      THEN lower(coalesce(f.display_name, f.instagram_handle)) END ASC NULLS LAST,
    f.id
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."search_models"("p_query" "text", "p_country" "text", "p_city" "text", "p_phone" "text", "p_has_phone" boolean, "p_has_onlyfans" boolean, "p_is_verified" boolean, "p_min_followers" integer, "p_max_followers" integer, "p_signed" boolean, "p_in_leadgen" boolean, "p_in_scouter" boolean, "p_in_closers" boolean, "p_order_by" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sembrar_cowork_de_agencia"("_agencia" "uuid", "_desde" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  n integer;
begin
  insert into public.cowork_break_limits (tenant_id, kind, label, minutos)
  select _agencia, l.kind, l.label, l.minutos
  from public.cowork_break_limits l
  where l.tenant_id = _desde
  on conflict (tenant_id, kind) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "public"."sembrar_cowork_de_agencia"("_agencia" "uuid", "_desde" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sembrar_cowork_de_agencia"("_agencia" "uuid", "_desde" "uuid") IS 'Copia los topes de pausa de la agencia _desde a la agencia _agencia (los que ya tenga no se tocan). Devuelve cuántos copió. Solo service_role (panel de plataforma).';



CREATE OR REPLACE FUNCTION "public"."sembrar_roles_de_agencia"("_agencia" "uuid", "_plan" "text", "_desde" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  nombres text[];
  n text;
  origen public.roles_config;
  nuevo_id uuid;
  creados int := 0;
begin
  if _plan = 'enterprise' then
    nombres := array['admin', 'supervisor', 'employee'];
  elsif _plan = 'agency' then
    nombres := array['admin', 'supervisor', 'employee', 'Chatter', 'Chatter Supervisor', 'closer'];
  else
    raise exception 'sembrar_roles_de_agencia: plan desconocido «%» (enterprise o agency)', _plan;
  end if;
  if _agencia is null or _desde is null or _agencia = _desde then
    raise exception 'sembrar_roles_de_agencia: hacen falta una agencia de destino y otra de origen, distintas';
  end if;
  if not exists (select 1 from public.tenants where id = _agencia) then
    raise exception 'sembrar_roles_de_agencia: la agencia % no existe', _agencia;
  end if;

  foreach n in array nombres loop
    select * into origen from public.roles_config where tenant_id = _desde and name = n;
    if not found then
      raise exception 'sembrar_roles_de_agencia: la agencia de origen no tiene el rol «%»', n;
    end if;

    nuevo_id := null;
    insert into public.roles_config (tenant_id, name, description, is_active, is_system, ai_daily_quota, level)
    values (_agencia, origen.name, origen.description, true, origen.is_system, origen.ai_daily_quota, origen.level)
    on conflict (tenant_id, name) do nothing
    returning id into nuevo_id;
    continue when nuevo_id is null;  -- ya lo tenía: no se pisa

    -- El tipo de acceso (el trigger de alta creó la fila como «empleado»).
    update public.role_groups g
       set is_admin = o.is_admin, is_manager_or_above = o.is_manager_or_above,
           is_supervisor_or_above = o.is_supervisor_or_above, is_member = o.is_member,
           description = o.description
      from public.role_groups o
     where g.tenant_id = _agencia and g.role_name = n and o.tenant_id = _desde and o.role_name = n;
    -- El nivel fino dentro de la franja: el trigger de role_groups lo devolvió a la base del tipo.
    update public.roles_config set level = origen.level where id = nuevo_id;

    insert into public.role_permissions (role_id, module, submodule, can_access, data_scope)
    select nuevo_id, rp.module, rp.submodule, rp.can_access, rp.data_scope
    from public.role_permissions rp where rp.role_id = origen.id;

    insert into public.role_base_grants (tenant_id, role_name, base_role, note)
    select _agencia, g.role_name, g.base_role, g.note
    from public.role_base_grants g where g.tenant_id = _desde and g.role_name = n
    on conflict do nothing;

    creados := creados + 1;
  end loop;
  return creados;
end $$;


ALTER FUNCTION "public"."sembrar_roles_de_agencia"("_agencia" "uuid", "_plan" "text", "_desde" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sembrar_roles_de_agencia"("_agencia" "uuid", "_plan" "text", "_desde" "uuid") IS 'Crea en una agencia nueva los roles de la plantilla de su plan (enterprise o agency), copiados de la agencia de origen. Solo service_role.';



CREATE OR REPLACE FUNCTION "public"."send_karma"("target" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_caller uuid := auth.uid();
begin
  if v_caller is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;
  if v_caller = target then
    return jsonb_build_object('ok', false, 'error', 'cannot_karma_self');
  end if;
  if not exists (select 1 from user_roles where user_id = v_caller) then
    return jsonb_build_object('ok', false, 'error', 'not_eligible');
  end if;
  -- A alguien de otra agencia no se le manda karma (20261001212100).
  if target not in (select public.gente_de_mi_agencia()) then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  insert into karma_sends (giver_id, recipient_id)
  values (v_caller, target)
  on conflict (giver_id, recipient_id) do nothing;
  return public.get_karma_profile(target);
end;
$$;


ALTER FUNCTION "public"."send_karma"("target" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_whatsapp_verification_on_phone_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce(old.phone_e164, '') = coalesce(new.phone_e164, '') then
    return new;
  end if;
  if old.whatsapp_verified_at is not null then
    new.whatsapp_verified_at := null;
    new.whatsapp_push_name := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."send_whatsapp_verification_on_phone_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_creator_kash_type_by_blu"("p_blu_names" "text"[], "p_kash_type" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_n int;
begin
  if not (public.blu_is_management(auth.uid())
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role') then
    raise exception 'forbidden: solo management o el micro (service_role)' using errcode='42501';
  end if;
  if p_kash_type not in ('Massive','Plus') then
    raise exception 'kash_type inválido: %', p_kash_type;
  end if;
  if p_blu_names is null or array_length(p_blu_names,1) is null then return 0; end if;

  with ids as (
    select distinct
      case when bm.status = 'ignored' then null
           else coalesce(bm.creator_id, public.blu_match_creator(x.n)) end as creator_id
    from unnest(p_blu_names) as x(n)
    left join public.blu_creator_map bm on lower(bm.blu_name) = lower(x.n)
  ),
  upd as (
    insert into public.creator_business (creator_id, kash_type)
    select creator_id, p_kash_type from ids where creator_id is not null
    on conflict (creator_id) do update set kash_type = excluded.kash_type
    returning 1
  )
  select count(*) into v_n from upd;
  return v_n;
end; $$;


ALTER FUNCTION "public"."set_creator_kash_type_by_blu"("p_blu_names" "text"[], "p_kash_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_creator_whatsapp"("p_creator_id" "uuid", "p_whatsapp" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'No autenticado' using errcode = '42501';
  end if;
  if not exists (select 1 from public.user_roles where user_id = auth.uid()) then
    raise exception 'Sin permiso' using errcode = '42501';
  end if;
  update public.creators
     set whatsapp_number = nullif(btrim(p_whatsapp), '')
   where id = p_creator_id and tenant_id = public.current_tenant_id();
end;
$$;


ALTER FUNCTION "public"."set_creator_whatsapp"("p_creator_id" "uuid", "p_whatsapp" "text") OWNER TO "postgres";


