CREATE OR REPLACE FUNCTION "public"."sql_salud_cron_hace"("_jobname" "text") RETURNS TABLE("hace_min" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'cron'
    AS $$
  select extract(epoch from (now() - max(r.end_time))) / 60.0 as hace_min
  from cron.job_run_details r
  join cron.job j on j.jobid = r.jobid
  where j.jobname = _jobname and r.status = 'succeeded';
$$;


