CREATE OR REPLACE FUNCTION "public"."start_prospect_onboarding"("p_prospect_id" "uuid", "p_agency" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  p     public.creator_prospects%rowtype;
  v_company_id uuid;
begin
  if v_uid is null then raise exception 'forbidden' using errcode='42501'; end if;
  select * into p from public.creator_prospects where id = p_prospect_id;
  if not found then raise exception 'prospect_not_found'; end if;

  -- 1) crear creadora (mismo id que el prospecto, como hace el front)
  insert into public.creators (
    id, name, email, phone, country, instagram_handle, tiktok_handle, category, status, created_at, created_by
  ) values (
    p.id, p.name, p.email, p.phone, p.country, p.instagram, p.tiktok, p.category, 'borrador', p.created_at, v_uid
  );

  -- 2) creator_business (lookup company por nombre, case-insensitive)
  select id into v_company_id from public.scouter_companies where name ilike p_agency limit 1;
  insert into public.creator_business (creator_id, assigned_agency, company_id)
  values (p.id, p_agency, v_company_id);

  -- 3) marcar prospecto convertido
  update public.creator_prospects set status = 'convertido' where id = p.id;

  return p.id;
end;
$$;


ALTER FUNCTION "public"."start_prospect_onboarding"("p_prospect_id" "uuid", "p_agency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_closers_contact_to_creators"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_kind text := coalesce(NEW.contact_kind, 'modelo');
BEGIN
  IF NEW.phone IS NULL OR trim(NEW.phone) = '' THEN
    RETURN NEW;
  END IF;

  -- LAS AGENCIAS NO ENTRAN AL EMBUDO DE MODELOS. Su tab las lee del DIRECTORIO;
  -- su fila de pipeline nace recién cuando un closer la toma. Crearla acá metía
  -- 464 empresas al pool de "Nuevas" y las duplicaba en su propio tab.
  IF v_kind = 'agencia' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.creators
    WHERE lower(trim(both '@' from instagram_handle)) = lower(trim(both '@' from NEW.handle))
  ) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.closer_creators WHERE source_contact_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.closer_creators (
    instagram_handle, source_account, category, phone, notes,
    stage, estimated_monetization, agency_commission, created_by, source_contact_id,
    lead_source
  ) VALUES (
    NEW.handle, NEW.company, NEW.physical_appearance, NEW.phone, NEW.notes,
    'Nuevo', 0, 0, NEW.created_by, NEW.id,
    CASE WHEN v_kind = 'ex_creadora' THEN 'ex_creadora' ELSE 'maven' END
  );
  RETURN NEW;
EXCEPTION WHEN unique_violation THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_closers_contact_to_creators"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_closers_contact_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.closer_creators
  SET instagram_handle = NEW.handle, source_account = NEW.company,
      category = NEW.physical_appearance, phone = NEW.phone, notes = NEW.notes
  WHERE source_contact_id = NEW.id AND stage = 'Nuevo';
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_closers_contact_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_contact_kind_on_creator_exit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce(new.status,'') in ('terminated','leaving','paused')
     and coalesce(new.instagram_handle,'') <> '' then
    update public.closers_contacts k
       set contact_kind = 'ex_creadora'
     where k.contact_kind = 'modelo'
       and lower(regexp_replace(coalesce(k.handle,''), '.*instagram\.com/|[@/ ]', '', 'gi'))
         = lower(regexp_replace(new.instagram_handle, '.*instagram\.com/|[@/ ]', '', 'gi'));
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."sync_contact_kind_on_creator_exit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_contact_status_from_closer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.source_contact_id IS NULL OR NEW.deal_type <> 'reclutamiento' THEN
    RETURN NEW;
  END IF;

  IF NEW.assigned_to IS NOT NULL THEN
    UPDATE public.closers_contacts
      SET status = 'converted'
      WHERE id = NEW.source_contact_id
        AND coalesce(status, '') <> 'converted';
  ELSIF NEW.stage = 'Nuevo' THEN
    UPDATE public.closers_contacts
      SET status = 'new'
      WHERE id = NEW.source_contact_id
        AND status = 'converted';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_contact_status_from_closer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_models_recent"("p_minutes" integer DEFAULT 10) RETURNS TABLE("models_inserted" integer, "models_updated" integer, "phones_inserted" integer, "links_updated" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_default_tenant uuid;
  v_cutoff timestamptz := now() - (p_minutes || ' minutes')::interval;
  v_models_before int;
  v_models_after int;
  v_phones_before int;
  v_phones_after int;
  v_links_before int;
  v_links_after int;
BEGIN
  SELECT id INTO v_default_tenant FROM public.tenants ORDER BY created_at LIMIT 1;

  SELECT count(*) INTO v_models_before FROM public.models;
  SELECT count(*) INTO v_phones_before FROM public.model_phones;
  SELECT
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.leadgen_entries) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.scouter_leads) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.closers_contacts) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.closer_creators) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.creators)
  INTO v_links_before;

  -- ─── 1. UPSERT models desde creators (prioridad alta) ───
  INSERT INTO public.models (
    tenant_id, instagram_handle, display_name, avatar_url, bio,
    country, city, onlyfans_url, tiktok_handle, twitter_handle, created_at
  )
  SELECT DISTINCT ON (lower(trim(c.instagram_handle)))
    v_default_tenant,
    lower(trim(c.instagram_handle)),
    c.name, COALESCE(c.profile_photo_url, c.piclink_url),
    c.bio, c.country, c.city, c.onlyfans_url,
    c.tiktok_handle, c.twitter_handle, c.created_at
  FROM public.creators c
  WHERE c.instagram_handle IS NOT NULL AND trim(c.instagram_handle) <> ''
    AND c.updated_at > v_cutoff
  ORDER BY lower(trim(c.instagram_handle)), c.created_at DESC
  ON CONFLICT (tenant_id, (lower(instagram_handle))) WHERE instagram_handle IS NOT NULL
  DO UPDATE SET
    display_name   = COALESCE(public.models.display_name, EXCLUDED.display_name),
    avatar_url     = COALESCE(public.models.avatar_url, EXCLUDED.avatar_url),
    bio            = COALESCE(public.models.bio, EXCLUDED.bio),
    country        = COALESCE(public.models.country, EXCLUDED.country),
    city           = COALESCE(public.models.city, EXCLUDED.city),
    onlyfans_url   = COALESCE(public.models.onlyfans_url, EXCLUDED.onlyfans_url),
    tiktok_handle  = COALESCE(public.models.tiktok_handle, EXCLUDED.tiktok_handle),
    twitter_handle = COALESCE(public.models.twitter_handle, EXCLUDED.twitter_handle);

  -- ─── 2. UPSERT models desde closer_creators ───
  INSERT INTO public.models (tenant_id, instagram_handle, city, onlyfans_url, created_at)
  SELECT DISTINCT ON (lower(trim(ccr.instagram_handle)))
    v_default_tenant,
    lower(trim(ccr.instagram_handle)),
    ccr.city, ccr.onlyfans_url, ccr.created_at
  FROM public.closer_creators ccr
  WHERE ccr.instagram_handle IS NOT NULL AND trim(ccr.instagram_handle) <> ''
    AND ccr.updated_at > v_cutoff
  ORDER BY lower(trim(ccr.instagram_handle)), ccr.created_at DESC
  ON CONFLICT (tenant_id, (lower(instagram_handle))) WHERE instagram_handle IS NOT NULL
  DO UPDATE SET
    city         = COALESCE(public.models.city, EXCLUDED.city),
    onlyfans_url = COALESCE(public.models.onlyfans_url, EXCLUDED.onlyfans_url);

  -- ─── 3. UPSERT models desde closers_contacts ───
  INSERT INTO public.models (
    tenant_id, instagram_handle, display_name, avatar_url, city, onlyfans_url, created_at
  )
  SELECT DISTINCT ON (lower(trim(cc.handle)))
    v_default_tenant,
    lower(trim(cc.handle)),
    cc.name, cc.profile_picture_url,
    cc.city, cc.onlyfans_url, cc.created_at
  FROM public.closers_contacts cc
  WHERE cc.handle IS NOT NULL AND trim(cc.handle) <> ''
    AND cc.updated_at > v_cutoff
  ORDER BY lower(trim(cc.handle)), cc.created_at DESC
  ON CONFLICT (tenant_id, (lower(instagram_handle))) WHERE instagram_handle IS NOT NULL
  DO UPDATE SET
    display_name = COALESCE(public.models.display_name, EXCLUDED.display_name),
    avatar_url   = COALESCE(public.models.avatar_url, EXCLUDED.avatar_url),
    city         = COALESCE(public.models.city, EXCLUDED.city),
    onlyfans_url = COALESCE(public.models.onlyfans_url, EXCLUDED.onlyfans_url);

  -- ─── 4. UPSERT models desde scouter_leads ───
  -- scouter_leads SÍ enriquece avatar/bio/followers — sobrescribe scraper data.
  INSERT INTO public.models (
    tenant_id, instagram_handle, display_name, avatar_url, bio,
    is_verified, country, city, onlyfans_url, followers_count, last_scraped_at, created_at
  )
  SELECT DISTINCT ON (lower(trim(sl.instagram_handle)))
    v_default_tenant,
    lower(trim(sl.instagram_handle)),
    sl.name, sl.photo_data_url, sl.bio,
    sl.verified, sl.country, sl.city, sl.onlyfans_url,
    sl.followers, sl.updated_at, sl.created_at
  FROM public.scouter_leads sl
  WHERE sl.instagram_handle IS NOT NULL AND trim(sl.instagram_handle) <> ''
    AND sl.updated_at > v_cutoff
  ORDER BY lower(trim(sl.instagram_handle)), sl.updated_at DESC
  ON CONFLICT (tenant_id, (lower(instagram_handle))) WHERE instagram_handle IS NOT NULL
  DO UPDATE SET
    display_name    = COALESCE(public.models.display_name, EXCLUDED.display_name),
    avatar_url      = COALESCE(public.models.avatar_url, EXCLUDED.avatar_url),
    bio             = COALESCE(public.models.bio, EXCLUDED.bio),
    is_verified     = COALESCE(public.models.is_verified, EXCLUDED.is_verified),
    country         = COALESCE(public.models.country, EXCLUDED.country),
    city            = COALESCE(public.models.city, EXCLUDED.city),
    onlyfans_url    = COALESCE(public.models.onlyfans_url, EXCLUDED.onlyfans_url),
    -- followers_count y last_scraped_at SÍ se actualizan con freshest data del scraper
    followers_count = EXCLUDED.followers_count,
    last_scraped_at = EXCLUDED.last_scraped_at;

  -- ─── 5. UPSERT models desde leadgen_entries ───
  INSERT INTO public.models (tenant_id, instagram_handle, city, state, onlyfans_url, created_at)
  SELECT DISTINCT ON (lower(trim(le.model_handle)))
    v_default_tenant,
    lower(trim(le.model_handle)),
    le.city, le.state, le.onlyfans_url, le.created_at
  FROM public.leadgen_entries le
  WHERE le.model_handle IS NOT NULL AND trim(le.model_handle) <> ''
    AND le.updated_at > v_cutoff
  ORDER BY lower(trim(le.model_handle)), le.created_at DESC
  ON CONFLICT (tenant_id, (lower(instagram_handle))) WHERE instagram_handle IS NOT NULL
  DO UPDATE SET
    city         = COALESCE(public.models.city, EXCLUDED.city),
    state        = COALESCE(public.models.state, EXCLUDED.state),
    onlyfans_url = COALESCE(public.models.onlyfans_url, EXCLUDED.onlyfans_url);

  -- ─── 6. UPSERT model_phones desde las 5 fuentes ───
  -- Phone-only creators dejados a un job de housekeeping separado (poco común).

  INSERT INTO public.model_phones (tenant_id, model_id, phone_e164, phone_raw, source_module, captured_by, captured_at, status)
  SELECT DISTINCT ON (m.id, regexp_replace(le.phone_e164, '[^0-9+]', '', 'g'))
    v_default_tenant, m.id,
    regexp_replace(le.phone_e164, '[^0-9+]', '', 'g'), le.phone_raw,
    'leadgen', le.lg_user_id, le.phone_first_set_at, 'active'
  FROM public.leadgen_entries le
  JOIN public.models m ON m.tenant_id = v_default_tenant
                       AND m.instagram_handle = lower(trim(le.model_handle))
  WHERE le.phone_first_set_at IS NOT NULL
    AND le.phone_e164 IS NOT NULL
    AND regexp_replace(le.phone_e164, '[^0-9+]', '', 'g') ~ '^\+?[0-9]{6,15}$'
    AND le.updated_at > v_cutoff
  ORDER BY m.id, regexp_replace(le.phone_e164, '[^0-9+]', '', 'g'), le.phone_first_set_at ASC
  ON CONFLICT (tenant_id, model_id, phone_e164) DO NOTHING;

  INSERT INTO public.model_phones (tenant_id, model_id, phone_e164, phone_raw, source_module, captured_at, status)
  SELECT DISTINCT ON (m.id, regexp_replace(sl.phone, '[^0-9+]', '', 'g'))
    v_default_tenant, m.id,
    regexp_replace(sl.phone, '[^0-9+]', '', 'g'), sl.phone,
    'scouter', sl.phone_first_set_at, 'active'
  FROM public.scouter_leads sl
  JOIN public.models m ON m.tenant_id = v_default_tenant
                       AND m.instagram_handle = lower(trim(sl.instagram_handle))
  WHERE sl.phone_first_set_at IS NOT NULL
    AND sl.phone IS NOT NULL
    AND regexp_replace(sl.phone, '[^0-9+]', '', 'g') ~ '^\+?[0-9]{6,15}$'
    AND sl.updated_at > v_cutoff
  ORDER BY m.id, regexp_replace(sl.phone, '[^0-9+]', '', 'g'), sl.phone_first_set_at ASC
  ON CONFLICT (tenant_id, model_id, phone_e164) DO NOTHING;

  INSERT INTO public.model_phones (tenant_id, model_id, phone_e164, phone_raw, source_module, captured_at, status)
  SELECT DISTINCT ON (m.id, regexp_replace(cc.phone, '[^0-9+]', '', 'g'))
    v_default_tenant, m.id,
    regexp_replace(cc.phone, '[^0-9+]', '', 'g'), cc.phone,
    'closers_contacts', cc.phone_first_set_at, 'active'
  FROM public.closers_contacts cc
  JOIN public.models m ON m.tenant_id = v_default_tenant
                       AND m.instagram_handle = lower(trim(cc.handle))
  WHERE cc.phone_first_set_at IS NOT NULL
    AND cc.phone IS NOT NULL
    AND regexp_replace(cc.phone, '[^0-9+]', '', 'g') ~ '^\+?[0-9]{6,15}$'
    AND cc.updated_at > v_cutoff
  ORDER BY m.id, regexp_replace(cc.phone, '[^0-9+]', '', 'g'), cc.phone_first_set_at ASC
  ON CONFLICT (tenant_id, model_id, phone_e164) DO NOTHING;

  INSERT INTO public.model_phones (tenant_id, model_id, phone_e164, phone_raw, source_module, captured_at, status)
  SELECT DISTINCT ON (m.id, regexp_replace(ccr.phone, '[^0-9+]', '', 'g'))
    v_default_tenant, m.id,
    regexp_replace(ccr.phone, '[^0-9+]', '', 'g'), ccr.phone,
    'closer_creators', ccr.phone_first_set_at, 'active'
  FROM public.closer_creators ccr
  JOIN public.models m ON m.tenant_id = v_default_tenant
                       AND m.instagram_handle = lower(trim(ccr.instagram_handle))
  WHERE ccr.phone_first_set_at IS NOT NULL
    AND ccr.phone IS NOT NULL
    AND regexp_replace(ccr.phone, '[^0-9+]', '', 'g') ~ '^\+?[0-9]{6,15}$'
    AND ccr.updated_at > v_cutoff
  ORDER BY m.id, regexp_replace(ccr.phone, '[^0-9+]', '', 'g'), ccr.phone_first_set_at ASC
  ON CONFLICT (tenant_id, model_id, phone_e164) DO NOTHING;

  INSERT INTO public.model_phones (tenant_id, model_id, phone_e164, phone_raw, source_module, captured_at, status)
  SELECT DISTINCT ON (m.id, p.phone_norm)
    v_default_tenant, m.id, p.phone_norm,
    COALESCE(c.phone, c.phone_e164), 'creators', c.phone_first_set_at, 'active'
  FROM public.creators c
  CROSS JOIN LATERAL (
    SELECT coalesce(regexp_replace(c.phone_e164, '[^0-9+]', '', 'g'),
                    regexp_replace(c.phone, '[^0-9+]', '', 'g')) AS phone_norm
  ) p
  JOIN public.models m ON m.tenant_id = v_default_tenant
                       AND m.instagram_handle = lower(trim(c.instagram_handle))
  WHERE c.phone_first_set_at IS NOT NULL
    AND c.instagram_handle IS NOT NULL AND trim(c.instagram_handle) <> ''
    AND p.phone_norm ~ '^\+?[0-9]{6,15}$'
    AND c.updated_at > v_cutoff
  ORDER BY m.id, p.phone_norm, c.phone_first_set_at ASC
  ON CONFLICT (tenant_id, model_id, phone_e164) DO NOTHING;

  -- ─── 7. UPDATE model_id en las 5 source tables ───

  UPDATE public.leadgen_entries le SET model_id = m.id
  FROM public.models m
  WHERE m.tenant_id = v_default_tenant
    AND m.instagram_handle = lower(trim(le.model_handle))
    AND le.model_handle IS NOT NULL AND trim(le.model_handle) <> ''
    AND le.model_id IS NULL
    AND le.updated_at > v_cutoff;

  UPDATE public.scouter_leads sl SET model_id = m.id
  FROM public.models m
  WHERE m.tenant_id = v_default_tenant
    AND m.instagram_handle = lower(trim(sl.instagram_handle))
    AND sl.instagram_handle IS NOT NULL AND trim(sl.instagram_handle) <> ''
    AND sl.model_id IS NULL
    AND sl.updated_at > v_cutoff;

  UPDATE public.closers_contacts cc SET model_id = m.id
  FROM public.models m
  WHERE m.tenant_id = v_default_tenant
    AND m.instagram_handle = lower(trim(cc.handle))
    AND cc.handle IS NOT NULL AND trim(cc.handle) <> ''
    AND cc.model_id IS NULL
    AND cc.updated_at > v_cutoff;

  UPDATE public.closer_creators ccr SET model_id = m.id
  FROM public.models m
  WHERE m.tenant_id = v_default_tenant
    AND m.instagram_handle = lower(trim(ccr.instagram_handle))
    AND ccr.instagram_handle IS NOT NULL AND trim(ccr.instagram_handle) <> ''
    AND ccr.model_id IS NULL
    AND ccr.updated_at > v_cutoff;

  UPDATE public.creators c SET model_id = m.id
  FROM public.models m
  WHERE m.tenant_id = v_default_tenant
    AND m.instagram_handle = lower(trim(c.instagram_handle))
    AND c.instagram_handle IS NOT NULL AND trim(c.instagram_handle) <> ''
    AND c.model_id IS NULL
    AND c.updated_at > v_cutoff;

  -- ─── 8. Recalcular is_primary/replaced para models con phones nuevos ───
  WITH affected AS (
    SELECT DISTINCT model_id FROM public.model_phones WHERE created_at > v_cutoff
  ),
  ranked AS (
    SELECT mp.id, mp.model_id,
           row_number() OVER (PARTITION BY mp.model_id ORDER BY mp.captured_at DESC) AS rk
    FROM public.model_phones mp
    JOIN affected a ON a.model_id = mp.model_id
  )
  UPDATE public.model_phones mp
  SET is_primary = (r.rk = 1),
      status     = CASE WHEN r.rk = 1 THEN 'active' ELSE 'replaced' END
  FROM ranked r
  WHERE mp.id = r.id;

  SELECT count(*) INTO v_models_after FROM public.models;
  SELECT count(*) INTO v_phones_after FROM public.model_phones;
  SELECT
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.leadgen_entries) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.scouter_leads) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.closers_contacts) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.closer_creators) +
    (SELECT count(*) FILTER (WHERE model_id IS NOT NULL) FROM public.creators)
  INTO v_links_after;

  RETURN QUERY SELECT
    (v_models_after - v_models_before)::int,
    0::int,  -- updated_count: no fácil de medir con DO UPDATE; queda en 0
    (v_phones_after - v_phones_before)::int,
    (v_links_after - v_links_before)::int;
END;
$_$;


