CREATE OR REPLACE FUNCTION "public"."target_level"("_user_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id) THEN 0
    ELSE COALESCE((SELECT MAX(COALESCE(rc.level, 999))
                   FROM public.user_roles ur
                   LEFT JOIN public.roles_config rc ON rc.name = ur.role::text and rc.tenant_id = ur.tenant_id
                   WHERE ur.user_id = _user_id), 999)
  END;
$$;


