CREATE OR REPLACE FUNCTION "public"."tg_contact_kind_autodetect"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_handle text;
begin
  -- Sólo cuando el tipo viene como 'modelo' (default). Lo explícito manda.
  if coalesce(new.contact_kind, 'modelo') <> 'modelo' then
    return new;
  end if;

  v_handle := lower(regexp_replace(coalesce(new.handle, ''), '.*instagram\.com/|[@/[:space:]]', '', 'gi'));
  if v_handle = '' then
    return new;
  end if;

  if exists (
    select 1 from public.creators c
    where lower(regexp_replace(coalesce(c.instagram_handle,''), '.*instagram\.com/|[@/[:space:]]', '', 'gi')) = v_handle
      and coalesce(c.status,'') in ('terminated', 'leaving', 'paused')
  ) then
    new.contact_kind := 'ex_creadora';
  end if;

  return new;
end $$;


ALTER FUNCTION "public"."tg_contact_kind_autodetect"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tg_contact_kind_autodetect"() IS 'BEFORE INSERT/UPDATE en closers_contacts: si el handle ya existe en creators con status terminated/leaving/paused, marca contact_kind=ex_creadora. Cubre TODOS los caminos de creación (Contactos, LeadGen, imports, edges) sin tener que cablear cada uno. No pisa un tipo declarado explícitamente.';



CREATE OR REPLACE FUNCTION "public"."tg_conversation_set_assignees"("p_conversation_id" "uuid", "p_user_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.has_permission(auth.uid(), 'Telegram', 'Asignar conversaciones') then
    raise exception 'No tienes permiso para asignar conversaciones.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.tg_conversations
    where id = p_conversation_id and tenant_id = public.current_tenant_id()
  ) then
    raise exception 'Conversación no encontrada.' using errcode = 'P0002';
  end if;

  delete from public.tg_conversation_assignees
   where conversation_id = p_conversation_id
     and (p_user_ids is null or not (user_id = any(p_user_ids)));
  if array_length(p_user_ids, 1) is not null then
    insert into public.tg_conversation_assignees (conversation_id, user_id, assigned_by)
    select p_conversation_id, uid, auth.uid()
    from unnest(p_user_ids) as uid
    on conflict (conversation_id, user_id) do nothing;
  end if;

  update public.tg_conversations
  set assigned_to = (case when array_length(p_user_ids,1) is null then null else p_user_ids[1] end)
  where id = p_conversation_id and tenant_id = public.current_tenant_id();

  return p_conversation_id;
end;
$$;


ALTER FUNCTION "public"."tg_conversation_set_assignees"("p_conversation_id" "uuid", "p_user_ids" "uuid"[]) OWNER TO "postgres";


