CREATE OR REPLACE FUNCTION "public"."tg_roles_config_level_en_franja"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare f int[];
begin
  select public.franja_de_tipo(rg.is_admin, rg.is_manager_or_above, rg.is_supervisor_or_above)
    into f from public.role_groups rg where rg.role_name = new.name and rg.tenant_id = new.tenant_id;
  if f is not null and (new.level < f[1] or new.level > f[2]) then
    raise exception 'El nivel % está fuera de la franja de su tipo (%–%).', new.level, f[1], f[2]
      using errcode = '23514';
  end if;
  return new;
end $$;


