CREATE OR REPLACE FUNCTION "public"."tg_roles_config_sync_role_groups"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.role_groups (tenant_id, role_name, is_member, description)
    VALUES (NEW.tenant_id, NEW.name, true, NEW.description)
    ON CONFLICT (tenant_id, role_name) DO NOTHING;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.name IS DISTINCT FROM OLD.name THEN
    INSERT INTO public.role_groups
      (tenant_id, role_name, is_admin, is_manager_or_above, is_supervisor_or_above, is_member, description, created_at, updated_at)
    SELECT NEW.tenant_id, NEW.name, is_admin, is_manager_or_above, is_supervisor_or_above, is_member, NEW.description, created_at, now()
    FROM public.role_groups WHERE role_name = OLD.name AND tenant_id = OLD.tenant_id
    ON CONFLICT (tenant_id, role_name) DO NOTHING;

    UPDATE public.user_roles SET role = NEW.name WHERE role = OLD.name AND tenant_id = OLD.tenant_id;

    DELETE FROM public.role_groups WHERE role_name = OLD.name AND tenant_id = OLD.tenant_id;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_roles_config_sync_role_groups"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_scouter_autopilot_tick"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_remaining int;
  v_active    boolean;
BEGIN
  IF NEW.status NOT IN ('done', 'failed') THEN RETURN NEW; END IF;
  IF NEW.kind NOT IN ('discover_seed', 'discover_hashtag') THEN RETURN NEW; END IF;
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;

  SELECT active INTO v_active FROM scouter_autopilot WHERE tenant_id = NEW.tenant_id;
  IF NOT COALESCE(v_active, false) THEN RETURN NEW; END IF;

  SELECT COUNT(*) INTO v_remaining
  FROM scouter_jobs
  WHERE tenant_id = NEW.tenant_id
    AND status IN ('queued', 'running')
    AND kind IN ('discover_seed', 'discover_hashtag')
    AND id <> NEW.id;
  IF v_remaining > 0 THEN RETURN NEW; END IF;

  PERFORM scouter_enqueue_autopilot_batch(NEW.tenant_id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_scouter_autopilot_tick"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_scouter_first_contact"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_lead_id uuid;
BEGIN
  -- Solo nos interesa tasks tipo 'comment' que ahora tienen screenshot.
  IF NEW.task_type IS DISTINCT FROM 'comment' OR NEW.screenshot_url IS NULL THEN
    RETURN NEW;
  END IF;

  -- En UPDATE solo el momento NULL→no-NULL del screenshot_url. Ediciones
  -- subsiguientes no recapturan.
  IF TG_OP = 'UPDATE' AND OLD.screenshot_url IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Resolver lead_id via assignment.
  SELECT lead_id INTO v_lead_id
  FROM public.scouter_daily_assignments
  WHERE id = NEW.assignment_id;

  IF v_lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Idempotente: solo setea si está NULL.
  UPDATE public.scouter_leads
  SET first_scouter_contact_at = NOW()
  WHERE id = v_lead_id
    AND first_scouter_contact_at IS NULL;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_scouter_first_contact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_scouter_lead_sync_company_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_first_slug text;
  v_new_company_id uuid;
  v_conflict_exists boolean;
BEGIN
  IF NEW.target_companies IS NULL OR jsonb_typeof(NEW.target_companies) <> 'array' THEN
    RETURN NEW;
  END IF;
  IF jsonb_array_length(NEW.target_companies) = 0 THEN
    RETURN NEW;
  END IF;

  v_first_slug := NEW.target_companies->>0;
  IF v_first_slug IS NULL OR v_first_slug = '' THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_new_company_id
  FROM public.scouter_companies
  WHERE slug = v_first_slug;

  IF v_new_company_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Sin cambio si el company_id ya está correcto.
  IF NEW.company_id = v_new_company_id THEN
    RETURN NEW;
  END IF;

  -- Chequea si otra row ya tiene (v_new_company_id, handle). Si sí,
  -- no sincronizamos — evitaría conflicto con la unique constraint.
  SELECT EXISTS (
    SELECT 1 FROM public.scouter_leads
    WHERE company_id = v_new_company_id
      AND LOWER(instagram_handle) = LOWER(NEW.instagram_handle)
      AND id <> NEW.id
  ) INTO v_conflict_exists;

  IF v_conflict_exists THEN
    RETURN NEW;
  END IF;

  NEW.company_id := v_new_company_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_scouter_lead_sync_company_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_scouter_phone_first_set"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
