    IF NEW.phone IS NOT NULL AND NEW.phone_first_set_at IS NULL THEN
      NEW.phone_first_set_at := NOW();
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.phone IS NULL
       AND NEW.phone IS NOT NULL
       AND NEW.phone_first_set_at IS NULL THEN
      NEW.phone_first_set_at := NOW();
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


