CREATE OR REPLACE FUNCTION "public"."ventas_tops"("_from" "date", "_to" "date", "_limite" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_chatters jsonb;
  v_closers  jsonb;
  v_managers jsonb;
begin
  if not (
    public.has_permission(auth.uid(), 'Creator Sales', null)
    or public.is_in_role_group(auth.uid(), 'manager_or_above')
  ) then
    raise exception 'sin permiso para ver los tops de ventas';
  end if;

  select coalesce(jsonb_agg(t order by t.ventas desc), '[]'::jsonb) into v_chatters
  from (
    select ci.display_name                          as nombre,
           round(sum(m.sales)::numeric, 2)          as ventas,
           round(sum(case when m.agency = 'plus' then m.sales else 0 end)::numeric, 0)    as plus,
           round(sum(case when m.agency = 'massive' then m.sales else 0 end)::numeric, 0) as massive,
           sum(m.sold_messages)                     as mensajes,
           count(distinct m.dia)                    as dias
    from public.chatter_model_daily m
    join public.chatter_identity ci on ci.id = m.identity_id
    where m.dia between _from and _to
    group by ci.id, ci.display_name
    having sum(m.sales) > 0
    order by sum(m.sales) desc
    limit _limite
  ) t;

  select coalesce(jsonb_agg(t order by t.usd_mensual desc), '[]'::jsonb) into v_closers
  from (
    select p.full_name                             as nombre,
           count(*)                                 as ganadas,
           round(coalesce(sum(mo.monthly_value_usd), 0)::numeric, 0) as usd_mensual,
           (select round(avg(n.nota_sugerida), 1)
              from public.corte_notas n
             where n.profile_id = mo.assigned_to
               and n.fecha between _from and _to)   as nota_corte
    from public.monetization_opportunities mo
    join public.profiles p on p.id = mo.assigned_to
    where mo.stage = 'won'
      and mo.won_at is not null
      and mo.won_at::date between _from and _to
    group by mo.assigned_to, p.full_name
    order by sum(coalesce(mo.monthly_value_usd, 0)) desc
    limit _limite
  ) t;

  select coalesce(jsonb_agg(t order by t.pct_dias desc), '[]'::jsonb) into v_managers
  from (
    with roster as (
      select c.id as creator_id, c.assigned_manager_id as manager_id, p.full_name as nombre
      from public.creadoras_de_mi_agencia() c
      join public.profiles p on p.id = c.assigned_manager_id
      where c.status = 'active'
    ), dias as (
      select e.creator_id, e.dia,
             max(case when lower(e.promoted) in ('si','sí','yes','true') then 1 else 0 end) as promovio
      from public.promolog_entries e
      where e.dia between _from and _to
      group by e.creator_id, e.dia
    )
    select r.nombre,
           count(distinct r.creator_id)                                    as creadoras,
           count(distinct d.creator_id) filter (where d.promovio = 1)      as promocionaron,
           count(*) filter (where d.promovio = 1)                          as dias_con_promo,
           count(d.dia)                                                    as dias_medidos,
           round(100.0 * count(*) filter (where d.promovio = 1)
                 / greatest(count(d.dia), 1), 1)                           as pct_dias,
           (select round(avg(n.nota_sugerida), 1)
              from public.corte_notas n
             where n.profile_id = r.manager_id
               and n.fecha between _from and _to)                          as nota_corte
    from roster r
    left join dias d on d.creator_id = r.creator_id
    group by r.manager_id, r.nombre
    order by pct_dias desc
    limit _limite
  ) t;

  return jsonb_build_object('chatters', v_chatters, 'closers', v_closers, 'managers', v_managers);
end;
$$;


ALTER FUNCTION "public"."ventas_tops"("_from" "date", "_to" "date", "_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vigilar_blu"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_salud jsonb;
  v_detalle text;
  v_n int := 0;
begin
  select s.value::jsonb into v_salud
    from public.blu_bridge_state s where s.key = 'salud_sync';
  if v_salud is null or coalesce((v_salud->>'ok')::boolean, true) then
    return 0;
  end if;
  if exists (select 1 from public.blu_avisos a where a.creado > now() - interval '24 hours') then
    return 0;
  end if;
  if (select max(e.date) from public.creator_daily_earnings e) >= (now() at time zone 'America/Bogota')::date - 1 then
    return 0;
  end if;

  v_detalle := coalesce((select string_agg(x, ', ') from jsonb_array_elements_text(v_salud->'detalle') x), 'sin detalle');

  insert into public.blu_avisos (detalle) values (v_salud);

  insert into public.notifications
    (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
  select o.user_id, 'blu_desconectado',
         'Blu está desconectado: no llegan los ingresos de las modelos',
         format('Fallan: %s. El último ingreso guardado es del %s. Hay que entrar a Blu y renovar la sesión de esa cuenta (BLU_JWT para Plus, BLU_JWT_MASSIVE para Massive).',
                v_detalle,
                coalesce(to_char((select max(e.date) from public.creator_daily_earnings e), 'DD/MM/YYYY'), 'nunca')),
         'blu', 'Finance', 'high', 'new', 'personal', '/dashboard'
    from public.tenant_owners o;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."vigilar_blu"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vigilar_cortes_de_llamada"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  dx record;
  v_ahora timestamptz := now();
  v_avisos int := 0;
begin
  for r in
    select c.user_id, p.full_name, tm.tenant_id
      from public.llamada_cortes c
      join public.profiles p on p.id = c.user_id and p.deleted_at is null
      join lateral (select m.tenant_id from public.tenant_members m where m.user_id = c.user_id limit 1) tm on true
     where c.creado >= v_ahora - interval '1 hour'
       and c.fase in ('parpadeo_ok', 'caida', 'reentrada_agotada', 'recarga')
     group by c.user_id, p.full_name, tm.tenant_id
    having count(*) >= 4
  loop
    continue when public.es_admin_o_dueno(r.user_id);
    continue when exists (select 1 from public.llamada_avisos a
                           where a.user_id = r.user_id and a.creado >= v_ahora - interval '3 hours');

    select * into dx from public.diagnostico_de_llamada(r.user_id, v_ahora - interval '1 hour');
    continue when dx.causa = 'sin_datos';

    insert into public.llamada_avisos (user_id, cortes, causa, detalle)
    values (r.user_id, dx.cortes, dx.causa, to_jsonb(dx));

    insert into public.notifications
      (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    values (r.user_id, 'llamada_cortes_tu',
            format('Se te cortó la llamada %s veces en la última hora', dx.cortes),
            public.consejo_de_llamada(dx.causa, dx.subida_kbps, dx.rtt_ms, dx.perdida_pct),
            'cowork', 'Cowork', 'medium', 'new', 'personal', '/cowork');

    insert into public.notifications
      (user_id, type, title, message, reference_id, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    select d.user_id, 'llamada_cortes',
           format('A %s se le cortó la llamada %s veces en la última hora',
                  coalesce(nullif(trim(r.full_name), ''), 'un empleado'), dx.cortes),
           format('Causa probable: %s.%s', public.causa_de_llamada_corta(dx.causa),
                  case when dx.nav is not null then format(' Equipo: %s%s.', dx.nav,
                       case when dx.nucleos is not null then format(', %s núcleos', dx.nucleos) else '' end) else '' end),
           r.user_id, 'profile', 'Cowork', 'medium', 'new', 'personal', '/dashboard'
      from public.destinatarios_de_aviso(r.user_id) d;

    v_avisos := v_avisos + 1;
  end loop;
  return v_avisos;
end;
$$;


ALTER FUNCTION "public"."vigilar_cortes_de_llamada"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vigilar_fuera_de_cowork"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  v_ahora timestamptz := now();
  v_avisos int := 0;
  v_n int;
  v_min int;
  v_nom text;
  v_turno date;
begin
  -- 1) Cerrar: volvió (Cowork, pausa u otra llamada de Maven), o se le acabó el turno.
  for r in select f.id, f.user_id, f.desde from public.cowork_fuera f where f.hasta is null loop
    if public.presente_en_cowork(r.user_id, v_ahora) then
      update public.cowork_fuera set hasta = v_ahora, motivo = 'volvio' where id = r.id;
    elsif not exists (select 1 from public.turno_en_curso(r.user_id, v_ahora)) then
      update public.cowork_fuera
         set hasta = least(v_ahora, coalesce((select t.fin from public.turno_en_curso(r.user_id, r.desde) t), v_ahora)),
             motivo = 'fin_de_turno'
       where id = r.id;
    end if;
  end loop;

  -- 2) Abrir: en su turno, entró para este turno, no está, y no se fue en los
  --    últimos 10 minutos del turno.
  for r in
    select p.id as uid, tm.tenant_id, t.inicio, t.fin,
           (select max(coalesce(s.ended_at, s.last_seen_at)) from public.cowork_tiempo_segmentos s
             where s.user_id = p.id and coalesce(s.ended_at, s.last_seen_at) >= t.inicio - interval '30 minutes') as ultimo
      from public.profiles p
      join lateral (select m.tenant_id from public.tenant_members m where m.user_id = p.id limit 1) tm on true
      cross join lateral public.turno_en_curso(p.id, v_ahora) t
     where p.deleted_at is null
       and public.debe_estar_en_cowork(p.id)
       and not coalesce((select h.exento from public.horario_de(p.id) h), false)
       and not exists (select 1 from public.cowork_fuera f where f.user_id = p.id and f.hasta is null)
  loop
    continue when r.ultimo is null;
    continue when public.presente_en_cowork(r.uid, v_ahora);
    continue when greatest(r.ultimo, r.inicio) >= r.fin - interval '10 minutes';
    insert into public.cowork_fuera (user_id, tenant_id, desde)
    values (r.uid, r.tenant_id, greatest(r.ultimo, r.inicio,
            coalesce((select max(f.hasta) from public.cowork_fuera f where f.user_id = r.uid), r.inicio)))
    on conflict do nothing;
  end loop;

  -- 3) Llamados: al minuto el primero, después cada 2 min hasta que vuelva. Al 3ro,
  --    «te estoy reportando» y el aviso a sus jefes (una vez por salida). La hora del
  --    aviso es la del turno en curso.
  for r in
    select f.id, f.user_id, f.desde, f.llamados, f.reportado_at, p.full_name,
           (t.inicio at time zone 'America/Bogota')::time as entrada,
           (t.fin at time zone 'America/Bogota')::time as salida
      from public.cowork_fuera f
      join public.profiles p on p.id = f.user_id
      left join lateral public.turno_en_curso(f.user_id, v_ahora) t on true
     where f.hasta is null and f.desde <= v_ahora - interval '1 minute'
       and (f.ultimo_llamado_at is null or f.ultimo_llamado_at <= v_ahora - interval '110 seconds')
  loop
    v_n := r.llamados + 1;
    v_min := greatest(1, round(extract(epoch from (v_ahora - r.desde)) / 60))::int;

    insert into public.notifications
      (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    values (r.user_id, 'cowork_fuera_tu',
            case when v_n >= 3 then 'Te estoy reportando: sigues fuera de Cowork'
                 when v_n = 2 then 'Sigues fuera de Cowork en tu turno'
                 else 'Saliste de Cowork en tu turno' end,
            case when v_n >= 3 then format('Llevas %s min fuera y no volviste. Ya le avisé a tu supervisor. Entra a Cowork ya, con cámara y pantalla.', v_min)
                 else format('Llevas %s min fuera. Entra a Cowork ya, con cámara y pantalla completa. Mientras estés fuera cuenta en tu nota.', v_min) end,
            'cowork', 'Cowork', 'high', 'new', 'personal', '/cowork');

    if v_n >= 3 and r.reportado_at is null then
      insert into public.notifications
        (user_id, type, title, message, reference_id, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
      select d.user_id, 'cowork_fuera',
             format('%s sigue fuera de Cowork', coalesce(nullif(trim(r.full_name), ''), 'Un empleado')),
             format('Está en su turno (%s–%s), salió a las %s y lleva %s min fuera. Argos le hizo 3 llamados y no volvió.',
                    to_char(r.entrada, 'HH24:MI'), to_char(r.salida, 'HH24:MI'),
                    to_char(r.desde at time zone 'America/Bogota', 'HH24:MI'), v_min),
             r.user_id, 'profile', 'HR', 'high', 'new', 'personal',
             format('/hr/en-vivo/%s?fuera=%s', r.user_id, r.id)
        from public.destinatarios_de_aviso(r.user_id) d;
    end if;

    update public.cowork_fuera
       set llamados = v_n, ultimo_llamado_at = v_ahora,
           avisado_at = coalesce(avisado_at, v_ahora),
           reportado_at = case when v_n >= 3 then coalesce(reportado_at, v_ahora) else reportado_at end
     where id = r.id;
    v_avisos := v_avisos + 1;
  end loop;

  -- 4) NUNCA ENTRÓ en su turno (solo con horario propio, también el horario por
  --    semana): a los 10 min de empezar, llamados cada 2 min; al 3ro, el reporte a sus
  --    jefes.
  for r in
    select p.id as uid, p.full_name, tm.tenant_id, t.inicio,
           (t.inicio at time zone 'America/Bogota')::time as entrada,
           n.llamados, n.reportado_at
      from public.profiles p
      join lateral (select m.tenant_id from public.tenant_members m where m.user_id = p.id limit 1) tm on true
      cross join lateral public.turno_en_curso(p.id, v_ahora) t
      left join lateral public.horario_de(p.id) h on true
      left join public.argos_no_entro n
             on n.user_id = p.id and n.turno = (t.inicio at time zone 'America/Bogota')::date
     where p.deleted_at is null
       and (p.hora_entrada is not null or p.turno_id is not null
            or exists (select 1 from public.horario_semanal hs where hs.user_id = p.id))
       and public.debe_estar_en_cowork(p.id)
       and not coalesce(h.exento, false)
       and v_ahora >= t.inicio + interval '10 minutes'
       and v_ahora < t.fin - interval '10 minutes'
       and not exists (select 1 from public.cowork_tiempo_segmentos s
                        where s.user_id = p.id and coalesce(s.ended_at, s.last_seen_at) >= t.inicio - interval '30 minutes')
       and (n.ultimo_llamado_at is null or n.ultimo_llamado_at <= v_ahora - interval '110 seconds')
  loop
    continue when public.presente_en_cowork(r.uid, v_ahora);
    v_turno := (r.inicio at time zone 'America/Bogota')::date;
    v_n := coalesce(r.llamados, 0) + 1;
    v_min := greatest(1, round(extract(epoch from (v_ahora - r.inicio)) / 60))::int;
    v_nom := coalesce(nullif(trim(r.full_name), ''), 'Un empleado');

    insert into public.notifications
      (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    values (r.uid, 'cowork_no_entro_tu',
            case when v_n >= 3 then 'Te estoy reportando: no has entrado a Cowork'
                 else 'Ya empezó tu turno y no has entrado a Cowork' end,
            case when v_n >= 3 then format('Tu turno empezó a las %s. Ya le avisé a tu supervisor. Entra a Cowork ya, con cámara y pantalla.', to_char(r.entrada, 'HH24:MI'))
                 else format('Tu turno empezó a las %s. Entra a Cowork ya, con cámara y pantalla completa.', to_char(r.entrada, 'HH24:MI')) end,
            'cowork', 'Cowork', 'high', 'new', 'personal', '/cowork');

    if v_n >= 3 and r.reportado_at is null then
      insert into public.notifications
        (user_id, type, title, message, reference_id, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
      select d.user_id, 'cowork_no_entro',
             format('%s no ha entrado a Cowork', v_nom),
             format('Debía entrar a las %s y lleva %s min sin entrar. Argos le hizo 3 llamados.', to_char(r.entrada, 'HH24:MI'), v_min),
             r.uid, 'profile', 'HR', 'high', 'new', 'personal', format('/hr/expediente/%s', r.uid)
        from public.destinatarios_de_aviso(r.uid) d;
    end if;

    insert into public.argos_no_entro (user_id, turno, llamados, ultimo_llamado_at, reportado_at, tenant_id)
    values (r.uid, v_turno, v_n, v_ahora, case when v_n >= 3 then v_ahora end, r.tenant_id)
    on conflict (user_id, turno) do update
      set llamados = excluded.llamados, ultimo_llamado_at = excluded.ultimo_llamado_at,
          reportado_at = coalesce(public.argos_no_entro.reportado_at, excluded.reportado_at);
    v_avisos := v_avisos + 1;
  end loop;

  return v_avisos;
end;
$$;


ALTER FUNCTION "public"."vigilar_fuera_de_cowork"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vigilar_saldo_ia"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v jsonb := public.ia_saldo_calculo();
  v_estado text := v ->> 'estado';
  v_tipo text;
  v_clave bigint;
  v_titulo text;
  v_mensaje text;
  v_saldo text := to_char(greatest(coalesce((v ->> 'saldo_usd')::numeric, 0), 0), 'FM999990.00');
  v_dias text := replace(to_char(coalesce((v ->> 'dias_restantes')::numeric, 2), 'FM990.0'), '.', ',');
  v_ritmo text := to_char(coalesce((v ->> 'ritmo_dia_usd')::numeric, 0), 'FM999990.00');
  v_cuando text := to_char(((v ->> 'se_acaba_at')::timestamptz) at time zone 'America/Bogota', 'DD/MM "a las" HH24:MI');
  v_nuevo integer;
begin
  if v_estado = 'sin_saldo' then
    v_tipo := 'sin_saldo';
    v_clave := (v ->> 'sin_saldo_id')::bigint;
    v_titulo := 'Gemini se quedó sin saldo: Argos dejó de juzgar';
    v_mensaje := 'Google cortó la IA de Argos y de la cámara por saldo agotado. Recarga en AI Studio (Billing → Buy credits) y anota el saldo en Costos; Argos vuelve solo al recargar.';
  elsif v_estado in ('se_acaba_hoy', 'pocos_dias', 'anotar') then
    v_tipo := v_estado;
    v_clave := (v -> 'punto' ->> 'id')::bigint;
    if v_estado = 'se_acaba_hoy' then
      v_titulo := 'El saldo de Gemini se acaba hoy';
      v_mensaje := format('Quedan ~USD %s y Argos gasta ~USD %s al día: alcanza hasta el %s. Recarga en AI Studio para que Argos no se apague.', v_saldo, v_ritmo, coalesce(v_cuando, 'hoy'));
    elsif v_estado = 'pocos_dias' then
      v_titulo := format('Al saldo de Gemini le quedan ~%s días', v_dias);
      v_mensaje := format('Quedan ~USD %s y Argos gasta ~USD %s al día: alcanza hasta el %s. Recarga en AI Studio antes de que se apague.', v_saldo, v_ritmo, coalesce(v_cuando, 'pronto'));
    else
      v_titulo := 'Argos sigue funcionando, pero Maven no sabe el saldo de Gemini';
      v_mensaje := 'Por la cuenta de Maven el saldo ya se acabó, pero Google sigue respondiendo: parece que recargaste. Anota en Costos el saldo que muestra AI Studio para seguir midiendo.';
    end if;
  else
    return 0;
  end if;
  if v_clave is null then
    return 0;
  end if;

  insert into public.costos_saldo_avisos (servicio_id, tipo, clave)
  values ('google_ia', v_tipo, v_clave)
  on conflict do nothing;
  get diagnostics v_nuevo = row_count;
  if v_nuevo = 0 then
    return 0;
  end if;

  insert into public.notifications
    (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
  select o.user_id, 'costos_saldo_ia', v_titulo, v_mensaje,
         'costos', 'Oficina', 'high', 'new', 'personal', '/oficina/costos'
    from (select distinct user_id from public.tenant_owners) o;
  return 1;
end
$$;


ALTER FUNCTION "public"."vigilar_saldo_ia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vigilar_subidas_trabadas"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  n integer := 0;
begin
  for r in
    select i.id, i.nombre_archivo, i.size_bytes, i.pct, i.estado, i.mensaje,
           l.created_by, l.item_id, coalesce(c.nombre, 'una carpeta') as carpeta
      from public.drive_aportar_intentos i
      join public.drive_upload_links l on l.token = i.token
      left join public.drive_items c on c.id = l.item_id
     where i.avisado_at is null
       and i.iniciado_at > now() - interval '2 days'
       and (i.estado = 'fallo'
            or (i.estado in ('subiendo', 'pausado') and i.actualizado_at < now() - interval '15 minutes'))
       -- La modelo ya lo retomó en otro intento (terminó o sigue vivo): no avisar.
       and not exists (
         select 1 from public.drive_aportar_intentos j
          where j.token = i.token and j.nombre_archivo = i.nombre_archivo
            and j.size_bytes is not distinct from i.size_bytes
            and j.id <> i.id and j.iniciado_at > i.iniciado_at
            and (j.estado = 'ok' or j.actualizado_at > now() - interval '15 minutes'))
     for update of i skip locked
  loop
    update public.drive_aportar_intentos set avisado_at = now() where id = r.id;
    continue when r.created_by is null;

    insert into public.notifications
      (user_id, type, title, message, reference_id, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    values (
      r.created_by, 'drive_subida_trabada',
      format('%s no pudo terminar de subir un archivo', r.carpeta),
      format('«%s» (%s) quedó en %s%%. %s',
             r.nombre_archivo, pg_size_pretty(coalesce(r.size_bytes, 0)), r.pct,
             case when r.estado = 'fallo'
                  then format('Falló: %s. Escríbele para que lo vuelva a intentar con el mismo link: sigue desde donde quedó.',
                              coalesce(left(r.mensaje, 160), 'sin detalle'))
                  else 'Lleva más de 15 minutos sin avanzar (bloqueó el teléfono, cerró la página o se quedó sin internet). Escríbele para que abra su link y elija el mismo video: sigue desde donde quedó.'
             end),
      r.item_id, 'drive_carpeta', 'Oficina', 'high', 'new', 'personal',
      case when r.item_id is not null then '/oficina/drive?carpeta=' || r.item_id else '/oficina/drive' end
    );
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."vigilar_subidas_trabadas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vigilar_tiempo_sin_pantalla"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  j record;
  v_ahora timestamptz := now();
  v_dia date := (now() at time zone 'America/Bogota')::date;
  v_turno date;
  v_sin int;
  v_perm int;
  v_entro boolean;
  v_faltas int;
  v_fotos int;
  v_nom text;
  v_avisos int := 0;
begin
  -- 4a) AL MOMENTO: en su turno, ya entró, y se pasó de lo permitido.
  for r in
    select p.id as uid, p.full_name, tm.tenant_id, t.inicio, t.fin
      from public.profiles p
      join lateral (select m.tenant_id from public.tenant_members m where m.user_id = p.id limit 1) tm on true
      cross join lateral public.turno_en_curso(p.id, v_ahora) t
     where p.deleted_at is null
       and public.debe_estar_en_cowork(p.id)
       and not coalesce((select h.exento from public.horario_de(p.id) h), false)
       and exists (select 1 from public.cowork_tiempo_segmentos s
                    where s.user_id = p.id and coalesce(s.ended_at, s.last_seen_at) >= t.inicio - interval '30 minutes')
  loop
    v_turno := (r.inicio at time zone 'America/Bogota')::date;
    continue when exists (select 1 from public.argos_tiempo_avisos a
                           where a.user_id = r.uid and a.turno = v_turno and a.tipo = 'pasado');
    v_perm := public.argos_permitido_min(r.uid);
    v_sin := round(public.argos_sin_pantalla_seg(r.uid, r.inicio, v_ahora) / 60.0);
    continue when v_sin <= v_perm;

    insert into public.argos_tiempo_avisos (user_id, turno, tipo, sin_pantalla_min, permitido_min, tenant_id)
    values (r.uid, v_turno, 'pasado', v_sin, v_perm, r.tenant_id)
    on conflict do nothing;

    v_nom := coalesce(nullif(trim(r.full_name), ''), 'Un empleado');
    insert into public.notifications
      (user_id, type, title, message, reference_id, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    select d.user_id, 'argos_tiempo_pasado',
           format('%s se pasó de su tiempo sin pantalla', v_nom),
           format('Lleva %s min sin pantalla en su turno (%s–%s) y tiene %s permitidos (comida + baño).',
                  v_sin, to_char(r.inicio at time zone 'America/Bogota', 'HH24:MI'),
                  to_char(r.fin at time zone 'America/Bogota', 'HH24:MI'), v_perm),
           r.uid, 'profile', 'HR', 'high', 'new', 'personal', format('/hr/expediente/%s', r.uid)
      from public.destinatarios_de_aviso(r.uid) d;

    insert into public.notifications
      (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    values (r.uid, 'argos_tiempo_pasado_tu', 'Te pasaste de tu tiempo sin pantalla',
            format('Llevas %s min sin compartir pantalla en tu turno y tienes %s (comida + baño). Vuelve a Cowork con cámara y pantalla.',
                   v_sin, v_perm),
            'cowork', 'Cowork', 'high', 'new', 'personal', '/cowork');
    v_avisos := v_avisos + 1;
  end loop;

  -- 4b) AL CERRAR EL TURNO: la foto de cada persona cuyo turno terminó hace 10 min
  --     o más (y menos de 3 h), una vez por turno. El turno de hoy y el de ayer, cada
  --     uno con turno_del_dia (un día de descanso no tiene turno).
  for r in
    select p.id as uid, p.full_name, tm.tenant_id, x.ini, x.fin
      from public.profiles p
      join lateral (select m.tenant_id from public.tenant_members m where m.user_id = p.id limit 1) tm on true
      join lateral public.horario_de(p.id) h on not coalesce(h.exento, false)
      cross join lateral (
        select t.inicio as ini, t.fin
          from unnest(array[0, -1]) as d
         cross join lateral public.turno_del_dia(p.id, v_dia + d) t
      ) x
     where p.deleted_at is null
       and public.debe_estar_en_cowork(p.id)
       and x.fin <= v_ahora - interval '10 minutes'
       and x.fin > v_ahora - interval '3 hours'
  loop
    v_turno := (r.ini at time zone 'America/Bogota')::date;
    continue when exists (select 1 from public.argos_tiempo_avisos a
                           where a.user_id = r.uid and a.turno = v_turno and a.tipo = 'resumen');
    v_entro := exists (select 1 from public.cowork_tiempo_segmentos s
                        where s.user_id = r.uid and s.started_at < r.fin
                          and coalesce(s.ended_at, s.last_seen_at) >= r.ini - interval '30 minutes');
    v_perm := public.argos_permitido_min(r.uid);
    v_sin := case when v_entro then round(public.argos_sin_pantalla_seg(r.uid, r.ini, r.fin) / 60.0) else 0 end;
    select count(*) into v_faltas from public.monitor_eventos e
     where e.user_id = r.uid and e.created_at >= r.ini and e.created_at < r.fin;
    select count(*) into v_fotos from public.monitor_capturas c
     where c.user_id = r.uid and c.tipo = 'pantalla' and c.created_at >= r.ini and c.created_at < r.fin;

    insert into public.argos_tiempo_avisos (user_id, turno, tipo, sin_pantalla_min, permitido_min, faltas, fotos, entro, tenant_id, created_at)
    values (r.uid, v_turno, 'resumen', v_sin, v_perm, v_faltas, v_fotos, v_entro, r.tenant_id, v_ahora)
    on conflict do nothing;

    if v_entro then
      insert into public.notifications
        (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
      values (r.uid, 'argos_resumen_turno_tu',
              case when v_sin > v_perm then 'Tu turno: te pasaste de tu tiempo sin pantalla' else 'Tu turno: dentro de tu tiempo' end,
              format('Estuviste %s min sin pantalla de %s permitidos · %s fallas · %s fotos.', v_sin, v_perm, v_faltas, v_fotos),
              'cowork', 'Cowork', 'medium', 'new', 'personal', '/dashboard');
    end if;
  end loop;

  -- 4c) UN resumen por jefe con su gente de este cierre (los que se pasaron arriba).
  --     Si nadie del cierre entró (día libre, festivo), no se manda.
  for j in
    select d.user_id as jefe,
           count(*) filter (where a.entro and a.sin_pantalla_min > a.permitido_min) as pasados,
           count(*) filter (where a.entro and a.sin_pantalla_min <= a.permitido_min) as dentro,
           count(*) filter (where not a.entro) as sin_entrar,
           -- Los 6 que más se pasaron; el resto se cuenta («+3 más»).
           (array_agg(format('%s %s de %s min', trim(split_part(p.full_name, ' ', 1) || ' ' || split_part(p.full_name, ' ', 2)),
                             a.sin_pantalla_min, a.permitido_min)
                      order by (a.sin_pantalla_min - a.permitido_min) desc)
              filter (where a.entro and a.sin_pantalla_min > a.permitido_min))[1:6] as top
      from public.argos_tiempo_avisos a
      join public.profiles p on p.id = a.user_id
      cross join lateral public.destinatarios_de_aviso(a.user_id) d
     where a.tipo = 'resumen' and a.created_at = v_ahora
     group by d.user_id
    having count(*) filter (where a.entro) > 0
  loop
    insert into public.notifications
      (user_id, type, title, message, reference_type, module_origin, priority, status, visibility_scope, deep_link_url)
    values (j.jefe, 'argos_resumen_turno',
            case when j.pasados = 0 then 'Resumen del turno: todos dentro de su tiempo'
                 when j.pasados = 1 then 'Resumen del turno: 1 se pasó de su tiempo sin pantalla'
                 else format('Resumen del turno: %s se pasaron de su tiempo sin pantalla', j.pasados) end,
            concat_ws(' ',
                      case when j.top is not null then array_to_string(j.top, ' · ')
                           || case when j.pasados > 6 then format(' · +%s más', j.pasados - 6) else '' end || '.' end,
                      format('%s dentro de su tiempo · %s sin entrar.', j.dentro, j.sin_entrar)),
            'profile', 'HR', 'medium', 'new', 'personal', '/hr/monitor-ia?t=dia');
    v_avisos := v_avisos + 1;
  end loop;

  return v_avisos;
end;
$$;


ALTER FUNCTION "public"."vigilar_tiempo_sin_pantalla"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wa_agent_lock_acquire"("p_group_id" "uuid", "p_holder" "uuid", "p_ttl_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare ok boolean;
begin
  insert into public.whatsapp_agent_locks(group_id, holder, acquired_at, expires_at)
  values (p_group_id, p_holder, now(), now() + make_interval(secs => p_ttl_seconds))
  on conflict (group_id) do update
    set holder = excluded.holder, acquired_at = now(), expires_at = excluded.expires_at
    where public.whatsapp_agent_locks.expires_at < now()
  returning true into ok;
  return coalesce(ok, false);
end $$;


