CREATE OR REPLACE FUNCTION "public"."wa_copilot_try_consume"("_user_id" "uuid") RETURNS TABLE("allowed" boolean, "used" integer, "lim" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_today     date := (now() at time zone 'America/Bogota')::date;
  v_lim       int;
  v_used      int;
  v_unlimited boolean := false;
begin
  if public.is_in_role_group(_user_id, 'manager_or_above') then
    v_unlimited := true;
  else
    select p.ai_daily_quota_override into v_lim
      from public.profiles p where p.id = _user_id;
    if v_lim is null then
      select rc.ai_daily_quota into v_lim
        from public.user_roles ur
        join public.roles_config rc on rc.name = ur.role and rc.tenant_id = ur.tenant_id and rc.is_active
        where ur.user_id = _user_id
        limit 1;
    end if;
    v_lim := coalesce(v_lim, 20);
  end if;

  select count into v_used
    from public.wa_copilot_usage
    where user_id = _user_id and usage_date = v_today;
  v_used := coalesce(v_used, 0);

  if not v_unlimited and v_used >= v_lim then
    return query select false, v_used, v_lim;
    return;
  end if;

  insert into public.wa_copilot_usage (user_id, usage_date, count)
    values (_user_id, v_today, 1)
    on conflict (user_id, usage_date)
    do update set count = public.wa_copilot_usage.count + 1;

  return query select true, v_used + 1, case when v_unlimited then null else v_lim end;
end;
$$;


ALTER FUNCTION "public"."wa_copilot_try_consume"("_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wa_copilot_try_consume"("_user_id" "uuid") IS 'Cuota IA del inbox (6a.3): resuelve el límite (override usuario > rol > 20; admin/manager ilimitado), chequea el uso de hoy (Bogotá) y consume 1. Devuelve (allowed, used, lim). La llama wa-inbox-suggest con service_role.';



