CREATE OR REPLACE FUNCTION "public"."wa_line_health"("p_hours" integer DEFAULT 24) RETURNS TABLE("channel_id" "uuid", "label" "text", "evolution_instance" "text", "total" integer, "ok" integer, "sent_pend" integer, "failed" integer, "pct_fallo" integer, "health" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not (public.is_in_role_group(auth.uid(), 'admin')
          or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role') then
    raise exception 'forbidden: solo admin' using errcode = '42501';
  end if;
  return query
  with s as (
    select ch.id AS cid, ch.label AS lbl, ch.evolution_instance AS inst,
      count(m.*) FILTER (WHERE m.direction='out')::int AS t,
      count(m.*) FILTER (WHERE m.direction='out' AND m.status IN ('delivered','read'))::int AS o,
      count(m.*) FILTER (WHERE m.direction='out' AND m.status='sent')::int AS sp,
      count(m.*) FILTER (WHERE m.direction='out' AND m.status='failed')::int AS f
    from public.wa_channels ch
    left join public.wa_conversations c ON c.channel_id = ch.id
    left join public.wa_conversation_messages m ON m.conversation_id = c.id
      AND m.created_at >= now() - make_interval(hours => greatest(p_hours,1))
    group by ch.id, ch.label, ch.evolution_instance
  )
  select s.cid, s.lbl, s.inst, s.t, s.o, s.sp, s.f,
    (round(100.0 * s.f / nullif(s.t,0)))::int AS pct,
    case
      when s.t < 3 then 'sin_datos'
      when s.f::numeric / s.t >= 0.40 then 'critico'
      when s.f::numeric / s.t >= 0.15 then 'alerta'
      else 'ok'
    end AS health
  from s
  order by (round(100.0 * s.f / nullif(s.t,0))) desc nulls last, s.t desc;
end;
$$;


ALTER FUNCTION "public"."wa_line_health"("p_hours" integer) OWNER TO "postgres";


