COMMENT ON FUNCTION "public"."whatsapp_group_in_business_hours"("p_group_id" "uuid") IS 'True si al menos un miembro linkeado del grupo está actualmente en turno (zona Bogotá). Usado por whatsapp-ingest para gate del modo always-listening.';



CREATE OR REPLACE FUNCTION "public"."whatsapp_pending_reminders"("p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "group_id" "uuid", "kind" "text", "commitment_id" "uuid", "body" "text", "attempt_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT id, tenant_id, group_id, kind, commitment_id, body, attempt_count
  FROM public.whatsapp_reminders
  WHERE status = 'pending' AND trigger_at <= now()
  ORDER BY trigger_at ASC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."whatsapp_pending_reminders"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."whatsapp_resolve_user_by_lid"("p_lid" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_user_id uuid;
BEGIN
  IF p_lid IS NULL OR length(trim(p_lid)) = 0 THEN RETURN NULL; END IF;
  SELECT id INTO v_user_id FROM public.profiles WHERE whatsapp_lid = trim(p_lid) LIMIT 1;
  RETURN v_user_id;
END;
$$;


ALTER FUNCTION "public"."whatsapp_resolve_user_by_lid"("p_lid" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."whatsapp_resolve_user_by_phone"("p_jid_or_phone" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_digits text;
  v_last10 text;
  v_user_id uuid;
BEGIN
  IF p_jid_or_phone IS NULL OR length(p_jid_or_phone) = 0 THEN
    RETURN NULL;
  END IF;
  v_digits := regexp_replace(p_jid_or_phone, '\D', '', 'g');
  IF length(v_digits) < 7 THEN
    RETURN NULL;
  END IF;
  v_last10 := right(v_digits, 10);
  SELECT id INTO v_user_id
  FROM public.profiles
  WHERE phone_e164 IS NOT NULL
    AND right(regexp_replace(phone_e164, '\D', '', 'g'), 10) = v_last10
  LIMIT 1;
  RETURN v_user_id;
END;
$$;


ALTER FUNCTION "public"."whatsapp_resolve_user_by_phone"("p_jid_or_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."whatsapp_resolve_user_by_push_name"("p_push_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count int;
  v_user_id uuid;
BEGIN
  IF p_push_name IS NULL OR length(trim(p_push_name)) = 0 THEN
    RETURN NULL;
  END IF;
  SELECT COUNT(*), MAX(id)
  INTO v_count, v_user_id
  FROM public.profiles
  WHERE lower(whatsapp_push_name) = lower(trim(p_push_name))
    AND whatsapp_verified_at IS NOT NULL;
  IF v_count = 1 THEN
    RETURN v_user_id;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."whatsapp_resolve_user_by_push_name"("p_push_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."whatsapp_touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."whatsapp_touch_updated_at"() OWNER TO "postgres";


