CREATE TABLE IF NOT EXISTS "public"."api_escritura_cupos" (
    "clave" "text" NOT NULL,
    "lim_msj_min" integer DEFAULT 60 NOT NULL,
    "lim_msj_hora" integer DEFAULT 1000 NOT NULL,
    "lim_msj_dia" integer DEFAULT 10000 NOT NULL,
    "lim_dest_min" integer DEFAULT 300 NOT NULL,
    "lim_dest_hora" integer DEFAULT 4000 NOT NULL,
    "lim_dest_dia" integer DEFAULT 40000 NOT NULL,
    "lim_chats_dia" integer DEFAULT 100 NOT NULL,
    "lim_edic_min" integer DEFAULT 30 NOT NULL,
    "lim_edic_hora" integer DEFAULT 300 NOT NULL,
    "min_inicio" timestamp with time zone,
    "min_msj" integer DEFAULT 0 NOT NULL,
    "min_dest" integer DEFAULT 0 NOT NULL,
    "min_edic" integer DEFAULT 0 NOT NULL,
    "hora_inicio" timestamp with time zone,
    "hora_msj" integer DEFAULT 0 NOT NULL,
    "hora_dest" integer DEFAULT 0 NOT NULL,
    "hora_edic" integer DEFAULT 0 NOT NULL,
    "dia_inicio" "date",
    "dia_msj" integer DEFAULT 0 NOT NULL,
    "dia_dest" integer DEFAULT 0 NOT NULL,
    "dia_chats" integer DEFAULT 0 NOT NULL,
    "actualizado" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "api_escritura_cupos_clave_check" CHECK (("clave" ~ '^(plataforma|agencia:[0-9a-f-]{36}|llave:[0-9a-f-]{36})$'::"text")),
    CONSTRAINT "api_escritura_cupos_lim_chats_dia_check" CHECK ((("lim_chats_dia" >= 0) AND ("lim_chats_dia" <= 100))),
    CONSTRAINT "api_escritura_cupos_lim_dest_dia_check" CHECK ((("lim_dest_dia" >= 52) AND ("lim_dest_dia" <= 80000))),
    CONSTRAINT "api_escritura_cupos_lim_dest_hora_check" CHECK ((("lim_dest_hora" >= 52) AND ("lim_dest_hora" <= 8000))),
    CONSTRAINT "api_escritura_cupos_lim_dest_min_check" CHECK ((("lim_dest_min" >= 52) AND ("lim_dest_min" <= 600))),
    CONSTRAINT "api_escritura_cupos_lim_edic_hora_check" CHECK ((("lim_edic_hora" >= 1) AND ("lim_edic_hora" <= 1000))),
    CONSTRAINT "api_escritura_cupos_lim_edic_min_check" CHECK ((("lim_edic_min" >= 1) AND ("lim_edic_min" <= 60))),
    CONSTRAINT "api_escritura_cupos_lim_msj_dia_check" CHECK ((("lim_msj_dia" >= 1) AND ("lim_msj_dia" <= 20000))),
    CONSTRAINT "api_escritura_cupos_lim_msj_hora_check" CHECK ((("lim_msj_hora" >= 1) AND ("lim_msj_hora" <= 2000))),
    CONSTRAINT "api_escritura_cupos_lim_msj_min_check" CHECK ((("lim_msj_min" >= 1) AND ("lim_msj_min" <= 120))),
    CONSTRAINT "api_escritura_cupos_ventanas" CHECK ((("lim_msj_min" <= "lim_msj_hora") AND ("lim_msj_hora" <= "lim_msj_dia") AND ("lim_dest_min" <= "lim_dest_hora") AND ("lim_dest_hora" <= "lim_dest_dia") AND ("lim_edic_min" <= "lim_edic_hora")))
);


ALTER TABLE "public"."api_escritura_cupos" OWNER TO "postgres";


