CREATE TABLE IF NOT EXISTS "public"."api_webhook_deliveries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "endpoint_id" "uuid" NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "body" "text" NOT NULL,
    "message_count" integer,
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "drop_reason" "text",
    "attempts" smallint DEFAULT 0 NOT NULL,
    "last_attempt_at" timestamp with time zone,
    "last_status_code" integer,
    "last_error" "text",
    "latency_ms" integer,
    "uncertain" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "delivered_at" timestamp with time zone,
    CONSTRAINT "api_webhook_deliveries_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "api_webhook_deliveries_body_check" CHECK (("octet_length"("body") <= 16384)),
    CONSTRAINT "api_webhook_deliveries_cantidad" CHECK (
CASE "event_type"
    WHEN 'messages.created'::"text" THEN (("message_count" IS NOT NULL) AND (("message_count" >= 1) AND ("message_count" <= 100)))
    ELSE ("message_count" IS NULL)
END),
    CONSTRAINT "api_webhook_deliveries_descartado" CHECK ((("state" = 'dropped'::"text") = ("drop_reason" IS NOT NULL))),
    CONSTRAINT "api_webhook_deliveries_drop_reason_check" CHECK (("drop_reason" = ANY (ARRAY['receiver_gone'::"text", 'receiver_failing'::"text", 'endpoint_paused'::"text", 'endpoint_disabled'::"text", 'test_failed'::"text"]))),
    CONSTRAINT "api_webhook_deliveries_entregado" CHECK ((("state" = 'delivered'::"text") = ("delivered_at" IS NOT NULL))),
    CONSTRAINT "api_webhook_deliveries_entregado_2xx" CHECK ((("state" <> 'delivered'::"text") OR ((("last_status_code" >= 200) AND ("last_status_code" <= 299)) AND ("attempts" >= 1)))),
    CONSTRAINT "api_webhook_deliveries_event_type_check" CHECK (("event_type" = ANY (ARRAY['messages.created'::"text", 'webhook.test'::"text"]))),
    CONSTRAINT "api_webhook_deliveries_last_error_check" CHECK (("char_length"("last_error") <= 60)),
    CONSTRAINT "api_webhook_deliveries_last_status_code_check" CHECK ((("last_status_code" >= 100) AND ("last_status_code" <= 999))),
    CONSTRAINT "api_webhook_deliveries_latency_ms_check" CHECK (("latency_ms" >= 0)),
    CONSTRAINT "api_webhook_deliveries_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'delivered'::"text", 'dropped'::"text"])))
);


ALTER TABLE "public"."api_webhook_deliveries" OWNER TO "postgres";


COMMENT ON TABLE "public"."api_webhook_deliveries" IS 'Timbres y pruebas de los webhooks del Messenger. Se guardan 14 días.';



