CREATE TABLE IF NOT EXISTS "public"."chatter_scorecards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "chatter_name" "text" NOT NULL,
    "company" "text" NOT NULL,
    "period" "date" NOT NULL,
    "blu_employee_id" bigint,
    "c1_puntualidad" smallint,
    "c2_calidad_chats" smallint,
    "c3_cumplimiento_meta" smallint,
    "c4_productividad_hubstaff" smallint,
    "c5_actitud_disciplina" smallint,
    "c6_gestion_estrategia" smallint,
    "c7_scripts" smallint,
    "c8_camara_pantalla" smallint,
    "total" smallint GENERATED ALWAYS AS ((((((((COALESCE(("c1_puntualidad")::integer, 0) + COALESCE(("c2_calidad_chats")::integer, 0)) + COALESCE(("c3_cumplimiento_meta")::integer, 0)) + COALESCE(("c4_productividad_hubstaff")::integer, 0)) + COALESCE(("c5_actitud_disciplina")::integer, 0)) + COALESCE(("c6_gestion_estrategia")::integer, 0)) + COALESCE(("c7_scripts")::integer, 0)) + COALESCE(("c8_camara_pantalla")::integer, 0))) STORED,
    "note" "text",
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chatter_scorecards_c1_puntualidad_check" CHECK ((("c1_puntualidad" >= 0) AND ("c1_puntualidad" <= 5))),
    CONSTRAINT "chatter_scorecards_c2_calidad_chats_check" CHECK ((("c2_calidad_chats" >= 0) AND ("c2_calidad_chats" <= 5))),
    CONSTRAINT "chatter_scorecards_c3_cumplimiento_meta_check" CHECK ((("c3_cumplimiento_meta" >= 0) AND ("c3_cumplimiento_meta" <= 5))),
    CONSTRAINT "chatter_scorecards_c4_productividad_hubstaff_check" CHECK ((("c4_productividad_hubstaff" >= 0) AND ("c4_productividad_hubstaff" <= 5))),
    CONSTRAINT "chatter_scorecards_c5_actitud_disciplina_check" CHECK ((("c5_actitud_disciplina" >= 0) AND ("c5_actitud_disciplina" <= 5))),
    CONSTRAINT "chatter_scorecards_c6_gestion_estrategia_check" CHECK ((("c6_gestion_estrategia" >= 0) AND ("c6_gestion_estrategia" <= 5))),
    CONSTRAINT "chatter_scorecards_c7_scripts_check" CHECK ((("c7_scripts" >= 0) AND ("c7_scripts" <= 5))),
    CONSTRAINT "chatter_scorecards_c8_camara_pantalla_check" CHECK ((("c8_camara_pantalla" >= 0) AND ("c8_camara_pantalla" <= 5))),
    CONSTRAINT "chatter_scorecards_company_check" CHECK (("company" = ANY (ARRAY['CP'::"text", 'CM'::"text", 'CU'::"text"])))
);


