CREATE TABLE IF NOT EXISTS "public"."cowork_breaks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid" NOT NULL,
    "room_id" "uuid",
    "user_id" "uuid" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ended_at" timestamp with time zone,
    "auto_closed" boolean DEFAULT false NOT NULL,
    "duration_seconds" integer GENERATED ALWAYS AS (
CASE
    WHEN ("ended_at" IS NULL) THEN NULL::integer
    ELSE GREATEST(0, (EXTRACT(epoch FROM ("ended_at" - "started_at")))::integer)
END) STORED,
    "kind" "text" DEFAULT 'bano'::"text" NOT NULL,
    CONSTRAINT "cowork_breaks_kind_chk" CHECK (("kind" = ANY (ARRAY['bano'::"text", 'break'::"text", 'almuerzo'::"text"])))
);


ALTER TABLE "public"."cowork_breaks" OWNER TO "postgres";


COMMENT ON TABLE "public"."cowork_breaks" IS 'Historico de pausas de Cowork. Los timestamps los pone el servidor via la edge cowork-session (startBreak/endBreak). El estado EN VIVO va por presence.';



COMMENT ON COLUMN "public"."cowork_breaks"."auto_closed" IS 'La cerro el sistema por quedar colgada (la persona cerro la pestana). Excluir de los promedios.';



COMMENT ON COLUMN "public"."cowork_breaks"."kind" IS 'bano = salida corta; break = descanso largo. Cada uno con su limite en cowork_break_limits.';



