COMMENT ON TABLE "public"."cowork_llamados" IS 'Llamados de atención de Cowork (cámara, encuadre, luz, pantalla). Solo registro: todavía no afecta la nota. Escribe únicamente cowork-session con service_role; el resto tiene REVOKE de escritura. El edge descarta cualquier llamado que se solape con una pausa registrada.';



CREATE TABLE IF NOT EXISTS "public"."cowork_meet_participants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "meet_id" "uuid" NOT NULL,
    "session_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "room_id" "uuid",
    "joined_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "left_at" timestamp with time zone,
    "left_reason" "text",
    "duration_seconds" integer GENERATED ALWAYS AS (
CASE
    WHEN ("left_at" IS NULL) THEN NULL::integer
    ELSE (GREATEST((0)::numeric, EXTRACT(epoch FROM ("left_at" - "joined_at"))))::integer
END) STORED,
    CONSTRAINT "cowork_meet_participants_left_reason_check" CHECK (("left_reason" = ANY (ARRAY['volvio'::"text", 'meet_terminado'::"text", 'barrido'::"text"])))
);


