    CONSTRAINT "creadora_accesos_clave_completa" CHECK (((("of_clave_cifrada" IS NULL) AND ("of_clave_nonce" IS NULL) AND ("of_clave_version" IS NULL)) OR (("of_clave_cifrada" IS NOT NULL) AND ("of_clave_nonce" IS NOT NULL) AND ("of_clave_version" IS NOT NULL)))),
    CONSTRAINT "creadora_accesos_desde" CHECK (("actualizado_desde" = ANY (ARRAY['equipo'::"text", 'creadora'::"text", 'importador'::"text"]))),
