    CONSTRAINT "drive_items_check1" CHECK ((("tipo" = 'archivo'::"text") = ("storage_key" IS NOT NULL))),
    CONSTRAINT "drive_items_estado_check" CHECK (("estado" = ANY (ARRAY['subiendo'::"text", 'procesando'::"text", 'listo'::"text"]))),
    CONSTRAINT "drive_items_nombre_check" CHECK (((("length"("btrim"("nombre")) >= 1) AND ("length"("btrim"("nombre")) <= 255)) AND ("nombre" !~ '[/\\]'::"text"))),
    CONSTRAINT "drive_items_sha256_check" CHECK ((("sha256" IS NULL) OR ("sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "drive_items_size_check" CHECK ((("size" IS NULL) OR ("size" >= 0))),
    CONSTRAINT "drive_items_tipo_check" CHECK (("tipo" = ANY (ARRAY['carpeta'::"text", 'archivo'::"text"])))
);


ALTER TABLE "public"."drive_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."drive_items" IS 'Drive de Oficina: la ficha de cada archivo/carpeta. El contenido vive en el NAS (infra/nas-drive), en <tenant_id>/<id>. Sin copia de seguridad por decisión de Jhon (28/09/2026).';



COMMENT ON COLUMN "public"."drive_items"."storage_key" IS 'Ruta en el NAS. La pone SOLO la edge drive; el navegador no puede tocarla (trigger drive_items_cuidar).';



COMMENT ON COLUMN "public"."drive_items"."trashed_by" IS 'Quién mandó la ficha a la papelera («Eliminado por»). La pone el trigger drive_items_borrado_por; null si no está en la papelera o si se tiró antes del 03/10/2026.';



