CREATE TABLE IF NOT EXISTS "public"."integracion_equipo_entregas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "webhook_id" "uuid" NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "evento" "text" NOT NULL,
    "user_id" "uuid",
    "datos" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "body" "text" NOT NULL,
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "drop_reason" "text",
    "attempts" smallint DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_until" timestamp with time zone,
    "last_attempt_at" timestamp with time zone,
    "last_status_code" integer,
    "last_error" "text",
    "latency_ms" integer,
    "uncertain" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "delivered_at" timestamp with time zone,
    CONSTRAINT "integracion_equipo_entregas_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "integracion_equipo_entregas_body_check" CHECK (("octet_length"("body") <= 16384)),
    CONSTRAINT "integracion_equipo_entregas_descartada" CHECK ((("state" = 'dropped'::"text") = ("drop_reason" IS NOT NULL))),
    CONSTRAINT "integracion_equipo_entregas_drop_reason_check" CHECK (("drop_reason" = ANY (ARRAY['receiver_gone'::"text", 'receiver_failing'::"text", 'endpoint_paused'::"text", 'endpoint_disabled'::"text", 'test_failed'::"text"]))),
    CONSTRAINT "integracion_equipo_entregas_entregada" CHECK ((("state" = 'delivered'::"text") = ("delivered_at" IS NOT NULL))),
    CONSTRAINT "integracion_equipo_entregas_evento_check" CHECK (("evento" = ANY (ARRAY['equipo.persona_entro'::"text", 'equipo.persona_salio'::"text", 'equipo.rol_cambio'::"text", 'webhook.test'::"text"]))),
    CONSTRAINT "integracion_equipo_entregas_last_error_check" CHECK (("char_length"("last_error") <= 60)),
    CONSTRAINT "integracion_equipo_entregas_last_status_code_check" CHECK ((("last_status_code" >= 100) AND ("last_status_code" <= 999))),
    CONSTRAINT "integracion_equipo_entregas_latency_ms_check" CHECK (("latency_ms" >= 0)),
    CONSTRAINT "integracion_equipo_entregas_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'delivered'::"text", 'dropped'::"text"])))
);


ALTER TABLE "public"."integracion_equipo_entregas" OWNER TO "postgres";


COMMENT ON TABLE "public"."integracion_equipo_entregas" IS 'Avisos del equipo por webhook, uno por suscripción y evento. Se guardan 14 días.';



CREATE TABLE IF NOT EXISTS "public"."integracion_equipo_pendientes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "correo" "text" NOT NULL,
    "nombre" "text",
    "rol" "text",
    "nivel" "text",
    "equipo" "text",
    "reporta_a_correo" "text",
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "veces" integer DEFAULT 1 NOT NULL,
    "primera_vez" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ultima_vez" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "uuid",
    "resuelta_por" "uuid",
    "resuelta_at" timestamp with time zone,
    CONSTRAINT "integracion_equipo_pendientes_correo_check" CHECK ((("correo" = "lower"("correo")) AND (("char_length"("correo") >= 3) AND ("char_length"("correo") <= 254)))),
    CONSTRAINT "integracion_equipo_pendientes_equipo_check" CHECK ((("equipo" IS NULL) OR (("char_length"("equipo") >= 1) AND ("char_length"("equipo") <= 80)))),
    CONSTRAINT "integracion_equipo_pendientes_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'aprobada'::"text", 'descartada'::"text"]))),
    CONSTRAINT "integracion_equipo_pendientes_nivel_check" CHECK ((("nivel" IS NULL) OR ("nivel" = ANY (ARRAY['manager'::"text", 'supervisor'::"text", 'agente'::"text"])))),
    CONSTRAINT "integracion_equipo_pendientes_nombre_check" CHECK ((("nombre" IS NULL) OR ("char_length"("nombre") <= 200))),
    CONSTRAINT "integracion_equipo_pendientes_reporta_a_correo_check" CHECK ((("reporta_a_correo" IS NULL) OR ("char_length"("reporta_a_correo") <= 254))),
    CONSTRAINT "integracion_equipo_pendientes_resuelta" CHECK ((("estado" = 'pendiente'::"text") = ("resuelta_at" IS NULL))),
    CONSTRAINT "integracion_equipo_pendientes_rol_check" CHECK ((("rol" IS NULL) OR ("char_length"("rol") <= 100))),
    CONSTRAINT "integracion_equipo_pendientes_veces_check" CHECK (("veces" >= 1))
);


ALTER TABLE "public"."integracion_equipo_pendientes" OWNER TO "postgres";


COMMENT ON TABLE "public"."integracion_equipo_pendientes" IS 'Gente que manda la plataforma de la agencia y no tiene cuenta en Maven. El dueño o un admin la aprueba (crea la cuenta) o la descarta.';



