CREATE TABLE IF NOT EXISTS "public"."mail_connections" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "provider" "text" DEFAULT 'zoho'::"text" NOT NULL,
    "email_address" "text" NOT NULL,
    "zoho_account_id" "text",
    "refresh_token" "text" NOT NULL,
    "scopes" "text",
    "connected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_used_at" timestamp with time zone,
    "last_error" "text",
    "revoked_at" timestamp with time zone,
    CONSTRAINT "mail_connections_provider_chk" CHECK (("provider" = 'zoho'::"text"))
);


ALTER TABLE "public"."mail_connections" OWNER TO "postgres";


COMMENT ON TABLE "public"."mail_connections" IS 'OAuth por usuario contra Zoho Mail. refresh_token NO está en el GRANT de authenticated: solo service_role lo lee. El frontend usa v_my_mail_connection.';



COMMENT ON COLUMN "public"."mail_connections"."refresh_token" IS 'Secreto. Fuera del GRANT de authenticated a propósito — no agregarlo.';



CREATE TABLE IF NOT EXISTS "public"."mail_credentials" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "email_address" "text" NOT NULL,
    "secret_cipher" "text" NOT NULL,
    "secret_nonce" "text" NOT NULL,
    "key_version" smallint DEFAULT 1 NOT NULL,
    "imap_host" "text" DEFAULT 'imap.zoho.com'::"text" NOT NULL,
    "imap_port" integer DEFAULT 993 NOT NULL,
    "smtp_host" "text" DEFAULT 'smtp.zoho.com'::"text" NOT NULL,
    "smtp_port" integer DEFAULT 465 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_used_at" timestamp with time zone,
    "last_error" "text",
    "revoked_at" timestamp with time zone,
    "last_sync_at" timestamp with time zone
);


ALTER TABLE "public"."mail_credentials" OWNER TO "postgres";


COMMENT ON TABLE "public"."mail_credentials" IS 'Credencial IMAP/SMTP por usuario, cifrada con AES-GCM. La clave vive en el secret MAIL_CRED_KEY, NO en la base: un volcado de la base no alcanza para leerlas. secret_cipher/secret_nonce estan fuera del GRANT de authenticated.';



COMMENT ON COLUMN "public"."mail_credentials"."last_sync_at" IS 'Última revisión de la casilla por el worker mail-sync (latido, como mucho cada 5 min). NULL = no la revisó desde que existe la columna.';



