    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "color" "text" DEFAULT 'primary'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "parent_id" "uuid",
    "bg_color" "text",
    "text_color" "text",
    "en_lista_etiquetas" "text" DEFAULT 'mostrar'::"text" NOT NULL,
    "en_lista_mensajes" boolean DEFAULT true NOT NULL,
    CONSTRAINT "mail_labels_color_check" CHECK (("color" = ANY (ARRAY['primary'::"text", 'accent'::"text", 'success'::"text", 'warning'::"text", 'destructive'::"text", 'muted'::"text"]))),
    CONSTRAINT "mail_labels_color_par_chk" CHECK ((("bg_color" IS NULL) = ("text_color" IS NULL))),
    CONSTRAINT "mail_labels_en_lista_etiquetas_chk" CHECK (("en_lista_etiquetas" = ANY (ARRAY['mostrar'::"text", 'si_no_leidas'::"text", 'ocultar'::"text"]))),
    CONSTRAINT "mail_labels_hex_chk" CHECK (((("bg_color" IS NULL) OR ("bg_color" ~ '^#[0-9a-f]{6}$'::"text")) AND (("text_color" IS NULL) OR ("text_color" ~ '^#[0-9a-f]{6}$'::"text")))),
    CONSTRAINT "mail_labels_no_es_su_padre_chk" CHECK ((("parent_id" IS NULL) OR ("parent_id" <> "id"))),
    CONSTRAINT "mail_labels_nombre_check" CHECK ((("length"("btrim"("nombre")) >= 1) AND ("length"("btrim"("nombre")) <= 225)))
);


ALTER TABLE "public"."mail_labels" OWNER TO "postgres";


COMMENT ON COLUMN "public"."mail_labels"."color" IS 'OBSOLETA desde 28/09 (la lee solo el frontend anterior). El color vive en bg_color/text_color.';



COMMENT ON COLUMN "public"."mail_labels"."parent_id" IS 'Etiqueta madre (subetiquetas). Borrar la madre borra las hijas, como en Gmail.';



COMMENT ON COLUMN "public"."mail_labels"."bg_color" IS 'Fondo de la etiqueta, hex de la paleta de Gmail. NULL junto con text_color = sin color.';



