CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "full_name" "text",
    "avatar_url" "text",
    "company_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "phone_e164" "text",
    "whatsapp_push_name" "text",
    "whatsapp_verified_at" timestamp with time zone,
    "whatsapp_lid" "text",
    "is_owner" boolean DEFAULT false NOT NULL,
    "ai_daily_quota_override" integer,
    "avatar_seed" "text",
    "ui_skin" "text",
    "ui_prefs" "jsonb",
    "status_text" "text",
    "status_expires_at" timestamp with time zone,
    "status" "text",
    "status_color" "text",
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    "nivel" "text",
    "exonera_camara_pantalla" boolean DEFAULT false NOT NULL,
    "hora_entrada" time without time zone,
    "hora_salida" time without time zone,
    "comida_min" integer,
    "bano_min" integer,
    "turno_id" "uuid",
    CONSTRAINT "profiles_nivel_check" CHECK (("nivel" = ANY (ARRAY['dueno'::"text", 'admin'::"text", 'manager'::"text", 'supervisor'::"text", 'agente'::"text"]))),
    CONSTRAINT "profiles_phone_e164_format" CHECK ((("phone_e164" IS NULL) OR ("phone_e164" ~ '^\+[0-9]{8,16}$'::"text"))),
    CONSTRAINT "profiles_status_color_valido" CHECK ((("status_color" IS NULL) OR ("status_color" = ANY (ARRAY['verde'::"text", 'amarillo'::"text", 'naranja'::"text", 'rojo'::"text", 'rosa'::"text", 'morado'::"text", 'azul'::"text", 'turquesa'::"text"])))),
    CONSTRAINT "profiles_status_valido" CHECK ((("status" IS NULL) OR ("status" = ANY (ARRAY['available'::"text", 'busy'::"text", 'away'::"text", 'offline'::"text"]))))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON COLUMN "public"."profiles"."phone_e164" IS 'Número de WhatsApp del user en formato E.164 (ej. +5491112345678). Self-service via Settings → Mi cuenta. Usado por whatsapp-ingest para auto-linkear whatsapp_members.user_id cuando llega un mensaje del grupo.';



COMMENT ON COLUMN "public"."profiles"."whatsapp_push_name" IS 'Nombre que aparece en WhatsApp del user (pushName), capturado cuando el bot recibe la confirmación SI por DM. Usado por whatsapp-ingest para auto-linkear wpp_members en grupos.';



COMMENT ON COLUMN "public"."profiles"."whatsapp_verified_at" IS 'Timestamp de cuando el user confirmó por DM que el phone_e164 es suyo. NULL = todavía no verificó.';



COMMENT ON COLUMN "public"."profiles"."is_owner" IS 'Si true, el bot de WhatsApp ajusta su respuesta cuando este user habla: tono más resumido, bullets, prioridad de respuesta. No otorga permisos extra — para eso está user_roles.';



COMMENT ON COLUMN "public"."profiles"."ai_daily_quota_override" IS 'Override de cuota diaria de IA para este usuario (gana sobre la del rol). NULL = usar la del rol.';



COMMENT ON COLUMN "public"."profiles"."ui_skin" IS 'Skin de acento de la UI elegido en Settings → Apariencia (maven/atardecer/esmeralda/orquidea/medianoche). NULL = default maven.';



COMMENT ON COLUMN "public"."profiles"."ui_prefs" IS 'Preferencias de apariencia de la UI (Settings → Apariencia): {oled, contrast, customHue, seasonalOptOut}. NULL = defaults.';



COMMENT ON COLUMN "public"."profiles"."status_text" IS 'Estado personalizado del Messenger (texto libre, max 64 en la UI). NULL = sin estado.';



COMMENT ON COLUMN "public"."profiles"."status_expires_at" IS 'Cuando se limpia solo el status_text. NULL = no expira. Al leer, si ya paso se trata como vacio.';



COMMENT ON COLUMN "public"."profiles"."status" IS 'Luz del estado: available | busy | dnd | away. NULL = disponible. La presencia sigue mandando el valor en vivo (y forzando away con la pestaña en segundo plano); esto es solo para que sobreviva a la recarga.';



COMMENT ON COLUMN "public"."profiles"."status_color" IS 'Color del puntito elegido en el estado personalizado. NULL = usa el color de `status`. Clave de paleta, no un hex, para que no entre CSS arbitrario.';



COMMENT ON COLUMN "public"."profiles"."deleted_at" IS 'Cuenta suspendida (papelera de 30 días). NULL = activa. La purga real la hace el cron.';



