    "contact_type" "text",
    "evidence_url" "text",
    "action_taken" "text",
    "created_by" "uuid",
    "tenant_id" "uuid" DEFAULT "public"."current_tenant_id"() NOT NULL,
    "apify_run_id" "text",
    "dispatch_run_id" "uuid",
    "analyzed_by_ai" boolean DEFAULT false NOT NULL,
    "ai_model" "text",
