CREATE OR REPLACE VIEW "public"."v_agencies" AS
 SELECT "id",
    "name",
    "contact_name",
    "website",
    "country_code",
    "status",
    "notes",
    "created_by",
    "created_at",
    "updated_at",
        CASE
            WHEN "public"."is_phone_privileged"() THEN "phone"
            ELSE "public"."mask_phone"("phone")
        END AS "phone",
        CASE
            WHEN "public"."is_phone_privileged"() THEN "email"
            ELSE "public"."mask_email"("email")
        END AS "email"
   FROM "public"."agencies";


ALTER VIEW "public"."v_agencies" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_chatter_anomalies" WITH ("security_invoker"='true') AS
 WITH "d" AS (
         SELECT "cp"."blu_employee_id",
            "cp"."name",
            ("date_trunc"('month'::"text", ("dd"."date")::timestamp with time zone))::"date" AS "period",
            "dd"."date",
            "round"((("dd"."tracked_seconds")::numeric / 3600.0), 1) AS "hours",
            "dd"."overall_activity" AS "act"
           FROM (("public"."hubstaff_daily_data" "dd"
             JOIN "public"."hubstaff_members" "hm" ON (("hm"."hubstaff_user_id" = "dd"."hubstaff_user_id")))
             JOIN "public"."chatter_performance" "cp" ON ((("lower"("btrim"("cp"."email")) = "lower"("btrim"("hm"."email"))) AND ("cp"."is_chatter" = true))))
          WHERE (("dd"."tracked_seconds" > 0) AND ("cp"."blu_employee_id" IS NOT NULL) AND "public"."has_role"("hm"."profile_id", 'Chatter'::"text"))
        )
 SELECT "blu_employee_id",
    "name",
    "period",
    "date",
    "hours",
    "act",
        CASE
            WHEN (("hours" >= (2)::numeric) AND ("act" < 35)) THEN 'baja_actividad'::"text"
            WHEN ("hours" > (12)::numeric) THEN 'dia_largo'::"text"
            ELSE 'dia_corto'::"text"
        END AS "tipo"
   FROM "d"
  WHERE ((("hours" >= (2)::numeric) AND ("act" < 35)) OR ("hours" > (12)::numeric) OR ("hours" < 2.5));


ALTER VIEW "public"."v_chatter_anomalies" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_chatter_attendance" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "cp"."blu_employee_id",
            "cp"."name",
            ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone))::"date" AS "period",
            "d"."date",
            (((EXTRACT(hour FROM ("d"."first_activity_at" AT TIME ZONE 'America/Bogota'::"text")) * (60)::numeric) + EXTRACT(minute FROM ("d"."first_activity_at" AT TIME ZONE 'America/Bogota'::"text"))))::integer AS "mod"
           FROM (("public"."hubstaff_daily_data" "d"
             JOIN "public"."hubstaff_members" "hm" ON (("hm"."hubstaff_user_id" = "d"."hubstaff_user_id")))
             JOIN "public"."chatter_performance" "cp" ON ((("lower"("btrim"("cp"."email")) = "lower"("btrim"("hm"."email"))) AND ("cp"."is_chatter" = true))))
          WHERE (("d"."first_activity_at" IS NOT NULL) AND ("cp"."blu_employee_id" IS NOT NULL) AND "public"."has_role"("hm"."profile_id", 'Chatter'::"text"))
        ), "perday" AS (
         SELECT "base"."blu_employee_id",
            "base"."name",
            "base"."period",
            "base"."date",
            "base"."mod",
                CASE
                    WHEN ((LEAST("base"."mod", (1440 - "base"."mod")) <= "abs"(("base"."mod" - 480))) AND (LEAST("base"."mod", (1440 - "base"."mod")) <= "abs"(("base"."mod" - 960)))) THEN 0
                    WHEN ("abs"(("base"."mod" - 480)) <= "abs"(("base"."mod" - 960))) THEN 480
                    ELSE 960
                END AS "nearest_shift"
           FROM "base"
        ), "shift_rank" AS (
         SELECT "perday"."blu_employee_id",
            "perday"."period",
            "perday"."nearest_shift",
            "row_number"() OVER (PARTITION BY "perday"."blu_employee_id", "perday"."period" ORDER BY ("count"(*)) DESC, "perday"."nearest_shift") AS "rn"
           FROM "perday"
          GROUP BY "perday"."blu_employee_id", "perday"."period", "perday"."nearest_shift"
        ), "chatter_shift" AS (
         SELECT "shift_rank"."blu_employee_id",
            "shift_rank"."period",
            "shift_rank"."nearest_shift" AS "shift_start"
           FROM "shift_rank"
          WHERE ("shift_rank"."rn" = 1)
        ), "perday2" AS (
         SELECT "p"."blu_employee_id",
            "p"."name",
            "p"."period",
            "p"."date",
            "p"."mod",
            "p"."nearest_shift",
            "cs"."shift_start",
            (((("p"."mod" - "cs"."shift_start") + 720) % 1440) - 720) AS "dev"
           FROM ("perday" "p"
             JOIN "chatter_shift" "cs" ON ((("cs"."blu_employee_id" = "p"."blu_employee_id") AND ("cs"."period" = "p"."period"))))
        )
 SELECT "blu_employee_id",
    "name",
    "period",
    "shift_start",
        CASE "shift_start"
            WHEN 0 THEN 'Madrugada · 12am–8am'::"text"
            WHEN 480 THEN 'Mañana · 8am–4pm'::"text"
            WHEN 960 THEN 'Tarde · 4pm–12am'::"text"
            ELSE NULL::"text"
        END AS "turno",
    "count"(*) AS "dias",
    (((("shift_start" + ("round"("avg"("dev")))::integer) % 1440) + 1440) % 1440) AS "checkin_prom_min",
    "count"(*) FILTER (WHERE ("dev" > 10)) AS "tardanzas",
    ("round"(((100.0 * ("count"(*) FILTER (WHERE ("dev" <= 10)))::numeric) / ("count"(*))::numeric)))::integer AS "pct_a_tiempo",
    ("round"("avg"("dev") FILTER (WHERE ("dev" > 10))))::integer AS "min_tarde_prom"
   FROM "perday2"
  GROUP BY "blu_employee_id", "name", "period", "shift_start";


ALTER VIEW "public"."v_chatter_attendance" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_chatter_hubstaff_monthly" WITH ("security_invoker"='true') AS
 SELECT "cp"."blu_employee_id",
    "cp"."name",
    ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone))::"date" AS "period",
    "count"(*) AS "days_tracked",
    "round"((("sum"("d"."tracked_seconds"))::numeric / 3600.0), 1) AS "total_hours",
    ("round"("avg"("d"."overall_activity")))::integer AS "avg_activity_pct"
   FROM (("public"."hubstaff_daily_data" "d"
     JOIN "public"."hubstaff_members" "hm" ON (("hm"."hubstaff_user_id" = "d"."hubstaff_user_id")))
     JOIN "public"."chatter_performance" "cp" ON ((("lower"("btrim"("cp"."email")) = "lower"("btrim"("hm"."email"))) AND ("cp"."is_chatter" = true))))
  WHERE (("d"."tracked_seconds" > 0) AND ("cp"."blu_employee_id" IS NOT NULL) AND "public"."has_role"("hm"."profile_id", 'Chatter'::"text"))
  GROUP BY "cp"."blu_employee_id", "cp"."name", ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone));


ALTER VIEW "public"."v_chatter_hubstaff_monthly" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_chatter_hubstaff_effort" WITH ("security_invoker"='true') AS
 WITH "ds_month" AS (
         SELECT "chatter_daily_sales"."blu_employee_id",
            ("date_trunc"('month'::"text", ("chatter_daily_sales"."date")::timestamp with time zone))::"date" AS "period",
            "sum"("chatter_daily_sales"."total_sales") AS "sales"
           FROM "public"."chatter_daily_sales"
          GROUP BY "chatter_daily_sales"."blu_employee_id", (("date_trunc"('month'::"text", ("chatter_daily_sales"."date")::timestamp with time zone))::"date")
        )
 SELECT "h"."blu_employee_id",
    "h"."name",
    "h"."period",
    "h"."days_tracked",
    "h"."total_hours",
    "h"."avg_activity_pct",
    ("round"("s"."sales"))::integer AS "sales",
    ("round"(("s"."sales" / NULLIF("h"."total_hours", (0)::numeric))))::integer AS "sales_per_hour",
    ("round"(("cp"."avg_response_seconds" / 60.0)))::integer AS "avg_response_min",
    "cp"."unlock_rate",
    "cp"."sold_messages",
    "cp"."fans_chatted",
    (("h"."total_hours" >= (25)::numeric) AND ("h"."avg_activity_pct" >= 50) AND ("round"(("s"."sales" / NULLIF("h"."total_hours", (0)::numeric))) < (15)::numeric)) AS "online_improductivo",
    ("round"(("cfg"."base_salary_cop" / NULLIF("cfg"."fx_cop_per_usd", (0)::numeric))))::integer AS "cost_usd",
    ("round"(((("s"."sales" * "cfg"."of_net_factor") * "cfg"."effective_agency_rate") / 100.0)))::integer AS "agency_revenue_usd",
    ("round"((((("s"."sales" * "cfg"."of_net_factor") * "cfg"."effective_agency_rate") / 100.0) - ("cfg"."base_salary_cop" / NULLIF("cfg"."fx_cop_per_usd", (0)::numeric)))))::integer AS "margin_usd",
    "round"((((("s"."sales" * "cfg"."of_net_factor") * "cfg"."effective_agency_rate") / 100.0) / NULLIF(("cfg"."base_salary_cop" / NULLIF("cfg"."fx_cop_per_usd", (0)::numeric)), (0)::numeric)), 2) AS "roi_x",
    (("s"."sales" > (0)::numeric) AND (((("s"."sales" * "cfg"."of_net_factor") * "cfg"."effective_agency_rate") / 100.0) < ("cfg"."base_salary_cop" / NULLIF("cfg"."fx_cop_per_usd", (0)::numeric)))) AS "no_rentable",
    "cfg"."effective_agency_rate" AS "agency_rate_used",
    ("s"."sales" = (0)::numeric) AS "sin_venta_blu"
   FROM (((("public"."v_chatter_hubstaff_monthly" "h"
     JOIN "public"."chatter_performance" "cp" ON (("cp"."blu_employee_id" = "h"."blu_employee_id")))
     LEFT JOIN "public"."chatter_cost_config" "cfg" ON (("cfg"."id" = true)))
     LEFT JOIN "ds_month" ON ((("ds_month"."blu_employee_id" = "h"."blu_employee_id") AND ("ds_month"."period" = "h"."period"))))
     CROSS JOIN LATERAL ( SELECT COALESCE("ds_month"."sales", "cp"."total_sales", (0)::numeric) AS "sales") "s");


ALTER VIEW "public"."v_chatter_hubstaff_effort" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_closer_hubstaff" WITH ("security_invoker"='true') AS
 WITH "cl" AS (
         SELECT "hm"."profile_id",
            "hm"."name",
            "hm"."hubstaff_user_id"
           FROM "public"."hubstaff_members" "hm"
          WHERE "public"."has_role"("hm"."profile_id", 'closer'::"text")
        ), "hs" AS (
         SELECT "cl"."profile_id",
            "cl"."name",
            ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone))::"date" AS "period",
            "count"(*) AS "dias",
            "round"((("sum"("d"."tracked_seconds"))::numeric / 3600.0), 1) AS "total_hours",
            ("round"("avg"("d"."overall_activity")))::integer AS "avg_activity_pct"
           FROM ("cl"
             JOIN "public"."hubstaff_daily_data" "d" ON (("d"."hubstaff_user_id" = "cl"."hubstaff_user_id")))
          WHERE ("d"."tracked_seconds" > 0)
          GROUP BY "cl"."profile_id", "cl"."name", ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone))
        ), "pipe" AS (
         SELECT "closer_creators"."assigned_to",
            "count"(*) AS "leads",
            "count"(*) FILTER (WHERE ("closer_creators"."stage" = ANY (ARRAY['Confirmada'::"text", 'Completada'::"text"]))) AS "cerradas",
            ("round"(COALESCE("sum"("closer_creators"."monthly_monetization") FILTER (WHERE ("closer_creators"."stage" = ANY (ARRAY['Confirmada'::"text", 'Completada'::"text"]))), (0)::numeric)))::integer AS "monetizacion_usd"
           FROM "public"."closer_creators"
          WHERE ("closer_creators"."assigned_to" IS NOT NULL)
          GROUP BY "closer_creators"."assigned_to"
        ), "qa" AS (
         SELECT "qa_calls"."closer_id",
            "count"(*) AS "qa_calls",
            ("round"("avg"("qa_calls"."claude_score")))::integer AS "avg_qa_score"
           FROM "public"."qa_calls"
          WHERE ("qa_calls"."closer_id" IS NOT NULL)
          GROUP BY "qa_calls"."closer_id"
        )
 SELECT "hs"."name",
    "hs"."period",
    "hs"."dias",
    "hs"."total_hours",
    "hs"."avg_activity_pct",
    COALESCE("pipe"."leads", (0)::bigint) AS "leads",
    COALESCE("pipe"."cerradas", (0)::bigint) AS "cerradas",
    COALESCE("pipe"."monetizacion_usd", 0) AS "monetizacion_usd",
    ("round"(((COALESCE("pipe"."monetizacion_usd", 0))::numeric / NULLIF("hs"."total_hours", (0)::numeric))))::integer AS "usd_por_hora",
    COALESCE("qa"."qa_calls", (0)::bigint) AS "qa_calls",
    "qa"."avg_qa_score",
    (("hs"."total_hours" >= (20)::numeric) AND (COALESCE("pipe"."cerradas", (0)::bigint) = 0)) AS "sin_cierres"
   FROM (("hs"
     LEFT JOIN "pipe" ON (("pipe"."assigned_to" = "hs"."profile_id")))
     LEFT JOIN "qa" ON (("qa"."closer_id" = "hs"."profile_id")));


