CREATE OR REPLACE VIEW "public"."v_qa_staff" WITH ("security_invoker"='true') AS
 SELECT "id" AS "profile_id",
    "full_name" AS "name",
    ( SELECT "ur"."role"
           FROM "public"."user_roles" "ur"
          WHERE ("ur"."user_id" = "p"."id")
          ORDER BY
                CASE "ur"."role"
                    WHEN 'admin'::"text" THEN 1
                    WHEN 'owner'::"text" THEN 1
                    WHEN 'manager'::"text" THEN 2
                    WHEN 'Chatter Supervisor'::"text" THEN 3
                    WHEN 'Team Leader'::"text" THEN 3
                    WHEN 'closer'::"text" THEN 4
                    WHEN 'Chatter'::"text" THEN 5
                    WHEN 'LLG'::"text" THEN 6
                    ELSE 9
                END, "ur"."role"
         LIMIT 1) AS "role",
    (EXISTS ( SELECT 1
           FROM "public"."hubstaff_members" "hm"
          WHERE ("hm"."profile_id" = "p"."id"))) AS "in_hubstaff"
   FROM "public"."profiles" "p"
  WHERE (EXISTS ( SELECT 1
           FROM "public"."user_roles" "ur"
          WHERE ("ur"."user_id" = "p"."id")));


