CREATE OR REPLACE VIEW "public"."v_hr_payroll" WITH ("security_invoker"='true') AS
 WITH "cfg" AS (
         SELECT "chatter_cost_config"."fx_cop_per_usd" AS "fx"
           FROM "public"."chatter_cost_config"
         LIMIT 1
        ), "ch" AS (
         SELECT DISTINCT ON (("lower"("v_chatter_hubstaff_effort"."name"))) "lower"("v_chatter_hubstaff_effort"."name") AS "lname",
            "v_chatter_hubstaff_effort"."cost_usd",
            "v_chatter_hubstaff_effort"."agency_revenue_usd",
            "v_chatter_hubstaff_effort"."margin_usd",
            "v_chatter_hubstaff_effort"."roi_x"
           FROM "public"."v_chatter_hubstaff_effort"
          ORDER BY ("lower"("v_chatter_hubstaff_effort"."name")), "v_chatter_hubstaff_effort"."period" DESC
        )
 SELECT "r"."profile_id",
    "r"."name",
    "r"."role",
    "r"."in_hubstaff",
    COALESCE("rc"."base_salary_cop", (0)::numeric) AS "base_salary_cop",
    COALESCE((
        CASE
            WHEN ("r"."role" = 'Chatter'::"text") THEN "ch"."cost_usd"
            ELSE NULL::integer
        END)::numeric, "round"((COALESCE("rc"."base_salary_cop", (0)::numeric) / NULLIF(( SELECT "cfg"."fx"
           FROM "cfg"), (0)::numeric)), 0)) AS "cost_usd",
        CASE
            WHEN ("r"."role" = 'Chatter'::"text") THEN "ch"."agency_revenue_usd"
            ELSE NULL::integer
        END AS "revenue_usd",
        CASE
            WHEN ("r"."role" = 'Chatter'::"text") THEN "ch"."margin_usd"
            ELSE NULL::integer
        END AS "margin_usd",
        CASE
            WHEN ("r"."role" = 'Chatter'::"text") THEN "ch"."roi_x"
            ELSE NULL::numeric
        END AS "roi_x",
    (("r"."role" = 'Chatter'::"text") AND ("ch"."lname" IS NOT NULL)) AS "cost_modelado"
   FROM (("public"."v_hr_roster" "r"
     LEFT JOIN "public"."hr_role_cost" "rc" ON (("rc"."role" = "r"."role")))
     LEFT JOIN "ch" ON (("ch"."lname" = "lower"("r"."name"))));


ALTER VIEW "public"."v_hr_payroll" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_qa_effort" WITH ("security_invoker"='true') AS
 WITH "mem" AS (
         SELECT "hm"."hubstaff_user_id",
            "hm"."profile_id",
            "hm"."name",
                CASE
                    WHEN "public"."has_role"("hm"."profile_id", 'Chatter'::"text") THEN 'Chatter'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'closer'::"text") THEN 'closer'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'manager'::"text") THEN 'manager'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'LLG'::"text") THEN 'LLG'::"text"
                    ELSE NULL::"text"
                END AS "role"
           FROM "public"."hubstaff_members" "hm"
          WHERE (("hm"."profile_id" IS NOT NULL) AND ("public"."has_role"("hm"."profile_id", 'Chatter'::"text") OR "public"."has_role"("hm"."profile_id", 'closer'::"text") OR "public"."has_role"("hm"."profile_id", 'manager'::"text") OR "public"."has_role"("hm"."profile_id", 'LLG'::"text")))
        )
 SELECT "m"."hubstaff_user_id",
    "m"."profile_id",
    "m"."name",
    "m"."role",
    ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone))::"date" AS "period",
    "count"(*) AS "dias",
    "round"((("sum"("d"."tracked_seconds"))::numeric / 3600.0), 1) AS "total_hours",
    ("round"("avg"("d"."overall_activity")))::integer AS "avg_activity_pct"
   FROM ("mem" "m"
     JOIN "public"."hubstaff_daily_data" "d" ON (("d"."hubstaff_user_id" = "m"."hubstaff_user_id")))
  WHERE ("d"."tracked_seconds" > 0)
  GROUP BY "m"."hubstaff_user_id", "m"."profile_id", "m"."name", "m"."role", ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone));


ALTER VIEW "public"."v_qa_effort" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_llg_hubstaff" WITH ("security_invoker"='true') AS
 SELECT "e"."name",
    "e"."period",
    "e"."dias",
    "e"."total_hours",
    "e"."avg_activity_pct",
    COALESCE("l"."leads", (0)::bigint) AS "leads",
    "round"(((COALESCE("l"."leads", (0)::bigint))::numeric / NULLIF("e"."total_hours", (0)::numeric)), 1) AS "leads_por_hora"
   FROM ("public"."v_qa_effort" "e"
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "leads"
           FROM "public"."leadgen_entries" "le"
          WHERE (("le"."lg_user_id" = "e"."profile_id") AND ("date_trunc"('month'::"text", "le"."created_at") = "e"."period"))) "l" ON (true))
  WHERE ("e"."role" = 'LLG'::"text");


ALTER VIEW "public"."v_llg_hubstaff" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_model_phone_captures" WITH ("security_invoker"='true') AS
 WITH "all_captures" AS (
         SELECT 'leadgen_entries'::"text" AS "source_table",
            ("leadgen_entries"."id")::"text" AS "source_id",
            "lower"(COALESCE("leadgen_entries"."model_handle", ''::"text")) AS "handle",
            "regexp_replace"(COALESCE("leadgen_entries"."phone_e164", ''::"text"), '[^0-9+]'::"text", ''::"text", 'g'::"text") AS "phone_norm",
            "leadgen_entries"."phone_e164" AS "phone",
            "leadgen_entries"."phone_first_set_at" AS "captured_at"
           FROM "public"."leadgen_entries"
          WHERE ("leadgen_entries"."phone_first_set_at" IS NOT NULL)
        UNION ALL
         SELECT 'scouter_leads'::"text",
            ("scouter_leads"."id")::"text" AS "id",
            "lower"(COALESCE("scouter_leads"."instagram_handle", ''::"text")) AS "lower",
            "regexp_replace"(COALESCE("scouter_leads"."phone", ''::"text"), '[^0-9+]'::"text", ''::"text", 'g'::"text") AS "regexp_replace",
            "scouter_leads"."phone",
            "scouter_leads"."phone_first_set_at"
           FROM "public"."scouter_leads"
          WHERE ("scouter_leads"."phone_first_set_at" IS NOT NULL)
        UNION ALL
         SELECT 'closer_creators'::"text",
            ("closer_creators"."id")::"text" AS "id",
            "lower"(COALESCE("closer_creators"."instagram_handle", ''::"text")) AS "lower",
            "regexp_replace"(COALESCE("closer_creators"."phone", ''::"text"), '[^0-9+]'::"text", ''::"text", 'g'::"text") AS "regexp_replace",
            "closer_creators"."phone",
            "closer_creators"."phone_first_set_at"
           FROM "public"."closer_creators"
          WHERE ("closer_creators"."phone_first_set_at" IS NOT NULL)
        UNION ALL
         SELECT 'closers_contacts'::"text",
            ("closers_contacts"."id")::"text" AS "id",
            "lower"(COALESCE("closers_contacts"."handle", ''::"text")) AS "lower",
            "regexp_replace"(COALESCE("closers_contacts"."phone", ''::"text"), '[^0-9+]'::"text", ''::"text", 'g'::"text") AS "regexp_replace",
            "closers_contacts"."phone",
            "closers_contacts"."phone_first_set_at"
           FROM "public"."closers_contacts"
          WHERE ("closers_contacts"."phone_first_set_at" IS NOT NULL)
        UNION ALL
         SELECT 'creators'::"text",
            ("creators"."id")::"text" AS "id",
            "lower"(COALESCE("creators"."instagram_handle", ''::"text")) AS "lower",
            "regexp_replace"(COALESCE("creators"."phone", ''::"text"), '[^0-9+]'::"text", ''::"text", 'g'::"text") AS "regexp_replace",
            "creators"."phone",
            "creators"."phone_first_set_at"
           FROM "public"."creators"
          WHERE ("creators"."phone_first_set_at" IS NOT NULL)
        )
 SELECT DISTINCT ON ("handle", "phone_norm") "source_table",
    "source_id",
    "handle",
    "phone",
    "phone_norm",
    "captured_at"
   FROM "all_captures"
  WHERE ("phone_norm" <> ''::"text")
  ORDER BY "handle", "phone_norm", "captured_at";


ALTER VIEW "public"."v_model_phone_captures" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_model_phone_captures" IS 'Capturas de teléfono únicas por (modelo, número) cross-table. Una entrada por modelo+phone, con la fecha de la primera captura. Usar para el dashboard "Números obtenidos".';



