CREATE OR REPLACE VIEW "public"."v_qa_anomalies" WITH ("security_invoker"='true') AS
 WITH "mem" AS (
         SELECT "hm"."hubstaff_user_id",
            "hm"."name",
                CASE
                    WHEN "public"."has_role"("hm"."profile_id", 'Chatter'::"text") THEN 'Chatter'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'closer'::"text") THEN 'closer'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'manager'::"text") THEN 'manager'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'LLG'::"text") THEN 'LLG'::"text"
                    ELSE NULL::"text"
                END AS "role"
           FROM "public"."hubstaff_members" "hm"
          WHERE (("hm"."profile_id" IS NOT NULL) AND ("public"."has_role"("hm"."profile_id", 'Chatter'::"text") OR "public"."has_role"("hm"."profile_id", 'closer'::"text") OR "public"."has_role"("hm"."profile_id", 'manager'::"text") OR "public"."has_role"("hm"."profile_id", 'LLG'::"text")))
        ), "d" AS (
         SELECT "m"."hubstaff_user_id",
            "m"."name",
            "m"."role",
            ("date_trunc"('month'::"text", ("dd"."date")::timestamp with time zone))::"date" AS "period",
            "dd"."date",
            "round"((("dd"."tracked_seconds")::numeric / 3600.0), 1) AS "hours",
            "dd"."overall_activity" AS "act"
           FROM ("mem" "m"
             JOIN "public"."hubstaff_daily_data" "dd" ON (("dd"."hubstaff_user_id" = "m"."hubstaff_user_id")))
          WHERE ("dd"."tracked_seconds" > 0)
        )
 SELECT "hubstaff_user_id",
    "name",
    "role",
    "period",
    "date",
    "hours",
    "act",
        CASE
            WHEN (("role" = ANY (ARRAY['Chatter'::"text", 'LLG'::"text"])) AND ("hours" >= (2)::numeric) AND ("act" < 35)) THEN 'baja_actividad'::"text"
            WHEN ("hours" > (12)::numeric) THEN 'dia_largo'::"text"
            ELSE 'dia_corto'::"text"
        END AS "tipo"
   FROM "d"
  WHERE ((("role" = ANY (ARRAY['Chatter'::"text", 'LLG'::"text"])) AND ("hours" >= (2)::numeric) AND ("act" < 35)) OR ("hours" > (12)::numeric) OR ("hours" < 2.5));


ALTER VIEW "public"."v_qa_anomalies" OWNER TO "postgres";


