);


ALTER TABLE "public"."whatsapp_user_schedules" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_qa_attendance" WITH ("security_invoker"='true') AS
 WITH "mem" AS (
         SELECT "hm"."hubstaff_user_id",
            "hm"."profile_id",
            "hm"."name",
                CASE
                    WHEN "public"."has_role"("hm"."profile_id", 'Chatter'::"text") THEN 'Chatter'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'closer'::"text") THEN 'closer'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'manager'::"text") THEN 'manager'::"text"
                    WHEN "public"."has_role"("hm"."profile_id", 'LLG'::"text") THEN 'LLG'::"text"
                    ELSE NULL::"text"
                END AS "role"
           FROM "public"."hubstaff_members" "hm"
          WHERE (("hm"."profile_id" IS NOT NULL) AND ("public"."has_role"("hm"."profile_id", 'Chatter'::"text") OR "public"."has_role"("hm"."profile_id", 'closer'::"text") OR "public"."has_role"("hm"."profile_id", 'manager'::"text") OR "public"."has_role"("hm"."profile_id", 'LLG'::"text")))
        ), "base" AS (
         SELECT "m"."hubstaff_user_id",
            "m"."profile_id",
            "m"."name",
            "m"."role",
            ("date_trunc"('month'::"text", ("d"."date")::timestamp with time zone))::"date" AS "period",
            "d"."date",
            (EXTRACT(isodow FROM "d"."date"))::integer AS "dow",
            (((EXTRACT(hour FROM ("d"."first_activity_at" AT TIME ZONE 'America/Bogota'::"text")) * (60)::numeric) + EXTRACT(minute FROM ("d"."first_activity_at" AT TIME ZONE 'America/Bogota'::"text"))))::integer AS "mod"
           FROM ("mem" "m"
             JOIN "public"."hubstaff_daily_data" "d" ON (("d"."hubstaff_user_id" = "m"."hubstaff_user_id")))
          WHERE ("d"."first_activity_at" IS NOT NULL)
        ), "sched" AS (
         SELECT "whatsapp_user_schedules"."user_id",
            "whatsapp_user_schedules"."weekday",
            (((EXTRACT(hour FROM "whatsapp_user_schedules"."start_time") * (60)::numeric) + EXTRACT(minute FROM "whatsapp_user_schedules"."start_time")))::integer AS "sched_start"
           FROM "public"."whatsapp_user_schedules"
          WHERE ("whatsapp_user_schedules"."start_time" IS NOT NULL)
        ), "perday" AS (
         SELECT "base"."hubstaff_user_id",
            "base"."profile_id",
            "base"."name",
            "base"."role",
            "base"."period",
            "base"."date",
            "base"."dow",
            "base"."mod",
                CASE
                    WHEN ((LEAST("base"."mod", (1440 - "base"."mod")) <= "abs"(("base"."mod" - 480))) AND (LEAST("base"."mod", (1440 - "base"."mod")) <= "abs"(("base"."mod" - 960)))) THEN 0
                    WHEN ("abs"(("base"."mod" - 480)) <= "abs"(("base"."mod" - 960))) THEN 480
                    ELSE 960
                END AS "nearest_shift"
           FROM "base"
        ), "shift_rank" AS (
         SELECT "perday"."hubstaff_user_id",
            "perday"."role",
            "perday"."period",
            "perday"."nearest_shift",
            "row_number"() OVER (PARTITION BY "perday"."hubstaff_user_id", "perday"."role", "perday"."period" ORDER BY ("count"(*)) DESC, "perday"."nearest_shift") AS "rn"
           FROM "perday"
          GROUP BY "perday"."hubstaff_user_id", "perday"."role", "perday"."period", "perday"."nearest_shift"
        ), "cs" AS (
         SELECT "shift_rank"."hubstaff_user_id",
            "shift_rank"."role",
            "shift_rank"."period",
            "shift_rank"."nearest_shift" AS "shift_start"
           FROM "shift_rank"
          WHERE ("shift_rank"."rn" = 1)
        ), "perday2" AS (
         SELECT "p"."hubstaff_user_id",
            "p"."profile_id",
            "p"."name",
            "p"."role",
            "p"."period",
            "p"."date",
            "p"."dow",
            "p"."mod",
            "p"."nearest_shift",
            "cs"."shift_start" AS "cluster_start",
            ("s"."sched_start" IS NOT NULL) AS "from_sched",
            (((("p"."mod" - COALESCE("s"."sched_start", "cs"."shift_start")) + 720) % 1440) - 720) AS "dev",
            (((("p"."mod" - "cs"."shift_start") + 720) % 1440) - 720) AS "dev_cluster"
           FROM (("perday" "p"
             LEFT JOIN "cs" ON ((("cs"."hubstaff_user_id" = "p"."hubstaff_user_id") AND ("cs"."role" = "p"."role") AND ("cs"."period" = "p"."period"))))
             LEFT JOIN "sched" "s" ON ((("s"."user_id" = "p"."profile_id") AND ("s"."weekday" = "p"."dow"))))
        )
 SELECT "hubstaff_user_id",
    "name",
    "role",
    "period",
    "max"("cluster_start") AS "shift_start",
        CASE
            WHEN "bool_or"("from_sched") THEN 'Según horario propio'::"text"
            WHEN ("max"("cluster_start") = 0) THEN 'Madrugada · 12am–8am'::"text"
            WHEN ("max"("cluster_start") = 480) THEN 'Mañana · 8am–4pm'::"text"
            ELSE 'Tarde · 4pm–12am'::"text"
        END AS "turno",
    "count"(*) AS "dias",
    (((("max"("cluster_start") + ("round"("avg"("dev_cluster")))::integer) % 1440) + 1440) % 1440) AS "checkin_prom_min",
    "count"(*) FILTER (WHERE ("dev" > 10)) AS "tardanzas",
    ("round"(((100.0 * ("count"(*) FILTER (WHERE ("dev" <= 10)))::numeric) / ("count"(*))::numeric)))::integer AS "pct_a_tiempo",
    ("round"("avg"("dev") FILTER (WHERE ("dev" > 10))))::integer AS "min_tarde_prom",
    "bool_or"("from_sched") AS "horario_cargado"
   FROM "perday2"
  GROUP BY "hubstaff_user_id", "name", "role", "period";


ALTER VIEW "public"."v_qa_attendance" OWNER TO "postgres";


