    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "public"."current_tenant_id"() NOT NULL,
    "name" "text" NOT NULL,
    "department" "text" DEFAULT 'other'::"text" NOT NULL,
