CREATE OR REPLACE VIEW "public"."whatsapp_commitments_overdue" AS
 SELECT "c"."id",
    "c"."tenant_id",
    "c"."group_id",
    "c"."source_message_id",
    "c"."committed_by_member_id",
    "c"."committed_by_text",
    "c"."subject",
    "c"."target_subject",
    "c"."related_entity_type",
    "c"."related_entity_id",
    "c"."due_at",
    "c"."status",
    "c"."resolved_at",
    "c"."resolved_by_message_id",
    "c"."resolution_note",
    "c"."last_followup_at",
    "c"."followup_count",
    "c"."confidence",
    "c"."metadata",
    "c"."created_at",
    "c"."updated_at",
    "g"."name" AS "group_name",
    "m"."display_name" AS "committed_by_display_name",
    (EXTRACT(epoch FROM ("now"() - "c"."due_at")) / (3600)::numeric) AS "hours_overdue"
   FROM (("public"."whatsapp_commitments" "c"
     JOIN "public"."whatsapp_groups" "g" ON (("g"."id" = "c"."group_id")))
     LEFT JOIN "public"."whatsapp_members" "m" ON (("m"."id" = "c"."committed_by_member_id")))
  WHERE (("c"."status" = ANY (ARRAY['pending'::"text", 'overdue'::"text"])) AND ("c"."due_at" IS NOT NULL) AND ("c"."due_at" < "now"()));


ALTER VIEW "public"."whatsapp_commitments_overdue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."whatsapp_costs_by_group_month" AS
 SELECT "tenant_id",
    (("context" ->> 'group_id'::"text"))::"uuid" AS "group_id",
    ("date_trunc"('month'::"text", "occurred_at"))::"date" AS "month",
    "count"(*) AS "calls",
    "sum"("cost_usd") AS "cost_usd",
    "sum"("cost_usd") FILTER (WHERE ("operation" = 'whatsapp_agent'::"text")) AS "agent_cost",
    "sum"("cost_usd") FILTER (WHERE ("operation" = 'whatsapp_extract_commitments'::"text")) AS "extract_cost",
    "sum"("cost_usd") FILTER (WHERE ("operation" = 'whatsapp-transcribe-audio'::"text")) AS "audio_cost",
    "sum"("cost_usd") FILTER (WHERE ("operation" = 'whatsapp-analyze-image'::"text")) AS "image_cost",
    "sum"("cost_usd") FILTER (WHERE (("operation" = 'whatsapp_agent'::"text") AND (("context" ->> 'invoked_by'::"text") = 'auto'::"text"))) AS "agent_auto_cost",
    "sum"("cost_usd") FILTER (WHERE (("operation" = 'whatsapp_agent'::"text") AND (("context" ->> 'invoked_by'::"text") <> 'auto'::"text") AND ("context" ? 'invoked_by'::"text"))) AS "agent_mention_cost"
   FROM "public"."api_usage_log" "l"
  WHERE (("operation" ~~ 'whatsapp%'::"text") AND ("context" ? 'group_id'::"text"))
  GROUP BY "tenant_id", (("context" ->> 'group_id'::"text"))::"uuid", ("date_trunc"('month'::"text", "occurred_at"));


ALTER VIEW "public"."whatsapp_costs_by_group_month" OWNER TO "postgres";


COMMENT ON VIEW "public"."whatsapp_costs_by_group_month" IS 'Costos del bot de WhatsApp por grupo y mes, leyendo api_usage_log y agrupando por context.group_id. Se renderiza en Panel de Control → WhatsApp Bot.';



