    "source" "text" DEFAULT 'wpp_message'::"text" NOT NULL,
    "source_message_id" "uuid",
    "announced_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "whatsapp_user_time_off_off_type_check" CHECK (("off_type" = ANY (ARRAY['day_off'::"text", 'partial'::"text", 'sick'::"text", 'vacation'::"text"]))),
    CONSTRAINT "whatsapp_user_time_off_source_check" CHECK (("source" = ANY (ARRAY['wpp_message'::"text", 'manual'::"text"])))
);


