  WHERE (("ur"."user_id" = "auth"."uid"()) AND ("ur"."role" = ANY (ARRAY['admin'::"text", 'manager'::"text", 'Closer Supervisor'::"text"]))))))) WITH CHECK (("tenant_id" = "public"."current_tenant_id"()));



